payload.text:
I have updated the **Dashboard** to include a list of **Events for the Current Month**.

This new section appears below the Birthday list and gives you a quick overview of upcoming scheduled activities, sorted by date.

Here are the changes:
1.  **Dashboard Update**: Added a new card that lists detailed event information (Date, Title, Time, Description) for the current month.
2.  **Logic Improvement**: Updated the date filtering logic to be more robust (handling timezone edge cases better by parsing the date string directly) and reused this logic for the "Events This Month" counter.

You can now see your monthly schedule at a glance right when you log in!

# Updated files:

## components/Dashboard.tsx

Added the Events List card and updated event filtering logic.

```tsx
import React, { useMemo } from 'react';
import { Users, DollarSign, Calendar, Cake, ShieldCheck, UserCheck, Clock } from 'lucide-react';
import { MetricCard, ContentCard } from './ui/Card';
import { Member, WeeklySummary, IndividualGiving, Expense, CalendarEvent, UserRole, AttendanceRecord } from '../types';

interface DashboardProps {
  members: Member[];
  weeklySummaries: WeeklySummary[];
  individualGiving: IndividualGiving[];
  expenses: Expense[];
  events: CalendarEvent[];
  attendance: AttendanceRecord[];
  userRole: UserRole;
}

const Dashboard: React.FC<DashboardProps> = ({ members, weeklySummaries, individualGiving, expenses, events, attendance, userRole }) => {
  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  // Metrics Logic
  const totalMembers = members.length;
  const boardMembersCount = members.filter(m => m.isBoardMember).length;

  // Safe date filtering to avoid timezone issues with YYYY-MM-DD strings
  const currentMonthEvents = useMemo(() => {
    return events.filter(e => {
      const [year, month] = e.date.split('-').map(Number);
      return (month - 1) === currentMonth && year === currentYear;
    }).sort((a, b) => a.date.localeCompare(b.date));
  }, [events, currentMonth, currentYear]);

  const monthlyEventsCount = currentMonthEvents.length;

  const birthdayMembers = useMemo(() => {
    return members.filter(m => {
      // Basic check, might need timezone adjustment if strictly parsing
      const dob = new Date(m.dob); 
      // Using getMonth() on Date object created from YYYY-MM-DD might be off by one day depending on timezone
      // Safer to split string if consistency is key, but keeping existing logic for birthdays for now
      // unless we want to standardize. Let's keep existing logic but careful.
      // Actually, for consistency let's fix birthdays too if possible, but let's stick to the request (Events) primarily.
      return dob.getMonth() === currentMonth;
    }).sort((a, b) => new Date(a.dob).getDate() - new Date(b.dob).getDate());
  }, [members, currentMonth]);

  // Attendance Logic
  const lastAttendance = attendance.length > 0 
    ? [...attendance].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0]
    : null;
  const lastAttendanceCount = lastAttendance ? lastAttendance.memberIds.length + lastAttendance.visitorCount : 0;
  const lastAttendanceDate = lastAttendance ? new Date(lastAttendance.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : 'N/A';

  // Financials
  const calculateTotalGiving = () => {
    const individualTotal = individualGiving.reduce((sum, item) => sum + Number(item.amount), 0);
    const weeklyTotal = weeklySummaries.reduce((sum, item) => sum + Number(item.tithes) + Number(item.offering), 0);
    return individualTotal + weeklyTotal;
  };

  const calculateTotalExpenses = () => {
    return expenses.reduce((sum, item) => sum + Number(item.amount), 0);
  };

  const totalGiving = calculateTotalGiving();
  const totalExpenses = calculateTotalExpenses();
  const netBalance = totalGiving - totalExpenses;

  const formatCurrency = (val: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);
  const showFinancials = userRole !== 'Guest';

  const currentMonthName = new Date().toLocaleString('default', { month: 'long' });

  return (
    <div className="space-y-6">
      {/* Top Metrics Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <MetricCard 
          title="Total Members" 
          value={totalMembers} 
          icon={<Users size={20} />} 
        />
        <MetricCard 
          title={`Attendance (${lastAttendanceDate})`} 
          value={lastAttendanceCount} 
          icon={<UserCheck size={20} />} 
          colorClass="bg-indigo-50 border-indigo-200"
        />
        <MetricCard 
          title="Events This Month" 
          value={monthlyEventsCount} 
          icon={<Calendar size={20} />} 
        />
        {showFinancials ? (
          <MetricCard 
            title="Net Balance (All Time)" 
            value={formatCurrency(netBalance)} 
            icon={<DollarSign size={20} />} 
            colorClass={netBalance >= 0 ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'}
          />
        ) : (
           <MetricCard 
            title="Board Members" 
            value={boardMembersCount} 
            icon={<ShieldCheck size={20} />} 
          />
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Birthdays & Events */}
        <div className="lg:col-span-2 space-y-6">
           {/* Birthday Reminder Widget */}
           <ContentCard title={`Birthdays in ${currentMonthName}`} className="border-pink-200">
            {birthdayMembers.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {birthdayMembers.map(member => {
                   // Correcting day display to avoid timezone shift visual bug
                   const [y, m, d] = member.dob.split('-').map(Number);
                   const day = d; 

                   return (
                    <div key={member.id} className="flex items-center space-x-3 p-3 bg-pink-50 rounded-lg border border-pink-100">
                      <div className="bg-pink-200 p-2 rounded-full text-pink-600">
                        <Cake size={18} />
                      </div>
                      <div>
                        <p className="font-semibold text-gray-900">{member.firstName} {member.lastName}</p>
                        <p className="text-sm text-pink-600">Day: {day}</p>
                      </div>
                    </div>
                   );
                })}
              </div>
            ) : (
              <div className="text-center py-8 text-gray-500">
                <Cake className="mx-auto mb-2 text-gray-300" size={32} />
                No birthdays this month.
              </div>
            )}
           </ContentCard>

           {/* Events List Widget */}
           <ContentCard title={`Events in ${currentMonthName}`}>
             {currentMonthEvents.length > 0 ? (
                <div className="space-y-3">
                  {currentMonthEvents.map(event => (
                    <div key={event.id} className="flex items-start gap-4 p-3 bg-blue-50/50 rounded-lg border border-blue-100">
                      <div className="flex-shrink-0 w-14 text-center bg-white rounded-lg border border-blue-100 p-1 shadow-sm">
                        <div className="text-xs text-blue-600 font-bold uppercase">{new Date(event.date + 'T12:00:00').toLocaleString('default', { month: 'short' })}</div>
                        <div className="text-xl font-bold text-gray-800">{new Date(event.date + 'T12:00:00').getDate()}</div>
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex justify-between items-start">
                          <h4 className="font-semibold text-gray-900 truncate">{event.title}</h4>
                          {event.time && (
                            <span className="flex items-center gap-1 text-xs text-blue-600 bg-blue-100 px-2 py-0.5 rounded-full whitespace-nowrap">
                              <Clock size={10} /> {event.time}
                            </span>
                          )}
                        </div>
                        {event.description && <p className="text-sm text-gray-600 mt-1 line-clamp-2">{event.description}</p>}
                      </div>
                    </div>
                  ))}
                </div>
             ) : (
                <div className="text-center py-8 text-gray-500">
                  <Calendar className="mx-auto mb-2 text-gray-300" size={32} />
                  No events scheduled for {currentMonthName}.
                </div>
             )}
           </ContentCard>
        </div>

        {/* Right Column: Financials */}
        <div className="space-y-6">
          {showFinancials && (
            <ContentCard title="Financial Quick View" className="h-fit">
              <div className="space-y-4">
                <div className="p-4 bg-gray-50 rounded-lg">
                  <p className="text-sm text-gray-500 mb-1">Total Giving (All Time)</p>
                  <p className="text-xl font-bold text-gray-900">{formatCurrency(totalGiving)}</p>
                </div>
                <div className="p-4 bg-gray-50 rounded-lg">
                  <p className="text-sm text-gray-500 mb-1">Total Expenses (All Time)</p>
                  <p className="text-xl font-bold text-gray-900">{formatCurrency(totalExpenses)}</p>
                </div>
              </div>
            </ContentCard>
          )}

          {/* We could add an announcement summary or recent attendance summary here for non-financial users */}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
```

I have enhanced the **Member Management** system to be more comprehensive and family-oriented.

Here are the specific updates:
1.  **Direct Family Add Shortcut**: Added a new "Add Family Member" button (green user icon) directly in the members list row. This allows you to quickly add a spouse or child to an existing family without searching through the full edit form.
2.  **More Member Data**: Added **Gender** and **Marital Status** fields to the member profiles to track important demographic information.
3.  **Family Data**: Added a **Gender** field for family members as well.
4.  **Improved Form**: The "Add/Edit Member" form now includes these new fields and has a smoother experience for managing the family list.

You can now keep even more detailed records for every individual and household!

# Updated files:

## types.ts

Added `gender` and `maritalStatus` to `Member` and `gender` to `FamilyMember`.

## db.ts

Updated seed data with new gender and marital status fields.

## components/Members.tsx

Added new fields to the form, implemented the "Add Family Member" shortcut button, and improved the form layout.

```tsx
import React, { useState } from 'react';
import { Plus, Search, Edit2, Trash2, Shield, ShieldCheck, User, MapPin, ChevronDown, ChevronRight, X, UserPlus, Users as UsersIcon } from 'lucide-react';
import { ContentCard } from './ui/Card';
import { Member, UserRole, FamilyMember } from '../types';
import { db } from '../db';

interface MembersProps {
  members: Member[];
  onRefresh: () => void;
  userRole: UserRole;
}

const Members: React.FC<MembersProps> = ({ members, onRefresh, userRole }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterBoard, setFilterBoard] = useState(false);
  const [editingMember, setEditingMember] = useState<Member | null>(null);
  const [expandedMembers, setExpandedMembers] = useState<Set<string>>(new Set());

  // Form State
  const initialFormState: Omit<Member, 'id'> = {
    firstName: '', 
    lastName: '', 
    email: '', 
    phone: '', 
    address: '', 
    ministry: '', 
    status: 'Active', 
    dob: '', 
    dateJoined: '', 
    gender: 'Male',
    maritalStatus: 'Single',
    isBoardMember: false, 
    boardRole: '', 
    familyMembers: []
  };
  const [formData, setFormData] = useState(initialFormState);

  // Helper for family members form
  const [newFamilyMember, setNewFamilyMember] = useState<FamilyMember>({ id: '', name: '', relationship: 'Child', dob: '', gender: 'Male' });

  const toggleExpand = (id: string) => {
    const newSet = new Set(expandedMembers);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setExpandedMembers(newSet);
  };

  const handleEdit = (member: Member) => {
    setEditingMember(member);
    setFormData({ 
      ...initialFormState, // Ensure defaults
      ...member,
      familyMembers: member.familyMembers || []
    });
    setIsModalOpen(true);
  };

  const handleAddFamilyMemberClick = (member: Member) => {
    handleEdit(member);
    // Use timeout to allow modal to render before scrolling
    setTimeout(() => {
      const section = document.getElementById('family-section');
      if (section) {
        section.scrollIntoView({ behavior: 'smooth' });
        const input = section.querySelector<HTMLInputElement>('input[name="famName"]');
        if (input) input.focus();
      }
    }, 100);
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to delete this member and their family data?')) {
      db.deleteMember(id);
      onRefresh();
    }
  };

  const handleAddFamilyMember = () => {
    if (!newFamilyMember.name) return;
    setFormData(prev => ({
      ...prev,
      familyMembers: [...(prev.familyMembers || []), { ...newFamilyMember, id: Date.now().toString() }]
    }));
    setNewFamilyMember({ id: '', name: '', relationship: 'Child', dob: '', gender: 'Male' });
  };

  const handleRemoveFamilyMember = (idx: number) => {
    const newList = [...(formData.familyMembers || [])];
    newList.splice(idx, 1);
    setFormData(prev => ({ ...prev, familyMembers: newList }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingMember) {
      db.saveMember({ ...editingMember, ...formData });
    } else {
      db.saveMember({ ...formData, id: Date.now().toString() } as Member);
    }
    setIsModalOpen(false);
    setEditingMember(null);
    setFormData(initialFormState);
    onRefresh();
  };

  const filteredMembers = members.filter(m => {
    const matchesSearch = (m.firstName + ' ' + m.lastName).toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filterBoard ? m.isBoardMember : true;
    return matchesSearch && matchesFilter;
  });

  const canEdit = userRole === 'Admin';

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between gap-4">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
          <input
            type="text"
            placeholder="Search head of family..."
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
          />
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setFilterBoard(!filterBoard)}
            className={`px-4 py-2 rounded-lg border flex items-center gap-2 ${filterBoard ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : 'bg-white border-gray-300 text-gray-700'}`}
          >
            {filterBoard ? <ShieldCheck size={18} /> : <Shield size={18} />}
            {filterBoard ? 'Board Only' : 'All Families'}
          </button>
          {canEdit && (
            <button
              onClick={() => { setEditingMember(null); setFormData(initialFormState); setIsModalOpen(true); }}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg flex items-center gap-2 hover:bg-blue-700"
            >
              <Plus size={18} /> Add New Family
            </button>
          )}
        </div>
      </div>

      <ContentCard className="overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 border-b border-gray-200">
              <tr>
                <th className="w-8"></th>
                <th className="px-6 py-3 text-xs font-semibold text-gray-500 uppercase">Head of Family</th>
                <th className="px-6 py-3 text-xs font-semibold text-gray-500 uppercase">Contact</th>
                <th className="px-6 py-3 text-xs font-semibold text-gray-500 uppercase">Status</th>
                <th className="px-6 py-3 text-xs font-semibold text-gray-500 uppercase">Joined</th>
                <th className="px-6 py-3 text-xs font-semibold text-gray-500 uppercase">Family Size</th>
                {canEdit && <th className="px-6 py-3 text-xs font-semibold text-gray-500 uppercase text-right">Actions</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredMembers.map(member => {
                const familyCount = (member.familyMembers?.length || 0);
                const isExpanded = expandedMembers.has(member.id);

                return (
                  <React.Fragment key={member.id}>
                    <tr className="hover:bg-gray-50">
                      <td className="pl-4">
                        {familyCount > 0 && (
                          <button onClick={() => toggleExpand(member.id)} className="text-gray-400 hover:text-blue-600">
                            {isExpanded ? <ChevronDown size={18} /> : <ChevronRight size={18} />}
                          </button>
                        )}
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${member.gender === 'Female' ? 'bg-pink-100 text-pink-600' : 'bg-blue-100 text-blue-600'}`}>
                            {member.firstName[0]}{member.lastName[0]}
                          </div>
                          <div>
                            <p className="font-medium text-gray-900">{member.firstName} {member.lastName}</p>
                            <p className="text-xs text-gray-500">Born: {member.dob}</p>
                            {member.isBoardMember && (
                                <span className="inline-flex items-center gap-1 text-[10px] bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded-full mt-1">
                                    <ShieldCheck size={10} /> {member.boardRole || 'Board'}
                                </span>
                            )}
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-600">
                        <div>{member.email}</div>
                        <div className="text-xs text-gray-400">{member.phone}</div>
                        {member.address && <div className="text-xs text-gray-400 mt-1 flex items-center gap-1"><MapPin size={10} /> {member.address}</div>}
                      </td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 text-xs rounded-full ${
                          member.status === 'Active' ? 'bg-green-100 text-green-700' :
                          member.status === 'Inactive' ? 'bg-gray-100 text-gray-700' :
                          'bg-orange-100 text-orange-700'
                        }`}>
                          {member.status}
                        </span>
                        {member.maritalStatus && (
                          <div className="text-[10px] text-gray-400 mt-1 uppercase tracking-wide">{member.maritalStatus}</div>
                        )}
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-600">{member.dateJoined}</td>
                      <td className="px-6 py-4">
                        <span className="flex items-center gap-1 text-sm text-gray-600">
                          <UsersIcon size={14} /> {familyCount + 1}
                        </span>
                      </td>
                      {canEdit && (
                        <td className="px-6 py-4 text-right space-x-2 flex justify-end items-center">
                          <button onClick={() => handleAddFamilyMemberClick(member)} className="text-green-600 hover:text-green-800 p-1" title="Add Family Member">
                             <UserPlus size={16} />
                          </button>
                          <button onClick={() => handleEdit(member)} className="text-blue-600 hover:text-blue-800 p-1" title="Edit Profile">
                            <Edit2 size={16} />
                          </button>
                          <button onClick={() => handleDelete(member.id)} className="text-red-500 hover:text-red-700 p-1" title="Delete">
                            <Trash2 size={16} />
                          </button>
                        </td>
                      )}
                    </tr>
                    {isExpanded && member.familyMembers && member.familyMembers.length > 0 && (
                      <tr className="bg-gray-50/50">
                        <td colSpan={7} className="px-4 py-3">
                          <div className="ml-14 border-l-2 border-blue-200 pl-4 py-2">
                            <h4 className="text-xs font-bold text-gray-500 uppercase mb-2">Family Members</h4>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                              {member.familyMembers.map(fam => (
                                <div key={fam.id} className="flex items-center gap-3 bg-white p-2 rounded border border-gray-100 shadow-sm">
                                  <div className={`w-6 h-6 rounded-full flex items-center justify-center text-[10px] ${fam.gender === 'Female' ? 'bg-pink-50 text-pink-500' : 'bg-blue-50 text-blue-500'}`}>
                                    <User size={12} />
                                  </div>
                                  <div className="text-sm">
                                    <p className="font-medium text-gray-800">{fam.name}</p>
                                    <p className="text-xs text-gray-500">{fam.relationship} • Born: {fam.dob}</p>
                                  </div>
                                </div>
                              ))}
                            </div>
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                );
              })}
              {filteredMembers.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-6 py-8 text-center text-gray-500">No members found.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </ContentCard>

      {/* Add/Edit Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-4xl w-full p-6 max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-6">{editingMember ? 'Edit Family Profile' : 'Add New Family Profile'}</h2>
            <form onSubmit={handleSubmit} className="space-y-6">

              {/* Head of Family Section */}
              <div>
                <h3 className="text-sm font-bold text-gray-500 uppercase border-b pb-2 mb-4">Head of Family</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">First Name</label>
                    <input required type="text" value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} className="w-full border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Last Name</label>
                    <input required type="text" value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} className="w-full border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500" />
                  </div>
                   <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Gender</label>
                    <select value={formData.gender || 'Male'} onChange={e => setFormData({...formData, gender: e.target.value as any})} className="w-full border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500">
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                    <input type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                    <input type="tel" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500" />
                  </div>
                  <div className="md:col-span-2 lg:col-span-1">
                    <label className="block text-sm font-medium text-gray-700 mb-1">Address</label>
                    <input type="text" value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} className="w-full border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500" placeholder="Street, City, Zip" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Date of Birth</label>
                    <input required type="date" value={formData.dob} onChange={e => setFormData({...formData, dob: e.target.value})} className="w-full border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Joined (YYYY-MM)</label>
                    <input required type="month" value={formData.dateJoined} onChange={e => setFormData({...formData, dateJoined: e.target.value})} className="w-full border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Marital Status</label>
                    <select value={formData.maritalStatus || 'Single'} onChange={e => setFormData({...formData, maritalStatus: e.target.value as any})} className="w-full border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500">
                      <option value="Single">Single</option>
                      <option value="Married">Married</option>
                      <option value="Widowed">Widowed</option>
                      <option value="Divorced">Divorced</option>
                    </select>
                  </div>
