                        className="w-full border rounded px-3 py-2 text-sm focus:outline-blue-500"
                      >
                        <option value="Male">Male</option>
                        <option value="Female">Female</option>
                      </select>
                    </div>
                    <div>
                      <select 
                        value={newFamilyMember.relationship} 
                        onChange={e => setNewFamilyMember({...newFamilyMember, relationship: e.target.value})} 
                        className="w-full border rounded px-3 py-2 text-sm focus:outline-blue-500"
                      >
                        <option>Spouse</option>
                        <option>Child</option>
                        <option>Parent</option>
                        <option>Sibling</option>
                        <option>Other</option>
                      </select>
                    </div>
                    <div className="flex gap-2">
                       <input 
                        type="date" 
                        value={newFamilyMember.dob} 
                        onChange={e => setNewFamilyMember({...newFamilyMember, dob: e.target.value})} 
                        className="w-full border rounded px-3 py-2 text-sm focus:outline-blue-500"
                      />
                      <button 
                        type="button" 
                        onClick={handleAddOrUpdateFamilyMember} 
                        disabled={!newFamilyMember.name}
                        className={`text-white px-3 py-2 rounded hover:opacity-90 disabled:opacity-50 flex-shrink-0 flex items-center gap-1 ${editingFamilyMemberIdx !== null ? 'bg-amber-500' : 'bg-blue-600'}`}
                        title={editingFamilyMemberIdx !== null ? "Update Details" : "Add to List"}
                      >
                         {editingFamilyMemberIdx !== null ? <Save size={16} /> : <Plus size={18} />}
                      </button>
                    </div>
                  </div>
                  {editingFamilyMemberIdx !== null && (
                    <div className="mt-2 text-right">
                       <button type="button" onClick={() => { setEditingFamilyMemberIdx(null); setNewFamilyMember({ id: '', name: '', relationship: 'Child', dob: '', gender: 'Male' }); }} className="text-xs text-gray-500 underline hover:text-gray-700">Cancel Edit</button>
                    </div>
                  )}
                </div>
              </div>

              <div className="flex gap-3 pt-6 border-t">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 px-4 py-2 border rounded-lg hover:bg-gray-50 font-medium">Cancel</button>
                <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-medium">Save Member</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

