class DBService {
  private get<T>(key: string): T[] {
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : [];
  }

  private set<T>(key: string, data: T[]) {
    localStorage.setItem(key, JSON.stringify(data));
  }

  // Admin Account Management
  createAdminAccount(username: string, passwordHash: string) {
    localStorage.setItem('twc_admin_auth', JSON.stringify({ username, passwordHash }));
  }

  getAdminAccount() {
    const data = localStorage.getItem('twc_admin_auth');
    return data ? JSON.parse(data) : null;
  }

  validateAdmin(username: string, passwordHash: string): boolean {
    const admin = this.getAdminAccount();
    if (!admin) return false;
    return admin.username === username && admin.passwordHash === passwordHash;
  }

  // Members
  getMembers(): Member[] {
    const data = this.get<Member>('twc_members');
    if (data.length === 0 && !localStorage.getItem('twc_members_init')) {
      this.set('twc_members', SEED_MEMBERS);
      localStorage.setItem('twc_members_init', 'true');
      return SEED_MEMBERS;
    }
    return data;
  }
  saveMember(member: Member) {
    const members = this.getMembers();
    const index = members.findIndex(m => m.id === member.id);
    if (index >= 0) {
      members[index] = member;
    } else {
      members.push(member);
    }
    this.set('twc_members', members);
  }
  deleteMember(id: string) {
    const members = this.getMembers().filter(m => m.id !== id);
    this.set('twc_members', members);
  }

  // Attendance
  getAttendance(): AttendanceRecord[] { return this.get('twc_attendance'); }
  saveAttendance(record: AttendanceRecord) {
    const records = this.getAttendance();
    const index = records.findIndex(r => r.id === record.id);
    if (index >= 0) records[index] = record; else records.push(record);
    this.set('twc_attendance', records);
  }
  deleteAttendance(id: string) {
    this.set('twc_attendance', this.getAttendance().filter(r => r.id !== id));
  }

  // Financials
  getWeeklySummaries(): WeeklySummary[] { return this.get('twc_weekly'); }
  saveWeeklySummary(item: WeeklySummary) {
    const items = this.getWeeklySummaries();
    const index = items.findIndex(i => i.id === item.id);
    if (index >= 0) items[index] = item; else items.push(item);
    this.set('twc_weekly', items);
  }

  getIndividualGiving(): IndividualGiving[] { return this.get('twc_giving'); }
  saveIndividualGiving(item: IndividualGiving) {
