  }

  getExpenses(): Expense[] { return this.get('twc_expenses'); }
  saveExpense(item: Expense) {
    const items = this.getExpenses();
    const index = items.findIndex(i => i.id === item.id);
    if (index >= 0) items[index] = item; else items.push(item);
    this.set('twc_expenses', items);
  }
  deleteExpense(id: string) {
    this.set('twc_expenses', this.getExpenses().filter(i => i.id !== id));
  }

  // Events
  getEvents(): CalendarEvent[] { return this.get('twc_events'); }
  saveEvent(item: CalendarEvent) {
    const items = this.getEvents();
    const index = items.findIndex(i => i.id === item.id);
    if (index >= 0) items[index] = item; else items.push(item);
    this.set('twc_events', items);
  }
  deleteEvent(id: string) {
    this.set('twc_events', this.getEvents().filter(i => i.id !== id));
