```tsx
import React, { useMemo, useState } from 'react';
import { Users, DollarSign, Calendar, Cake, ShieldCheck, UserCheck, Clock, Home, Megaphone, Plus, Trash2, Image as ImageIcon } from 'lucide-react';
import { MetricCard, ContentCard } from './ui/Card';
import { Member, WeeklySummary, IndividualGiving, Expense, CalendarEvent, UserRole, AttendanceRecord, Announcement } from '../types';
import { db } from '../db';

interface DashboardProps {
  members: Member[];
  weeklySummaries: WeeklySummary[];
  individualGiving: IndividualGiving[];
  expenses: Expense[];
  events: CalendarEvent[];
  attendance: AttendanceRecord[];
  announcements: Announcement[];
  userRole: UserRole;
  onRefresh: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ members, weeklySummaries, individualGiving, expenses, events, attendance, announcements, userRole, onRefresh }) => {
  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();
  const [isAnnounceModalOpen, setIsAnnounceModalOpen] = useState(false);
  const [newAnnouncement, setNewAnnouncement] = useState<Partial<Announcement>>({
    title: '',
    content: '',
    imageUrl: '',
    date: new Date().toISOString().split('T')[0]
  });

  const canEdit = userRole === 'Admin';

  // Metrics Logic
  const totalFamilies = members.length;

  // Calculate total people (Heads + Family Members)
  const totalPeople = members.reduce((total, member) => {
    return total + 1 + (member.familyMembers?.length || 0);
  }, 0);

  const boardMembersCount = members.filter(m => m.isBoardMember).length;

  // Safe date filtering to avoid timezone issues with YYYY-MM-DD strings
  const currentMonthEvents = useMemo(() => {
    return events.filter(e => {
      const [year, month] = e.date.split('-').map(Number);
      return (month - 1) === currentMonth && year === currentYear;
    }).sort((a, b) => a.date.localeCompare(b.date));
  }, [events, currentMonth, currentYear]);

  const monthlyEventsCount = currentMonthEvents.length;

  const birthdayMembers = useMemo(() => {
    let allPeople: { name: string; dob: string; isHead: boolean }[] = [];

    // Flatten list of all people with DOBs
    members.forEach(m => {
      if (m.dob) allPeople.push({ name: `${m.firstName} ${m.lastName}`, dob: m.dob, isHead: true });
      if (m.familyMembers) {
        m.familyMembers.forEach(f => {
          if (f.dob) allPeople.push({ name: f.name, dob: f.dob, isHead: false });
        });
      }
    });

    return allPeople.filter(p => {
      const dob = new Date(p.dob); 
      return dob.getMonth() === currentMonth;
    }).sort((a, b) => new Date(a.dob).getDate() - new Date(b.dob).getDate());
  }, [members, currentMonth]);

  // Attendance Logic
  const lastAttendance = attendance.length > 0 
    ? [...attendance].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0]
    : null;
  const lastAttendanceCount = lastAttendance ? lastAttendance.memberIds.length + lastAttendance.visitorCount : 0;
  const lastAttendanceDate = lastAttendance ? new Date(lastAttendance.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : 'N/A';

  // Financials
  const calculateTotalGiving = () => {
    const individualTotal = individualGiving.reduce((sum, item) => sum + Number(item.amount), 0);
    const weeklyTotal = weeklySummaries.reduce((sum, item) => sum + Number(item.tithes) + Number(item.offering), 0);
    return individualTotal + weeklyTotal;
  };

  const calculateTotalExpenses = () => {
    return expenses.reduce((sum, item) => sum + Number(item.amount), 0);
  };

  const totalGiving = calculateTotalGiving();
  const totalExpenses = calculateTotalExpenses();
  const netBalance = totalGiving - totalExpenses;

  const formatCurrency = (val: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);
  const showFinancials = userRole !== 'Guest';

  const currentMonthName = new Date().toLocaleString('default', { month: 'long' });

  // Announcement Handlers
  const handleAnnouncementSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newAnnouncement.title || !newAnnouncement.content) return;

    db.saveAnnouncement({
      id: Date.now().toString(),
      title: newAnnouncement.title!,
      content: newAnnouncement.content!,
      date: newAnnouncement.date || new Date().toISOString().split('T')[0],
      imageUrl: newAnnouncement.imageUrl
    });

    setIsAnnounceModalOpen(false);
    setNewAnnouncement({ title: '', content: '', imageUrl: '', date: new Date().toISOString().split('T')[0] });
    onRefresh();
  };

  const handleDeleteAnnouncement = (id: string) => {
    if(confirm('Are you sure you want to remove this announcement?')) {
      db.deleteAnnouncement(id);
      onRefresh();
    }
  };

  const sortedAnnouncements = [...announcements].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="space-y-6">
      {/* Top Metrics Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <MetricCard 
          title="Total People" 
          value={totalPeople} 
          icon={<Users size={20} />} 
        />
        <MetricCard 
          title="Total Families" 
          value={totalFamilies} 
          icon={<Home size={20} />} 
          colorClass="bg-blue-50 border-blue-200"
        />
        <MetricCard 
          title={`Attendance (${lastAttendanceDate})`} 
          value={lastAttendanceCount} 
          icon={<UserCheck size={20} />} 
          colorClass="bg-indigo-50 border-indigo-200"
        />
        {showFinancials ? (
          <MetricCard 
            title="Net Balance" 
            value={formatCurrency(netBalance)} 
            icon={<DollarSign size={20} />} 
            colorClass={netBalance >= 0 ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'}
          />
        ) : (
           <MetricCard 
            title="Board Members" 
            value={boardMembersCount} 
            icon={<ShieldCheck size={20} />} 
          />
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Announcements, Birthdays & Events */}
        <div className="lg:col-span-2 space-y-6">
           {/* Announcements Section */}
           <div className="space-y-4">
             <div className="flex items-center justify-between">
                <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                  <Megaphone size={20} className="text-blue-600" /> Announcements
                </h3>
                {canEdit && (
                  <button 
                    onClick={() => setIsAnnounceModalOpen(true)}
                    className="text-sm bg-blue-600 text-white px-3 py-1.5 rounded-lg flex items-center gap-1 hover:bg-blue-700"
                  >
                    <Plus size={16} /> Add New
                  </button>
                )}
             </div>

             {sortedAnnouncements.length > 0 ? (
               <div className="grid gap-4">
                 {sortedAnnouncements.map(announce => (
                   <ContentCard key={announce.id} className="overflow-hidden border-l-4 border-l-blue-500">
                     <div className="flex flex-col md:flex-row gap-6">
                       {announce.imageUrl && (
                         <div className="w-full md:w-1/3 h-48 md:h-auto flex-shrink-0 rounded-lg overflow-hidden bg-gray-100">
                           <img 
                            src={announce.imageUrl} 
                            alt={announce.title} 
                            className="w-full h-full object-cover"
                            onError={(e) => (e.currentTarget.style.display = 'none')}
                           />
                         </div>
                       )}
                       <div className="flex-1 relative">
                         {canEdit && (
                            <button 
                              onClick={() => handleDeleteAnnouncement(announce.id)}
                              className="absolute top-0 right-0 text-gray-400 hover:text-red-500 p-1"
                              title="Delete Announcement"
                            >
                              <Trash2 size={16} />
                            </button>
                         )}
                         <span className="text-xs text-gray-500 font-medium mb-1 block">{new Date(announce.date).toLocaleDateString(undefined, { dateStyle: 'long' })}</span>
                         <h4 className="text-xl font-bold text-gray-900 mb-2">{announce.title}</h4>
                         <p className="text-gray-600 whitespace-pre-wrap leading-relaxed">{announce.content}</p>
                       </div>
                     </div>
                   </ContentCard>
                 ))}
               </div>
             ) : (
               <div className="text-center py-8 bg-white rounded-xl border border-dashed border-gray-300">
                 <p className="text-gray-500">No announcements posted.</p>
               </div>
             )}
           </div>

           {/* Birthday Reminder Widget */}
           <ContentCard title={`Birthdays in ${currentMonthName}`} className="border-pink-200">
            {birthdayMembers.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {birthdayMembers.map((person, idx) => {
                   // Correcting day display to avoid timezone shift visual bug
                   const [y, m, d] = person.dob.split('-').map(Number);
                   const day = d; 

                   return (
