import React, { useMemo, useState } from 'react';
import { Users, DollarSign, Calendar, Cake, ShieldCheck, UserCheck, Clock, Home, Megaphone, Plus, Trash2, Image as ImageIcon } from 'lucide-react';
import { MetricCard, ContentCard } from './ui/Card';
import { Member, WeeklySummary, IndividualGiving, Expense, CalendarEvent, UserRole, AttendanceRecord, Announcement } from '../types';
import { db } from '../db';

interface DashboardProps {
  members: Member[];
  weeklySummaries: WeeklySummary[];
  individualGiving: IndividualGiving[];
  expenses: Expense[];
  events: CalendarEvent[];
  attendance: AttendanceRecord[];
  announcements: Announcement[];
  userRole: UserRole;
  onRefresh: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ members, weeklySummaries, individualGiving, expenses, events, attendance, announcements, userRole, onRefresh }) => {
  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();
  const [isAnnounceModalOpen, setIsAnnounceModalOpen] = useState(false);
  const [newAnnouncement, setNewAnnouncement] = useState<Partial<Announcement>>({
    title: '',
    content: '',
    imageUrl: '',
    date: new Date().toISOString().split('T')[0]
  });

  // Permissions: Admin can edit announcements
  const canEdit = userRole === 'Admin';

  // Metrics Logic
  const totalFamilies = members.length;

  // Calculate total people (Heads + Family Members)
  const totalPeople = members.reduce((total, member) => {
    return total + 1 + (member.familyMembers?.length || 0);
  }, 0);

  const boardMembersCount = members.filter(m => m.isBoardMember).length;

  // Safe date filtering to avoid timezone issues with YYYY-MM-DD strings
  const currentMonthEvents = useMemo(() => {
    return events.filter(e => {
      const [year, month] = e.date.split('-').map(Number);
      return (month - 1) === currentMonth && year === currentYear;
    }).sort((a, b) => a.date.localeCompare(b.date));
  }, [events, currentMonth, currentYear]);

  const monthlyEventsCount = currentMonthEvents.length;

  const birthdayMembers = useMemo(() => {
    let allPeople: { name: string; dob: string; isHead: boolean }[] = [];

    // Flatten list of all people with DOBs
    members.forEach(m => {
      if (m.dob) allPeople.push({ name: `${m.firstName} ${m.lastName}`, dob: m.dob, isHead: true });
      if (m.familyMembers) {
        m.familyMembers.forEach(f => {
          if (f.dob) allPeople.push({ name: f.name, dob: f.dob, isHead: false });
        });
      }
    });

    return allPeople.filter(p => {
      const dob = new Date(p.dob); 
      return dob.getMonth() === currentMonth;
    }).sort((a, b) => new Date(a.dob).getDate() - new Date(b.dob).getDate());
  }, [members, currentMonth]);

  // Attendance Logic
  const lastAttendance = attendance.length > 0 
    ? [...attendance].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0]
    : null;
  const lastAttendanceCount = lastAttendance ? lastAttendance.memberIds.length + lastAttendance.visitorCount : 0;
  const lastAttendanceDate = lastAttendance ? new Date(lastAttendance.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : 'N/A';

  // Financials
  const calculateTotalGiving = () => {
    const individualTotal = individualGiving.reduce((sum, item) => sum + Number(item.amount), 0);
    const weeklyTotal = weeklySummaries.reduce((sum, item) => sum + Number(item.tithes) + Number(item.offering), 0);
    return individualTotal + weeklyTotal;
  };

  const calculateTotalExpenses = () => {
    return expenses.reduce((sum, item) => sum + Number(item.amount), 0);
  };

  const totalGiving = calculateTotalGiving();
  const totalExpenses = calculateTotalExpenses();
  const netBalance = totalGiving - totalExpenses;

  const formatCurrency = (val: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);
  const showFinancials = userRole !== 'Guest';

