    }
  };

  const formatPhoneNumber = (value: string) => {
    const phone = value.replace(/\D/g, '');
    if (phone.length < 4) return phone;
    if (phone.length < 7) return `(${phone.slice(0, 3)}) ${phone.slice(3)}`;
    return `(${phone.slice(0, 3)}) ${phone.slice(3, 6)}-${phone.slice(6, 10)}`;
  };

  const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const formatted = formatPhoneNumber(e.target.value);
    setFormData(prev => ({ ...prev, phone: formatted }));
  };

  const handleAddOrUpdateFamilyMember = () => {
    if (!newFamilyMember.name) return;

    if (editingFamilyMemberIdx !== null) {
      // Update existing
      setFormData(prev => {
        const updatedList = [...(prev.familyMembers || [])];
        if (updatedList[editingFamilyMemberIdx]) {
           updatedList[editingFamilyMemberIdx] = { ...newFamilyMember, id: updatedList[editingFamilyMemberIdx].id };
        }
        return { ...prev, familyMembers: updatedList };
      });
      setEditingFamilyMemberIdx(null);
    } else {
      // Add new
      setFormData(prev => ({
        ...prev,
        familyMembers: [...(prev.familyMembers || []), { ...newFamilyMember, id: Date.now().toString() }]
      }));
    }
    setNewFamilyMember({ id: '', name: '', relationship: 'Child', dob: '', gender: 'Male' });
  };

  const handleEditFamilyMember = (idx: number) => {
    const memberToEdit = formData.familyMembers?.[idx];
    if (memberToEdit) {
      setNewFamilyMember(memberToEdit);
      setEditingFamilyMemberIdx(idx);
    }
  };

  const handleRemoveFamilyMember = (idx: number) => {
    const newList = [...(formData.familyMembers || [])];
    newList.splice(idx, 1);
    setFormData(prev => ({ ...prev, familyMembers: newList }));
    if (editingFamilyMemberIdx === idx) {
      setEditingFamilyMemberIdx(null);
      setNewFamilyMember({ id: '', name: '', relationship: 'Child', dob: '', gender: 'Male' });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingMember) {
      db.saveMember({ ...editingMember, ...formData });
    } else {
      db.saveMember({ ...formData, id: Date.now().toString() } as Member);
    }
    setIsModalOpen(false);
    setEditingMember(null);
    setFormData(initialFormState);
    onRefresh();
  };

  const filteredMembers = members.filter(m => {
