## components/Financials.tsx

Added filtering, annual reporting logic, and a printable statement view.

```tsx
import React, { useState, useMemo } from 'react';
import { Plus, Trash2, Calendar, DollarSign, FileText, Link as LinkIcon, Printer, Filter, Download } from 'lucide-react';
import { ContentCard } from './ui/Card';
import { Member, WeeklySummary, IndividualGiving, Expense, AppSettings } from '../types';
import { db } from '../db';

interface FinancialsProps {
  type: 'giving' | 'expenses';
  members: Member[];
  weeklySummaries: WeeklySummary[];
  individualGiving: IndividualGiving[];
  expenses: Expense[];
  settings: AppSettings;
  onRefresh: () => void;
}

const Financials: React.FC<FinancialsProps> = ({ type, members, weeklySummaries, individualGiving, expenses, settings, onRefresh }) => {
  const [activeGivingTab, setActiveGivingTab] = useState<'individual' | 'weekly'>('individual');
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Filters State
  const currentYear = new Date().getFullYear().toString();
  const [filterMemberId, setFilterMemberId] = useState<string>('');
  const [filterYear, setFilterYear] = useState<string>(currentYear);

  // Forms State
  const [indivForm, setIndivForm] = useState<Partial<IndividualGiving>>({ date: new Date().toISOString().split('T')[0], type: 'Tithes', amount: 0 });
  const [weeklyForm, setWeeklyForm] = useState<Partial<WeeklySummary>>({ date: new Date().toISOString().split('T')[0], tithes: 0, offering: 0 });
  const [expenseForm, setExpenseForm] = useState<Partial<Expense>>({ date: new Date().toISOString().split('T')[0], amount: 0, category: 'Utilities', description: '', receiptUrl: '' });

  const formatCurrency = (val: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(val);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (type === 'giving') {
      if (activeGivingTab === 'individual') {
        const member = members.find(m => m.id === indivForm.memberId);
        if (!member) return;
        db.saveIndividualGiving({ 
          ...indivForm, 
          memberName: `${member.firstName} ${member.lastName}`,
          id: Date.now().toString() 
        } as IndividualGiving);
      } else {
        db.saveWeeklySummary({ ...weeklyForm, id: Date.now().toString() } as WeeklySummary);
      }
    } else {
      db.saveExpense({ ...expenseForm, id: Date.now().toString() } as Expense);
    }
    setIsModalOpen(false);
    onRefresh();
  };

  const handleDelete = (id: string, storeType: 'individual' | 'weekly' | 'expense') => {
    if (!confirm('Delete record?')) return;
    if (storeType === 'individual') db.deleteIndividualGiving(id);
    else if (storeType === 'expense') db.deleteExpense(id);
    onRefresh();
  };

  const handlePrint = () => {
    window.print();
  };

  // Filter Logic for Individual Giving
  const filteredIndividualGiving = useMemo(() => {
    return individualGiving.filter(item => {
      const matchMember = filterMemberId ? item.memberId === filterMemberId : true;
      const matchYear = filterYear ? item.date.startsWith(filterYear) : true;
      return matchMember && matchYear;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [individualGiving, filterMemberId, filterYear]);

  // Totals Calculation for Filtered Data
  const totals = useMemo(() => {
    return filteredIndividualGiving.reduce((acc, curr) => {
      if (curr.type === 'Tithes') acc.tithes += Number(curr.amount);
      else if (curr.type === 'Offering') acc.offering += Number(curr.amount);
      else acc.other += Number(curr.amount);
      return acc;
    }, { tithes: 0, offering: 0, other: 0 });
  }, [filteredIndividualGiving]);

  const selectedMember = members.find(m => m.id === filterMemberId);

  // Render Giving View
  if (type === 'giving') {
    return (
      <div className="space-y-6">
        {/* Screen View */}
        <div className="print:hidden space-y-6">
          <div className="flex gap-4 border-b border-gray-200 pb-2">
            <button onClick={() => setActiveGivingTab('individual')} className={`pb-2 px-4 font-medium ${activeGivingTab === 'individual' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500'}`}>Individual Giving</button>
            <button onClick={() => setActiveGivingTab('weekly')} className={`pb-2 px-4 font-medium ${activeGivingTab === 'weekly' ? 'text-blue-600 border-b-2 border-blue-600' : 'text-gray-500'}`}>Weekly Summaries</button>
          </div>

          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
             {activeGivingTab === 'individual' && (
               <div className="flex flex-wrap items-center gap-3 bg-white p-2 rounded-lg border border-gray-200">
                  <div className="flex items-center gap-2 px-2">
                    <Filter size={16} className="text-gray-400" />
                    <span className="text-sm font-medium text-gray-600">Filter:</span>
                  </div>
                  <select 
                    value={filterMemberId} 
                    onChange={e => setFilterMemberId(e.target.value)} 
                    className="border-gray-300 border rounded-md text-sm py-1.5 px-2 outline-none focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="">All Members</option>
                    {members.map(m => <option key={m.id} value={m.id}>{m.firstName} {m.lastName}</option>)}
                  </select>
                  <select 
                    value={filterYear} 
                    onChange={e => setFilterYear(e.target.value)}
                    className="border-gray-300 border rounded-md text-sm py-1.5 px-2 outline-none focus:ring-2 focus:ring-blue-500"
                  >
                     {Array.from({length: 5}, (_, i) => (parseInt(currentYear) - i).toString()).map(yr => (
                       <option key={yr} value={yr}>{yr}</option>
                     ))}
                  </select>
                  {filterMemberId && (
                    <button onClick={handlePrint} className="ml-2 flex items-center gap-1 text-sm bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-1.5 rounded-md transition-colors">
                      <Printer size={16} /> Print Statement
                    </button>
                  )}
               </div>
             )}

            <button onClick={() => setIsModalOpen(true)} className="px-4 py-2 bg-green-600 text-white rounded-lg flex items-center gap-2 hover:bg-green-700 ml-auto">
              <Plus size={18} /> Record {activeGivingTab === 'individual' ? 'Donation' : 'Summary'}
            </button>
          </div>

          {activeGivingTab === 'individual' ? (
            <div className="space-y-4">
              {/* Annual Summary Card (only shows when a filter is applied to give context) */}
              {(filterMemberId || filterYear) && (
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                    <p className="text-sm text-blue-600 font-medium">Annual Tithes ({filterYear})</p>
                    <p className="text-2xl font-bold text-blue-900">{formatCurrency(totals.tithes)}</p>
                  </div>
                  <div className="bg-green-50 p-4 rounded-xl border border-green-100">
                    <p className="text-sm text-green-600 font-medium">Annual Offering ({filterYear})</p>
                    <p className="text-2xl font-bold text-green-900">{formatCurrency(totals.offering)}</p>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
                    <p className="text-sm text-gray-600 font-medium">Total Giving ({filterYear})</p>
                    <p className="text-2xl font-bold text-gray-900">{formatCurrency(totals.tithes + totals.offering + totals.other)}</p>
                  </div>
                </div>
              )}

              <ContentCard>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-gray-50"><tr><th className="p-3">Date</th><th className="p-3">Member</th><th className="p-3">Type</th><th className="p-3">Amount</th><th className="p-3 text-right">Action</th></tr></thead>
                    <tbody>
                      {filteredIndividualGiving.length > 0 ? filteredIndividualGiving.map(item => (
                        <tr key={item.id} className="border-b hover:bg-gray-50">
                          <td className="p-3">{item.date}</td>
                          <td className="p-3 font-medium">{item.memberName}</td>
                          <td className="p-3"><span className={`px-2 py-1 rounded text-xs ${item.type === 'Tithes' ? 'bg-blue-100 text-blue-700' : 'bg-green-100 text-green-700'}`}>{item.type}</span></td>
                          <td className="p-3 font-mono">{formatCurrency(item.amount)}</td>
                          <td className="p-3 text-right"><button onClick={() => handleDelete(item.id, 'individual')} className="text-red-500 hover:bg-red-50 p-1 rounded"><Trash2 size={16} /></button></td>
                        </tr>
                      )) : (
                        <tr><td colSpan={5} className="p-8 text-center text-gray-500">No records found for the selected filters.</td></tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </ContentCard>
            </div>
          ) : (
            <ContentCard>
               <table className="w-full text-left">
                <thead className="bg-gray-50"><tr><th className="p-3">Service Date</th><th className="p-3">Tithes</th><th className="p-3">Offering</th><th className="p-3">Total</th></tr></thead>
                <tbody>
                  {weeklySummaries.map(item => (
                    <tr key={item.id} className="border-b hover:bg-gray-50">
                      <td className="p-3 font-medium">{item.date}</td>
                      <td className="p-3">{formatCurrency(item.tithes)}</td>
                      <td className="p-3">{formatCurrency(item.offering)}</td>
                      <td className="p-3 font-bold text-green-700">{formatCurrency(Number(item.tithes) + Number(item.offering))}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </ContentCard>
          )}
        </div>

        {/* Printable Statement View (Hidden on screen, Visible on print) */}
        <div className="hidden print:block p-8 bg-white text-black">
            <div className="text-center mb-8 border-b-2 border-gray-800 pb-4">
                {settings.logoUrl && <img src={settings.logoUrl} alt="Logo" className="h-16 mx-auto mb-2" />}
                <h1 className="text-3xl font-bold uppercase tracking-wide">True Worship Church</h1>
                <h2 className="text-xl mt-2 font-semibold">Annual Giving Statement</h2>
                <p className="text-gray-600">Statement Period: Jan 1, {filterYear} - Dec 31, {filterYear}</p>
            </div>

            <div className="flex justify-between mb-8">
                <div>
                    <h3 className="font-bold text-lg mb-1">Donor Information:</h3>
