                            <p className="text-xl">{selectedMember.firstName} {selectedMember.lastName}</p>
                            <p>{selectedMember.address}</p>
                            <p>{selectedMember.email}</p>
                        </>
                    ) : (
                        <p className="text-gray-500 italic">All Members Report</p>
                    )}
                </div>
                <div className="text-right">
