  const totalFamilies = members.length;

  // Calculate total people (Heads + Family Members)
  const totalPeople = members.reduce((total, member) => {
    return total + 1 + (member.familyMembers?.length || 0);
  }, 0);

  const boardMembersCount = members.filter(m => m.isBoardMember).length;

  // Date Logic for Reminders
  const today = new Date();
  // formatting to YYYY-MM-DD using local time to match input values
  const todayStr = today.toLocaleDateString('en-CA'); 

  const nextWeekDate = new Date(today);
  nextWeekDate.setDate(today.getDate() + 7);
  const nextWeekStr = nextWeekDate.toLocaleDateString('en-CA');

  // Filter: Daily Events (Today)
  const dailyEvents = events.filter(e => e.date === todayStr);

  // Filter: Weekly Events (Tomorrow -> Next 7 days)
  const weeklyEvents = events.filter(e => e.date > todayStr && e.date <= nextWeekStr)
    .sort((a,b) => a.date.localeCompare(b.date));

  // Filter: Month Events (for general calendar view)
  const currentMonthEvents = useMemo(() => {
    return events.filter(e => {
      const [year, month] = e.date.split('-').map(Number);
      return (month - 1) === currentMonth && year === currentYear;
    }).sort((a, b) => a.date.localeCompare(b.date));
