  const [copySuccess, setCopySuccess] = useState('');
  const [activeReminderTab, setActiveReminderTab] = useState<'email' | 'text'>('email');

  const getDaysInMonth = (date: Date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const days = new Date(year, month + 1, 0).getDate();
    const firstDay = new Date(year, month, 1).getDay();
    return { days, firstDay };
  };

  const { days, firstDay } = getDaysInMonth(currentDate);
  const monthName = currentDate.toLocaleString('default', { month: 'long' });
  const year = currentDate.getFullYear();
  const canEdit = userRole === 'Admin';

  const handlePrevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1));
  const handleNextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1));

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    db.saveEvent({ ...newEvent, id: Date.now().toString() } as CalendarEvent);
    setIsModalOpen(false);
    onRefresh();
  };

  const deleteEvent = (id: string) => {
    if(confirm("Delete this event?")) {
        db.deleteEvent(id);
        onRefresh();
    }
  };

  const handleEmailReminder = () => {
    if (!reminderEvent) return;

    const emails = members
      .filter(m => m.status === 'Active' && m.email)
      .map(m => m.email)
      .join(',');

    const subject = encodeURIComponent(`Reminder: ${reminderEvent.title}`);
    const body = encodeURIComponent(`Dear Church Family,\n\nThis is a reminder for the upcoming event:\n\nEvent: ${reminderEvent.title}\nDate: ${reminderEvent.date}\nTime: ${reminderEvent.time || 'All Day'}\n\n${reminderEvent.description || ''}\n\nWe hope to see you there!\n\nTrue Worship Church`);

    window.open(`mailto:?bcc=${emails}&subject=${subject}&body=${body}`);
  };

  const handleCopyPhones = () => {
    if (!reminderEvent) return;

    const phones = members
      .filter(m => m.status === 'Active' && m.phone)
      .map(m => m.phone)
      .join(', ');

    navigator.clipboard.writeText(phones).then(() => {
        setCopySuccess('Copied!');
        setTimeout(() => setCopySuccess(''), 2000);
    });
