                {blanksArray.map(i => <div key={`blank-${i}`} className="h-24 bg-gray-50/50 rounded-lg"></div>)}
                {daysArray.map(day => {
                    const dateStr = `${year}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
                    const dayEvents = events.filter(e => e.date === dateStr);
                    const isToday = new Date().toISOString().split('T')[0] === dateStr;

                    return (
                        <div key={day} className={`h-24 border rounded-lg p-2 text-left relative overflow-hidden group ${isToday ? 'bg-blue-50 border-blue-200' : 'bg-white border-gray-100'}`}>
