      const newArtistName = songData.artist?.trim() || artist;

      // Handle Artist Rename
      if (newArtistName !== artist) {
          if (window.confirm(`Renaming artist from "${artist}" to "${newArtistName}". This will move the song page URL. Continue?`)) {
              // 1. Save song under new artist ID
              saveCustomSong(newArtistName, song, songData);
              // 2. Update view count for new ID (optional, or carry over)
              if (editForm.views !== undefined) {
                  setViewCount(newArtistName, song, editForm.views);
              }
              // 3. Delete old entry
              deleteCustomSong(artist, song);

              // 4. Update Artist Profile if needed
