```typescript
// A lightweight phonetic mapper for Roman to Nepali Unicode

const VOWELS: Record<string, string> = {
  'a': 'अ', 'aa': 'आ', 'i': 'इ', 'ee': 'ई', 'u': 'उ', 'oo': 'ऊ',
  'e': 'ए', 'ai': 'ऐ', 'o': 'ओ', 'au': 'औ', 'am': 'अं', 'an': 'अँ', 'ri': 'ऋ'
};

const MATRAS: Record<string, string> = {
  'a': '', 'aa': 'ा', 'i': 'ि', 'ee': 'ी', 'u': 'ु', 'oo': 'ू',
  'e': 'े', 'ai': 'ै', 'o': 'ो', 'au': 'ौ', 'am': 'ं', 'an': 'ँ', 'ri': 'ृ'
};

const CONSONANTS: Record<string, string> = {
  'k': 'क', 'kh': 'ख', 'g': 'ग', 'gh': 'घ', 'ng': 'ङ',
  'ch': 'च', 'chh': 'छ', 'j': 'ज', 'jh': 'झ', 'yn': 'ञ',
  't': 'ट', 'th': 'ठ', 'd': 'ड', 'dh': 'ढ', 'n': 'ण',
  'T': 'त', 'Th': 'थ', 'D': 'द', 'Dh': 'ध', 'N': 'न', // Case sensitive usually, but we handle logic below
  'p': 'प', 'ph': 'फ', 'f': 'फ', 'b': 'ब', 'bh': 'भ', 'm': 'म',
  'y': 'य', 'r': 'र', 'l': 'ल', 'v': 'व', 'w': 'व',
  'sh': 'श', 'Sh': 'ष', 's': 'स', 'h': 'ह',
  'gy': 'ज्ञ', 'tr': 'त्र', 'ksh': 'क्ष'
};

// Simplified mapping logic
// In a real input tool, we'd use a trie or complex state machine. 
// This functions by tokenizing and replacing based on longest match.

export const convertToNepali = (text: string): string => {
  if (!text) return "";

  // Split by non-word characters to preserve spacing/punctuation, but process words
  // Simple approach: Process the whole string by iterating characters

  let result = "";
  let i = 0;

  while (i < text.length) {
    let handled = false;
    const char = text[i];

    // Pass through non-letters (numbers, punctuation, spaces)
    if (!/[a-zA-Z]/.test(char)) {
        // Handle common punctuation mapping if needed, e.g. | -> ।
        if (char === '|') result += '।';
        else result += char;
        i++;
        continue;
    }

    // Attempt to find consonant match (Length 3, 2, 1)
    let consonant = "";
    let cLen = 0;

    for (let len = 3; len > 0; len--) {
        const sub = text.substr(i, len).toLowerCase();
        // Special case handling for 't' vs 'T' (ta vs Ta) if we wanted strict mapping
        // For simplicity, we stick to lowercase dictionary but handle 't' logic

        if (CONSONANTS[sub]) {
            consonant = CONSONANTS[sub];
            cLen = len;

            // Hardcoded fixes for common variations
            if (sub === 't' && text[i] === 't') consonant = 'त'; // default t to त
            if (sub === 'th' && text[i] === 't') consonant = 'थ'; 
            if (sub === 'd' && text[i] === 'd') consonant = 'द';
            if (sub === 'dh' && text[i] === 'd') consonant = 'ध';
            if (sub === 'n' && text[i] === 'n') consonant = 'न';

            break;
        }
    }

    if (consonant) {
        i += cLen;

        // Look ahead for vowel/matra
        let matra = "";
        let mLen = 0;
        let hasVowel = false;

        for (let len = 2; len > 0; len--) {
            if (i + len <= text.length) {
                const sub = text.substr(i, len).toLowerCase();
                if (MATRAS[sub] !== undefined) {
                    matra = MATRAS[sub];
                    mLen = len;
                    hasVowel = true;
                    break;
                }
            }
        }

        if (hasVowel) {
            result += consonant + matra;
            i += mLen;
        } else {
            // No vowel implies 'a' (inherent) or halant? 
            // In English typing "k" usually means "क" (ka), "ka" means "क" or "का".
            // Logic: "k" -> क, "ka" -> क, "kaa" -> का

            // However, typical phonetic:
            // namaste -> n(a) m(a) s t e
            // n -> न् (half) if followed by consonant? 

            // Simple Logic: 
            // If consonant is at end of word -> halant (sometimes) or full.
            // Let's default to Full char. 
            // To get half char, users usually type specific sequence or we detect consonant cluster.

            // Check if next char is another consonant (consonant cluster)
            // If next is consonant, this one is likely half (halant)
            // Exception: 'a' explicitly completes it.

            let nextIsConsonant = false;
            if (i < text.length) {
                const nextChar = text[i].toLowerCase();
                // Simple check
                if (CONSONANTS[nextChar] || (i+1 < text.length && CONSONANTS[text.substr(i,2).toLowerCase()])) {
                    nextIsConsonant = true;
                }
            }

            if (nextIsConsonant) {
                result += consonant + '्'; // Halant
            } else {
                result += consonant; 
            }
        }
        handled = true;
    } 

    // If not a consonant, check if it is a standalone vowel (at start of word)
    if (!handled) {
        let vowel = "";
        let vLen = 0;
        for (let len = 2; len > 0; len--) {
            const sub = text.substr(i, len).toLowerCase();
            if (VOWELS[sub]) {
                vowel = VOWELS[sub];
                vLen = len;
                break;
            }
        }

        if (vowel) {
            result += vowel;
            i += vLen;
            handled = true;
        }
    }

    if (!handled) {
        // Fallback
        result += text[i];
        i++;
    }
  }

  return result;
};
