## utils/nepaliConverter.ts

New file containing the logic to convert English text to Nepali.

```typescript
// A lightweight phonetic mapper for Roman to Nepali Unicode

const VOWELS: Record<string, string> = {
  'a': 'अ', 'aa': 'आ', 'i': 'इ', 'ee': 'ई', 'u': 'उ', 'oo': 'ऊ',
  'e': 'ए', 'ai': 'ऐ', 'o': 'ओ', 'au': 'औ', 'am': 'अं', 'an': 'अँ', 'ri': 'ऋ'
};

const MATRAS: Record<string, string> = {
  'a': '', 'aa': 'ा', 'i': 'ि', 'ee': 'ी', 'u': 'ु', 'oo': 'ू',
  'e': 'े', 'ai': 'ै', 'o': 'ो', 'au': 'ौ', 'am': 'ं', 'an': 'ँ', 'ri': 'ृ'
};

const CONSONANTS: Record<string, string> = {
  'k': 'क', 'kh': 'ख', 'g': 'ग', 'gh': 'घ', 'ng': 'ङ',
  'ch': 'च', 'chh': 'छ', 'j': 'ज', 'jh': 'झ', 'yn': 'ञ',
  't': 'ट', 'th': 'ठ', 'd': 'ड', 'dh': 'ढ', 'n': 'ण',
  'T': 'त', 'Th': 'थ', 'D': 'द', 'Dh': 'ध', 'N': 'न',
  'p': 'प', 'ph': 'फ', 'f': 'फ', 'b': 'ब', 'bh': 'भ', 'm': 'म',
  'y': 'य', 'r': 'र', 'l': 'ल', 'v': 'व', 'w': 'व',
  'sh': 'श', 'Sh': 'ष', 's': 'स', 'h': 'ह',
  'gy': 'ज्ञ', 'tr': 'त्र', 'ksh': 'क्ष'
};

export const convertToNepali = (text: string): string => {
  if (!text) return "";

  let result = "";
  let i = 0;

  while (i < text.length) {
    let handled = false;
    const char = text[i];

    // Pass through non-letters (numbers, punctuation, spaces)
    if (!/[a-zA-Z]/.test(char)) {
        if (char === '|') result += '।';
        else result += char;
        i++;
        continue;
    }

    // Attempt to find consonant match (Length 3, 2, 1)
    let consonant = "";
    let cLen = 0;

    for (let len = 3; len > 0; len--) {
        const sub = text.substr(i, len).toLowerCase();

        // Custom logic for T/D/N casing mapping
        let mapKey = sub;
        if (sub === 't' && text[i] === 't') mapKey = 'T'; // lowercase t -> त (T in map)
        if (sub === 't' && text[i] === 'T') mapKey = 't'; // uppercase T -> ट (t in map)
        if (sub === 'd' && text[i] === 'd') mapKey = 'D'; 
        if (sub === 'd' && text[i] === 'D') mapKey = 'd';

        // Check map (using our slightly mixed case logic above, or direct lookup)
        // Actually, let's simplify: Use the map directly but handle the specific mapping logic inside the map definition or here.
        // Let's use the standard mapping where 't'=ट, 'T'=त is NOT standard. 
        // Standard: t=त, T=ट.

        // Refined Logic based on common phonetic typing:
        // t -> त
        // T -> ट
        // th -> थ
        // Th -> ठ

        // We need to check exact case for single chars first
        let found = CONSONANTS[sub]; // Try exact match first? No, map keys are mostly specific.

        // Let's map specific cases manually for accuracy before generic lowercase
        if (len === 1) {
             if (text[i] === 't') found = 'त';
             else if (text[i] === 'T') found = 'ट';
             else if (text[i] === 'd') found = 'द';
             else if (text[i] === 'D') found = 'ड';
             else if (text[i] === 'n') found = 'न';
             else if (text[i] === 'N') found = 'ण';
             else if (text[i] === 's') found = 'स';
             else if (text[i] === 'S') found = 'ष'; // or sh
        } 

        if (!found) found = CONSONANTS[sub]; // Try dictionary

        if (found) {
            consonant = found;
            cLen = len;
            break;
        }
    }

    if (consonant) {
        i += cLen;

        // Look ahead for vowel/matra
        let matra = "";
        let mLen = 0;
        let hasVowel = false;

        for (let len = 2; len > 0; len--) {
            if (i + len <= text.length) {
                const sub = text.substr(i, len).toLowerCase();
                if (MATRAS[sub] !== undefined) {
                    matra = MATRAS[sub];
                    mLen = len;
                    hasVowel = true;
                    break;
                }
            }
        }

        if (hasVowel) {
            result += consonant + matra;
            i += mLen;
        } else {
            // Check if next char is another consonant (consonant cluster) implies Halant
            let nextIsConsonant = false;
            if (i < text.length) {
                const nextChar = text[i];
                // Very basic check: is it a letter and likely a consonant?
                // If the user types 'k' then space, it's 'क'. If 'k' then 't', it's 'क्त' (k+halant+t)
                if (/[a-zA-Z]/.test(nextChar) && !VOWELS[nextChar.toLowerCase()]) {
                     nextIsConsonant = true;
                }
            }

            if (nextIsConsonant) {
                result += consonant + '्'; // Halant
            } else {
                result += consonant; 
            }
        }
        handled = true;
    } 

    // If not a consonant, check if it is a standalone vowel (at start of word)
    if (!handled) {
        let vowel = "";
        let vLen = 0;
        for (let len = 2; len > 0; len--) {
            const sub = text.substr(i, len).toLowerCase();
            if (VOWELS[sub]) {
                vowel = VOWELS[sub];
                vLen = len;
                break;
            }
        }

        if (vowel) {
            result += vowel;
            i += vLen;
            handled = true;
        }
    }

    if (!handled) {
        // Fallback
        result += text[i];
        i++;
    }
  }

  return result;
};
