```typescript
// A lightweight phonetic mapper for Roman to Nepali Unicode

const VOWELS: Record<string, string> = {
  'a': 'अ', 'aa': 'आ', 'i': 'इ', 'ee': 'ई', 'u': 'उ', 'oo': 'ऊ',
  'e': 'ए', 'ai': 'ऐ', 'o': 'ओ', 'au': 'औ', 'am': 'अं', 'an': 'अँ', 'ri': 'ऋ'
};

const MATRAS: Record<string, string> = {
  'a': '', 'aa': 'ा', 'i': 'ि', 'ee': 'ी', 'u': 'ु', 'oo': 'ू',
  'e': 'े', 'ai': 'ै', 'o': 'ो', 'au': 'ौ', 'am': 'ं', 'an': 'ँ', 'ri': 'ृ',
  'om': 'ॐ' // Special handling if needed
};

// Reverse map to check if a char is a Nepali consonant
const NEPALI_CONSONANTS = new Set([
  'क', 'ख', 'ग', 'घ', 'ङ',
  'च', 'छ', 'ज', 'झ', 'ञ',
  'ट', 'ठ', 'ड', 'ढ', 'ण',
  'त', 'थ', 'द', 'ध', 'न',
  'प', 'फ', 'ब', 'भ', 'म',
  'य', 'र', 'ल', 'व',
  'श', 'ष', 'स', 'ह',
  'क्ष', 'त्र', 'ज्ञ'
]);

const CONSONANTS: Record<string, string> = {
  'k': 'क', 'kh': 'ख', 'g': 'ग', 'gh': 'घ', 'ng': 'ङ',
  'ch': 'च', 'chh': 'छ', 'j': 'ज', 'jh': 'झ', 'yn': 'ञ',
  't': 'ट', 'th': 'ठ', 'd': 'ड', 'dh': 'ढ', 'n': 'ण',
  'T': 'त', 'Th': 'थ', 'D': 'द', 'Dh': 'ध', 'N': 'न',
  'p': 'प', 'ph': 'फ', 'f': 'फ', 'b': 'ब', 'bh': 'भ', 'm': 'म',
  'y': 'य', 'r': 'र', 'l': 'ल', 'v': 'व', 'w': 'व',
  'sh': 'श', 'Sh': 'ष', 's': 'स', 'h': 'ह',
  'gy': 'ज्ञ', 'tr': 'त्र', 'ksh': 'क्ष'
};

export const convertToNepali = (text: string): string => {
  if (!text) return "";

  let result = "";
  let i = 0;

  while (i < text.length) {
    let handled = false;
    const char = text[i];

    // 1. Pass through non-letters (numbers, punctuation, spaces)
    // We allow existing Nepali chars to pass through to result
    // We check against Roman alphabet to decide if we should transliterate
    if (!/[a-zA-Z]/.test(char)) {
        if (char === '|') result += '।';
        else result += char;
        i++;
        continue;
    }

    // 2. Attempt to find Consonant match (Length 3, 2, 1)
    let consonant = "";
    let cLen = 0;

    for (let len = 3; len > 0; len--) {
        const sub = text.substr(i, len).toLowerCase();

        // Manual Case Logic for t/d/n
        let found = '';
        if (len === 1) {
             if (text[i] === 't') found = 'त';
             else if (text[i] === 'T') found = 'ट';
             else if (text[i] === 'd') found = 'द';
             else if (text[i] === 'D') found = 'ड';
             else if (text[i] === 'n') found = 'न';
             else if (text[i] === 'N') found = 'ण';
             else if (text[i] === 's') found = 'स';
             else if (text[i] === 'S') found = 'ष';
        } 

        if (!found) found = CONSONANTS[sub]; 

        if (found) {
            consonant = found;
            cLen = len;
            break;
        }
    }

    if (consonant) {
        i += cLen;

        // Look ahead for vowel/matra
        let matra = "";
        let mLen = 0;
        let hasVowel = false;

        for (let len = 2; len > 0; len--) {
            if (i + len <= text.length) {
                const sub = text.substr(i, len).toLowerCase();
                if (MATRAS[sub] !== undefined) {
                    matra = MATRAS[sub];
                    mLen = len;
                    hasVowel = true;
                    break;
                }
            }
        }

        if (hasVowel) {
            result += consonant + matra;
            i += mLen;
        } else {
            // Smart Halant Logic
            let nextIsConsonant = false;
            if (i < text.length) {
                const nextChar = text[i];
                // If next char is Roman letter and NOT a vowel, it's likely a consonant cluster
                if (/[a-zA-Z]/.test(nextChar) && !VOWELS[nextChar.toLowerCase()]) {
                     nextIsConsonant = true;
                }
            }

            if (nextIsConsonant) {
                result += consonant + '्'; // Halant
            } else {
                result += consonant; 
            }
        }
        handled = true;
    } 

    // 3. If not a consonant, check if it is a Vowel
    if (!handled) {
        let vowel = "";
        let matra = "";
        let vLen = 0;

        // Try longest match first (e.g. 'aa')
        for (let len = 2; len > 0; len--) {
            const sub = text.substr(i, len).toLowerCase();

            // Check dictionary
            if (VOWELS[sub]) {
                vowel = VOWELS[sub];
                matra = MATRAS[sub] !== undefined ? MATRAS[sub] : "";
                vLen = len;
                break;
            }
        }

        if (vLen > 0) {
            // Crucial Step for Single Box:
            // Check if the previous character in `result` is a Nepali Consonant.
            // If so, use the MATRA. If not, use the Full VOWEL.

            const lastChar = result.slice(-1);
            // Also handle Halant: if last was 'k' + 'halant', and now we type 'a', we should remove halant?
            // Actually, my logic above adds halant if next is consonant. If next is vowel, we wouldn't have added halant?
            // Wait, if I type 'k', output is 'क'. Next I type 'a'. 
            // 'क' is in NEPALI_CONSONANTS.

            // Special handling for Halant at end
            let effectiveLastChar = lastChar;
            let removeLast = false;

            if (lastChar === '्') {
                // If ending in halant, we check the char before it
                effectiveLastChar = result.slice(-2, -1);
                // If we apply a matra, we effectively replace the halant?
                // Usually `k`+`a` -> `ka` (no halant).
                // My logic produces `k`->`क` (no halant).
                // So this halant check is for explicit halants or clusters?
            }

            if (NEPALI_CONSONANTS.has(effectiveLastChar)) {
                // Apply Matra
                result += matra;
            } else {
                // Standalone Vowel
                result += vowel;
            }

            i += vLen;
            handled = true;
        }
    }

    if (!handled) {
        // Fallback for unmatched chars
        result += text[i];
        i++;
    }
  }

  return result;
};
