             <div className="bg-yellow-50 p-6 rounded-2xl border border-yellow-200 shadow-sm animate-in slide-in-from-top-4">
                <h3 className="font-bold text-yellow-800 mb-4 border-b border-yellow-200 pb-2">Edit Details</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-2 uppercase">Categories</label>
                        <div className="bg-white border rounded p-2 max-h-32 overflow-y-auto grid grid-cols-2 sm:grid-cols-3 gap-2">
                             {availableCategories.map(cat => (
                                <button 
                                    key={cat}
                                    onClick={() => toggleCategorySelection(cat)}
                                    className={`text-xs px-2 py-1 rounded text-left ${
                                        (editForm.categories || []).includes(cat)
                                        ? 'bg-primary text-white font-bold'
                                        : 'bg-slate-50 hover:bg-slate-100 text-slate-600'
                                    }`}
                                >
                                    {cat}
                                </button>
                             ))}
                        </div>
                    </div>

                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">YouTube URL</label>
                        <input 
                            type="text" 
                            className="w-full border p-2 rounded bg-white" 
                            value={editForm.youtubeUrl || ''} 
                            onChange={e => setEditForm({...editForm, youtubeUrl: e.target.value})}
                            placeholder="https://youtube.com/watch?v=..."
                        />
                         <div className="flex items-center mt-2">
                            <input 
                                type="checkbox" 
                                id="ytEditVisible"
                                checked={editForm.isYoutubeVisible}
                                onChange={e => setEditForm({...editForm, isYoutubeVisible: e.target.checked})}
                                className="mr-2"
                            />
                            <label htmlFor="ytEditVisible" className="text-sm text-slate-700">Video Visible to Public</label>
                        </div>
                    </div>
                </div>
             </div>
         )}

         {/* 2. Main Lyrics Card (Glassmorphism Effect) */}
         <div className="bg-white/90 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/50 print:border-none print:shadow-none overflow-hidden">

             {/* Toolbar */}
             {!isEditing && (
                <div className="flex flex-col sm:flex-row justify-between items-center p-6 border-b border-slate-100 bg-white/50 no-print gap-4">

                    {/* Segmented Control */}
                    <div className="flex bg-slate-100 p-1 rounded-xl w-full sm:w-auto">
                        <button
                            onClick={() => setActiveTab('nepali')}
                            className={`flex-1 sm:flex-none px-6 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'nepali' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                        >
                        Nepali
                        </button>
                        <button
                            onClick={() => setActiveTab('roman')}
                            className={`flex-1 sm:flex-none px-6 py-1.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'roman' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                        >
                        Romanized
                        </button>
                    </div>

                    <div className="flex items-center gap-1 overflow-x-auto max-w-full">
                        {/* Video Toggle */}
                        {showYoutube && youtubeId && (
                            <button 
                                onClick={() => setShowVideo(!showVideo)} 
                                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-bold border transition-colors whitespace-nowrap ${showVideo ? 'bg-red-50 text-red-600 border-red-100' : 'bg-white text-slate-600 border-slate-200 hover:border-red-200 hover:text-red-500'}`}
                            >
                                <Youtube className="w-4 h-4" /> {showVideo ? 'Close Video' : 'Watch Video'}
                            </button>
                        )}
                        <div className="w-px h-6 bg-slate-200 mx-2"></div>
                        <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-primary rounded-lg transition-colors" title="Zoom Out"><ZoomOut className="w-4 h-4" /></button>
                        <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-primary rounded-lg transition-colors" title="Zoom In"><ZoomIn className="w-4 h-4" /></button>
                        <button 
                            onClick={handleFavorite} 
                            className={`p-2 rounded-lg transition-colors ${isFav ? 'text-red-500 bg-red-50' : 'text-slate-400 hover:text-red-500'}`}
                            title={isFav ? "Saved" : "Save"}
                        >
                            <Heart className={`w-4 h-4 ${isFav ? 'fill-current' : ''}`} />
                        </button>
                        <button onClick={handleCopy} className="p-2 text-slate-400 hover:text-primary rounded-lg transition-colors" title="Copy">
                            {copied ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}
                        </button>
                    </div>
                </div>
             )}

             {/* Collapsible Video Section */}
             {!isEditing && showYoutube && showVideo && youtubeId && (
                 <div className="bg-black aspect-video w-full animate-in slide-in-from-top-10 duration-300">
                     <iframe 
                        src={`https://www.youtube.com/embed/${youtubeId}?autoplay=1`} 
                        title="YouTube video player" 
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                        allowFullScreen
                        className="w-full h-full"
                     ></iframe>
                 </div>
             )}

             {/* Lyrics Content */}
             <div className="p-6 md:p-12">
                {isEditing ? (
                    <div className="space-y-6">
                        <div>
                            <label className="block text-sm font-bold text-slate-500 mb-1">Nepali Lyrics</label>
                            <textarea className="w-full h-64 p-4 border rounded-xl font-sans bg-slate-50 focus:bg-white transition-colors" value={editForm.lyrics_nepali || ''} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-slate-500 mb-1">Romanized Lyrics</label>
                            <textarea className="w-full h-64 p-4 border rounded-xl font-sans bg-slate-50 focus:bg-white transition-colors" value={editForm.lyrics_roman || ''} onChange={e => setEditForm({...editForm, lyrics_roman: e.target.value})} />
                        </div>
                    </div>
                ) : (
                    <div 
                        className="whitespace-pre-wrap font-sans leading-loose text-slate-800 tracking-wide lyrics-scroll"
                        style={{ fontSize: `${fontSize}px`, lineHeight: 1.8 }}
                    >
                        {activeTab === 'nepali' 
                            ? (data.lyrics_nepali || data.lyrics || "Lyrics available in Romanized version only.") 
                            : (data.lyrics_roman || "Romanized lyrics not available.")}
                    </div>
                )}
             </div>

             {/* Collapsible Credits Section */}
             {!isEditing && (
                 <div className="border-t border-slate-100 bg-slate-50/50">
                     <button 
                        onClick={() => setShowCredits(!showCredits)}
                        className="w-full flex items-center justify-between p-4 text-xs font-bold text-slate-400 uppercase tracking-widest hover:bg-slate-50 transition-colors"
                     >
                         <span>Song Credits</span>
                         {showCredits ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                     </button>

                     {showCredits && (
                         <div className="p-6 pt-0 grid grid-cols-1 sm:grid-cols-2 gap-6 animate-in slide-in-from-top-2">
                            <div className="flex items-start space-x-4 p-4 rounded-2xl bg-white border border-slate-100 shadow-sm">
                                <div className="p-2.5 bg-indigo-50 rounded-full text-indigo-500"><Music className="w-4 h-4" /></div>
                                <div>
                                    <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Composer</p>
                                    {renderCredits(composersList)}
                                </div>
                            </div>
                            <div className="flex items-start space-x-4 p-4 rounded-2xl bg-white border border-slate-100 shadow-sm">
                                <div className="p-2.5 bg-purple-50 rounded-full text-purple-500"><PenTool className="w-4 h-4" /></div>
                                <div>
                                    <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Lyrics By</p>
                                    {renderCredits(lyricistsList)}
                                </div>
                            </div>
                         </div>
                     )}
                 </div>
             )}

             {/* Edit Mode Credits */}
             {isEditing && (
                 <div className="p-6 border-t border-slate-100 bg-slate-50">
                     <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Edit Credits</h3>
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-bold text-slate-500 mb-1">Composer (Display)</label>
                            <input type="text" className="w-full border p-3 rounded-lg bg-white" value={editForm.composer} onChange={e => setEditForm({...editForm, composer: e.target.value})} />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-slate-500 mb-1">Lyricist (Display)</label>
                            <input type="text" className="w-full border p-3 rounded-lg bg-white" value={editForm.lyricist} onChange={e => setEditForm({...editForm, lyricist: e.target.value})} />
                        </div>
                     </div>
                 </div>
             )}
         </div>

        {/* 4. More From Artist */}
         <div className="bg-gradient-to-r from-indigo-500 to-purple-500 p-[2px] rounded-3xl shadow-lg no-print group">
            <Link 
