```typescript
import { LyricsData, ArtistDetails, Banner, Announcement } from '../types';
import { generateId } from './storage';

// Local Storage Keys
const SONGS_KEY = 'sansarplus_custom_songs_v2';
const ARTISTS_KEY = 'sansarplus_custom_artists_v2';
const BANNERS_KEY = 'sansarplus_banners_v2';
const SETTINGS_KEY = 'sansarplus_settings_v2';
const CATEGORIES_KEY = 'sansarplus_categories_v2';

export interface BackupData {
    songs: any[];
    artists: any[];
    categories: string[];
}

// --- HELPER FUNCTIONS ---
const getLocal = <T>(key: string, defaultVal: T): T => {
    try {
        const stored = localStorage.getItem(key);
        return stored ? JSON.parse(stored) : defaultVal;
    } catch {
        return defaultVal;
    }
};

const setLocal = (key: string, value: any) => {
    localStorage.setItem(key, JSON.stringify(value));
    window.dispatchEvent(new Event('content-change'));
};

// --- SONGS API ---

export const getAllCustomSongs = async (): Promise<any[]> => {
  // Simulate network delay for realism if desired, but kept fast for UI
  return Promise.resolve(getLocal<any[]>(SONGS_KEY, []));
};

export const getCustomSong = async (artist: string, title: string): Promise<any | null> => {
  const songs = getLocal<any[]>(SONGS_KEY, []);
  const id = generateId('song', title, artist);
  return Promise.resolve(songs.find(s => s.id === id) || null);
};

export const saveCustomSong = async (artist: string, title: string, data: LyricsData) => {
  const songs = getLocal<any[]>(SONGS_KEY, []);
  const id = generateId('song', title, artist);

  const newSong = {
    ...data,
    id,
    title,
    artist,
    lastUpdated: Date.now()
  };

  const index = songs.findIndex(s => s.id === id);
  if (index >= 0) {
      songs[index] = newSong;
  } else {
      songs.push(newSong);
  }

  setLocal(SONGS_KEY, songs);
  return Promise.resolve();
};

export const deleteCustomSong = async (artist: string, title: string) => {
  const songs = getLocal<any[]>(SONGS_KEY, []);
  const id = generateId('song', title, artist);
  const newSongs = songs.filter(s => s.id !== id);
  setLocal(SONGS_KEY, newSongs);
  return Promise.resolve();
};

// --- ARTISTS API ---

export const getAllCustomArtists = async (): Promise<any[]> => {
  return Promise.resolve(getLocal<any[]>(ARTISTS_KEY, []));
};

export const getCustomArtist = async (name: string): Promise<any | null> => {
  const artists = getLocal<any[]>(ARTISTS_KEY, []);
  const id = generateId('artist', name);
  return Promise.resolve(artists.find(a => a.id === id) || null);
};

export const saveCustomArtist = async (name: string, data: ArtistDetails) => {
  const artists = getLocal<any[]>(ARTISTS_KEY, []);
  const id = generateId('artist', name);

  const newArtist = {
    ...data,
    id,
    lastUpdated: Date.now()
  };

  const index = artists.findIndex(a => a.id === id);
  if (index >= 0) {
      artists[index] = newArtist;
  } else {
      artists.push(newArtist);
  }

  setLocal(ARTISTS_KEY, artists);
  return Promise.resolve();
};

export const deleteCustomArtist = async (name: string) => {
  const artists = getLocal<any[]>(ARTISTS_KEY, []);
  const id = generateId('artist', name);
  const newArtists = artists.filter(a => a.id !== id);
  setLocal(ARTISTS_KEY, newArtists);
  return Promise.resolve();
};

// --- CATEGORIES API ---

export const getCategories = async (): Promise<string[]> => {
  return Promise.resolve(getLocal<string[]>(CATEGORIES_KEY, ['Worship', 'Praise', 'Hymn']));
};

export const addCategory = async (category: string) => {
  const current = getLocal<string[]>(CATEGORIES_KEY, ['Worship', 'Praise', 'Hymn']);
  if (!current.includes(category)) {
    setLocal(CATEGORIES_KEY, [...current, category]);
  }
  return Promise.resolve();
};

export const updateCategory = async (oldCat: string, newCat: string) => {
  const current = getLocal<string[]>(CATEGORIES_KEY, ['Worship', 'Praise', 'Hymn']);
  const index = current.indexOf(oldCat);
  if (index > -1) {
      current[index] = newCat;
      setLocal(CATEGORIES_KEY, current);
  }
  return Promise.resolve();
};

export const deleteCategory = async (category: string) => {
  const current = getLocal<string[]>(CATEGORIES_KEY, ['Worship', 'Praise', 'Hymn']);
  const newList = current.filter(c => c !== category);
  setLocal(CATEGORIES_KEY, newList);
  return Promise.resolve();
};

// --- BANNERS API ---

export const getBanners = async (): Promise<Banner[]> => {
  return Promise.resolve(getLocal<Banner[]>(BANNERS_KEY, []));
};

export const saveBanner = async (banner: Banner) => {
  const banners = getLocal<Banner[]>(BANNERS_KEY, []);
  const index = banners.findIndex(b => b.id === banner.id);
  if (index >= 0) banners[index] = banner;
  else banners.push(banner);
  setLocal(BANNERS_KEY, banners);
  return Promise.resolve();
};

export const deleteBanner = async (id: string) => {
  const banners = getLocal<Banner[]>(BANNERS_KEY, []);
  const newBanners = banners.filter(b => b.id !== id);
  setLocal(BANNERS_KEY, newBanners);
  return Promise.resolve();
};

// --- VIEW COUNTS ---

export const getViewCount = async (artist: string, title: string): Promise<number> => {
  const song = await getCustomSong(artist, title);
  return song ? (song.views || 0) : 0;
};

export const incrementViewCount = async (artist: string, title: string) => {
  const songs = getLocal<any[]>(SONGS_KEY, []);
  const id = generateId('song', title, artist);
  const index = songs.findIndex(s => s.id === id);

  if (index >= 0) {
      songs[index].views = (songs[index].views || 0) + 1;
      // Note: We avoid dispatching 'content-change' for views to prevent re-renders of the whole app
      localStorage.setItem(SONGS_KEY, JSON.stringify(songs));
  }
  return Promise.resolve();
};

export const setViewCount = async (artist: string, title: string, count: number) => {
  const songs = getLocal<any[]>(SONGS_KEY, []);
  const id = generateId('song', title, artist);
  const index = songs.findIndex(s => s.id === id);

  if (index >= 0) {
      songs[index].views = count;
      localStorage.setItem(SONGS_KEY, JSON.stringify(songs));
  }
  return Promise.resolve();
};

// --- LOGO & ANNOUNCEMENT ---

export const getSiteLogo = async (): Promise<string> => {
  const settings = getLocal<any>(SETTINGS_KEY, {});
  return Promise.resolve(settings.logoUrl || '');
};

export const saveSiteLogo = async (url: string) => {
  const settings = getLocal<any>(SETTINGS_KEY, {});
  settings.logoUrl = url;
  localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  window.dispatchEvent(new Event('logo-change'));
  return Promise.resolve();
};

export const getAnnouncement = async (): Promise<Announcement | null> => {
  const settings = getLocal<any>(SETTINGS_KEY, {});
  return Promise.resolve(settings.announcement || null);
};

export const saveAnnouncement = async (announcement: Announcement) => {
  const settings = getLocal<any>(SETTINGS_KEY, {});
  settings.announcement = announcement;
  setLocal(SETTINGS_KEY, settings);
  return Promise.resolve();
};

// --- BACKUP ---

export const exportAllData = async (): Promise<BackupData> => {
    const songs = await getAllCustomSongs();
    const artists = await getAllCustomArtists();
    const categories = await getCategories();
    return { songs, artists, categories };
};

export const importAllData = async (data: BackupData): Promise<boolean> => {
    try {
        if (!data.songs || !data.artists) return false;
        setLocal(SONGS_KEY, data.songs);
        setLocal(ARTISTS_KEY, data.artists);
        if (data.categories) setLocal(CATEGORIES_KEY, data.categories);
        return true;
    } catch (e) {
        console.error("Import failed", e);
        return false;
    }
};
