  } catch (error) {
    console.error("Logout failed:", error);
  }
};

// Hook to track authentication state
export const useAuth = () => {
  const [currentUser, setCurrentUser] = useState<AdminUser | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        // Fetch custom role and details from Firestore
        const userDoc = await getDoc(doc(db, COLL_USERS, firebaseUser.uid));
        if (userDoc.exists()) {
            const userData = userDoc.data() as AdminUser;
            setCurrentUser(userData);
        } else {
            // Fallback for new users who might not have a doc yet
            setCurrentUser({
                uid: firebaseUser.uid,
                username: firebaseUser.email || '',
                role: 'USER',
                name: firebaseUser.displayName || 'User',
                profilePicture: firebaseUser.photoURL || ''
            });
        }
      } else {
        setCurrentUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  return { user: currentUser, loading, isAuth: !!currentUser };
};

