    // NOTE: This function is tricky in Firebase because auth.currentUser is not always immediately available on page load.
    // Use the useAuth hook for UI rendering. This is best effort.
    const fbUser = auth.currentUser;
    if (!fbUser) return null;

    // We can't synchronously get the role from Firestore here. 
    // We return basic info. If you need role, use the hook.
    return {
        uid: fbUser.uid,
        username: fbUser.email || '',
        role: 'USER', // Default, will be inaccurate for Admins in synchronous calls
        name: fbUser.displayName || '',
        profilePicture: fbUser.photoURL || ''
    };
