    // Update Profile Display Name
    await updateProfile(fbUser, { displayName: name });

    // Create User Document in Firestore with Role
    const newUser: AdminUser = {
        uid: fbUser.uid,
        username: email,
        name: name,
        role: 'USER',
        profilePicture: ''
    };

    await setDoc(doc(db, COLL_USERS, fbUser.uid), newUser);
