import { useState, useEffect } from "react";
import { auth, db } from "../firebaseConfig";
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signOut, 
  onAuthStateChanged,
  User as FirebaseUser,
  updateProfile
} from "firebase/auth";
import { doc, getDoc, setDoc, updateDoc, collection, getDocs, deleteDoc } from "firebase/firestore";

export type UserRole = 'SUPER_ADMIN' | 'ADMIN' | 'USER';

export interface AdminUser {
  uid: string;
  username: string; // This will be email in Firebase
  role: UserRole;
  name?: string;
  profilePicture?: string;
}

const COLL_USERS = 'users';

// --- AUTH ACTIONS ---

export const login = async (email: string, pass: string): Promise<boolean> => {
  try {
    await signInWithEmailAndPassword(auth, email, pass);
    return true;
  } catch (error) {
    console.error("Login failed:", error);
    return false;
  }
};

export const logout = async () => {
  try {
    await signOut(auth);
    window.dispatchEvent(new Event('auth-change'));
  } catch (error) {
    console.error("Logout failed:", error);
  }
};

// Hook to track authentication state
export const useAuth = () => {
  const [currentUser, setCurrentUser] = useState<AdminUser | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        // Fetch custom role and details from Firestore
        const userDoc = await getDoc(doc(db, COLL_USERS, firebaseUser.uid));
        if (userDoc.exists()) {
            const userData = userDoc.data() as AdminUser;
            setCurrentUser(userData);
        } else {
            // Fallback for new users who might not have a doc yet
            setCurrentUser({
                uid: firebaseUser.uid,
                username: firebaseUser.email || '',
                role: 'USER',
                name: firebaseUser.displayName || 'User',
                profilePicture: firebaseUser.photoURL || ''
            });
        }
      } else {
        setCurrentUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  return { user: currentUser, loading, isAuth: !!currentUser };
};

// Helper for non-hook usage (async because we might need to fetch from DB)
export const getCurrentUser = (): AdminUser | null => {
    const fbUser = auth.currentUser;
    if (!fbUser) return null;

    return {
        uid: fbUser.uid,
        username: fbUser.email || '',
        role: 'USER', // Default, will be inaccurate for Admins in synchronous calls
        name: fbUser.displayName || '',
        profilePicture: fbUser.photoURL || ''
    };
};

export const registerUser = async (name: string, email: string, pass: string): Promise<boolean> => {
  try {
    const userCredential = await createUserWithEmailAndPassword(auth, email, pass);
    const fbUser = userCredential.user;

    await updateProfile(fbUser, { displayName: name });

    const newUser: AdminUser = {
        uid: fbUser.uid,
        username: email,
        name: name,
        role: 'USER',
        profilePicture: ''
    };

    await setDoc(doc(db, COLL_USERS, fbUser.uid), newUser);
    return true;
  } catch (error) {
    console.error("Registration error:", error);
    return false;
  }
};

export const updateUser = async (email: string, data: { name?: string; profilePicture?: string }): Promise<boolean> => {
    const fbUser = auth.currentUser;
    if (!fbUser || fbUser.email !== email) return false;

    try {
        if (data.name || data.profilePicture) {
            await updateProfile(fbUser, {
                displayName: data.name || fbUser.displayName,
                photoURL: data.profilePicture || fbUser.photoURL
            });
        }

        await updateDoc(doc(db, COLL_USERS, fbUser.uid), data);
        return true;
    } catch (e) {
        console.error("Update failed", e);
        return false;
    }
};

export const resetPasswordWithRecovery = (username: string, code: string, newPass: string): { success: boolean, message: string } => {
