// Firebase configuration has been removed.
// The application now uses LocalStorage for data persistence.
export const db = null;
export const auth = null;

import { useState, useEffect } from "react";

export type UserRole = 'SUPER_ADMIN' | 'ADMIN' | 'USER';

export interface AdminUser {
  uid: string;
  username: string; // Email
  role: UserRole;
  name?: string;
  profilePicture?: string;
}

const STORAGE_KEY_USERS = 'sp_users';
const STORAGE_KEY_SESSION = 'sp_session';

// Helper to get local users
const getLocalUsers = (): AdminUser[] => {
  const stored = localStorage.getItem(STORAGE_KEY_USERS);
  return stored ? JSON.parse(stored) : [];
};

const saveLocalUsers = (users: AdminUser[]) => {
  localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(users));
};

export const login = async (email: string, pass: string): Promise<boolean> => {
  // Simple mock password check (in real app, hash this!)
  const users = getLocalUsers();
  // We check specifically for the 'password' property which we store insecurely in this local version
  const user = users.find(u => u.username === email && (u as any).password === pass);

  if (user) {
    localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(user));
    window.dispatchEvent(new Event('auth-change'));
    return true;
  }
  return false;
};

export const logout = async () => {
  localStorage.removeItem(STORAGE_KEY_SESSION);
  window.dispatchEvent(new Event('auth-change'));
};

export const useAuth = () => {
  const [currentUser, setCurrentUser] = useState<AdminUser | null>(null);
  const [loading, setLoading] = useState(true);

  const checkAuth = () => {
    const session = localStorage.getItem(STORAGE_KEY_SESSION);
    if (session) {
      setCurrentUser(JSON.parse(session));
    } else {
      setCurrentUser(null);
    }
    setLoading(false);
  };

  useEffect(() => {
    checkAuth();
    window.addEventListener('auth-change', checkAuth);
    return () => window.removeEventListener('auth-change', checkAuth);
  }, []);

  return { user: currentUser, loading, isAuth: !!currentUser };
};

export const getCurrentUser = (): AdminUser | null => {
  const session = localStorage.getItem(STORAGE_KEY_SESSION);
  return session ? JSON.parse(session) : null;
};

export const registerUser = async (name: string, email: string, pass: string): Promise<boolean> => {
  const users = getLocalUsers();

  if (users.some(u => u.username === email)) {
    return false; // User exists
  }

  // First user is Super Admin
  const role: UserRole = users.length === 0 ? 'SUPER_ADMIN' : 'USER';

  const newUser: AdminUser = {
    uid: 'user_' + Date.now(),
    username: email,
    name,
    role,
    profilePicture: ''
  };

  // Store password insecurely for local demo purposes
  (newUser as any).password = pass;

  users.push(newUser);
  saveLocalUsers(users);

  // Auto login
  localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(newUser));
  window.dispatchEvent(new Event('auth-change'));

  return true;
};

export const updateUser = async (email: string, data: { name?: string; profilePicture?: string }): Promise<boolean> => {
  const users = getLocalUsers();
  const idx = users.findIndex(u => u.username === email);

  if (idx === -1) return false;

  const updatedUser = { ...users[idx], ...data };
  // Preserve password
  (updatedUser as any).password = (users[idx] as any).password;

  users[idx] = updatedUser;
  saveLocalUsers(users);

  // Update session if it's the current user
  const currentUser = getCurrentUser();
  if (currentUser && currentUser.username === email) {
      localStorage.setItem(STORAGE_KEY_SESSION, JSON.stringify(updatedUser));
      window.dispatchEvent(new Event('auth-change'));
  }

  return true;
};

// Admin Functions
export const getAdmins = async (): Promise<AdminUser[]> => {
  return getLocalUsers().filter(u => u.role === 'ADMIN' || u.role === 'SUPER_ADMIN');
};

export const getUsers = async (): Promise<AdminUser[]> => {
  return getLocalUsers().filter(u => u.role === 'USER');
};

export const deleteUser = async (username: string) => {
  const users = getLocalUsers();
  const newUsers = users.filter(u => u.username !== username);
  saveLocalUsers(newUsers);
};

export const createAdmin = async (email: string, pass: string): Promise<boolean> => {
    const users = getLocalUsers();
    if (users.some(u => u.username === email)) return false;

    const newUser: AdminUser = {
        uid: 'admin_' + Date.now(),
        username: email,
        role: 'ADMIN',
        name: 'Admin',
        profilePicture: ''
    };
    (newUser as any).password = pass;

    users.push(newUser);
    saveLocalUsers(users);
    return true;
};

export const deleteAdmin = async (username: string) => {
    return deleteUser(username);
};

export const resetPasswordWithRecovery = (username: string, code: string, newPass: string): { success: boolean, message: string } => {
    // Mock implementation for local storage
    const users = getLocalUsers();
    const idx = users.findIndex(u => u.username === username);

    if (idx === -1) {
        return { success: false, message: "User not found." };
    }

    (users[idx] as any).password = newPass;
    saveLocalUsers(users);
    return { success: true, message: "Password updated successfully." };
};

import { LyricsData, ArtistDetails, Banner, Announcement } from '../types';
import { generateId } from './storage';

export interface BackupData {
    songs: any[];
    artists: any[];
    categories: string[];
}

const STORAGE_SONGS = 'sp_songs';
const STORAGE_ARTISTS = 'sp_artists';
const STORAGE_CATEGORIES = 'sp_categories';
const STORAGE_BANNERS = 'sp_banners';
const STORAGE_LOGO = 'sp_logo';
const STORAGE_ANNOUNCEMENT = 'sp_announcement';

// --- HELPERS ---
const getLocal = <T>(key: string, def: T): T => {
    const s = localStorage.getItem(key);
    return s ? JSON.parse(s) : def;
};
const setLocal = (key: string, val: any) => {
    localStorage.setItem(key, JSON.stringify(val));
};

// --- SONGS ---
export const getAllCustomSongs = async (): Promise<any[]> => {
    return getLocal(STORAGE_SONGS, []);
};

export const getCustomSong = async (artist: string, title: string): Promise<any | null> => {
    const songs = getLocal<any[]>(STORAGE_SONGS, []);
    const id = generateId('song', title, artist);
    // Try to find by ID or exact match
    return songs.find(s => s.id === id || (s.title === title && s.artist === artist)) || null;
};

export const saveCustomSong = async (artist: string, title: string, data: LyricsData) => {
    const songs = getLocal<any[]>(STORAGE_SONGS, []);
    const id = generateId('song', title, artist);
    const index = songs.findIndex(s => s.id === id);

    const songData = { ...data, id, title, artist, lastUpdated: Date.now() };

    if (index >= 0) {
        songs[index] = songData;
    } else {
        songs.push(songData);
    }
    setLocal(STORAGE_SONGS, songs);
    window.dispatchEvent(new Event('content-change'));
};

export const deleteCustomSong = async (artist: string, title: string) => {
    const songs = getLocal<any[]>(STORAGE_SONGS, []);
    const id = generateId('song', title, artist);
    const newSongs = songs.filter(s => s.id !== id);
    setLocal(STORAGE_SONGS, newSongs);
    window.dispatchEvent(new Event('content-change'));
};

// --- ARTISTS ---
export const getAllCustomArtists = async (): Promise<any[]> => {
    return getLocal(STORAGE_ARTISTS, []);
};

export const getCustomArtist = async (name: string): Promise<any | null> => {
    const artists = getLocal<any[]>(STORAGE_ARTISTS, []);
    return artists.find(a => a.name.toLowerCase() === name.toLowerCase()) || null;
};

export const saveCustomArtist = async (name: string, data: ArtistDetails) => {
    const artists = getLocal<any[]>(STORAGE_ARTISTS, []);
    const index = artists.findIndex(a => a.name.toLowerCase() === name.toLowerCase());
    const artistData = { ...data, lastUpdated: Date.now() };

    if (index >= 0) {
        artists[index] = artistData;
    } else {
        artists.push(artistData);
    }
    setLocal(STORAGE_ARTISTS, artists);
    window.dispatchEvent(new Event('content-change'));
};

export const deleteCustomArtist = async (name: string) => {
    const artists = getLocal<any[]>(STORAGE_ARTISTS, []);
    const newArtists = artists.filter(a => a.name.toLowerCase() !== name.toLowerCase());
    setLocal(STORAGE_ARTISTS, newArtists);
    window.dispatchEvent(new Event('content-change'));
};

// --- CATEGORIES ---
export const getCategories = async (): Promise<string[]> => {
    return getLocal(STORAGE_CATEGORIES, ['Worship', 'Praise', 'Hymn']);
};

export const addCategory = async (category: string) => {
    const cats = await getCategories();
    if (!cats.includes(category)) {
        cats.push(category);
        setLocal(STORAGE_CATEGORIES, cats);
        window.dispatchEvent(new Event('content-change'));
    }
};

export const updateCategory = async (oldCat: string, newCat: string) => {
    const cats = await getCategories();
    const idx = cats.indexOf(oldCat);
    if (idx >= 0) {
        cats[idx] = newCat;
        setLocal(STORAGE_CATEGORIES, cats);
        window.dispatchEvent(new Event('content-change'));
    }
};

export const deleteCategory = async (category: string) => {
    const cats = await getCategories();
    const newCats = cats.filter(c => c !== category);
    setLocal(STORAGE_CATEGORIES, newCats);
    window.dispatchEvent(new Event('content-change'));
};

// --- BANNERS ---
export const getBanners = async (): Promise<Banner[]> => {
    return getLocal(STORAGE_BANNERS, []);
};

export const saveBanner = async (banner: Banner) => {
    const banners = await getBanners();
    const idx = banners.findIndex(b => b.id === banner.id);
    if (idx >= 0) banners[idx] = banner;
    else banners.push(banner);
    setLocal(STORAGE_BANNERS, banners);
    window.dispatchEvent(new Event('content-change'));
};

export const deleteBanner = async (id: string) => {
    const banners = await getBanners();
    const newBanners = banners.filter(b => b.id !== id);
    setLocal(STORAGE_BANNERS, newBanners);
    window.dispatchEvent(new Event('content-change'));
};

// --- VIEWS ---
export const getViewCount = async (artist: string, title: string): Promise<number> => {
    const song = await getCustomSong(artist, title);
    return song ? (song.views || 0) : 0;
};

export const incrementViewCount = async (artist: string, title: string) => {
    const songs = getLocal<any[]>(STORAGE_SONGS, []);
    const id = generateId('song', title, artist);
    const idx = songs.findIndex(s => s.id === id);
    if (idx >= 0) {
        songs[idx].views = (songs[idx].views || 0) + 1;
        setLocal(STORAGE_SONGS, songs);
    }
};

export const setViewCount = async (artist: string, title: string, count: number) => {
    const songs = getLocal<any[]>(STORAGE_SONGS, []);
    const id = generateId('song', title, artist);
    const idx = songs.findIndex(s => s.id === id);
    if (idx >= 0) {
        songs[idx].views = count;
        setLocal(STORAGE_SONGS, songs);
    }
};

// --- SETTINGS ---
export const getSiteLogo = async (): Promise<string> => {
    return localStorage.getItem(STORAGE_LOGO) || '';
};

export const saveSiteLogo = async (url: string) => {
    localStorage.setItem(STORAGE_LOGO, url);
    window.dispatchEvent(new Event('logo-change'));
};

export const getAnnouncement = async (): Promise<Announcement | null> => {
