};

export const saveAnnouncement = async (announcement: Announcement) => {
    setLocal(STORAGE_ANNOUNCEMENT, announcement);
    window.dispatchEvent(new Event('content-change'));
};

// --- BACKUP ---
export const exportAllData = async (): Promise<BackupData> => {
    return {
        songs: await getAllCustomSongs(),
        artists: await getAllCustomArtists(),
        categories: await getCategories()
    };
};

export const importAllData = async (data: BackupData): Promise<boolean> => {
    try {
        if (data.songs) setLocal(STORAGE_SONGS, data.songs);
        if (data.artists) setLocal(STORAGE_ARTISTS, data.artists);
        if (data.categories) setLocal(STORAGE_CATEGORIES, data.categories);
        window.dispatchEvent(new Event('content-change'));
        return true;
    } catch (e) {
        return false;
    }
};

