Here is the step-by-step guide to connecting your application to Supabase, followed by the code changes required to replace the LocalStorage system with the Supabase SDK.

### Part 1: Supabase Dashboard Setup (Do this first)

1.  **Create Project**: Go to [database.new](https://database.new) and create a new project.
2.  **Get Credentials**: Go to **Project Settings > API**. Copy the **Project URL** and the **anon / public** Key. You will need these for the code below.
3.  **Run SQL Query**: Go to the **SQL Editor** in the left sidebar, paste the following SQL, and click **Run**. This sets up your database structure and security policies.

```sql
-- 1. Create Profiles table (for Roles)
create table profiles (
  id uuid references auth.users on delete cascade not null primary key,
  email text,
  role text default 'USER', -- 'SUPER_ADMIN', 'ADMIN', 'USER'
  name text,
  profile_picture text
);

-- 2. Create Content Tables
create table songs (
  id uuid default gen_random_uuid() primary key,
  title text not null,
  artist text not null,
  artists text[], -- Array of strings
  lyrics_nepali text,
  lyrics_roman text,
  composer text,
  composers text[],
  lyricist text,
  lyricists text[],
  singer text,
  singers text[],
  views bigint default 0,
  category text,
  categories text[],
  youtube_url text,
  is_youtube_visible boolean default true,
  language text default 'nepali',
  created_at timestamptz default now()
);

create table artists (
  id uuid default gen_random_uuid() primary key,
  name text not null unique,
  bio text,
  top_songs text[],
  image_url text,
  facebook_url text,
  instagram_url text,
  youtube_url text,
  is_facebook_visible boolean default true,
  is_instagram_visible boolean default true,
  is_artist_youtube_visible boolean default true,
  created_at timestamptz default now()
);

create table banners (
  id uuid default gen_random_uuid() primary key,
  image_url text not null,
  title text,
  subtitle text,
  link text,
  created_at timestamptz default now()
);

create table categories (
  id uuid default gen_random_uuid() primary key,
  name text unique not null,
  created_at timestamptz default now()
);

create table site_settings (
  key text primary key,
  value jsonb
);

-- 3. Enable Row Level Security (RLS)
alter table profiles enable row level security;
alter table songs enable row level security;
alter table artists enable row level security;
alter table banners enable row level security;
alter table categories enable row level security;
alter table site_settings enable row level security;

-- 4. Create Policies
-- Allow everyone to READ content
create policy "Public songs are viewable by everyone" on songs for select using (true);
create policy "Public artists are viewable by everyone" on artists for select using (true);
create policy "Public banners are viewable by everyone" on banners for select using (true);
create policy "Public categories are viewable by everyone" on categories for select using (true);
create policy "Public settings are viewable by everyone" on site_settings for select using (true);

-- Allow authenticated users to READ profiles
create policy "Users can see own profile" on profiles for select using (auth.uid() = id);

-- Allow Admins to WRITE (Insert/Update/Delete)
-- Note: This is a simplified check. In production, you might want a stricter function.
create policy "Admins can insert songs" on songs for insert with check (exists (select 1 from profiles where id = auth.uid() and role in ('ADMIN', 'SUPER_ADMIN')));
create policy "Admins can update songs" on songs for update using (exists (select 1 from profiles where id = auth.uid() and role in ('ADMIN', 'SUPER_ADMIN')));
create policy "Admins can delete songs" on songs for delete using (exists (select 1 from profiles where id = auth.uid() and role in ('ADMIN', 'SUPER_ADMIN')));

-- Repeat Admin Write policies for Artists, Banners, Categories, Settings...
-- (Shortened for brevity: repeat the logic above for other tables if strict security is needed, 
--  otherwise, for this demo, we will allow authenticated users to write for simplicity, or you can run the full admin checks)

create policy "Enable all access for users based on role" on artists for all using (exists (select 1 from profiles where id = auth.uid() and role in ('ADMIN', 'SUPER_ADMIN')));
create policy "Enable all access for users based on role" on banners for all using (exists (select 1 from profiles where id = auth.uid() and role in ('ADMIN', 'SUPER_ADMIN')));
create policy "Enable all access for users based on role" on categories for all using (exists (select 1 from profiles where id = auth.uid() and role in ('ADMIN', 'SUPER_ADMIN')));
create policy "Enable all access for users based on role" on site_settings for all using (exists (select 1 from profiles where id = auth.uid() and role in ('ADMIN', 'SUPER_ADMIN')));

-- 5. Auto-create profile on signup trigger
create or replace function public.handle_new_user() 
returns trigger as $$
begin
  insert into public.profiles (id, email, name, role)
  values (new.id, new.email, new.raw_user_meta_data->>'name', 'USER');
  return new;
end;
$$ language plpgsql security definer;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();
```

### Part 2: Code Implementation

This will configure the app to talk to Supabase instead of LocalStorage.

**IMPORTANT:** You must replace `YOUR_SUPABASE_URL` and `YOUR_SUPABASE_ANON_KEY` in `supabaseClient.ts` below with the credentials from Step 1.

