import { createClient } from '@supabase/supabase-js';

// REPLACE THESE WITH YOUR ACTUAL SUPABASE CREDENTIALS
const SUPABASE_URL = 'YOUR_SUPABASE_URL';
const SUPABASE_ANON_KEY = 'YOUR_SUPABASE_ANON_KEY';

export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

import { useState, useEffect } from "react";
import { supabase } from "../supabaseClient";

export type UserRole = 'SUPER_ADMIN' | 'ADMIN' | 'USER';

export interface AdminUser {
  uid: string;
  username: string; // Email
  role: UserRole;
  name?: string;
  profilePicture?: string;
}

export const login = async (email: string, pass: string): Promise<boolean> => {
  const { error } = await supabase.auth.signInWithPassword({
    email,
    password: pass,
  });
  if (error) {
    console.error("Login error:", error.message);
    return false;
  }
  window.dispatchEvent(new Event('auth-change'));
  return true;
};

export const logout = async () => {
  await supabase.auth.signOut();
  window.dispatchEvent(new Event('auth-change'));
};

export const useAuth = () => {
  const [currentUser, setCurrentUser] = useState<AdminUser | null>(null);
  const [loading, setLoading] = useState(true);

  const checkAuth = async () => {
    const { data: { session } } = await supabase.auth.getSession();

    if (session?.user) {
      // Fetch profile data including role
      const { data: profile } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', session.user.id)
        .single();

      if (profile) {
        setCurrentUser({
          uid: profile.id,
          username: profile.email,
          role: profile.role || 'USER',
          name: profile.name,
          profilePicture: profile.profile_picture
        });
      }
    } else {
      setCurrentUser(null);
    }
    setLoading(false);
  };

  useEffect(() => {
    checkAuth();

    const { data: authListener } = supabase.auth.onAuthStateChange(() => {
      checkAuth();
    });

    window.addEventListener('auth-change', checkAuth);

    return () => {
      authListener.subscription.unsubscribe();
      window.removeEventListener('auth-change', checkAuth);
    };
  }, []);

  return { user: currentUser, loading, isAuth: !!currentUser };
};

export const getCurrentUser = (): AdminUser | null => {
  // Note: This is synchronous and might return null initially in a fresh page load 
  // before the async checkAuth completes. 
  // In a real app, prefer useAuth hook. This is kept for backward compatibility with existing utils.
  // We can try to grab from local storage token if needed, but for now we return null
  // or simple check.
  return null; 
};

export const registerUser = async (name: string, email: string, pass: string): Promise<boolean> => {
  const { error } = await supabase.auth.signUp({
    email,
    password: pass,
    options: {
      data: {
        name: name,
      },
    },
  });

  if (error) {
    console.error("Signup error:", error.message);
    return false;
  }

  return true;
};

export const updateUser = async (email: string, data: { name?: string; profilePicture?: string }): Promise<boolean> => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return false;

  const updates: any = {};
  if (data.name) updates.name = data.name;
  if (data.profilePicture) updates.profile_picture = data.profilePicture;

  const { error } = await supabase
    .from('profiles')
    .update(updates)
    .eq('id', user.id);

  if (!error) {
    window.dispatchEvent(new Event('auth-change'));
    return true;
  }
  return false;
};

// Admin Functions
export const getAdmins = async (): Promise<AdminUser[]> => {
  const { data } = await supabase
    .from('profiles')
    .select('*')
    .in('role', ['ADMIN', 'SUPER_ADMIN']);

  return (data || []).map((p: any) => ({
    uid: p.id,
    username: p.email,
    role: p.role,
    name: p.name,
    profilePicture: p.profile_picture
  }));
};

export const getUsers = async (): Promise<AdminUser[]> => {
  const { data } = await supabase
    .from('profiles')
    .select('*')
    .eq('role', 'USER');

  return (data || []).map((p: any) => ({
    uid: p.id,
    username: p.email,
    role: p.role,
    name: p.name,
    profilePicture: p.profile_picture
  }));
};

// Note: Supabase Client SDK cannot delete users from auth.users easily without a server-side function.
// We will just delete the profile for now or set role to banned.
// For true deletion, you need a Supabase Edge Function.
export const deleteUser = async (username: string) => {
   // Placeholder: In real Supabase app, use Admin API
   console.log("Delete not fully supported in client-side only mode for:", username);
};

export const createAdmin = async (email: string, pass: string): Promise<boolean> => {
    // Requires Admin privs or Edge Function to set role immediately.
    // For now, register then manually update DB in Supabase Dashboard.
    return registerUser('Admin', email, pass);
};

export const deleteAdmin = async (username: string) => {
    return deleteUser(username);
};

export const resetPasswordWithRecovery = (username: string, code: string, newPass: string): { success: boolean, message: string } => {
    // Supabase handles this differently (via email link).
    // We will trigger a password reset email instead.
    supabase.auth.resetPasswordForEmail(username);
    return { success: true, message: "If account exists, password reset email sent." };
};

import { LyricsData, ArtistDetails, Banner, Announcement } from '../types';
import { supabase } from '../supabaseClient';
import { generateId } from './storage';

export interface BackupData {
    songs: any[];
    artists: any[];
    categories: string[];
}

// --- SONGS ---
export const getAllCustomSongs = async (): Promise<any[]> => {
    const { data, error } = await supabase
        .from('songs')
        .select('*');

    if (error) {
        console.error('Error fetching songs:', error);
        return [];
    }

    // Map snake_case db columns to camelCase app props if necessary, or ensure app uses DB structure.
    // We map DB structure back to app structure
    return data.map((s: any) => ({
        ...s,
        id: s.id, // UUID from DB
        lyrics_nepali: s.lyrics_nepali,
        lyrics_roman: s.lyrics_roman,
        youtubeUrl: s.youtube_url,
        isYoutubeVisible: s.is_youtube_visible,
        // Arrays are natively supported in Supabase/Postgres
        artists: s.artists || [s.artist],
        composers: s.composers || [],
        lyricists: s.lyricists || [],
        singers: s.singers || [],
        categories: s.categories || [s.category]
    }));
};

export const getCustomSong = async (artist: string, title: string): Promise<any | null> => {
    const { data, error } = await supabase
        .from('songs')
        .select('*')
        .ilike('title', title)
        .ilike('artist', artist)
        .maybeSingle();

    if (error || !data) return null;

    return {
        ...data,
        youtubeUrl: data.youtube_url,
        isYoutubeVisible: data.is_youtube_visible,
    };
};

export const saveCustomSong = async (artist: string, title: string, data: LyricsData) => {
    // Check if exists to update or insert
    const existing = await getCustomSong(artist, title);

    const payload = {
        title,
        artist,
        artists: data.artists || [artist],
        lyrics_nepali: data.lyrics_nepali,
        lyrics_roman: data.lyrics_roman,
        composer: data.composer,
        composers: data.composers,
        lyricist: data.lyricist,
        lyricists: data.lyricists,
        singer: data.singer,
        singers: data.singers,
        views: data.views,
        category: data.category,
        categories: data.categories,
        youtube_url: data.youtubeUrl,
        is_youtube_visible: data.isYoutubeVisible,
        language: data.language
    };

    if (existing) {
        await supabase.from('songs').update(payload).eq('id', existing.id);
    } else {
        await supabase.from('songs').insert([payload]);
    }
    window.dispatchEvent(new Event('content-change'));
};

export const deleteCustomSong = async (artist: string, title: string) => {
    const existing = await getCustomSong(artist, title);
    if (existing) {
        await supabase.from('songs').delete().eq('id', existing.id);
        window.dispatchEvent(new Event('content-change'));
    }
};

// --- ARTISTS ---
export const getAllCustomArtists = async (): Promise<any[]> => {
    const { data } = await supabase.from('artists').select('*');
    return (data || []).map((a: any) => ({
        ...a,
        imageUrl: a.image_url,
        topSongs: a.top_songs || [],
        facebookUrl: a.facebook_url,
        instagramUrl: a.instagram_url,
        youtubeUrl: a.youtube_url,
        isFacebookVisible: a.is_facebook_visible,
        isInstagramVisible: a.is_instagram_visible,
        isArtistYoutubeVisible: a.is_artist_youtube_visible
    }));
};

export const getCustomArtist = async (name: string): Promise<any | null> => {
    const { data } = await supabase
        .from('artists')
        .select('*')
        .ilike('name', name)
        .maybeSingle();

    if (!data) return null;

    return {
        ...data,
        imageUrl: data.image_url,
        topSongs: data.top_songs || [],
        facebookUrl: data.facebook_url,
        instagramUrl: data.instagram_url,
        youtubeUrl: data.youtube_url,
        isFacebookVisible: data.is_facebook_visible,
        isInstagramVisible: data.is_instagram_visible,
        isArtistYoutubeVisible: data.is_artist_youtube_visible
    };
};

export const saveCustomArtist = async (name: string, data: ArtistDetails) => {
    const existing = await getCustomArtist(name);

    const payload = {
        name,
        bio: data.bio,
        top_songs: data.topSongs,
        image_url: data.imageUrl,
        facebook_url: data.facebookUrl,
        instagram_url: data.instagramUrl,
        youtube_url: data.youtubeUrl,
        is_facebook_visible: data.isFacebookVisible,
        is_instagram_visible: data.isInstagramVisible,
        is_artist_youtube_visible: data.isArtistYoutubeVisible
    };

    if (existing) {
        await supabase.from('artists').update(payload).eq('id', existing.id);
    } else {
        await supabase.from('artists').insert([payload]);
    }
    window.dispatchEvent(new Event('content-change'));
};

export const deleteCustomArtist = async (name: string) => {
    const existing = await getCustomArtist(name);
    if (existing) {
        await supabase.from('artists').delete().eq('id', existing.id);
        window.dispatchEvent(new Event('content-change'));
    }
};

// --- CATEGORIES ---
export const getCategories = async (): Promise<string[]> => {
    const { data } = await supabase.from('categories').select('name');
    if (!data || data.length === 0) return ['Worship', 'Praise', 'Hymn'];
    return data.map((c: any) => c.name);
};

export const addCategory = async (category: string) => {
    await supabase.from('categories').insert([{ name: category }]);
    window.dispatchEvent(new Event('content-change'));
};

export const updateCategory = async (oldCat: string, newCat: string) => {
    await supabase.from('categories').update({ name: newCat }).eq('name', oldCat);
    window.dispatchEvent(new Event('content-change'));
};

export const deleteCategory = async (category: string) => {
    await supabase.from('categories').delete().eq('name', category);
    window.dispatchEvent(new Event('content-change'));
};

// --- BANNERS ---
export const getBanners = async (): Promise<Banner[]> => {
    const { data } = await supabase.from('banners').select('*');
    return (data || []).map((b: any) => ({
        id: b.id,
        imageUrl: b.image_url,
        title: b.title,
        subtitle: b.subtitle,
        link: b.link
    }));
};

export const saveBanner = async (banner: Banner) => {
    const payload = {
        image_url: banner.imageUrl,
        title: banner.title,
        subtitle: banner.subtitle,
        link: banner.link
    };
    // If ID exists and is UUID, update. If timestamp ID (from localstorage migration), treat as new insert
    if (banner.id && banner.id.length > 20) {
        // Try update
        const { error } = await supabase.from('banners').update(payload).eq('id', banner.id);
        if (error) await supabase.from('banners').insert([payload]);
    } else {
        await supabase.from('banners').insert([payload]);
    }
    window.dispatchEvent(new Event('content-change'));
};

export const deleteBanner = async (id: string) => {
    await supabase.from('banners').delete().eq('id', id);
    window.dispatchEvent(new Event('content-change'));
};

// --- VIEWS ---
export const getViewCount = async (artist: string, title: string): Promise<number> => {
    const song = await getCustomSong(artist, title);
    return song ? (song.views || 0) : 0;
};

export const incrementViewCount = async (artist: string, title: string) => {
    // Supabase RPC is better for atomic increments, but we'll use simple read-write for now
    const song = await getCustomSong(artist, title);
    if (song) {
        await supabase.from('songs').update({ views: (song.views || 0) + 1 }).eq('id', song.id);
    }
};

export const setViewCount = async (artist: string, title: string, count: number) => {
    const song = await getCustomSong(artist, title);
    if (song) {
        await supabase.from('songs').update({ views: count }).eq('id', song.id);
    }
};

// --- SETTINGS ---
export const getSiteLogo = async (): Promise<string> => {
    const { data } = await supabase.from('site_settings').select('value').eq('key', 'site_logo').maybeSingle();
    return data?.value?.url || '';
};

export const saveSiteLogo = async (url: string) => {
    await supabase.from('site_settings').upsert({ key: 'site_logo', value: { url } });
    window.dispatchEvent(new Event('logo-change'));
};

export const getAnnouncement = async (): Promise<Announcement | null> => {
    const { data } = await supabase.from('site_settings').select('value').eq('key', 'announcement').maybeSingle();
    return data?.value || null;
};

export const saveAnnouncement = async (announcement: Announcement) => {
    await supabase.from('site_settings').upsert({ key: 'announcement', value: announcement });
    window.dispatchEvent(new Event('content-change'));
};

// --- BACKUP (Supabase makes this less critical, but good for JSON export) ---
export const exportAllData = async (): Promise<BackupData> => {
    return {
        songs: await getAllCustomSongs(),
        artists: await getAllCustomArtists(),
        categories: await getCategories()
    };
};

export const importAllData = async (data: BackupData): Promise<boolean> => {
    try {
        // Mass Insert - note: this might duplicate if not handled carefully
        if (data.songs) {
            const songs = data.songs.map(s => ({
                title: s.title, artist: s.artist, lyrics_nepali: s.lyrics_nepali || s.lyrics,
                // map other fields...
            }));
            await supabase.from('songs').insert(songs);
        }
        // ... artists, categories
        window.dispatchEvent(new Event('content-change'));
        return true;
    } catch (e) {
        console.error(e);
        return false;
    }
};

import { createClient } from '@supabase/supabase-js';

// REPLACE THESE WITH YOUR ACTUAL SUPABASE CREDENTIALS
// Note: The URL must be a valid URL string (e.g., https://...) to avoid "Invalid URL" errors.
// Go to Supabase Dashboard -> Project Settings -> API to get these.

const SUPABASE_URL = 'https://your-project.supabase.co'; // Changed from 'YOUR_SUPABASE_URL' to a valid URL format
const SUPABASE_ANON_KEY = 'your-anon-key';

export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

// This optional code is used to register a service worker.
// register() is not called by default.

const isLocalhost = Boolean(
  window.location.hostname === 'localhost' ||
    // [::1] is the IPv6 localhost address.
    window.location.hostname === '[::1]' ||
    // 127.0.0.0/8 are considered localhost for IPv4.
    window.location.hostname.match(/^127(?:\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)){3}$/)
);

type Config = {
  onSuccess?: (registration: ServiceWorkerRegistration) => void;
  onUpdate?: (registration: ServiceWorkerRegistration) => void;
};

export function register(config?: Config) {
  if ('serviceWorker' in navigator) {
    // Handle process.env safely
    const publicUrlString = (typeof process !== 'undefined' && process.env && process.env.PUBLIC_URL) || '';
    // Ensure we construct URL correctly relative to current location if publicUrl is relative or empty
    const publicUrl = new URL(publicUrlString, window.location.href);

    if (publicUrl.origin !== window.location.origin) {
      // Our service worker won't work if PUBLIC_URL is on a different origin
      // from what our page is served on. This might happen if a CDN is used to
      // serve assets; see https://github.com/facebook/create-react-app/issues/2374
      return;
    }

    window.addEventListener('load', () => {
      // Construct SW URL safely
      const swPath = publicUrlString ? `${publicUrlString}/service-worker.js` : '/service-worker.js';
      // Clean up double slashes if any
      const swUrl = swPath.replace('//', '/');

      if (isLocalhost) {
        // This is running on localhost. Let's check if a service worker still exists or not.
        checkValidServiceWorker(swUrl, config);
        navigator.serviceWorker.ready.then(() => {
          console.log(
            'This web app is being served cache-first by a service ' +
              'worker. To learn more, visit https://cra.link/PWA'
          );
        });
      } else {
        // Is not localhost. Just register service worker
        registerValidSW(swUrl, config);
      }
    });
  }
}

function registerValidSW(swUrl: string, config?: Config) {
  navigator.serviceWorker
    .register(swUrl)
    .then((registration) => {
      registration.onupdatefound = () => {
        const installingWorker = registration.installing;
        if (installingWorker == null) {
          return;
        }
        installingWorker.onstatechange = () => {
          if (installingWorker.state === 'installed') {
            if (navigator.serviceWorker.controller) {
              // At this point, the updated precached content has been fetched,
              // but the previous service worker will still serve the older
              // content until all client tabs are closed.
              console.log(
                'New content is available and will be used when all ' +
                  'tabs for this page are closed. See https://cra.link/PWA.'
              );

              // Execute callback
              if (config && config.onUpdate) {
                config.onUpdate(registration);
              }
            } else {
              // At this point, everything has been precached.
              // It's the perfect time to display a
              // "Content is cached for offline use." message.
              console.log('Content is cached for offline use.');

              // Execute callback
              if (config && config.onSuccess) {
                config.onSuccess(registration);
              }
            }
          }
        };
      };
    })
    .catch((error) => {
      console.error('Error during service worker registration:', error);
    });
}

function checkValidServiceWorker(swUrl: string, config?: Config) {
  // Check if the service worker can be found. If it can't reload the page.
  fetch(swUrl, { headers: { 'Service-Worker': 'script' } })
    .then((response) => {
      // Ensure service worker exists, and that we really are getting a JS file.
      const contentType = response.headers.get('content-type');
      if (
        response.status === 404 ||
        (contentType != null && contentType.indexOf('javascript') === -1)
      ) {
        // No service worker found. Probably a different app. Reload the page.
        navigator.serviceWorker.ready.then((registration) => {
          registration.unregister().then(() => {
            window.location.reload();
          });
        });
      } else {
        // Service worker found. Proceed as normal.
        registerValidSW(swUrl, config);
      }
    })
    .catch(() => {
      console.log('No internet connection found. App is running in offline mode.');
    });
}

export function unregister() {
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.ready
      .then((registration) => {
        registration.unregister();
      })
      .catch((error) => {
        console.error(error.message);
      });
  }
}

