                                <div className="w-12 h-12 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-4">
                                    <Download className="w-6 h-6" />
                                </div>
                                <h3 className="font-bold text-slate-800 mb-2">Export Data</h3>
                                <p className="text-sm text-slate-500 mb-4">Download all songs, artists, and categories as a JSON file.</p>
                                <button onClick={handleDownloadBackup} className="bg-green-600 text-white px-4 py-2 rounded-lg font-bold hover:bg-green-700 w-full">Download Backup</button>
                            </div>

                            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col items-center text-center">
                                <div className="w-12 h-12 bg-orange-100 text-orange-600 rounded-full flex items-center justify-center mb-4">
                                    <Upload className="w-6 h-6" />
                                </div>
                                <h3 className="font-bold text-slate-800 mb-2">Import Data</h3>
                                <p className="text-sm text-slate-500 mb-4">Restore data from a JSON backup file. <span className="text-red-500 font-bold">Overwrites existing data.</span></p>
                                <label className="bg-orange-600 text-white px-4 py-2 rounded-lg font-bold hover:bg-orange-700 w-full cursor-pointer">
                                    Upload File
                                    <input type="file" ref={fileInputRef} onChange={handleUploadBackup} className="hidden" accept=".json" />
                                </label>
                            </div>
                        </div>
                    </div>
                )}

            </div>
        </div>
      </div>
    </div>
  );
};

