  const handleAddSong = async (e: React.FormEvent) => {
    e.preventDefault();
    const titleClean = songForm.title.trim();
    let artistList = songForm.artists.length > 0 ? songForm.artists : songForm.artist.split(',').map(s => s.trim()).filter(s => s);
    const displayArtist = songForm.artist.trim(); 

    let composerList = songForm.composers.length > 0 ? songForm.composers : songForm.composer.split(',').map(s => s.trim()).filter(s => s);
    const displayComposer = songForm.composer.trim();

    let lyricistList = songForm.lyricists.length > 0 ? songForm.lyricists : songForm.lyricist.split(',').map(s => s.trim()).filter(s => s);
    const displayLyricist = songForm.lyricist.trim();

    let singerList = songForm.singers.length > 0 ? songForm.singers : songForm.singer.split(',').map(s => s.trim()).filter(s => s);
    const displaySinger = songForm.singer.trim();

    if (artistList.length === 0 && !displayArtist) return;
    if (artistList.length === 0) artistList = [displayArtist];

    if (composerList.length === 0 && !displayComposer) composerList = [];
    if (lyricistList.length === 0 && !displayLyricist) lyricistList = [];
    if (singerList.length === 0 && !displaySinger) singerList = [];

    if (!titleClean) return;

    await saveCustomSong(displayArtist, titleClean, {
        lyrics_nepali: songForm.lyrics_nepali,
        lyrics_roman: songForm.lyrics_roman,
        composer: displayComposer || 'Unknown',
