  const { user, isAuth, loading: authLoading } = useAuth();
  const navigate = useNavigate();
  const userRole = user?.role;
  const isSuperAdmin = userRole === 'SUPER_ADMIN';
  const isRegularUser = userRole === 'USER';

  const [activeTab, setActiveTab] = useState<'songs' | 'artists' | 'banners' | 'categories' | 'admins' | 'users' | 'backup' | 'settings' | 'addSong' | 'addArtist' | 'addBanner' | 'announcement'>('songs');
  const [customSongs, setCustomSongs] = useState<any[]>([]);
  const [customArtists, setCustomArtists] = useState<any[]>([]);
  const [banners, setBanners] = useState<Banner[]>([]);
  const [categories, setCategories] = useState<string[]>([]);
  const [adminUsers, setAdminUsers] = useState<AdminUser[]>([]);
  const [regularUsers, setRegularUsers] = useState<AdminUser[]>([]);
  const [announcement, setAnnouncement] = useState<Announcement>({ imageUrl: '', link: '', isVisible: false });

  // Form States
  const [songForm, setSongForm] = useState({ 
      title: '', 
      artist: '', 
      artists: [] as string[], 
      lyrics_nepali: '', lyrics_roman: '', 
      composer: '', composers: [] as string[], 
      lyricist: '', lyricists: [] as string[], 
      singer: '', singers: [] as string[], 
      views: 0, artist_bio: '', categories: [] as string[],
      youtubeUrl: '', isYoutubeVisible: true,
      language: 'nepali' as 'nepali' | 'hindi' | 'english'
  });
  const [artistForm, setArtistForm] = useState({ 
      name: '', bio: '', topSongs: '', imageUrl: '', 
      facebookUrl: '', instagramUrl: '', youtubeUrl: '',
      isFacebookVisible: true, isInstagramVisible: true, isArtistYoutubeVisible: true
  });
  const [bannerForm, setBannerForm] = useState({ imageUrl: '', title: '', subtitle: '', link: '' });
  const [categoryForm, setCategoryForm] = useState('');
  const [newAdminForm, setNewAdminForm] = useState({ username: '', password: '' });
  const [adminError, setAdminError] = useState('');
  const [siteLogo, setSiteLogo] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null); 
  const bannerUploadRef = useRef<HTMLInputElement>(null); 

  // Edit Category State
  const [editingCategory, setEditingCategory] = useState<{original: string, current: string} | null>(null);

  // Autocomplete State
  const [artistInput, setArtistInput] = useState('');

  const [filteredArtists, setFilteredArtists] = useState<{name: string, imageUrl?: string}[]>([]);

  useEffect(() => {
    if (!authLoading) {
      if (!isAuth) {
        navigate('/login');
      } else if (isRegularUser) {
        // Just in case, if they are user, they can't be here
      } else {
        refreshData();
      }
    }
  }, [isAuth, isRegularUser, authLoading, navigate]);

  const refreshData = async () => {
    setCustomSongs(await getAllCustomSongs());
    setCustomArtists(await getAllCustomArtists());
    setBanners(await getBanners());
    setCategories(await getCategories());
    setSiteLogo(await getSiteLogo());

    const ann = await getAnnouncement();
    if (ann) setAnnouncement(ann);

    if (isSuperAdmin) {
        setAdminUsers(await getAdmins());
        setRegularUsers(await getUsers());
    }
  };

  const filterSuggestions = (query: string) => {
      if (!query) return [];
      return customArtists.filter(a => a.name.toLowerCase().includes(query.toLowerCase()));
  };

  useEffect(() => {
    setFilteredArtists(filterSuggestions(artistInput));
  }, [artistInput, customArtists]);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const ensureArtistProfile = async (artistName: string, songTitle: string, bio?: string) => {
      const cleanName = artistName.trim();
      if (!cleanName || cleanName.toLowerCase() === 'unknown') return;

      const existingArtist = await getCustomArtist(cleanName);
      const currentSongs = existingArtist?.topSongs || [];

      let updatedSongs = [...currentSongs];
      if (!updatedSongs.includes(songTitle)) {
          updatedSongs.push(songTitle);
      }

      saveCustomArtist(cleanName, {
          name: cleanName,
          bio: bio || existingArtist?.bio || '',
          topSongs: updatedSongs,
          imageUrl: existingArtist?.imageUrl || '',
          facebookUrl: existingArtist?.facebookUrl || '',
          instagramUrl: existingArtist?.instagramUrl || '',
          youtubeUrl: existingArtist?.youtubeUrl || '',
          isFacebookVisible: existingArtist?.isFacebookVisible ?? true,
          isInstagramVisible: existingArtist?.isInstagramVisible ?? true,
          isArtistYoutubeVisible: existingArtist?.isArtistYoutubeVisible ?? true
      });
  };

  const handleAddSong = async (e: React.FormEvent) => {
    e.preventDefault();
    const titleClean = songForm.title.trim();
    let artistList = songForm.artists.length > 0 ? songForm.artists : songForm.artist.split(',').map(s => s.trim()).filter(s => s);
    const displayArtist = songForm.artist.trim(); 

    let composerList = songForm.composers.length > 0 ? songForm.composers : songForm.composer.split(',').map(s => s.trim()).filter(s => s);
    const displayComposer = songForm.composer.trim();

    let lyricistList = songForm.lyricists.length > 0 ? songForm.lyricists : songForm.lyricist.split(',').map(s => s.trim()).filter(s => s);
    const displayLyricist = songForm.lyricist.trim();

    let singerList = songForm.singers.length > 0 ? songForm.singers : songForm.singer.split(',').map(s => s.trim()).filter(s => s);
    const displaySinger = songForm.singer.trim();

    if (artistList.length === 0 && !displayArtist) return;
    if (artistList.length === 0) artistList = [displayArtist];

    if (composerList.length === 0 && !displayComposer) composerList = [];
    if (lyricistList.length === 0 && !displayLyricist) lyricistList = [];
    if (singerList.length === 0 && !displaySinger) singerList = [];

    if (!titleClean) return;

    await saveCustomSong(displayArtist, titleClean, {
        lyrics_nepali: songForm.lyrics_nepali,
        lyrics_roman: songForm.lyrics_roman,
        composer: displayComposer || 'Unknown',
        composers: composerList,
        lyricist: displayLyricist || 'Unknown',
        lyricists: lyricistList,
        singer: displaySinger,
        singers: singerList,
        views: songForm.views,
        categories: songForm.categories.length > 0 ? songForm.categories : ['Worship'],
        youtubeUrl: songForm.youtubeUrl.trim(),
        isYoutubeVisible: songForm.isYoutubeVisible,
        artists: artistList,
        language: songForm.language
    });

    for (const art of artistList) {
        await ensureArtistProfile(art, titleClean, songForm.artist_bio);
    }
    // ... [Rest of update logic] ...

    setSongForm({ 
        title: '', artist: '', artists: [], lyrics_nepali: '', lyrics_roman: '', 
        composer: '', composers: [], lyricist: '', lyricists: [], singer: '', singers: [],
        views: 0, artist_bio: '', categories: [],
        youtubeUrl: '', isYoutubeVisible: true,
        language: 'nepali'
    });
    setArtistInput('');
    setActiveTab('songs');
    refreshData();
  };

  const handleAddArtist = (e: React.FormEvent) => {
    e.preventDefault();
    const nameClean = artistForm.name.trim();
    if (!nameClean) return;

    saveCustomArtist(nameClean, {
        name: nameClean,
        bio: artistForm.bio,
        topSongs: artistForm.topSongs.split(',').map(s => s.trim()).filter(s => s),
        imageUrl: artistForm.imageUrl.trim(),
        facebookUrl: artistForm.facebookUrl.trim(),
        instagramUrl: artistForm.instagramUrl.trim(),
        youtubeUrl: artistForm.youtubeUrl.trim(),
        isFacebookVisible: artistForm.isFacebookVisible,
        isInstagramVisible: artistForm.isInstagramVisible,
        isArtistYoutubeVisible: artistForm.isArtistYoutubeVisible
    });
    setArtistForm({ 
        name: '', bio: '', topSongs: '', imageUrl: '', 
        facebookUrl: '', instagramUrl: '', youtubeUrl: '',
        isFacebookVisible: true, isInstagramVisible: true, isArtistYoutubeVisible: true
    });
    setActiveTab('artists');
    refreshData();
  };

  const handleAddBanner = (e: React.FormEvent) => {
    e.preventDefault();
    const id = Date.now().toString();
    saveBanner({
        id,
        imageUrl: bannerForm.imageUrl || `https://picsum.photos/seed/${id}/1200/400`,
        title: bannerForm.title || 'Verse Content',
        subtitle: bannerForm.subtitle || 'Reference',
        link: bannerForm.link
    });
    setBannerForm({ imageUrl: '', title: '', subtitle: '', link: '' });
    setActiveTab('banners');
    refreshData();
  };

  const handleAddCategory = (e: React.FormEvent) => {
    e.preventDefault();
    if (categoryForm.trim()) {
      addCategory(categoryForm.trim());
      setCategoryForm('');
      refreshData();
    }
  };

  const handleBannerFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { 
        alert("File size too large. Please upload an image under 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setBannerForm(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdateCategory = () => {
    if (editingCategory && editingCategory.current.trim()) {
      updateCategory(editingCategory.original, editingCategory.current.trim());
      setEditingCategory(null);
      refreshData();
    }
  };

  const handleDeleteSong = (artist: string, title: string) => {
    if (window.confirm('Delete this custom song?')) {
        deleteCustomSong(artist, title);
        refreshData();
    }
  };

  const handleDeleteArtist = (name: string) => {
    if (window.confirm('Delete this custom artist?')) {
        deleteCustomArtist(name);
        refreshData();
    }
  };

  const handleDeleteBanner = (id: string) => {
    if (window.confirm('Delete this banner?')) {
        deleteBanner(id);
        refreshData();
    }
  };

  const handleDeleteCategory = (cat: string) => {
    if (window.confirm(`Delete category "${cat}"?`)) {
        deleteCategory(cat);
        refreshData();
    }
  };

  const handleDeleteAdmin = async (username: string) => {
    if (window.confirm(`Are you sure you want to remove admin access for ${username}?`)) {
        await deleteAdmin(username);
        refreshData();
    }
  };

  const handleDeleteUser = async (username: string) => {
    if (window.confirm(`Are you sure you want to delete user ${username}?`)) {
        await deleteUser(username);
        refreshData();
    }
  };

  const handleSaveSettings = (e: React.FormEvent) => {
      e.preventDefault();
      saveSiteLogo(siteLogo);
      alert('Site settings saved successfully!');
  };

  const handleSaveAnnouncement = (e: React.FormEvent) => {
      e.preventDefault();
      saveAnnouncement(announcement);
      alert('Announcement updated successfully!');
  };

  const handleUploadBackup = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (!file) return;

      if (window.confirm("WARNING: Importing data will overwrite your current songs, artists, and categories. This cannot be undone. Are you sure?")) {
          const reader = new FileReader();
          reader.onload = async (e) => {
              try {
                  const json = JSON.parse(e.target?.result as string) as BackupData;
                  if (await importAllData(json)) {
                      alert("Backup restored successfully! The page will now reload.");
                      window.location.reload();
                  } else {
                      alert("Failed to restore backup. Invalid file format.");
                  }
              } catch (error) {
                  console.error(error);
                  alert("Error parsing backup file.");
              }
          };
          reader.readAsText(file);
      }

      if (fileInputRef.current) {
          fileInputRef.current.value = '';
      }
  };

  const handleDownloadBackup = async () => {
      const data = await exportAllData();
      const jsonString = JSON.stringify(data, null, 2);
      const blob = new Blob([jsonString], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `sansarplus_backup_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
  };

  // --- RENDERING ---

  if (authLoading) {
      return <Loader fullScreen text="Verifying admin credentials..." />;
  }

  if (isRegularUser) {
      return (
          <div className="min-h-screen flex items-center justify-center bg-red-50 p-4 text-center">
              <div className="max-w-md">
                  <AlertTriangle className="w-16 h-16 text-red-500 mx-auto mb-4" />
                  <h1 className="text-2xl font-bold text-red-700">Access Denied</h1>
                  <p className="text-red-600 mb-6">You do not have permission to view the Admin Dashboard.</p>
                  <Link to="/" className="bg-red-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-red-700">Return Home</Link>
              </div>
          </div>
      );
  }

  const getSongColorClass = (lang: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-800';
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <div className="bg-slate-900 text-white py-8 px-4">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
            <div>
                <h1 className="text-3xl font-bold flex items-center">
                    Admin Dashboard
                    {isSuperAdmin && <span className="ml-3 text-xs bg-yellow-500 text-black px-2 py-1 rounded font-bold uppercase tracking-wider">Super Admin</span>}
                </h1>
                <p className="text-slate-400">Manage custom content</p>
            </div>
            <button onClick={handleLogout} className="flex items-center text-red-400 hover:text-red-300">
                <LogOut className="w-5 h-5 mr-2" /> Logout
            </button>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 -mt-8">
        <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden min-h-[500px] flex flex-col md:flex-row">
            {/* Sidebar */}
            <div className="w-full md:w-64 bg-slate-50 md:border-r border-b md:border-b-0 border-slate-200 p-2 md:p-4 flex md:flex-col overflow-x-auto md:overflow-visible space-x-2 md:space-x-0 md:space-y-2 no-scrollbar">

                <p className="hidden md:block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 px-2">Content</p>

                <button onClick={() => setActiveTab('songs')} className={`flex-shrink-0 md:w-full flex items-center justify-between p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'songs' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}>
                    <span className="flex items-center"><Music className="w-4 h-4 mr-2" /> Custom Songs</span>
                    <span className="text-xs bg-white px-2 py-0.5 rounded-full border border-slate-200 ml-2">{customSongs.length}</span>
                </button>
                <button onClick={() => setActiveTab('artists')} className={`flex-shrink-0 md:w-full flex items-center justify-between p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'artists' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}>
                     <span className="flex items-center"><User className="w-4 h-4 mr-2" /> Custom Artists</span>
                     <span className="text-xs bg-white px-2 py-0.5 rounded-full border border-slate-200 ml-2">{customArtists.length}</span>
                </button>
                <button onClick={() => setActiveTab('banners')} className={`flex-shrink-0 md:w-full flex items-center justify-between p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'banners' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}>
                     <span className="flex items-center"><BannerIcon className="w-4 h-4 mr-2" /> Banners</span>
                     <span className="text-xs bg-white px-2 py-0.5 rounded-full border border-slate-200 ml-2">{banners.length}</span>
                </button>
                <button onClick={() => setActiveTab('announcement')} className={`flex-shrink-0 md:w-full flex items-center justify-between p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'announcement' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}>
                     <span className="flex items-center"><Megaphone className="w-4 h-4 mr-2" /> Announcement</span>
                </button>
                <button onClick={() => setActiveTab('categories')} className={`flex-shrink-0 md:w-full flex items-center justify-between p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'categories' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}>
                     <span className="flex items-center"><Grid className="w-4 h-4 mr-2" /> Categories</span>
                     <span className="text-xs bg-white px-2 py-0.5 rounded-full border border-slate-200 ml-2">{categories.length}</span>
                </button>

                {isSuperAdmin && (
                    <>
                        <p className="hidden md:block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 px-2 mt-6 text-yellow-600">Super Admin</p>
                        <button onClick={() => setActiveTab('admins')} className={`flex-shrink-0 md:w-full flex items-center justify-between p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'admins' ? 'bg-yellow-100 text-yellow-800' : 'text-slate-600 hover:bg-slate-100'}`}>
                            <span className="flex items-center"><Shield className="w-4 h-4 mr-2" /> Admins</span>
                        </button>
                         <button onClick={() => setActiveTab('users')} className={`flex-shrink-0 md:w-full flex items-center justify-between p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'users' ? 'bg-purple-100 text-purple-800' : 'text-slate-600 hover:bg-slate-100'}`}>
                            <span className="flex items-center"><Users className="w-4 h-4 mr-2" /> Users</span>
                        </button>
                         <button onClick={() => setActiveTab('settings')} className={`flex-shrink-0 md:w-full flex items-center justify-between p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'settings' ? 'bg-gray-200 text-gray-800' : 'text-slate-600 hover:bg-slate-100'}`}>
                            <span className="flex items-center"><Settings className="w-4 h-4 mr-2" /> Settings</span>
                        </button>
                         <button onClick={() => setActiveTab('backup')} className={`flex-shrink-0 md:w-full flex items-center justify-between p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'backup' ? 'bg-blue-100 text-blue-800' : 'text-slate-600 hover:bg-slate-100'}`}>
                            <span className="flex items-center"><Database className="w-4 h-4 mr-2" /> Backup</span>
                        </button>
                    </>
                )}

                <p className="hidden md:block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 px-2 mt-6">Actions</p>
                <button onClick={() => setActiveTab('addSong')} className={`flex-shrink-0 md:w-full flex items-center p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'addSong' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}>
                    <Plus className="w-4 h-4 mr-2" /> Song
                </button>
                 <button onClick={() => setActiveTab('addArtist')} className={`flex-shrink-0 md:w-full flex items-center p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'addArtist' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}>
                    <Plus className="w-4 h-4 mr-2" /> Artist
                </button>
                <button onClick={() => setActiveTab('addBanner')} className={`flex-shrink-0 md:w-full flex items-center p-2 md:p-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${activeTab === 'addBanner' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}>
                    <Plus className="w-4 h-4 mr-2" /> Banner
                </button>
            </div>

            {/* Main Content */}
            <div className="flex-1 p-6 md:p-8 overflow-y-auto max-h-[800px]">

                {activeTab === 'songs' && (
                    <div className="space-y-4">
                        <h2 className="text-xl font-bold text-slate-800">Custom Songs</h2>
                        {customSongs.length === 0 ? <p className="text-slate-500 italic">No custom songs added yet.</p> : (
                            <div className="grid gap-3">
                                {customSongs.map(song => (
                                    <div key={song.id} className="flex items-center justify-between p-4 border border-slate-200 rounded-lg hover:border-primary/30 bg-white">
                                        <div>
                                            <h3 className={`font-bold ${getSongColorClass(song.language)}`}>{song.title}</h3>
                                            <p className="text-sm text-slate-500">{song.artist}</p>
                                        </div>
                                        <div className="flex space-x-2">
                                            <Link to={`/lyrics/${encodeURIComponent(song.artist)}/${encodeURIComponent(song.title)}`} className="p-2 text-slate-400 hover:text-primary"><Edit2 className="w-4 h-4" /></Link>
                                            <button onClick={() => handleDeleteSong(song.artist, song.title)} className="p-2 text-slate-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {/* ... other tabs ... */}
                 {activeTab === 'artists' && (
                        <div className="space-y-4">
                            <h2 className="text-xl font-bold text-slate-800">Custom Artists</h2>
                            {customArtists.length === 0 ? <p className="text-slate-500 italic">No custom artists added yet.</p> : (
                                <div className="grid gap-3">
                                    {customArtists.map(artist => (
                                        <div key={artist.id} className="flex items-center justify-between p-4 border border-slate-200 rounded-lg hover:border-primary/30 bg-white">
                                            <div className="flex items-center">
                                                {artist.imageUrl ? <img src={artist.imageUrl} alt={artist.name} className="w-10 h-10 rounded-full mr-3 object-cover border border-slate-200" /> : <div className="w-10 h-10 rounded-full mr-3 bg-slate-100 flex items-center justify-center text-slate-400"><User className="w-5 h-5" /></div>}
                                                <div>
                                                    <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                                        {artist.name}
                                                        {!artist.isRegistered && (
                                                            <span className="text-[10px] bg-indigo-50 text-indigo-500 px-2 py-0.5 rounded-full border border-indigo-100 font-normal">Credit Only</span>
                                                        )}
                                                    </h3>
                                                </div>
                                            </div>
                                            <div className="flex space-x-2">
                                                <Link to={`/artist/${encodeURIComponent(artist.name)}`} className="p-2 text-slate-400 hover:text-primary"><Edit2 className="w-4 h-4" /></Link>
                                                {artist.isRegistered && (
                                                    <button onClick={() => handleDeleteArtist(artist.name)} className="p-2 text-slate-400 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                )}

                {/* ... banners, announcement, categories ... */}
                {activeTab === 'banners' && (
                        <div className="space-y-4">
                            <h2 className="text-xl font-bold text-slate-800">Banners</h2>
                             {banners.length === 0 ? <p className="text-slate-500 italic">No banners active.</p> : (
                                <div className="grid gap-4">
                                    {banners.map(banner => (
                                        <div key={banner.id} className="relative aspect-video rounded-lg overflow-hidden group">
                                            <img src={banner.imageUrl} alt={banner.title} className="w-full h-full object-cover" />
                                            <div className="absolute inset-0 bg-black/40 flex flex-col justify-end p-4">
                                                <h3 className="text-white font-bold">{banner.title}</h3>
                                                <p className="text-white/80 text-sm">{banner.subtitle}</p>
                                            </div>
                                            <button onClick={() => handleDeleteBanner(banner.id)} className="absolute top-2 right-2 bg-red-500 text-white p-2 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 className="w-4 h-4" /></button>
                                        </div>
                                    ))}
                                </div>
