import { LyricsData, ArtistDetails, Banner, Announcement } from '../types';
import { supabase } from '../supabaseClient';
import { generateId } from './storage';

export interface BackupData {
    songs: any[];
    artists: any[];
    categories: string[];
}

// --- SONGS ---
export const getAllCustomSongs = async (): Promise<any[]> => {
    const { data, error } = await supabase
        .from('songs')
        .select('*');

    if (error) {
        console.error('Error fetching songs:', error);
        return [];
    }

    // Map snake_case db columns to camelCase app props if necessary, or ensure app uses DB structure.
    // We map DB structure back to app structure
    return data.map((s: any) => ({
        ...s,
        id: s.id, // UUID from DB
        lyrics_nepali: s.lyrics_nepali,
        lyrics_roman: s.lyrics_roman,
        youtubeUrl: s.youtube_url,
        isYoutubeVisible: s.is_youtube_visible,
        // Arrays are natively supported in Supabase/Postgres
        artists: s.artists || [s.artist],
        composers: s.composers || [],
        lyricists: s.lyricists || [],
        singers: s.singers || [],
        categories: s.categories || [s.category]
    }));
};

export const getCustomSong = async (artist: string, title: string): Promise<any | null> => {
    const { data, error } = await supabase
        .from('songs')
        .select('*')
        .ilike('title', title)
        .ilike('artist', artist)
        .maybeSingle();

    if (error || !data) return null;

    return {
        ...data,
        youtubeUrl: data.youtube_url,
        isYoutubeVisible: data.is_youtube_visible,
    };
};

export const saveCustomSong = async (artist: string, title: string, data: LyricsData) => {
    // Check if exists to update or insert
    const existing = await getCustomSong(artist, title);

    const payload = {
        title,
        artist,
        artists: data.artists || [artist],
        lyrics_nepali: data.lyrics_nepali,
        lyrics_roman: data.lyrics_roman,
        composer: data.composer,
        composers: data.composers,
        lyricist: data.lyricist,
        lyricists: data.lyricists,
        singer: data.singer,
        singers: data.singers,
        views: data.views,
        category: data.category,
        categories: data.categories,
        youtube_url: data.youtubeUrl,
        is_youtube_visible: data.isYoutubeVisible,
        language: data.language
    };

    if (existing) {
        await supabase.from('songs').update(payload).eq('id', existing.id);
    } else {
        await supabase.from('songs').insert([payload]);
    }
    window.dispatchEvent(new Event('content-change'));
};

export const deleteCustomSong = async (artist: string, title: string) => {
    const existing = await getCustomSong(artist, title);
    if (existing) {
        await supabase.from('songs').delete().eq('id', existing.id);
        window.dispatchEvent(new Event('content-change'));
    }
};

// --- ARTISTS ---
export const getAllCustomArtists = async (): Promise<any[]> => {
    // 1. Fetch Registered Artists (Manually created with profiles)
    const { data: dbData } = await supabase.from('artists').select('*');
    const dbArtists = (dbData || []).map((a: any) => ({
        ...a,
        imageUrl: a.image_url,
        topSongs: a.top_songs || [],
        facebookUrl: a.facebook_url,
        instagramUrl: a.instagram_url,
        youtubeUrl: a.youtube_url,
        isFacebookVisible: a.is_facebook_visible,
        isInstagramVisible: a.is_instagram_visible,
        isArtistYoutubeVisible: a.is_artist_youtube_visible,
        isRegistered: true // Flag to distinguish in Admin Dashboard
    }));

    // 2. Fetch Songs to find "Implied" Artists (Composers/Lyricists without profiles)
    const { data: songs } = await supabase
        .from('songs')
        .select('artist, artists, composers, lyricists, singers, composer, lyricist, singer');

    // Set of names that already have a full profile
    const registeredNames = new Set(dbArtists.map((a: any) => a.name.toLowerCase()));
    const virtualMap = new Map<string, any>();

    const processName = (rawName: any) => {
        if (!rawName) return;
        const name = String(rawName).trim();
        if (!name || name.toLowerCase() === 'unknown') return;

        // Skip if this person already has a registered profile
        if (registeredNames.has(name.toLowerCase())) return;

        // If not already in our virtual list, add them
        const lower = name.toLowerCase();
        if (!virtualMap.has(lower)) {
            virtualMap.set(lower, {
                id: `virtual-${lower}`,
                name: name, // Preserve original casing of first occurrence
                imageUrl: '',
                topSongs: [],
                isRegistered: false // Flag: "Credit Only"
            });
        }
    };

    songs?.forEach((s: any) => {
        // Handle Arrays (New Standard)
        if (Array.isArray(s.artists)) s.artists.forEach(processName);
        if (Array.isArray(s.composers)) s.composers.forEach(processName);
        if (Array.isArray(s.lyricists)) s.lyricists.forEach(processName);
        if (Array.isArray(s.singers)) s.singers.forEach(processName);

        // Handle Strings/Legacy
        processName(s.artist);
        if ((!s.composers || s.composers.length === 0) && s.composer) s.composer.split(',').forEach(processName);
        if ((!s.lyricists || s.lyricists.length === 0) && s.lyricist) s.lyricist.split(',').forEach(processName);
        if ((!s.singers || s.singers.length === 0) && s.singer) s.singer.split(',').forEach(processName);
    });

    const virtualArtists = Array.from(virtualMap.values());

    // 3. Merge, Filter Unknowns, and Sort Alphabetically
    return [...dbArtists, ...virtualArtists]
        .filter(a => a.name.toLowerCase() !== 'unknown')
        .sort((a, b) => a.name.localeCompare(b.name));
};

export const getCustomArtist = async (name: string): Promise<any | null> => {
    const { data } = await supabase
        .from('artists')
        .select('*')
        .ilike('name', name)
        .maybeSingle();

    if (!data) return null;

    return {
        ...data,
        imageUrl: data.image_url,
        topSongs: data.top_songs || [],
        facebookUrl: data.facebook_url,
        instagramUrl: data.instagram_url,
        youtubeUrl: data.youtube_url,
        isFacebookVisible: data.is_facebook_visible,
        isInstagramVisible: data.is_instagram_visible,
        isArtistYoutubeVisible: data.is_artist_youtube_visible
    };
};

export const saveCustomArtist = async (name: string, data: ArtistDetails) => {
    const existing = await getCustomArtist(name);

    const payload = {
        name,
        bio: data.bio,
        top_songs: data.topSongs,
        image_url: data.imageUrl,
        facebook_url: data.facebookUrl,
        instagram_url: data.instagramUrl,
        youtube_url: data.youtubeUrl,
        is_facebook_visible: data.isFacebookVisible,
        is_instagram_visible: data.isInstagramVisible,
        is_artist_youtube_visible: data.isArtistYoutubeVisible
    };

    if (existing) {
        await supabase.from('artists').update(payload).eq('id', existing.id);
    } else {
        await supabase.from('artists').insert([payload]);
    }
    window.dispatchEvent(new Event('content-change'));
};

export const deleteCustomArtist = async (name: string) => {
    const existing = await getCustomArtist(name);
    if (existing) {
        await supabase.from('artists').delete().eq('id', existing.id);
        window.dispatchEvent(new Event('content-change'));
    }
};

// --- CATEGORIES ---
export const getCategories = async (): Promise<string[]> => {
    const { data } = await supabase.from('categories').select('name');
    if (!data || data.length === 0) return ['Worship', 'Praise', 'Hymn'];
    return data.map((c: any) => c.name);
};

export const addCategory = async (category: string) => {
    await supabase.from('categories').insert([{ name: category }]);
    window.dispatchEvent(new Event('content-change'));
};

export const updateCategory = async (oldCat: string, newCat: string) => {
    await supabase.from('categories').update({ name: newCat }).eq('name', oldCat);
    window.dispatchEvent(new Event('content-change'));
};

export const deleteCategory = async (category: string) => {
    await supabase.from('categories').delete().eq('name', category);
    window.dispatchEvent(new Event('content-change'));
};

// --- BANNERS ---
export const getBanners = async (): Promise<Banner[]> => {
    const { data } = await supabase.from('banners').select('*');
    return (data || []).map((b: any) => ({
        id: b.id,
        imageUrl: b.image_url,
        title: b.title,
        subtitle: b.subtitle,
        link: b.link
    }));
};

export const saveBanner = async (banner: Banner) => {
    const payload = {
        image_url: banner.imageUrl,
        title: banner.title,
        subtitle: banner.subtitle,
        link: banner.link
    };
    // If ID exists and is UUID, update. If timestamp ID (from localstorage migration), treat as new insert
    if (banner.id && banner.id.length > 20) {
        // Try update
        const { error } = await supabase.from('banners').update(payload).eq('id', banner.id);
        if (error) await supabase.from('banners').insert([payload]);
    } else {
        await supabase.from('banners').insert([payload]);
    }
    window.dispatchEvent(new Event('content-change'));
};

export const deleteBanner = async (id: string) => {
    await supabase.from('banners').delete().eq('id', id);
    window.dispatchEvent(new Event('content-change'));
};

// --- VIEWS ---
export const getViewCount = async (artist: string, title: string): Promise<number> => {
    const song = await getCustomSong(artist, title);
    return song ? (song.views || 0) : 0;
};

export const incrementViewCount = async (artist: string, title: string) => {
    // Supabase RPC is better for atomic increments, but we'll use simple read-write for now
    const song = await getCustomSong(artist, title);
    if (song) {
        await supabase.from('songs').update({ views: (song.views || 0) + 1 }).eq('id', song.id);
    }
};

export const setViewCount = async (artist: string, title: string, count: number) => {
    const song = await getCustomSong(artist, title);
    if (song) {
        await supabase.from('songs').update({ views: count }).eq('id', song.id);
    }
};

// --- SETTINGS ---
export const getSiteLogo = async (): Promise<string> => {
    const { data } = await supabase.from('site_settings').select('value').eq('key', 'site_logo').maybeSingle();
    return data?.value?.url || '';
};

export const saveSiteLogo = async (url: string) => {
    await supabase.from('site_settings').upsert({ key: 'site_logo', value: { url } });
    window.dispatchEvent(new Event('logo-change'));
};

export const getAnnouncement = async (): Promise<Announcement | null> => {
    const { data } = await supabase.from('site_settings').select('value').eq('key', 'announcement').maybeSingle();
    return data?.value || null;
};

export const saveAnnouncement = async (announcement: Announcement) => {
    await supabase.from('site_settings').upsert({ key: 'announcement', value: announcement });
    window.dispatchEvent(new Event('content-change'));
};

// --- BACKUP (Supabase makes this less critical, but good for JSON export) ---
export const exportAllData = async (): Promise<BackupData> => {
    return {
        songs: await getAllCustomSongs(),
        artists: await getAllCustomArtists(),
        categories: await getCategories()
    };
};

export const importAllData = async (data: BackupData): Promise<boolean> => {
    try {
        // Mass Insert - note: this might duplicate if not handled carefully
        if (data.songs) {
            const songs = data.songs.map(s => ({
                title: s.title, artist: s.artist, lyrics_nepali: s.lyrics_nepali || s.lyrics,
                // map other fields...
            }));
            await supabase.from('songs').insert(songs);
        }
        // ... artists, categories
        window.dispatchEvent(new Event('content-change'));
        return true;
    } catch (e) {
        console.error(e);
        return false;
    }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getFavorites, FavoriteItem } from '../utils/storage';
import { getSongLyrics } from '../services/geminiService';
import { LyricsData } from '../types';
import { Heart, Mic2, Disc, ArrowRight, Play, X, ChevronLeft, ChevronRight, Loader2, ZoomIn, ZoomOut, Maximize, Minimize, PlayCircle, PauseCircle, ListOrdered, Circle, SkipBack, SkipForward } from 'lucide-react';

const FavoritesPage: React.FC = () => {
  const [favorites, setFavorites] = useState<FavoriteItem[]>([]);
  const navigate = useNavigate();

  // Selection / Ordering State
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [presentationQueue, setPresentationQueue] = useState<FavoriteItem[]>([]);

  // Presentation State
  const [isPresenting, setIsPresenting] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [lyricsData, setLyricsData] = useState<LyricsData | null>(null);
  const [loadingLyrics, setLoadingLyrics] = useState(false);
  const [fontSize, setFontSize] = useState(32); // Default presentation font size

  // New Features State
  const [isBrowserFullscreen, setIsBrowserFullscreen] = useState(false);
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Initial Load
    setFavorites(getFavorites());

    // Listen for live updates (e.g. if a song in favorites is deleted or renamed elsewhere)
    const handleContentChange = () => {
        setFavorites(getFavorites());
    };
    window.addEventListener('content-change', handleContentChange);
    return () => {
        window.removeEventListener('content-change', handleContentChange);
    };
  }, []);

  // Filter only songs for presentation
  const allFavoriteSongs = favorites.filter(f => f.type === 'song');

  // The actual list to present: either the custom queue or all favorites
  const slidesToPresent = presentationQueue.length > 0 ? presentationQueue : allFavoriteSongs;

  const fetchSlideLyrics = async (index: number) => {
    setLoadingLyrics(true);
    setLyricsData(null); // Clear previous lyrics while loading

    // Reset Scroll and AutoScroll
    setIsAutoScrolling(false);
    if (scrollContainerRef.current) {
        scrollContainerRef.current.scrollTop = 0;
    }

    const item = slidesToPresent[index];
    if (item) {
        // item.subtext is Artist, item.name is Title
        const data = await getSongLyrics(item.subtext, item.name);
        setLyricsData(data);
    }
    setLoadingLyrics(false);
  };

  const startPresentation = () => {
    if (slidesToPresent.length === 0) return;
    setCurrentIndex(0);
    setIsPresenting(true);
    fetchSlideLyrics(0);
  };

  const nextSlide = useCallback(() => {
    if (currentIndex < slidesToPresent.length - 1) {
      const newIndex = currentIndex + 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex, slidesToPresent.length]);

  const prevSlide = useCallback(() => {
    if (currentIndex > 0) {
      const newIndex = currentIndex - 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex]);

  const closePresentation = useCallback(() => {
    setIsPresenting(false);
    setLyricsData(null);
    setIsAutoScrolling(false);
    // Exit native fullscreen if active
    if (document.fullscreenElement) {
        document.exitFullscreen().catch(e => console.error(e));
    }
  }, []);

  const handleZoomIn = useCallback(() => {
    setFontSize(prev => Math.min(prev + 4, 96));
  }, []);

  const handleZoomOut = useCallback(() => {
    setFontSize(prev => Math.max(prev - 4, 16));
  }, []);

  const toggleBrowserFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().then(() => {
            setIsBrowserFullscreen(true);
        }).catch(err => {
            console.error(`Error attempting to enable full-screen mode: ${err}`);
        });
    } else {
        document.exitFullscreen().then(() => {
            setIsBrowserFullscreen(false);
        });
    }
  }, []);

  const toggleAutoScroll = () => {
      setIsAutoScrolling(!isAutoScrolling);
  };

  // Selection Logic
  const toggleSelectionMode = () => {
      setIsSelectionMode(!isSelectionMode);
      setPresentationQueue([]); // Reset queue when toggling
  };

  const handleSelectSong = (item: FavoriteItem) => {
      const existsIdx = presentationQueue.findIndex(i => i.id === item.id);
      if (existsIdx >= 0) {
          // Remove
          const newQueue = [...presentationQueue];
          newQueue.splice(existsIdx, 1);
          setPresentationQueue(newQueue);
      } else {
          // Add to end
          setPresentationQueue([...presentationQueue, item]);
      }
  };

  // Handle Fullscreen change events
  useEffect(() => {
      const handleFsChange = () => {
          setIsBrowserFullscreen(!!document.fullscreenElement);
      };
      document.addEventListener('fullscreenchange', handleFsChange);
      return () => document.removeEventListener('fullscreenchange', handleFsChange);
  }, []);

  // Auto Scroll Effect
  useEffect(() => {
      let interval: ReturnType<typeof setInterval>;
      if (isAutoScrolling && scrollContainerRef.current) {
          interval = setInterval(() => {
              if (scrollContainerRef.current) {
                  // Scroll down by 1px every 50ms
                  scrollContainerRef.current.scrollTop += 1;

                  // Stop if reached bottom
                  if (scrollContainerRef.current.scrollHeight - scrollContainerRef.current.scrollTop === scrollContainerRef.current.clientHeight) {
                      setIsAutoScrolling(false);
                  }
              }
          }, 40);
      }
      return () => clearInterval(interval);
  }, [isAutoScrolling]);

  // Keyboard Navigation
  useEffect(() => {
    if (!isPresenting) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight') {
        nextSlide();
      } else if (e.key === 'ArrowLeft') {
        prevSlide();
      } else if (e.key === 'Escape') {
        if (!document.fullscreenElement) {
            closePresentation();
        }
      } else if (e.key === '+' || e.key === '=') {
        handleZoomIn();
      } else if (e.key === '-') {
        handleZoomOut();
      } else if (e.key === 'f') {
        toggleBrowserFullscreen();
      } else if (e.key === ' ') {
        e.preventDefault(); // Prevent accidental page scroll
        toggleAutoScroll(); // Space to toggle scroll
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPresenting, nextSlide, prevSlide, closePresentation, handleZoomIn, handleZoomOut, toggleBrowserFullscreen, isAutoScrolling]);

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-900';
  };

  // --- Presentation View ---
  if (isPresenting) {
    const currentItem = slidesToPresent[currentIndex];

    // Generate a consistent "worship" style background based on song name
    const defaultBgUrl = `https://picsum.photos/seed/${encodeURIComponent(currentItem.name + 'worship')}/1920/1080?blur=1`;

    return (
      <div className="fixed inset-0 z-50 bg-black text-white flex flex-col overflow-hidden">
        {/* Background Layer */}
        <div className="absolute inset-0 z-0">
           <img 
             src={defaultBgUrl} 
             alt="Background" 
             className="w-full h-full object-cover transition-all duration-700"
           />
           {/* Overlay for legibility */}
           <div className="absolute inset-0 bg-black/50 transition-opacity duration-300"></div>
        </div>

        {/* Toolbar */}
        <div className="flex justify-between items-center p-3 md:p-4 bg-black/40 backdrop-blur-md z-20 absolute top-0 left-0 right-0 transition-opacity hover:opacity-100 opacity-0 md:opacity-100 border-b border-white/10 overflow-x-auto no-scrollbar">
           <div className="text-sm font-medium text-white/80 whitespace-nowrap hidden sm:block">
              {currentIndex + 1} / {slidesToPresent.length}
           </div>

           <div className="flex items-center space-x-2 md:space-x-3 min-w-max mx-auto sm:mx-0">

               {/* Nav Controls */}
               <button 
                  onClick={prevSlide} 
                  disabled={currentIndex === 0}
                  className="p-2 hover:bg-white/20 rounded-full transition-colors disabled:opacity-30" 
                  title="Previous Song"
               >
                   <SkipBack className="w-5 h-5" />
               </button>
               <button 
                  onClick={nextSlide} 
                  disabled={currentIndex === slidesToPresent.length - 1}
                  className="p-2 hover:bg-white/20 rounded-full transition-colors disabled:opacity-30" 
                  title="Next Song"
               >
                   <SkipForward className="w-5 h-5" />
               </button>

               <div className="w-px h-6 bg-white/20 mx-1"></div>

               {/* Scroll Toggle */}
               <button onClick={toggleAutoScroll} className={`p-2 rounded-full transition-colors ${isAutoScrolling ? 'bg-primary text-white' : 'hover:bg-white/20'}`} title="Auto Scroll (Space)">
                   {isAutoScrolling ? <PauseCircle className="w-5 h-5" /> : <PlayCircle className="w-5 h-5" />}
               </button>

               <div className="w-px h-6 bg-white/20 mx-1"></div>

               {/* Font Size */}
               <button onClick={handleZoomOut} className="p-2 hover:bg-white/20 rounded-full transition-colors" title="Zoom Out (-)">
                   <ZoomOut className="w-5 h-5" />
               </button>
               <button onClick={handleZoomIn} className="p-2 hover:bg-white/20 rounded-full transition-colors" title="Zoom In (+)">
                   <ZoomIn className="w-5 h-5" />
               </button>

               <div className="w-px h-6 bg-white/20 mx-1"></div>

               {/* Fullscreen Toggle */}
               <button onClick={toggleBrowserFullscreen} className="p-2 hover:bg-white/20 rounded-full transition-colors" title="Toggle Fullscreen (F)">
                   {isBrowserFullscreen ? <Minimize className="w-5 h-5" /> : <Maximize className="w-5 h-5" />}
               </button>

               <button onClick={closePresentation} className="p-2 hover:bg-red-500/20 rounded-full transition-colors text-red-400 hover:text-red-300" title="Close Presentation (Esc)">
                   <X className="w-5 h-5" />
               </button>
           </div>
        </div>

        {/* Click Zones for Navigation (Hidden but clickable) */}
        <div className="absolute inset-y-0 left-0 w-12 md:w-24 z-10 hover:bg-white/5 cursor-pointer flex items-center justify-start group" onClick={prevSlide}>
             <ChevronLeft className="w-6 h-6 md:w-12 md:h-12 text-white/20 group-hover:text-white/50 transition-colors ml-1 md:ml-4 drop-shadow-lg" />
        </div>
        <div className="absolute inset-y-0 right-0 w-12 md:w-24 z-10 hover:bg-white/5 cursor-pointer flex items-center justify-end group" onClick={nextSlide}>
             <ChevronRight className="w-6 h-6 md:w-12 md:h-12 text-white/20 group-hover:text-white/50 transition-colors mr-1 md:mr-4 drop-shadow-lg" />
        </div>

        {/* Content Area */}
        <div 
            ref={scrollContainerRef}
            className="flex-1 flex flex-col items-center justify-start p-4 md:p-12 lg:p-24 overflow-y-auto no-scrollbar w-full scroll-smooth z-10 relative mt-12 md:mt-0"
        >
            <div className="w-full max-w-7xl mx-auto py-8 md:py-12">
                {loadingLyrics ? (
                   <div className="flex justify-center py-20">
                      <Loader2 className="w-16 h-16 animate-spin text-white/80" />
                   </div>
                ) : lyricsData ? (
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-8 md:gap-16 w-full pb-24">
                       {/* Nepali Column */}
                       <div className="text-center md:text-right border-b md:border-b-0 md:border-r border-white/20 pb-8 md:pb-0 md:pr-8">
                           <h3 className="text-sm uppercase tracking-[0.2em] text-white/60 mb-4 md:mb-8 font-bold drop-shadow-md">Nepali</h3>
                           <div 
                              className="whitespace-pre-wrap leading-relaxed font-sans font-medium text-white drop-shadow-[0_4px_6px_rgba(0,0,0,0.9)]"
                              style={{ fontSize: `${fontSize}px` }}
                           >
                               {lyricsData.lyrics_nepali || "Nepali lyrics not available"}
                           </div>
                       </div>

                       {/* Roman Column */}
                       <div className="text-center md:text-left pt-8 md:pt-0 md:pl-8">
                           <h3 className="text-sm uppercase tracking-[0.2em] text-white/60 mb-4 md:mb-8 font-bold drop-shadow-md">Romanized</h3>
                            <div 
                              className="whitespace-pre-wrap leading-relaxed font-sans text-white/95 drop-shadow-[0_4px_6px_rgba(0,0,0,0.9)]"
                              style={{ fontSize: `${fontSize}px` }}
                           >
                               {lyricsData.lyrics_roman || "Romanized lyrics not available"}
                           </div>
                       </div>
                   </div>
                ) : (
                   <p className="text-center text-white/50 text-xl">Could not load lyrics for this song.</p>
                )}
            </div>
        </div>
      </div>
    );
  }

  // --- Normal View ---
  return (
    <div className="min-h-screen max-w-7xl mx-auto px-4 py-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <h1 className="text-3xl font-bold text-slate-900">Favorites</h1>

        {allFavoriteSongs.length > 0 && (
           <div className="flex items-center space-x-2 w-full md:w-auto">
               <button 
                 onClick={toggleSelectionMode}
                 className={`flex-1 md:flex-none flex items-center justify-center px-4 py-2.5 rounded-full transition-all ${
                     isSelectionMode 
                     ? 'bg-slate-200 text-slate-700 font-medium' 
                     : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
                 }`}
               >
                  {isSelectionMode ? <X className="w-5 h-5 mr-2" /> : <ListOrdered className="w-5 h-5 mr-2" />}
                  {isSelectionMode ? 'Cancel Selection' : 'Select Order'}
               </button>

               <button 
                 onClick={startPresentation}
                 className="flex-1 md:flex-none flex items-center justify-center bg-primary text-white px-5 py-2.5 rounded-full hover:bg-primary/90 transition-all shadow-lg hover:shadow-primary/30 font-medium"
               >
                  <Play className="w-5 h-5 mr-2 fill-current" />
                  {isSelectionMode && presentationQueue.length > 0 
                     ? `Play (${presentationQueue.length})` 
                     : 'Play All'}
               </button>
           </div>
        )}
      </div>

      {isSelectionMode && (
          <div className="mb-6 bg-blue-50 border border-blue-100 text-blue-800 p-4 rounded-xl flex items-center">
              <ListOrdered className="w-5 h-5 mr-3 text-blue-600" />
              <div>
                  <p className="font-bold text-sm">Custom Presentation Mode</p>
                  <p className="text-xs mt-1 opacity-80">Click songs to add them to your presentation queue. The numbers indicate the slide order.</p>
              </div>
          </div>
      )}

      {favorites.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-2xl border border-slate-200 shadow-sm">
          <Heart className="w-16 h-16 text-slate-200 mx-auto mb-4" />
          <h3 className="text-2xl font-bold text-slate-900 mb-2">No favorites yet</h3>
          <p className="text-slate-500 mb-6">Start browsing songs and artists to add them to your collection.</p>
          <Link to="/" className="inline-flex items-center text-primary font-bold hover:underline">
            Browse Music <ArrowRight className="w-4 h-4 ml-1" />
          </Link>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {favorites.map((item) => {
            // Check if selected for queue
            const queueIndex = presentationQueue.findIndex(q => q.id === item.id);
            const isSelected = queueIndex >= 0;

            const titleClass = item.type === 'song' ? getSongColorClass(item.language) : 'text-slate-900';

            const CardContent = (
               <>
                <div className={`w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0 mr-4 transition-colors ${item.type === 'artist' ? 'bg-secondary/10 text-secondary group-hover:bg-secondary group-hover:text-white' : 'bg-primary/10 text-primary group-hover:bg-primary group-hover:text-white'}`}>
                    {item.type === 'artist' ? <Mic2 className="w-6 h-6" /> : <Disc className="w-6 h-6" />}
                </div>

                <div className="flex-1 min-w-0">
                    <div className="flex items-center space-x-2 mb-1">
                        {item.type === 'artist' ? <Mic2 className="w-3 h-3 text-secondary" /> : <Disc className="w-3 h-3 text-primary" />}
                        <span className="text-[10px] font-bold uppercase text-slate-400">{item.type}</span>
                    </div>
                    <h3 className={`text-lg font-bold transition-colors truncate ${titleClass}`}>{item.name}</h3>
                    <p className="text-slate-500 text-sm truncate">{item.subtext}</p>
                </div>

                {isSelectionMode && item.type === 'song' && (
                    <div className="ml-3">
                        {isSelected ? (
                            <div className="w-8 h-8 rounded-full bg-primary text-white flex items-center justify-center font-bold shadow-md transform scale-110 transition-transform">
                                {queueIndex + 1}
                            </div>
                        ) : (
                            <Circle className="w-8 h-8 text-slate-300" />
                        )}
                    </div>
                )}
               </>
            );

            // In selection mode, we use a div with onClick handler
            if (isSelectionMode && item.type === 'song') {
                return (
                    <div
                        key={item.id}
                        onClick={() => handleSelectSong(item)}
                        className={`flex items-center p-4 bg-white rounded-xl border cursor-pointer transition-all shadow-sm hover:shadow-md ${isSelected ? 'border-primary ring-1 ring-primary/50' : 'border-slate-200 hover:border-slate-300'}`}
                    >
                        {CardContent}
                    </div>
                );
            }

            // Normal mode
            return (
                <Link
                key={item.id}
                to={item.type === 'artist' 
                    ? `/artist/${encodeURIComponent(item.name)}` 
                    : `/lyrics/${encodeURIComponent(item.subtext)}/${encodeURIComponent(item.name)}`
                }
                className="flex items-center p-4 bg-white rounded-xl border border-slate-200 hover:border-primary/50 hover:bg-slate-50 transition-all group shadow-sm hover:shadow-md"
                >
                {CardContent}
                </Link>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default FavoritesPage;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getFavorites, FavoriteItem } from '../utils/storage';
import { getSongLyrics } from '../services/geminiService';
import { LyricsData } from '../types';
import { Heart, Mic2, Disc, ArrowRight, Play, X, ChevronLeft, ChevronRight, Loader2, ZoomIn, ZoomOut, Maximize, Minimize, PlayCircle, PauseCircle, ListOrdered, Circle, SkipBack, SkipForward, Settings, Upload, RefreshCw, Image as ImageIcon } from 'lucide-react';

const FavoritesPage: React.FC = () => {
  const [favorites, setFavorites] = useState<FavoriteItem[]>([]);
  const navigate = useNavigate();

  // Selection / Ordering State
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [presentationQueue, setPresentationQueue] = useState<FavoriteItem[]>([]);

  // Presentation State
  const [isPresenting, setIsPresenting] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [lyricsData, setLyricsData] = useState<LyricsData | null>(null);
  const [loadingLyrics, setLoadingLyrics] = useState(false);
  const [fontSize, setFontSize] = useState(48); // Default presentation font size

  // Presentation Customization State
  const [bgImage, setBgImage] = useState<string>('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
  const [bgBlur, setBgBlur] = useState(4);
  const [bgOpacity, setBgOpacity] = useState(50);
  const [showSettings, setShowSettings] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // New Features State
  const [isBrowserFullscreen, setIsBrowserFullscreen] = useState(false);
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Initial Load
    setFavorites(getFavorites());

    // Listen for live updates (e.g. if a song in favorites is deleted or renamed elsewhere)
    const handleContentChange = () => {
        setFavorites(getFavorites());
    };
    window.addEventListener('content-change', handleContentChange);
    return () => {
        window.removeEventListener('content-change', handleContentChange);
    };
  }, []);

  // Filter only songs for presentation
  const allFavoriteSongs = favorites.filter(f => f.type === 'song');

  // The actual list to present: either the custom queue or all favorites
  const slidesToPresent = presentationQueue.length > 0 ? presentationQueue : allFavoriteSongs;

  const fetchSlideLyrics = async (index: number) => {
    setLoadingLyrics(true);
    setLyricsData(null); // Clear previous lyrics while loading

    // Reset Scroll and AutoScroll
    setIsAutoScrolling(false);
    if (scrollContainerRef.current) {
        scrollContainerRef.current.scrollTop = 0;
    }

    const item = slidesToPresent[index];
    if (item) {
        // item.subtext is Artist, item.name is Title
        const data = await getSongLyrics(item.subtext, item.name);
        setLyricsData(data);
    }
    setLoadingLyrics(false);
  };

  const startPresentation = () => {
    if (slidesToPresent.length === 0) return;
    setCurrentIndex(0);
    setIsPresenting(true);
    fetchSlideLyrics(0);
  };

  const nextSlide = useCallback(() => {
    if (currentIndex < slidesToPresent.length - 1) {
      const newIndex = currentIndex + 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex, slidesToPresent.length]);

  const prevSlide = useCallback(() => {
    if (currentIndex > 0) {
      const newIndex = currentIndex - 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex]);

  const closePresentation = useCallback(() => {
    setIsPresenting(false);
    setLyricsData(null);
    setIsAutoScrolling(false);
    setShowSettings(false);
    // Exit native fullscreen if active
    if (document.fullscreenElement) {
        document.exitFullscreen().catch(e => console.error(e));
    }
  }, []);

  const handleZoomIn = useCallback(() => {
    setFontSize(prev => Math.min(prev + 4, 120));
  }, []);

  const handleZoomOut = useCallback(() => {
    setFontSize(prev => Math.max(prev - 4, 16));
  }, []);

  const toggleBrowserFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().then(() => {
            setIsBrowserFullscreen(true);
        }).catch(err => {
            console.error(`Error attempting to enable full-screen mode: ${err}`);
        });
    } else {
        document.exitFullscreen().then(() => {
            setIsBrowserFullscreen(false);
        });
    }
  }, []);

  const toggleAutoScroll = () => {
      setIsAutoScrolling(!isAutoScrolling);
  };

  // Selection Logic
  const toggleSelectionMode = () => {
      setIsSelectionMode(!isSelectionMode);
      setPresentationQueue([]); // Reset queue when toggling
  };

  const handleSelectSong = (item: FavoriteItem) => {
      const existsIdx = presentationQueue.findIndex(i => i.id === item.id);
      if (existsIdx >= 0) {
          // Remove
          const newQueue = [...presentationQueue];
          newQueue.splice(existsIdx, 1);
          setPresentationQueue(newQueue);
      } else {
          // Add to end
          setPresentationQueue([...presentationQueue, item]);
      }
  };

  // Background Settings Handlers
  const handleBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
            setBgImage(reader.result as string);
        };
        reader.readAsDataURL(file);
    }
  };

  const resetSettings = () => {
      setBgImage('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
      setBgBlur(4);
      setBgOpacity(50);
  };

  // Handle Fullscreen change events
  useEffect(() => {
      const handleFsChange = () => {
          setIsBrowserFullscreen(!!document.fullscreenElement);
      };
      document.addEventListener('fullscreenchange', handleFsChange);
      return () => document.removeEventListener('fullscreenchange', handleFsChange);
  }, []);

  // Auto Scroll Effect
  useEffect(() => {
      let interval: ReturnType<typeof setInterval>;
      if (isAutoScrolling && scrollContainerRef.current) {
          interval = setInterval(() => {
              if (scrollContainerRef.current) {
                  // Scroll down by 1px every 50ms
                  scrollContainerRef.current.scrollTop += 1;

                  // Stop if reached bottom
                  if (scrollContainerRef.current.scrollHeight - scrollContainerRef.current.scrollTop === scrollContainerRef.current.clientHeight) {
                      setIsAutoScrolling(false);
                  }
              }
          }, 40);
      }
      return () => clearInterval(interval);
  }, [isAutoScrolling]);

  // Keyboard Navigation
  useEffect(() => {
    if (!isPresenting) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight') {
        nextSlide();
      } else if (e.key === 'ArrowLeft') {
        prevSlide();
      } else if (e.key === 'Escape') {
        if (!document.fullscreenElement) {
            closePresentation();
        }
      } else if (e.key === '+' || e.key === '=') {
        handleZoomIn();
      } else if (e.key === '-') {
        handleZoomOut();
      } else if (e.key === 'f') {
        toggleBrowserFullscreen();
      } else if (e.key === ' ') {
        e.preventDefault(); // Prevent accidental page scroll
        toggleAutoScroll(); // Space to toggle scroll
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPresenting, nextSlide, prevSlide, closePresentation, handleZoomIn, handleZoomOut, toggleBrowserFullscreen, isAutoScrolling]);

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-900';
  };

  // --- Presentation View ---
  if (isPresenting) {
    return (
      <div className="fixed inset-0 z-50 bg-black text-white flex flex-col overflow-hidden">
        {/* Background Layer */}
        <div className="absolute inset-0 z-0">
           <img 
             src={bgImage} 
             alt="Background" 
             className="w-full h-full object-cover transition-all duration-700"
             style={{ filter: `blur(${bgBlur}px)` }}
           />
           {/* Overlay for legibility */}
           <div 
             className="absolute inset-0 bg-black transition-opacity duration-300"
             style={{ opacity: bgOpacity / 100 }}
           ></div>
        </div>

        {/* Toolbar */}
        <div className="flex justify-between items-center p-3 md:p-4 bg-black/40 backdrop-blur-md z-30 absolute top-0 left-0 right-0 transition-opacity hover:opacity-100 opacity-0 md:opacity-100 border-b border-white/10 overflow-visible">
           <div className="text-sm font-medium text-white/80 whitespace-nowrap hidden sm:block">
              {currentIndex + 1} / {slidesToPresent.length}
           </div>

           <div className="flex items-center space-x-2 md:space-x-3 min-w-max mx-auto sm:mx-0">

               {/* Nav Controls */}
               <button 
                  onClick={prevSlide} 
                  disabled={currentIndex === 0}
                  className="p-2 hover:bg-white/20 rounded-full transition-colors disabled:opacity-30" 
                  title="Previous Song"
               >
                   <SkipBack className="w-5 h-5" />
               </button>
               <button 
                  onClick={nextSlide} 
                  disabled={currentIndex === slidesToPresent.length - 1}
                  className="p-2 hover:bg-white/20 rounded-full transition-colors disabled:opacity-30" 
                  title="Next Song"
               >
                   <SkipForward className="w-5 h-5" />
               </button>

               <div className="w-px h-6 bg-white/20 mx-1"></div>

               {/* Scroll Toggle */}
               <button onClick={toggleAutoScroll} className={`p-2 rounded-full transition-colors ${isAutoScrolling ? 'bg-primary text-white' : 'hover:bg-white/20'}`} title="Auto Scroll (Space)">
                   {isAutoScrolling ? <PauseCircle className="w-5 h-5" /> : <PlayCircle className="w-5 h-5" />}
               </button>

               <div className="w-px h-6 bg-white/20 mx-1"></div>

               {/* Font Size */}
               <button onClick={handleZoomOut} className="p-2 hover:bg-white/20 rounded-full transition-colors" title="Zoom Out (-)">
                   <ZoomOut className="w-5 h-5" />
               </button>
               <button onClick={handleZoomIn} className="p-2 hover:bg-white/20 rounded-full transition-colors" title="Zoom In (+)">
                   <ZoomIn className="w-5 h-5" />
               </button>

               <div className="w-px h-6 bg-white/20 mx-1"></div>

               {/* Settings Toggle */}
               <div className="relative">
                   <button 
                        onClick={() => setShowSettings(!showSettings)} 
                        className={`p-2 rounded-full transition-colors ${showSettings ? 'bg-white/20' : 'hover:bg-white/20'}`}
                        title="Presentation Settings"
                   >
                       <Settings className="w-5 h-5" />
                   </button>

                   {/* Settings Dropdown Panel */}
                   {showSettings && (
                       <div className="absolute top-full right-0 mt-2 w-72 bg-slate-900/95 backdrop-blur-xl border border-white/10 rounded-2xl p-4 shadow-2xl z-50 text-left">
                           <div className="space-y-4">
                               <div>
                                   <label className="text-xs font-bold text-slate-400 uppercase mb-2 block">Background Image</label>
                                   <button 
                                        onClick={() => fileInputRef.current?.click()}
                                        className="w-full flex items-center justify-center gap-2 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-sm transition-colors border border-white/5"
                                   >
                                       <Upload className="w-4 h-4" /> Upload Image
                                   </button>
                                   <input 
                                        type="file" 
                                        ref={fileInputRef}
                                        onChange={handleBgUpload}
                                        className="hidden" 
                                        accept="image/*"
                                   />
                               </div>

                               <div>
                                   <div className="flex justify-between text-xs mb-1">
                                       <span className="text-slate-400 font-bold uppercase">Blur</span>
                                       <span className="text-white font-mono">{bgBlur}px</span>
                                   </div>
                                   <input 
                                        type="range" 
                                        min="0" 
                                        max="20" 
                                        value={bgBlur} 
                                        onChange={(e) => setBgBlur(Number(e.target.value))}
                                        className="w-full h-1 bg-white/20 rounded-full appearance-none cursor-pointer [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-3 [&::-webkit-slider-thumb]:h-3 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-white"
                                   />
                               </div>

                               <div>
                                   <div className="flex justify-between text-xs mb-1">
                                       <span className="text-slate-400 font-bold uppercase">Dark Overlay</span>
                                       <span className="text-white font-mono">{bgOpacity}%</span>
                                   </div>
                                   <input 
                                        type="range" 
                                        min="0" 
                                        max="90" 
                                        value={bgOpacity} 
                                        onChange={(e) => setBgOpacity(Number(e.target.value))}
                                        className="w-full h-1 bg-white/20 rounded-full appearance-none cursor-pointer [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-3 [&::-webkit-slider-thumb]:h-3 [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-white"
                                   />
                               </div>

                               <div className="pt-2 border-t border-white/10">
                                   <button 
                                        onClick={resetSettings}
                                        className="w-full flex items-center justify-center gap-2 py-2 text-xs text-red-400 hover:text-red-300 hover:bg-red-500/10 rounded-lg transition-colors"
                                   >
                                       <RefreshCw className="w-3 h-3" /> Reset to Defaults
                                   </button>
                               </div>
                           </div>
                       </div>
                   )}
               </div>

               {/* Fullscreen Toggle */}
               <button onClick={toggleBrowserFullscreen} className="p-2 hover:bg-white/20 rounded-full transition-colors" title="Toggle Fullscreen (F)">
                   {isBrowserFullscreen ? <Minimize className="w-5 h-5" /> : <Maximize className="w-5 h-5" />}
               </button>

               <button onClick={closePresentation} className="p-2 hover:bg-red-500/20 rounded-full transition-colors text-red-400 hover:text-red-300" title="Close Presentation (Esc)">
                   <X className="w-5 h-5" />
               </button>
           </div>
        </div>

        {/* Click Zones for Navigation (Hidden but clickable) */}
        <div className="absolute inset-y-0 left-0 w-12 md:w-24 z-20 hover:bg-white/5 cursor-pointer flex items-center justify-start group" onClick={prevSlide}>
             <ChevronLeft className="w-6 h-6 md:w-12 md:h-12 text-white/20 group-hover:text-white/50 transition-colors ml-1 md:ml-4 drop-shadow-lg" />
        </div>
        <div className="absolute inset-y-0 right-0 w-12 md:w-24 z-20 hover:bg-white/5 cursor-pointer flex items-center justify-end group" onClick={nextSlide}>
             <ChevronRight className="w-6 h-6 md:w-12 md:h-12 text-white/20 group-hover:text-white/50 transition-colors mr-1 md:mr-4 drop-shadow-lg" />
        </div>

        {/* Content Area */}
        <div 
            ref={scrollContainerRef}
            className="flex-1 flex flex-col items-center justify-center p-4 md:p-12 lg:p-24 overflow-y-auto no-scrollbar w-full scroll-smooth z-10 relative mt-12 md:mt-0"
        >
            <div className="w-full max-w-7xl mx-auto py-8 md:py-12">
                {loadingLyrics ? (
                   <div className="flex justify-center py-20">
                      <Loader2 className="w-16 h-16 animate-spin text-white/80" />
                   </div>
                ) : lyricsData ? (
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-8 md:gap-16 w-full pb-24 items-center">
                       {/* Nepali Column */}
                       <div className="text-center md:text-right border-b md:border-b-0 md:border-r border-white/20 pb-8 md:pb-0 md:pr-8">
                           <h3 className="text-sm uppercase tracking-[0.2em] text-white/60 mb-4 md:mb-8 font-bold drop-shadow-md">Nepali</h3>
                           <div 
                              className="whitespace-pre-wrap leading-relaxed font-sans font-bold text-white drop-shadow-[0_4px_6px_rgba(0,0,0,0.9)]"
                              style={{ fontSize: `${fontSize}px` }}
                           >
                               {lyricsData.lyrics_nepali || "Nepali lyrics not available"}
                           </div>
                       </div>

                       {/* Roman Column */}
                       <div className="text-center md:text-left pt-8 md:pt-0 md:pl-8">
                           <h3 className="text-sm uppercase tracking-[0.2em] text-white/60 mb-4 md:mb-8 font-bold drop-shadow-md">Romanized</h3>
                            <div 
                              className="whitespace-pre-wrap leading-relaxed font-sans text-white/95 drop-shadow-[0_4px_6px_rgba(0,0,0,0.9)] font-medium"
                              style={{ fontSize: `${fontSize}px` }}
                           >
                               {lyricsData.lyrics_roman || "Romanized lyrics not available"}
                           </div>
                       </div>
                   </div>
                ) : (
                   <p className="text-center text-white/50 text-xl">Could not load lyrics for this song.</p>
                )}
            </div>
        </div>
      </div>
    );
  }

  // --- Normal View ---
  return (
    <div className="min-h-screen max-w-7xl mx-auto px-4 py-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <h1 className="text-3xl font-bold text-slate-900">Favorites</h1>

        {allFavoriteSongs.length > 0 && (
           <div className="flex items-center space-x-2 w-full md:w-auto">
               <button 
                 onClick={toggleSelectionMode}
                 className={`flex-1 md:flex-none flex items-center justify-center px-4 py-2.5 rounded-full transition-all ${
                     isSelectionMode 
                     ? 'bg-slate-200 text-slate-700 font-medium' 
                     : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
                 }`}
               >
                  {isSelectionMode ? <X className="w-5 h-5 mr-2" /> : <ListOrdered className="w-5 h-5 mr-2" />}
                  {isSelectionMode ? 'Cancel Selection' : 'Select Order'}
               </button>

               <button 
                 onClick={startPresentation}
                 className="flex-1 md:flex-none flex items-center justify-center bg-primary text-white px-5 py-2.5 rounded-full hover:bg-primary/90 transition-all shadow-lg hover:shadow-primary/30 font-medium"
               >
                  <Play className="w-5 h-5 mr-2 fill-current" />
                  {isSelectionMode && presentationQueue.length > 0 
                     ? `Play (${presentationQueue.length})` 
                     : 'Play All'}
               </button>
           </div>
        )}
      </div>

      {isSelectionMode && (
          <div className="mb-6 bg-blue-50 border border-blue-100 text-blue-800 p-4 rounded-xl flex items-center">
              <ListOrdered className="w-5 h-5 mr-3 text-blue-600" />
              <div>
                  <p className="font-bold text-sm">Custom Presentation Mode</p>
                  <p className="text-xs mt-1 opacity-80">Click songs to add them to your presentation queue. The numbers indicate the slide order.</p>
              </div>
          </div>
      )}

      {favorites.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-2xl border border-slate-200 shadow-sm">
          <Heart className="w-16 h-16 text-slate-200 mx-auto mb-4" />
          <h3 className="text-2xl font-bold text-slate-900 mb-2">No favorites yet</h3>
          <p className="text-slate-500 mb-6">Start browsing songs and artists to add them to your collection.</p>
          <Link to="/" className="inline-flex items-center text-primary font-bold hover:underline">
            Browse Music <ArrowRight className="w-4 h-4 ml-1" />
          </Link>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {favorites.map((item) => {
            // Check if selected for queue
            const queueIndex = presentationQueue.findIndex(q => q.id === item.id);
            const isSelected = queueIndex >= 0;

            const titleClass = item.type === 'song' ? getSongColorClass(item.language) : 'text-slate-900';

            const CardContent = (
               <>
                <div className={`w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0 mr-4 transition-colors ${item.type === 'artist' ? 'bg-secondary/10 text-secondary group-hover:bg-secondary group-hover:text-white' : 'bg-primary/10 text-primary group-hover:bg-primary group-hover:text-white'}`}>
                    {item.type === 'artist' ? <Mic2 className="w-6 h-6" /> : <Disc className="w-6 h-6" />}
                </div>

                <div className="flex-1 min-w-0">
                    <div className="flex items-center space-x-2 mb-1">
                        {item.type === 'artist' ? <Mic2 className="w-3 h-3 text-secondary" /> : <Disc className="w-3 h-3 text-primary" />}
                        <span className="text-[10px] font-bold uppercase text-slate-400">{item.type}</span>
                    </div>
                    <h3 className={`text-lg font-bold transition-colors truncate ${titleClass}`}>{item.name}</h3>
                    <p className="text-slate-500 text-sm truncate">{item.subtext}</p>
                </div>

                {isSelectionMode && item.type === 'song' && (
                    <div className="ml-3">
                        {isSelected ? (
                            <div className="w-8 h-8 rounded-full bg-primary text-white flex items-center justify-center font-bold shadow-md transform scale-110 transition-transform">
                                {queueIndex + 1}
                            </div>
                        ) : (
                            <Circle className="w-8 h-8 text-slate-300" />
                        )}
                    </div>
                )}
               </>
            );

            // In selection mode, we use a div with onClick handler
            if (isSelectionMode && item.type === 'song') {
                return (
                    <div
                        key={item.id}
                        onClick={() => handleSelectSong(item)}
                        className={`flex items-center p-4 bg-white rounded-xl border cursor-pointer transition-all shadow-sm hover:shadow-md ${isSelected ? 'border-primary ring-1 ring-primary/50' : 'border-slate-200 hover:border-slate-300'}`}
                    >
                        {CardContent}
                    </div>
                );
            }

            // Normal mode
            return (
                <Link
                key={item.id}
                to={item.type === 'artist' 
                    ? `/artist/${encodeURIComponent(item.name)}` 
                    : `/lyrics/${encodeURIComponent(item.subtext)}/${encodeURIComponent(item.name)}`
                }
                className="flex items-center p-4 bg-white rounded-xl border border-slate-200 hover:border-primary/50 hover:bg-slate-50 transition-all group shadow-sm hover:shadow-md"
                >
                {CardContent}
                </Link>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default FavoritesPage;

import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Music2, LogOut, User as UserIcon } from 'lucide-react';
import { useAuth, getCurrentUser, logout } from '../utils/auth';
import { getSiteLogo } from '../utils/dataManager';

const Navbar: React.FC = () => {
  const isAuth = useAuth();
  const user = getCurrentUser();
  const navigate = useNavigate();
  const [logoUrl, setLogoUrl] = useState(getSiteLogo());
  // Local state to force re-render on auth changes if user details update
  const [, setTick] = useState(0);

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  useEffect(() => {
    const handleLogoChange = () => {
      setLogoUrl(getSiteLogo()); // getSiteLogo is async, but this is fire-and-forget inside effect wrapper
      getSiteLogo().then(setLogoUrl);
    };
    const handleAuthChange = () => {
      setTick(t => t + 1);
    }
    window.addEventListener('logo-change', handleLogoChange);
    window.addEventListener('auth-change', handleAuthChange);
    // Initial fetch
    getSiteLogo().then(setLogoUrl);
    return () => {
        window.removeEventListener('logo-change', handleLogoChange);
        window.removeEventListener('auth-change', handleAuthChange);
    }
  }, []);

  return (
    <nav className="sticky top-0 z-40 bg-white/80 backdrop-blur-lg border-b border-slate-200 h-16">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-full">
        <div className="flex items-center justify-between h-full relative">

          {/* Logo */}
          <Link to="/" className="flex items-center space-x-2 group">
            {logoUrl ? (
                <img 
                    src={logoUrl} 
                    alt="SansarPlus" 
                    className="w-10 h-10 rounded-xl object-cover shadow-lg shadow-primary/20 group-hover:shadow-primary/40 transition-all duration-300" 
                />
            ) : (
