import { LyricsData, SearchResult, ArtistDetails, HomeData } from "../types";
import { 
  getCustomSong, 
  getCustomArtist, 
  getViewCount, 
  getAllCustomSongs, 
  getAllCustomArtists 
} from "../utils/dataManager";

export const getTrendingContent = async (): Promise<HomeData | null> => {
  try {
    // Await the async Firestore call
    const allSongs = await getAllCustomSongs();
    const allArtists = await getAllCustomArtists();

    // 1. Trending Songs: Sort by views descending, take top 10
    const trendingSongs = allSongs
      .sort((a, b) => (b.views || 0) - (a.views || 0))
      .slice(0, 10)
      .map(s => ({ title: s.title, artist: s.artist, language: s.language }));

    // 2. Popular Artists: Sort by aggregated views of their songs
    // Calculate total views per artist
    const artistViews: Record<string, number> = {};
    allSongs.forEach(song => {
        const v = song.views || 0;
        const mainArtist = song.artist.trim();
        if (mainArtist) {
             artistViews[mainArtist] = (artistViews[mainArtist] || 0) + v;
        }
        // Also attribute views to credited artists in the array if needed, 
        // but typically 'Top Artist' charts use the main artist credit.
        // We will stick to main artist for a cleaner chart.
    });

    const popularArtists = allArtists
      .map(a => ({ 
          name: a.name, 
          // Get views from map, default to 0. 
          // Note: allArtists includes 'virtual' artists from credits so this works well.
          totalViews: artistViews[a.name] || 0 
      }))
      .sort((a, b) => b.totalViews - a.totalViews)
      .slice(0, 10)
      .map(a => a.name);

    return {
      trendingSongs,
      popularArtists
    };
  } catch (error) {
    console.error("Error fetching trending content:", error);
    return { trendingSongs: [], popularArtists: [] };
  }
};

export const getSongsByLetter = async (letter: string): Promise<{title: string, artist: string, language?: string}[]> => {
  try {
    const allSongs = await getAllCustomSongs(); // Await
    const isAll = letter.toLowerCase() === 'all';
    const charCode = letter.toLowerCase();

    return allSongs
      .filter(s => {
        if (isAll) return true;
        const titleLower = s.title.toLowerCase();
        if (charCode === '0-9') return /^\d/.test(titleLower);
        return titleLower.startsWith(charCode);
      })
      .map(s => ({ title: s.title, artist: s.artist, language: s.language }))
      .sort((a, b) => a.title.localeCompare(b.title));
  } catch (error) {
    return [];
  }
};

export const getArtistsByLetter = async (letter: string): Promise<string[]> => {
  try {
    const allArtists = await getAllCustomArtists(); // Await
    const isAll = letter.toLowerCase() === 'all';
    const charCode = letter.toLowerCase();

    return allArtists
      .filter(a => {
        if (isAll) return true;
        const nameLower = a.name.toLowerCase();
        if (charCode === '0-9') return /^\d/.test(nameLower);
        return nameLower.startsWith(charCode);
      })
      .map(a => a.name)
      .sort((a, b) => a.localeCompare(b));
  } catch (error) {
    return [];
  }
};

export const searchMusic = async (query: string): Promise<SearchResult[]> => {
  try {
    const q = query.toLowerCase().trim();
    if (!q) return [];

    const allSongs = await getAllCustomSongs(); // Await
    const allArtists = await getAllCustomArtists(); // Await

    const songResults: SearchResult[] = allSongs
      .filter(s => 
          s.title.toLowerCase().includes(q) || 
          s.artist.toLowerCase().includes(q) || 
          (s.lyrics_nepali && s.lyrics_nepali.toLowerCase().includes(q)) || 
          (s.lyrics_roman && s.lyrics_roman.toLowerCase().includes(q))
      )
      .map(s => ({ type: 'song', name: s.title, subtext: s.artist, language: s.language }));

    const artistResults: SearchResult[] = allArtists
      .filter(a => a.name.toLowerCase().includes(q))
      .map(a => ({ type: 'artist', name: a.name, subtext: 'Artist' }));

    return [...artistResults, ...songResults].slice(0, 50);
  } catch (error) {
    return [];
  }
};

export const getArtistDetails = async (artistName: string): Promise<ArtistDetails | null> => {
  return await getCustomArtist(artistName); 
};

export const getSongLyrics = async (artist: string, title: string): Promise<LyricsData | null> => {
  const localData = await getCustomSong(artist, title);
  if (localData) {
    // Views might be outdated in the song doc, fetch fresh view count
    const currentViews = await getViewCount(artist, title);
    return { ...localData, views: currentViews };
  }
  return null;
};

