import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { getCategories, addCategory, updateCategory, deleteCategory } from '../utils/dataManager';
import { useAuth } from '../utils/auth';
import { Edit2, Trash2, Check, X, Settings } from 'lucide-react';
import { Category } from '../types';

const CategoriesPage: React.FC = () => {
  const [categories, setCategories] = useState<Category[]>([]);

  // Admin State
  const { user, isAuth } = useAuth();
  const isSuperAdmin = isAuth && user?.role === 'SUPER_ADMIN';
  const [isAdminMode, setIsAdminMode] = useState(false);

  const [newCategory, setNewCategory] = useState('');
  const [newCategoryImg, setNewCategoryImg] = useState('');
  const [editingCategory, setEditingCategory] = useState<{original: string, current: string, imageUrl: string} | null>(null);

  useEffect(() => {
    refreshCategories();

    const handleContentChange = () => {
        refreshCategories();
    };
    window.addEventListener('content-change', handleContentChange);
    return () => {
        window.removeEventListener('content-change', handleContentChange);
    };
  }, []);

  const refreshCategories = async () => {
    setCategories(await getCategories());
  };

  // Generate consistent colors based on string hash (Fallback)
  const getGradient = (str: string) => {
    const hash = str.split('').reduce((acc, char) => char.charCodeAt(0) + ((acc << 5) - acc), 0);
    const gradients = [
      'from-pink-500 to-rose-500', 'from-red-500 to-orange-500', 'from-purple-500 to-indigo-500',
      'from-blue-500 to-cyan-500', 'from-amber-500 to-yellow-500', 'from-emerald-500 to-teal-500',
      'from-indigo-500 to-violet-500', 'from-slate-600 to-slate-800', 'from-orange-500 to-amber-500',
      'from-lime-500 to-green-500', 'from-fuchsia-500 to-purple-600', 'from-rose-400 to-red-500'
    ];
    return gradients[Math.abs(hash) % gradients.length];
  };

  const handleAdd = () => {
      if(newCategory.trim()) {
          addCategory(newCategory.trim(), newCategoryImg.trim());
          setNewCategory('');
          setNewCategoryImg('');
          refreshCategories();
      }
  };

  const handleUpdate = () => {
      if(editingCategory && editingCategory.current.trim()) {
          updateCategory(editingCategory.original, editingCategory.current.trim(), editingCategory.imageUrl.trim());
          setEditingCategory(null);
          refreshCategories();
      }
  };

  const handleDelete = (cat: string) => {
      if(window.confirm(`Are you sure you want to delete category "${cat}"?`)) {
          deleteCategory(cat);
          refreshCategories();
      }
  };

  return (
    <div className="min-h-screen max-w-7xl mx-auto px-4 py-8 pb-32">
      <div className="flex justify-between items-center mb-8">
          <h1 className="text-3xl font-bold text-slate-900">Categories</h1>

          {isSuperAdmin && (
              <button 
                onClick={() => setIsAdminMode(!isAdminMode)}
                className={`flex items-center px-4 py-2 rounded-full font-bold text-sm transition-all ${isAdminMode ? 'bg-primary text-white shadow-lg' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
              >
                  {isAdminMode ? <Check className="w-4 h-4 mr-2" /> : <Settings className="w-4 h-4 mr-2" />}
                  {isAdminMode ? 'Done Editing' : 'Manage'}
              </button>
          )}
      </div>

      {isAdminMode && (
          <div className="mb-8 p-4 bg-slate-100 rounded-xl border border-slate-200 animate-in fade-in slide-in-from-top-4">
              <h3 className="text-sm font-bold text-slate-500 uppercase mb-2">Add New Category</h3>
              <div className="flex flex-col md:flex-row gap-2">
                  <input 
                    type="text" 
                    className="flex-1 p-3 rounded-lg border border-slate-300 focus:outline-none focus:ring-2 focus:ring-primary"
                    placeholder="Category Name"
                    value={newCategory}
                    onChange={(e) => setNewCategory(e.target.value)}
                  />
                  <input 
                    type="text" 
                    className="flex-1 p-3 rounded-lg border border-slate-300 focus:outline-none focus:ring-2 focus:ring-primary"
                    placeholder="Background Image URL (Optional)"
                    value={newCategoryImg}
                    onChange={(e) => setNewCategoryImg(e.target.value)}
                  />
                  <button onClick={handleAdd} className="bg-primary text-white px-6 py-3 rounded-lg font-bold hover:bg-primary/90">Add</button>
              </div>
          </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
        {categories.map((cat) => (
            <div key={cat.name} className="relative group">
                {editingCategory?.original === cat.name ? (
                    <div className="h-48 rounded-2xl bg-white border-2 border-primary p-4 flex flex-col justify-center items-center shadow-lg space-y-2 z-10 relative">
                        <input 
                            className="w-full text-center font-bold text-slate-800 border-b border-primary mb-1 focus:outline-none"
                            value={editingCategory.current}
                            onChange={(e) => setEditingCategory({...editingCategory, current: e.target.value})}
                            placeholder="Name"
                            autoFocus
                        />
                        <input 
                            className="w-full text-center text-xs text-slate-500 border-b border-slate-300 mb-2 focus:outline-none"
                            value={editingCategory.imageUrl}
                            onChange={(e) => setEditingCategory({...editingCategory, imageUrl: e.target.value})}
                            placeholder="Image URL"
                        />
                        <div className="flex gap-2">
                            <button onClick={handleUpdate} className="bg-green-500 text-white p-1 rounded hover:bg-green-600"><Check className="w-4 h-4"/></button>
                            <button onClick={() => setEditingCategory(null)} className="bg-slate-400 text-white p-1 rounded hover:bg-slate-500"><X className="w-4 h-4"/></button>
                        </div>
                    </div>
                ) : (
                  <Link
                    to={`/category/${encodeURIComponent(cat.name)}`}
                    className={`
                        block relative h-32 rounded-2xl overflow-hidden shadow-lg hover:shadow-xl transition-all hover:scale-105
                        ${!cat.imageUrl ? `bg-gradient-to-br ${getGradient(cat.name)}` : ''}
                        ${isAdminMode ? 'opacity-90 hover:opacity-100 cursor-default' : ''}
                    `}
                    style={cat.imageUrl ? { backgroundImage: `url(${cat.imageUrl})`, backgroundSize: 'cover', backgroundPosition: 'center' } : {}}
                    onClick={(e) => isAdminMode && e.preventDefault()} // Disable navigation in admin mode
                  >
                    {/* Dark overlay if image present */}
                    {cat.imageUrl && <div className="absolute inset-0 bg-black/40"></div>}

                    <div className="absolute inset-0 flex items-center justify-center p-4">
                       <span className="text-white text-xl font-bold tracking-wide text-center drop-shadow-md">{cat.name}</span>
                    </div>
                  </Link>
                )}

                {/* Admin Overlays */}
                {isAdminMode && !editingCategory && (
                    <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity bg-black/20 backdrop-blur-sm p-1 rounded-lg z-20">
                        <button 
                            onClick={(e) => { e.preventDefault(); setEditingCategory({original: cat.name, current: cat.name, imageUrl: cat.imageUrl || ''}); }} 
                            className="p-1.5 bg-white text-slate-800 rounded hover:bg-primary hover:text-white transition-colors shadow-sm"
                        >
                            <Edit2 className="w-3 h-3" />
                        </button>
                        <button 
                            onClick={(e) => { e.preventDefault(); handleDelete(cat.name); }} 
                            className="p-1.5 bg-white text-red-500 rounded hover:bg-red-500 hover:text-white transition-colors shadow-sm"
                        >
                            <Trash2 className="w-3 h-3" />
                        </button>
                    </div>
                )}
            </div>
        ))}
      </div>
    </div>
  );
};

export default CategoriesPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { User, Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, Flag, X, Edit, Trash2, Save, Printer, Tag, Youtube, Mic2 } from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { saveCustomSong, deleteCustomSong, incrementViewCount, setViewCount, saveCustomArtist, getCategories } from '../utils/dataManager';

const LyricsPage: React.FC = () => {
  const { artist, song } = useParams<{ artist: string; song: string }>();
  const [data, setData] = useState<LyricsData | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(20); // Default font size
  const [availableCategories, setAvailableCategories] = useState<string[]>([]);

  // Auth & Editing
  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const navigate = useNavigate();

  // Extended edit form
  const [editForm, setEditForm] = useState<LyricsData & { artist_bio?: string }>({
      lyrics_nepali: '',
      lyrics_roman: '',
      composer: '',
      composers: [],
      lyricist: '',
      lyricists: [],
      singer: '',
      singers: [],
      views: 0,
      artist_bio: '',
      category: '',
      categories: [],
      youtubeUrl: '',
      isYoutubeVisible: true
  });

  // Feedback Modal State
  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('lyrics');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      if (artist && song) {
        setLoading(true);
        // Await the categories since getCategories is async
        const cats = await getCategories();
        // Map objects to names for the dropdown
        setAvailableCategories(cats.map(c => c.name));

        // Parallel Fetch
        const [lyricsResult, artistResult] = await Promise.all([
            getSongLyrics(artist, song),
            getArtistDetails(artist)
        ]);

        setData(lyricsResult);
        setArtistData(artistResult);

        if (lyricsResult) {
            // Handle legacy category vs new categories array
            let initialCats = lyricsResult.categories || [];
            if (initialCats.length === 0 && lyricsResult.category) {
                initialCats = [lyricsResult.category];
            }

            // Flatten credits for editing if arrays exist, otherwise use string
            const composerStr = lyricsResult.composers && lyricsResult.composers.length > 0 
                ? lyricsResult.composers.join(', ') 
                : lyricsResult.composer || '';

            const lyricistStr = lyricsResult.lyricists && lyricsResult.lyricists.length > 0 
                ? lyricsResult.lyricists.join(', ') 
                : lyricsResult.lyricist || '';

            const singerStr = lyricsResult.singers && lyricsResult.singers.length > 0 
                ? lyricsResult.singers.join(', ') 
                : lyricsResult.singer || '';

            setEditForm({ 
                ...lyricsResult, 
                views: lyricsResult.views || 0,
                artist_bio: artistResult?.bio || '',
                category: lyricsResult.category || 'Worship',
                categories: initialCats,
                composer: composerStr,
                lyricist: lyricistStr,
                singer: singerStr,
                youtubeUrl: lyricsResult.youtubeUrl || '',
                isYoutubeVisible: lyricsResult.isYoutubeVisible !== false // Default true if undefined
            });
        }

        setIsFav(isFavorite(generateId('song', song, artist)));
        setLoading(false);

        // Keep tracking views in background, but don't display
        incrementViewCount(artist, song);
      }
    };
    fetchData();
  }, [artist, song]);

  const handleFavorite = () => {
    if (!data || !artist || !song) return;
    const item = {
        id: generateId('song', song, artist),
        type: 'song' as const,
        name: song,
        subtext: artist,
        language: data.language // Save language to favorites for correct color display
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePrint = () => {
    window.print();
  };

  const handleZoomIn = () => {
    setFontSize(prev => Math.min(prev + 4, 64));
  };

  const handleZoomOut = () => {
    setFontSize(prev => Math.max(prev - 2, 16));
  };

  const submitFeedback = (e: React.FormEvent) => {
    e.preventDefault();
    setTimeout(() => {
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
            setFeedbackType('lyrics');
        }, 2000);
    }, 500);
  };

  // --- Admin Functions ---
  const handleSaveEdit = () => {
      if (!artist || !song) return;

      const { artist_bio, ...songData } = editForm;

      // Convert inputs to arrays for credits
      const composers = editForm.composer.split(',').map(s => s.trim()).filter(s => s);
      const lyricists = editForm.lyricist.split(',').map(s => s.trim()).filter(s => s);
      const singers = editForm.singer.split(',').map(s => s.trim()).filter(s => s);

      const updatedSongData = {
          ...songData,
          composers: composers.length > 0 ? composers : [],
          lyricists: lyricists.length > 0 ? lyricists : [],
          singers: singers.length > 0 ? singers : [],
          // Ensure display strings are synced
          composer: editForm.composer,
          lyricist: editForm.lyricist,
          singer: editForm.singer,
          // Sync singular category for legacy/mapping consistency
          category: (songData.categories && songData.categories.length > 0) ? songData.categories[0] : songData.category
      };

      saveCustomSong(artist, song, updatedSongData);

      // Still allow saving views if they were edited via form state
      if (editForm.views !== undefined) {
         setViewCount(artist, song, editForm.views);
      }

      if (artist_bio && artist_bio !== artistData?.bio) {
          const updatedArtist: ArtistDetails = {
              name: artist,
              bio: artist_bio,
              topSongs: artistData?.topSongs || []
          };
          saveCustomArtist(artist, updatedArtist);
          setArtistData(updatedArtist);
      }

      setData(updatedSongData);
      setIsEditing(false);
  };

  const toggleCategorySelection = (cat: string) => {
      setEditForm(prev => {
          const cats = prev.categories || [];
          if (cats.includes(cat)) {
              return { ...prev, categories: cats.filter(c => c !== cat) };
          } else {
              return { ...prev, categories: [...cats, cat] };
          }
      });
  };

  const handleDeleteSong = () => {
      if (!artist || !song) return;
      if (window.confirm("Are you sure you want to delete this lyrics page?")) {
          deleteCustomSong(artist, song);
          navigate('/');
      }
  };

  // Extract video ID for YouTube Embed
  const getYoutubeId = (url: string) => {
      const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
      const match = url.match(regExp);
