export default Home;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getFavorites, FavoriteItem } from '../utils/storage';
import { getSongLyrics } from '../services/geminiService';
import { LyricsData } from '../types';
import { Heart, Mic2, Disc, ArrowRight, Play, X, ChevronLeft, ChevronRight, Loader2, ZoomIn, ZoomOut, Maximize, Minimize, PlayCircle, PauseCircle, ListOrdered, Circle, SkipBack, SkipForward, Settings, Upload, RefreshCw, Image as ImageIcon } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

const FavoritesPage: React.FC = () => {
  const [favorites, setFavorites] = useState<FavoriteItem[]>([]);
  const navigate = useNavigate();
  const { t } = useLanguage();

  // Selection / Ordering State
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [presentationQueue, setPresentationQueue] = useState<FavoriteItem[]>([]);

  // Presentation State
  const [isPresenting, setIsPresenting] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [lyricsData, setLyricsData] = useState<LyricsData | null>(null);
  const [loadingLyrics, setLoadingLyrics] = useState(false);
  const [fontSize, setFontSize] = useState(24); // Default presentation font size set to 24

  // Presentation Customization State
  const [bgImage, setBgImage] = useState<string>('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
  const [bgBlur, setBgBlur] = useState(4);
  const [bgOpacity, setBgOpacity] = useState(50);
  const [showSettings, setShowSettings] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // New Features State
  const [isBrowserFullscreen, setIsBrowserFullscreen] = useState(false);
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Initial Load
    setFavorites(getFavorites());

    // Listen for live updates (e.g. if a song in favorites is deleted or renamed elsewhere)
    const handleContentChange = () => {
        setFavorites(getFavorites());
    };
    window.addEventListener('content-change', handleContentChange);
    return () => {
        window.removeEventListener('content-change', handleContentChange);
    };
  }, []);

  // Filter only songs for presentation
  const allFavoriteSongs = favorites.filter(f => f.type === 'song');

  // The actual list to present: either the custom queue or all favorites
  const slidesToPresent = presentationQueue.length > 0 ? presentationQueue : allFavoriteSongs;

  const fetchSlideLyrics = async (index: number) => {
    setLoadingLyrics(true);
    setLyricsData(null); // Clear previous lyrics while loading

    // Reset Scroll and AutoScroll
    setIsAutoScrolling(false);
    if (scrollContainerRef.current) {
        scrollContainerRef.current.scrollTop = 0;
    }

    const item = slidesToPresent[index];
    if (item) {
        // item.subtext is Artist, item.name is Title
        const data = await getSongLyrics(item.subtext, item.name);
        setLyricsData(data);
    }
    setLoadingLyrics(false);
  };

  const startPresentation = () => {
    if (slidesToPresent.length === 0) return;
    setCurrentIndex(0);
    setIsPresenting(true);
    fetchSlideLyrics(0);
  };

  const nextSlide = useCallback(() => {
    if (currentIndex < slidesToPresent.length - 1) {
      const newIndex = currentIndex + 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex, slidesToPresent.length]);

  const prevSlide = useCallback(() => {
    if (currentIndex > 0) {
      const newIndex = currentIndex - 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex]);

  const closePresentation = useCallback(() => {
    setIsPresenting(false);
    setLyricsData(null);
    setIsAutoScrolling(false);
    setShowSettings(false);
    // Exit native fullscreen if active
    if (document.fullscreenElement) {
        document.exitFullscreen().catch(e => console.error(e));
    }
  }, []);

  const handleZoomIn = useCallback(() => {
    setFontSize(prev => Math.min(prev + 4, 120));
  }, []);

  const handleZoomOut = useCallback(() => {
    setFontSize(prev => Math.max(prev - 4, 16));
  }, []);

  const toggleBrowserFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().then(() => {
            setIsBrowserFullscreen(true);
        }).catch(err => {
            console.error(`Error attempting to enable full-screen mode: ${err}`);
        });
    } else {
        document.exitFullscreen().then(() => {
            setIsBrowserFullscreen(false);
        });
    }
  }, []);

  const toggleAutoScroll = () => {
      setIsAutoScrolling(!isAutoScrolling);
  };

  // Selection Logic
  const toggleSelectionMode = () => {
      setIsSelectionMode(!isSelectionMode);
      setPresentationQueue([]); // Reset queue when toggling
  };

  const handleSelectSong = (item: FavoriteItem) => {
      const existsIdx = presentationQueue.findIndex(i => i.id === item.id);
      if (existsIdx >= 0) {
          // Remove
          const newQueue = [...presentationQueue];
          newQueue.splice(existsIdx, 1);
          setPresentationQueue(newQueue);
      } else {
          // Add to end
          setPresentationQueue([...presentationQueue, item]);
      }
  };

  // Background Settings Handlers
  const handleBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
            setBgImage(reader.result as string);
        };
        reader.readAsDataURL(file);
    }
  };

  const resetSettings = () => {
      setBgImage('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
      setBgBlur(4);
      setBgOpacity(50);
  };

  // Handle Fullscreen change events
  useEffect(() => {
      const handleFsChange = () => {
          setIsBrowserFullscreen(!!document.fullscreenElement);
      };
      document.addEventListener('fullscreenchange', handleFsChange);
      return () => document.removeEventListener('fullscreenchange', handleFsChange);
  }, []);

  // Auto Scroll Effect
  useEffect(() => {
      let interval: ReturnType<typeof setInterval>;
      if (isAutoScrolling && scrollContainerRef.current) {
          interval = setInterval(() => {
              if (scrollContainerRef.current) {
                  // Scroll down by 1px every 50ms
                  scrollContainerRef.current.scrollTop += 1;

                  // Stop if reached bottom
                  if (scrollContainerRef.current.scrollHeight - scrollContainerRef.current.scrollTop === scrollContainerRef.current.clientHeight) {
                      setIsAutoScrolling(false);
                  }
              }
          }, 40);
      }
      return () => clearInterval(interval);
  }, [isAutoScrolling]);

  // Keyboard Navigation
  useEffect(() => {
    if (!isPresenting) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight') {
        nextSlide();
      } else if (e.key === 'ArrowLeft') {
        prevSlide();
      } else if (e.key === 'Escape') {
        if (!document.fullscreenElement) {
            closePresentation();
        }
      } else if (e.key === '+' || e.key === '=') {
        handleZoomIn();
      } else if (e.key === '-') {
        handleZoomOut();
      } else if (e.key === 'f') {
        toggleBrowserFullscreen();
      } else if (e.key === ' ') {
        e.preventDefault(); // Prevent accidental page scroll
        toggleAutoScroll(); // Space to toggle scroll
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPresenting, nextSlide, prevSlide, closePresentation, handleZoomIn, handleZoomOut, toggleBrowserFullscreen, isAutoScrolling]);

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-900';
  };

  // --- Presentation View ---
  if (isPresenting) {
    return (
      <div className="fixed inset-0 z-50 bg-black text-white flex flex-col overflow-hidden">
        {/* Background Layer */}
        <div className="absolute inset-0 z-0">
           <img 
             src={bgImage} 
             alt="Background" 
             className="w-full h-full object-cover transition-all duration-700"
             style={{ filter: `blur(${bgBlur}px)` }}
           />
           {/* Overlay for legibility */}
           <div 
             className="absolute inset-0 bg-black transition-opacity duration-300"
             style={{ opacity: bgOpacity / 100 }}
           ></div>
        </div>

        {/* Toolbar */}
        <div className="flex justify-between items-center p-3 md:p-4 bg-black/40 backdrop-blur-md z-30 absolute top-0 left-0 right-0 transition-opacity hover:opacity-100 opacity-0 md:opacity-100 border-b border-white/10 overflow-visible">
           <div className="text-sm font-medium text-white/80 whitespace-nowrap hidden sm:block">
              {currentIndex + 1} / {slidesToPresent.length}
           </div>

           <div className="flex items-center space-x-2 md:space-x-3 min-w-max mx-auto sm:mx-0">

               {/* Nav Controls */}
               <button 
                  onClick={prevSlide} 
                  disabled={currentIndex === 0}
                  className="p-2 hover:bg-white/20 rounded-full transition-colors disabled:opacity-30" 
                  title="Previous Song"
               >
                   <SkipBack className="w-5 h-5" />
               </button>
               <button 
                  onClick={nextSlide} 
                  disabled={currentIndex === slidesToPresent.length - 1}
                  className="p-2 hover:bg-white/20 rounded-full transition-colors disabled:opacity-30" 
                  title="Next Song"
               >
                   <SkipForward className="w-5 h-5" />
               </button>

               <div className="w-px h-6 bg-white/20 mx-1"></div>

               {/* Scroll Toggle */}
               <button onClick={toggleAutoScroll} className={`p-2 rounded-full transition-colors ${isAutoScrolling ? 'bg-primary text-white' : 'hover:bg-white/20'}`} title="Auto Scroll (Space)">
                   {isAutoScrolling ? <PauseCircle className="w-5 h-5" /> : <PlayCircle className="w-5 h-5" />}
               </button>

               <div className="w-px h-6 bg-white/20 mx-1"></div>

               {/* Font Size */}
               <button onClick={handleZoomOut} className="p-2 hover:bg-white/20 rounded-full transition-colors" title="Zoom Out (-)">
                   <ZoomOut className="w-5 h-5" />
               </button>
               <button onClick={handleZoomIn} className="p-2 hover:bg-white/20 rounded-full transition-colors" title="Zoom In (+)">
                   <ZoomIn className="w-5 h-5" />
               </button>

               <div className="w-px h-6 bg-white/20 mx-1"></div>

               {/* Settings Toggle */}
               <div className="relative">
                   <button 
                        onClick={() => setShowSettings(!showSettings)} 
                        className={`p-2 rounded-full transition-colors ${showSettings ? 'bg-white/20' : 'hover:bg-white/20'}`}
                        title="Presentation Settings"
                   >
                       <Settings className="w-5 h-5" />
                   </button>

                   {/* Settings Dropdown Panel */}
                   {showSettings && (
                       <div className="absolute top-full right-0 mt-2 w-72 bg-slate-900/95 backdrop-blur-xl border border-white/10 rounded-2xl p-4 shadow-2xl z-50 text-left">
                           <div className="space-y-4">
                               <div>
                                   <label className="text-xs font-bold text-slate-400 uppercase mb-2 block">Background Image</label>
                                   <button 
                                        onClick={() => fileInputRef.current?.click()}
                                        className="w-full flex items-center justify-center gap-2 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-sm transition-colors border border-white/5"
                                   >
                                       <Upload className="w-4 h-4" /> Upload Image
                                   </button>
                                   <input 
                                        type="file" 
                                        ref={fileInputRef}
                                        onChange={handleBgUpload}
                                        className="hidden" 
                                        accept="image/*"
                                   />
                               </div>

                               <div>
                                   <div className="flex justify-between text-xs mb-1">
                                       <span className="text-slate-400 font-bold uppercase">Blur</span>
                                       <span className="text-white font-mono">{bgBlur}px</span>
                                   </div>
                                   <input 
                                        type="range" 
                                        min="0" 
                                        max="20" 
