export const getBanners = async (): Promise<Banner[]> => {
    // Try to fetch with order_index if it exists
    const { data } = await supabase
        .from('banners')
        .select('*')
        .order('order_index', { ascending: true }); // Ensure ordering

    return (data || []).map((b: any) => ({
        id: b.id,
        imageUrl: b.image_url,
        title: b.title,
        subtitle: b.subtitle,
        link: b.link,
        orderIndex: b.order_index ?? 0
    }));
};

export const saveBanner = async (banner: Banner) => {
    const payload = {
        image_url: banner.imageUrl,
        title: banner.title,
        subtitle: banner.subtitle,
        link: banner.link,
        order_index: banner.orderIndex ?? 0
    };
    // If ID exists and is UUID, update. If timestamp ID (from localstorage migration), treat as new insert
    if (banner.id && banner.id.length > 20) {
        // Try update
        const { error } = await supabase.from('banners').update(payload).eq('id', banner.id);
        if (error) await supabase.from('banners').insert([payload]);
    } else {
        await supabase.from('banners').insert([payload]);
    }
    window.dispatchEvent(new Event('content-change'));
};

export const updateBannerOrder = async (banners: Banner[]) => {
    const updates = banners.map((b, index) => ({
        id: b.id,
        order_index: index,
        image_url: b.imageUrl,
        title: b.title,
        subtitle: b.subtitle,
        link: b.link
    }));

    const { error } = await supabase.from('banners').upsert(updates);
    if (error) console.error("Error reordering banners:", error);

    window.dispatchEvent(new Event('content-change'));
}

