            <div className="w-full md:w-64 bg-slate-50 md:border-r border-b md:border-b-0 border-slate-200 p-2 md:p-4 flex md:flex-col overflow-x-auto md:overflow-visible space-x-2 md:space-x-0 md:space-y-2 no-scrollbar">

