import { getBanners, getAllCustomSongs, getAnnouncement } from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const Home: React.FC = () => {
  const [data, setData] = useState<HomeData | null>(null);
  const [loading, setLoading] = useState(true);
  const [searchInput, setSearchInput] = useState('');
  const [banners, setBanners] = useState<Banner[]>([]);
  const [currentBannerIndex, setCurrentBannerIndex] = useState(0);
  const [totalSongs, setTotalSongs] = useState(0);
  const [announcement, setAnnouncement] = useState<Announcement | null>(null);
  const navigate = useNavigate();
  const { t } = useLanguage();

  // Updated Publisher ID
  const AD_CLIENT_ID = "ca-pub-9823795221574715"; 
  const AD_SLOT_ID = "1234567890"; // TODO: Create an Ad Unit in AdSense console and replace this

  const fetchData = async () => {
    const trendingResult = await getTrendingContent();
    setData(trendingResult);
    setBanners(await getBanners());
    // Get count of locally added songs
    const customSongs = await getAllCustomSongs();
    setTotalSongs(customSongs.length);
    setAnnouncement(await getAnnouncement());
    setLoading(false);
  };

  useEffect(() => {
    fetchData();

    // Listen for live updates from Admin Dashboard
    const handleContentChange = () => {
        fetchData();
    };
    window.addEventListener('content-change', handleContentChange);
    return () => {
        window.removeEventListener('content-change', handleContentChange);
    };
  }, []);

