export const getAnalytics = async (): Promise<AnalyticsData> => {
    // 1. Fetch comprehensive analytics object
    const { data } = await supabase.from('site_settings').select('value').eq('key', 'analytics').maybeSingle();

    // Default structure
    const analytics = data?.value || { total: 0, daily: {} };

    // If analytics is empty, try to fetch the legacy 'total_visits' to not lose old counts
    if (!data) {
        const { data: oldData } = await supabase.from('site_settings').select('value').eq('key', 'total_visits').maybeSingle();
        if (oldData?.value?.count) {
            analytics.total = oldData.value.count;
        }
    }

    const today = new Date().toISOString().split('T')[0];
    const daily = analytics.daily || {};

    // Helper to sum a range of days
    const sumDays = (startOffset: number, endOffset: number) => {
        let sum = 0;
        for (let i = startOffset; i <= endOffset; i++) {
            const d = new Date();
            d.setDate(d.getDate() - i);
            const key = d.toISOString().split('T')[0];
            sum += (daily[key] || 0);
        }
        return sum;
    };

    return {
        lifetime: analytics.total || 0,
        today: daily[today] || 0,
        thisWeek: sumDays(0, 6), // Last 7 days including today
        lastWeek: sumDays(7, 13) // Days 8-14 ago
    };
};

export const recordVisit = async (): Promise<void> => {
    // 1. Get current analytics data
    let { data } = await supabase.from('site_settings').select('value').eq('key', 'analytics').maybeSingle();
    let analytics = data?.value || { total: 0, daily: {} };

    // If brand new, check legacy total just in case
    if (!data) {
        const { data: oldData } = await supabase.from('site_settings').select('value').eq('key', 'total_visits').maybeSingle();
        if (oldData?.value?.count) {
            analytics.total = oldData.value.count;
        }
    }

    // 2. Update Counts
    const today = new Date().toISOString().split('T')[0];
    const daily = analytics.daily || {};

    daily[today] = (daily[today] || 0) + 1;
    analytics.total = (analytics.total || 0) + 1;

    // Cleanup: Keep only last 365 days to prevent JSON size explosion
    const sortedKeys = Object.keys(daily).sort();
    if (sortedKeys.length > 365) {
        const newDaily: Record<string, number> = {};
        // Keep last 365
        sortedKeys.slice(sortedKeys.length - 365).forEach(k => {
            newDaily[k] = daily[k];
        });
        analytics.daily = newDaily;
    } else {
        analytics.daily = daily;
    }

    // 3. Save back
    await supabase.from('site_settings').upsert({ key: 'analytics', value: analytics });
};

