  }
  return null;
};

// --- QUIZ GENERATION ---
export const generateBibleQuiz = async (level: number): Promise<QuizQuestion[]> => {
    // Using gemini-2.5-flash for speed and structured output
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Scale difficulty based on level (1 to 20)
    let difficultyDescription = "";
    if (level <= 5) difficultyDescription = "easy, Sunday School level";
    else if (level <= 10) difficultyDescription = "moderate, general Bible knowledge";
    else if (level <= 15) difficultyDescription = "hard, specific details and verses";
    else difficultyDescription = "expert, theologian level, obscure facts";

    const prompt = `Generate 10 Bible trivia multiple-choice questions for difficulty level ${level} (${difficultyDescription}).

    Requirements:
    1. Each question must have 4 options.
    2. One option must be the correct answer.
    3. The content must be accurate according to the Bible (KJV/NKJV/NIV).
    4. Provide the correct answer exactly as it appears in the options list.

    Return a valid JSON array of objects.`;

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            question: { type: Type.STRING },
                            options: { type: Type.ARRAY, items: { type: Type.STRING } },
                            correctAnswer: { type: Type.STRING }
                        },
                        required: ["question", "options", "correctAnswer"]
                    }
                }
            }
        });

        if (response.text) {
            const questions = JSON.parse(response.text) as QuizQuestion[];
            return questions;
        }
        return [];
    } catch (e) {
        console.error("Error generating quiz:", e);
        return [];
    }
};

