import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getQuizByLevel } from '../utils/dataManager';
import { QuizQuestion } from '../types';
import Loader from '../components/Loader';
import { ArrowRight, CheckCircle, XCircle, RotateCcw, Home, Trophy, AlertTriangle } from 'lucide-react';

const QuizGamePage: React.FC = () => {
  const { level } = useParams<{ level: string }>();
  const navigate = useNavigate();

  const [questions, setQuestions] = useState<QuizQuestion[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Game State
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [showResult, setShowResult] = useState(false);

  useEffect(() => {
    const loadQuiz = async () => {
        if (!level) return;
        setLoading(true);
        const quiz = await getQuizByLevel(parseInt(level));
        if (quiz && quiz.questions.length > 0) {
            setQuestions(quiz.questions);
        } else {
            setError("This level is not available yet.");
        }
        setLoading(false);
    };
    loadQuiz();
  }, [level]);

  const handleOptionClick = (option: string) => {
      if (isAnswered) return;

      setSelectedOption(option);
      setIsAnswered(true);

      const currentQ = questions[currentQuestionIndex];
      if (option === currentQ.correctAnswer) {
          setScore(prev => prev + 1);
      }
  };

  const handleNext = () => {
      if (currentQuestionIndex < questions.length - 1) {
          setCurrentQuestionIndex(prev => prev + 1);
          setSelectedOption(null);
          setIsAnswered(false);
      } else {
          setShowResult(true);
      }
  };

  if (loading) return <Loader fullScreen text="Preparing questions..." />;

  if (error) return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50 p-4 text-center">
          <AlertTriangle className="w-16 h-16 text-yellow-500 mb-4" />
          <h2 className="text-2xl font-bold text-slate-800 mb-2">Oops!</h2>
          <p className="text-slate-500 mb-6">{error}</p>
          <Link to="/quiz" className="bg-primary text-white px-6 py-2 rounded-lg font-bold">Back to Levels</Link>
      </div>
  );

  // --- RESULT SCREEN ---
  if (showResult) {
      const percentage = Math.round((score / questions.length) * 100);
      let message = "Keep Practicing!";
      if (percentage >= 90) message = "Bible Scholar!";
      else if (percentage >= 70) message = "Great Job!";
      else if (percentage >= 50) message = "Good Effort!";

      return (
          <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-3xl shadow-xl p-8 max-w-md w-full text-center border border-slate-100">
                  <div className="w-24 h-24 mx-auto bg-gradient-to-br from-yellow-400 to-orange-500 rounded-full flex items-center justify-center mb-6 shadow-lg shadow-orange-200">
                      <Trophy className="w-12 h-12 text-white" />
                  </div>

                  <h1 className="text-3xl font-extrabold text-slate-900 mb-2">Level {level} Complete!</h1>
                  <p className="text-slate-500 font-medium mb-6">{message}</p>

                  <div className="bg-slate-50 rounded-xl p-6 mb-8 border border-slate-100">
                      <div className="text-sm text-slate-400 font-bold uppercase tracking-wider mb-1">Your Score</div>
                      <div className="text-5xl font-black text-primary">{score} / {questions.length}</div>
                  </div>

                  <div className="space-y-3">
                      <button 
                        onClick={() => window.location.reload()} 
                        className="w-full flex items-center justify-center py-3 bg-primary text-white rounded-xl font-bold hover:bg-primary/90 transition-colors"
                      >
                          <RotateCcw className="w-5 h-5 mr-2" /> Play Again
                      </button>
                      <Link 
                        to="/quiz" 
                        className="w-full flex items-center justify-center py-3 bg-slate-100 text-slate-700 rounded-xl font-bold hover:bg-slate-200 transition-colors"
                      >
                          <Home className="w-5 h-5 mr-2" /> Back to Levels
                      </Link>
                  </div>
              </div>
          </div>
      );
  }

  // --- GAME SCREEN ---
  const currentQ = questions[currentQuestionIndex];
  const progress = ((currentQuestionIndex + 1) / questions.length) * 100;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col max-w-2xl mx-auto shadow-2xl min-h-screen bg-white">
        {/* Header */}
        <div className="px-6 py-6 border-b border-slate-100 flex justify-between items-center bg-white sticky top-0 z-10">
            <div className="flex flex-col">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">Level {level}</span>
                <span className="text-lg font-bold text-slate-900">Question {currentQuestionIndex + 1}<span className="text-slate-400 text-sm">/{questions.length}</span></span>
            </div>
            <button onClick={() => navigate('/quiz')} className="p-2 bg-slate-100 rounded-full hover:bg-slate-200 text-slate-500">
                <XCircle className="w-6 h-6" />
            </button>
        </div>

        {/* Progress Bar */}
        <div className="h-2 bg-slate-100 w-full">
            <div className="h-full bg-orange-500 transition-all duration-300 ease-out" style={{ width: `${progress}%` }}></div>
        </div>

        {/* Content */}
        <div className="flex-1 p-6 flex flex-col">
            <div className="mb-8">
                <h2 className="text-xl md:text-2xl font-bold text-slate-800 leading-relaxed">
                    {currentQ.question}
                </h2>
            </div>

            <div className="space-y-4 mb-8">
                {currentQ.options.map((option, idx) => {
                    let btnClass = "w-full p-4 rounded-xl border-2 text-left font-medium transition-all transform active:scale-98 flex justify-between items-center ";

                    if (isAnswered) {
                        if (option === currentQ.correctAnswer) {
                            // Correct Answer (Always Green)
                            btnClass += "bg-green-50 border-green-500 text-green-700 shadow-sm";
                        } else if (option === selectedOption) {
                            // Selected Wrong Answer (Red)
                            btnClass += "bg-red-50 border-red-500 text-red-700";
                        } else {
                            // Unselected options
                            btnClass += "bg-white border-slate-100 text-slate-400 opacity-60";
                        }
                    } else {
                        // Default State
                        btnClass += "bg-white border-slate-200 text-slate-700 hover:border-primary hover:bg-indigo-50 hover:text-primary";
                    }

                    return (
                        <button 
                            key={idx} 
                            onClick={() => handleOptionClick(option)}
                            disabled={isAnswered}
                            className={btnClass}
                        >
                            <span>{option}</span>
                            {isAnswered && option === currentQ.correctAnswer && <CheckCircle className="w-5 h-5 text-green-600" />}
                            {isAnswered && option === selectedOption && option !== currentQ.correctAnswer && <XCircle className="w-5 h-5 text-red-600" />}
                        </button>
                    );
                })}
            </div>

            {/* Bottom Controls */}
            <div className="mt-auto">
                <button 
                    onClick={handleNext}
                    disabled={!isAnswered}
                    className={`w-full py-4 rounded-xl font-bold text-lg flex items-center justify-center transition-all ${
                        isAnswered 
                        ? 'bg-primary text-white shadow-lg hover:bg-primary/90' 
                        : 'bg-slate-200 text-slate-400 cursor-not-allowed'
                    }`}
                >
                    {currentQuestionIndex === questions.length - 1 ? 'Finish Quiz' : 'Next Question'}
                    {isAnswered && <ArrowRight className="w-5 h-5 ml-2" />}
                </button>
            </div>
        </div>
    </div>
  );
};

export default QuizGamePage;

import React, { useState, useEffect, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth, logout, getAdmins, createAdmin, deleteAdmin, AdminUser, getUsers, deleteUser } from '../utils/auth';
import { getAllCustomSongs, saveCustomSong, saveCustomArtist, getAllCustomArtists, deleteCustomSong, deleteCustomArtist, getCustomArtist, getBanners, saveBanner, deleteBanner, getCategories, addCategory, updateCategory, deleteCategory, exportAllData, importAllData, BackupData, getSiteLogo, saveSiteLogo, getAnnouncement, saveAnnouncement, getContactInfo, saveContactInfo, updateBannerOrder, getAnalytics, AnalyticsData, getQuizByLevel, saveQuizLevel } from '../utils/dataManager';
import { generateBibleQuiz } from '../services/geminiService';
import { LogOut, Plus, Music, User, Trash2, Edit2, ChevronRight, Eye, Image as ImageIcon, Grid, ImageIcon as BannerIcon, Check, X, Shield, Lock, Download, Upload, Database, AlertTriangle, Users, Settings, Megaphone, Facebook, Search, UserPlus, HelpCircle, Youtube, Instagram, Link as LinkIcon, PenTool, Mic, Loader2, Info, ArrowUp, ArrowDown, Activity, Calendar, Clock, BrainCircuit, Sparkles, Save } from 'lucide-react';
import { Banner, Announcement, Category, ContactInfo, QuizQuestion } from '../types';
import Loader from '../components/Loader';
import ArtistSelector from '../components/ArtistSelector';
import { supabase } from '../supabaseClient';

const AdminDashboard: React.FC = () => {
  const { user, isAuth, loading: authLoading } = useAuth();
  const navigate = useNavigate();
  const userRole = user?.role;
  const isSuperAdmin = userRole === 'SUPER_ADMIN';
  const isRegularUser = userRole === 'USER';

  const [activeTab, setActiveTab] = useState<'overview' | 'songs' | 'artists' | 'banners' | 'categories' | 'contact' | 'admins' | 'users' | 'backup' | 'settings' | 'addSong' | 'addArtist' | 'addBanner' | 'announcement' | 'quiz'>('overview');
  const [customSongs, setCustomSongs] = useState<any[]>([]);
  const [customArtists, setCustomArtists] = useState<any[]>([]);
  const [banners, setBanners] = useState<Banner[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [adminUsers, setAdminUsers] = useState<AdminUser[]>([]);
  const [regularUsers, setRegularUsers] = useState<AdminUser[]>([]);
  const [announcement, setAnnouncement] = useState<Announcement>({ imageUrl: '', link: '', isVisible: false });
  const [contactInfo, setContactInfo] = useState<ContactInfo>({
      missionTitle: '', missionText: '', visionTitle: '', visionText: '',
      email: '', whatsapp: '', facebookUrl: '', footerTitle: '', footerText: ''
  });

  // Analytics
  const [analytics, setAnalytics] = useState<AnalyticsData>({ lifetime: 0, today: 0, thisWeek: 0, lastWeek: 0 });
  const [onlineCount, setOnlineCount] = useState(0);

  // Form States
  const [songForm, setSongForm] = useState({ 
      title: '', 
      artist: '', 
      artists: [] as string[], 
      lyrics_nepali: '', lyrics_roman: '', 
      composer: '', composers: [] as string[], 
      lyricist: '', lyricists: [] as string[], 
      singer: '', singers: [] as string[], 
      views: 0, artist_bio: '', categories: [] as string[],
      youtubeUrl: '', isYoutubeVisible: true,
      language: 'nepali' as 'nepali' | 'hindi' | 'english'
  });
  const [artistForm, setArtistForm] = useState({ 
      name: '', bio: '', topSongs: '', imageUrl: '', 
      facebookUrl: '', instagramUrl: '', youtubeUrl: '',
      isFacebookVisible: true, isInstagramVisible: true, isArtistYoutubeVisible: true
  });
  const [bannerForm, setBannerForm] = useState({ imageUrl: '', title: '', subtitle: '', link: '' });
  const [editingBannerId, setEditingBannerId] = useState<string | null>(null); // For editing banners

  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '' });
  // Local state for quick adding category in Add Song tab
  const [quickCategory, setQuickCategory] = useState('');

  // Quiz State
  const [quizLevel, setQuizLevel] = useState(1);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [isGeneratingQuiz, setIsGeneratingQuiz] = useState(false);

  const [siteLogo, setSiteLogo] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null); 
  const bannerUploadRef = useRef<HTMLInputElement>(null); 

  // Edit Category State
  const [editingCategory, setEditingCategory] = useState<{original: string, current: string, imageUrl: string} | null>(null);

  useEffect(() => {
    if (!authLoading) {
      if (!isAuth) {
        navigate('/login');
      } else if (isRegularUser) {
        // Just in case, if they are user, they can't be here
      } else {
        refreshData();
        setupPresence();
      }
    }
  }, [isAuth, isRegularUser, authLoading, navigate]);

  const setupPresence = () => {
    // Listen to online_users channel to count presence
    const channel = supabase.channel('online_users');
    channel
        .on('presence', { event: 'sync' }, () => {
            const newState = channel.presenceState();
            // Count unique keys (session IDs)
            setOnlineCount(Object.keys(newState).length);
        })
        .subscribe();

    return () => { channel.unsubscribe(); }
  };

  const refreshData = async () => {
    setCustomSongs(await getAllCustomSongs());
    setCustomArtists(await getAllCustomArtists());
    setBanners(await getBanners());
    setCategories(await getCategories());
    setSiteLogo(await getSiteLogo());
    setAnalytics(await getAnalytics());

    const ann = await getAnnouncement();
    if (ann) setAnnouncement(ann);

    const info = await getContactInfo();
    if (info) setContactInfo(info);

    if (isSuperAdmin) {
        setAdminUsers(await getAdmins());
        setRegularUsers(await getUsers());
    }
  };

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const ensureArtistProfile = async (artistName: string, songTitle: string, bio?: string) => {
      const cleanName = artistName.trim();
      if (!cleanName || cleanName.toLowerCase() === 'unknown') return;

      const existingArtist = await getCustomArtist(cleanName);
      const currentSongs = existingArtist?.topSongs || [];

      let updatedSongs = [...currentSongs];
      if (!updatedSongs.includes(songTitle)) {
          updatedSongs.push(songTitle);
      }

      saveCustomArtist(cleanName, {
          name: cleanName,
          bio: bio || existingArtist?.bio || '',
          topSongs: updatedSongs,
          imageUrl: existingArtist?.imageUrl || '',
          facebookUrl: existingArtist?.facebookUrl || '',
          instagramUrl: existingArtist?.instagramUrl || '',
          youtubeUrl: existingArtist?.youtubeUrl || '',
          isFacebookVisible: existingArtist?.isFacebookVisible ?? true,
          isInstagramVisible: existingArtist?.isInstagramVisible ?? true,
          isArtistYoutubeVisible: existingArtist?.isArtistYoutubeVisible ?? true
      });
  };

  const handleAddSong = async (e: React.FormEvent) => {
    e.preventDefault();
    const titleClean = songForm.title.trim();

    // Process Arrays from ArtistSelector
    const artistList = songForm.artists.length > 0 ? songForm.artists : (songForm.artist ? [songForm.artist] : []);
    const composerList = songForm.composers;
    const lyricistList = songForm.lyricists;
    const singerList = songForm.singers;

    // Create display strings (legacy fallback)
    const displayArtist = artistList.length > 0 ? artistList.join(', ') : 'Unknown';
    const displayComposer = composerList.length > 0 ? composerList.join(', ') : '';
    const displayLyricist = lyricistList.length > 0 ? lyricistList.join(', ') : '';
    const displaySinger = singerList.length > 0 ? singerList.join(', ') : '';

    if (!titleClean) return;

    await saveCustomSong(displayArtist, titleClean, {
        lyrics_nepali: songForm.lyrics_nepali,
        lyrics_roman: songForm.lyrics_roman,
        composer: displayComposer || 'Unknown',
        composers: composerList,
        lyricist: displayLyricist || 'Unknown',
        lyricists: lyricistList,
        singer: displaySinger,
        singers: singerList,
        views: songForm.views,
        categories: songForm.categories.length > 0 ? songForm.categories : ['Worship'],
        youtubeUrl: songForm.youtubeUrl.trim(),
        isYoutubeVisible: songForm.isYoutubeVisible,
        artists: artistList,
        language: songForm.language,
        artist: displayArtist
    });

    for (const art of artistList) {
        await ensureArtistProfile(art, titleClean, songForm.artist_bio);
    }

    setSongForm({ 
        title: '', artist: '', artists: [], lyrics_nepali: '', lyrics_roman: '', 
        composer: '', composers: [], lyricist: '', lyricists: [], singer: '', singers: [],
        views: 0, artist_bio: '', categories: [],
        youtubeUrl: '', isYoutubeVisible: true,
        language: 'nepali'
    });
    setActiveTab('songs');
    refreshData();
  };

  const handleQuickAddCategory = async () => {
      if (quickCategory.trim()) {
          const catName = quickCategory.trim();
          const result = await addCategory(catName, '');

          if (result.success) {
              // Update categories list
              const updatedCats = await getCategories();
              setCategories(updatedCats);
              // Add to current selection
              setSongForm(prev => ({
                  ...prev,
                  categories: [...prev.categories, catName]
              }));
              setQuickCategory('');
          } else {
              alert("Error adding category: " + result.error);
          }
      }
  };

  const handleAddArtist = (e: React.FormEvent) => {
    e.preventDefault();
    const nameClean = artistForm.name.trim();
    if (!nameClean) return;

    saveCustomArtist(nameClean, {
        name: nameClean,
        bio: artistForm.bio,
        topSongs: artistForm.topSongs.split(',').map(s => s.trim()).filter(s => s),
        imageUrl: artistForm.imageUrl.trim(),
        facebookUrl: artistForm.facebookUrl.trim(),
        instagramUrl: artistForm.instagramUrl.trim(),
        youtubeUrl: artistForm.youtubeUrl.trim(),
        isFacebookVisible: artistForm.isFacebookVisible,
        isInstagramVisible: artistForm.isInstagramVisible,
        isArtistYoutubeVisible: artistForm.isArtistYoutubeVisible
    });
    setArtistForm({ 
        name: '', bio: '', topSongs: '', imageUrl: '', 
        facebookUrl: '', instagramUrl: '', youtubeUrl: '',
        isFacebookVisible: true, isInstagramVisible: true, isArtistYoutubeVisible: true
    });
    setActiveTab('artists');
    refreshData();
  };

  const handleAddBanner = async (e: React.FormEvent) => {
    e.preventDefault();
    // Use existing ID if editing, else generate new
    const id = editingBannerId || Date.now().toString();

    // Find current index to preserve it if editing, else append
    let orderIndex = 0;
    if (editingBannerId) {
        const existing = banners.find(b => b.id === editingBannerId);
        orderIndex = existing?.orderIndex ?? 0;
    } else {
        orderIndex = banners.length; // Append to end
    }

    await saveBanner({
        id,
        imageUrl: bannerForm.imageUrl || `https://picsum.photos/seed/${id}/1200/400`,
        title: bannerForm.title,
        subtitle: bannerForm.subtitle,
        link: bannerForm.link,
        orderIndex
    });

    setBannerForm({ imageUrl: '', title: '', subtitle: '', link: '' });
    setEditingBannerId(null);
    setActiveTab('banners');
    refreshData();
  };

  const handleEditBanner = (banner: Banner) => {
      setBannerForm({
          imageUrl: banner.imageUrl,
          title: banner.title,
          subtitle: banner.subtitle,
          link: banner.link || ''
      });
      setEditingBannerId(banner.id);
      setActiveTab('addBanner');
  };

  const handleMoveBanner = async (index: number, direction: 'up' | 'down') => {
      if (direction === 'up' && index === 0) return;
      if (direction === 'down' && index === banners.length - 1) return;

      const newBanners = [...banners];
      const targetIndex = direction === 'up' ? index - 1 : index + 1;

      // Swap elements
      [newBanners[index], newBanners[targetIndex]] = [newBanners[targetIndex], newBanners[index]];

      // Update local state immediately for UI response
      setBanners(newBanners);

      // Persist new order
      await updateBannerOrder(newBanners);
  };

  const handleAddCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    if (categoryForm.name.trim()) {
      const result = await addCategory(categoryForm.name.trim(), categoryForm.imageUrl.trim());
      if (result.success) {
          setCategoryForm({ name: '', imageUrl: '' });
          refreshData();
      } else {
          alert("Error adding category: " + result.error);
      }
    }
  };

  const handleBannerFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { 
        alert("File size too large. Please upload an image under 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setBannerForm(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdateCategory = async () => {
    if (editingCategory && editingCategory.current.trim()) {
      await updateCategory(editingCategory.original, editingCategory.current.trim(), editingCategory.imageUrl.trim());
      setEditingCategory(null);
      refreshData();
    }
  };

  const handleDeleteSong = (artist: string, title: string) => {
    if (window.confirm('Delete this custom song?')) {
        deleteCustomSong(artist, title);
        refreshData();
    }
  };

  const handleDeleteArtist = (name: string) => {
    if (window.confirm('Delete this custom artist?')) {
        deleteCustomArtist(name);
        refreshData();
    }
  };

  const handleDeleteBanner = (id: string) => {
    if (window.confirm('Delete this banner?')) {
        deleteBanner(id);
        refreshData();
    }
  };

  const handleDeleteCategory = async (cat: string) => {
    if (window.confirm(`Delete category "${cat}"?`)) {
        await deleteCategory(cat);
        refreshData();
    }
  };

  const handleDeleteAdmin = async (username: string) => {
    if (window.confirm(`Are you sure you want to remove admin access for ${username}?`)) {
        await deleteAdmin(username);
        refreshData();
    }
  };

  const handleDeleteUser = async (username: string) => {
    if (window.confirm(`Are you sure you want to delete user ${username}?`)) {
        await deleteUser(username);
        refreshData();
    }
  };

  const handleSaveSettings = (e: React.FormEvent) => {
      e.preventDefault();
      saveSiteLogo(siteLogo);
      alert('Site settings saved successfully!');
  };

  const handleSaveAnnouncement = (e: React.FormEvent) => {
      e.preventDefault();
      saveAnnouncement(announcement);
      alert('Announcement updated successfully!');
  };

  const handleSaveContactInfo = (e: React.FormEvent) => {
      e.preventDefault();
      saveContactInfo(contactInfo);
      alert('Contact Page info updated successfully!');
  };

  // --- QUIZ HANDLERS ---
  const handleLoadQuiz = async () => {
      setQuizQuestions([]);
      const quiz = await getQuizByLevel(quizLevel);
      if (quiz && quiz.questions.length > 0) {
          setQuizQuestions(quiz.questions);
      } else {
          alert(`No quiz found for Level ${quizLevel}. Click 'Generate' to create one.`);
      }
  };

  const handleGenerateQuiz = async () => {
      if (!window.confirm(`Generate new AI questions for Level ${quizLevel}? This will replace existing questions if not saved.`)) return;

      setIsGeneratingQuiz(true);
      const questions = await generateBibleQuiz(quizLevel);
      setQuizQuestions(questions);
      setIsGeneratingQuiz(false);
  };

  const handleSaveQuiz = async () => {
      if (quizQuestions.length === 0) return;
      try {
          await saveQuizLevel(quizLevel, quizQuestions);
          alert(`Level ${quizLevel} Quiz Saved Successfully!`);
      } catch (e: any) {
          alert(e.message || "Failed to save quiz");
      }
  };

  const handleQuestionChange = (index: number, field: string, value: any) => {
      const updated = [...quizQuestions];
      if (field === 'question') updated[index].question = value;
      else if (field === 'correctAnswer') updated[index].correctAnswer = value;
      else if (field.startsWith('option-')) {
          const optIndex = parseInt(field.split('-')[1]);
          updated[index].options[optIndex] = value;
      }
      setQuizQuestions(updated);
  };

  const handleUploadBackup = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (!file) return;

      if (window.confirm("WARNING: Importing data will overwrite your current songs, artists, and categories. This cannot be undone. Are you sure?")) {
          const reader = new FileReader();
          reader.onload = async (e) => {
              try {
                  const json = JSON.parse(e.target?.result as string) as BackupData;
                  if (await importAllData(json)) {
                      alert("Backup restored successfully! The page will now reload.");
                      window.location.reload();
                  } else {
                      alert("Failed to restore backup. Invalid file format.");
                  }
              } catch (error) {
                  console.error(error);
                  alert("Error parsing backup file.");
              }
          };
          reader.readAsText(file);
      }

      if (fileInputRef.current) {
          fileInputRef.current.value = '';
      }
  };

  const handleDownloadBackup = async () => {
      const data = await exportAllData();
      const jsonString = JSON.stringify(data, null, 2);
      const blob = new Blob([jsonString], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `sansarplus_backup_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
  };

  // --- RENDERING ---

  if (authLoading) {
      return <Loader fullScreen text="Verifying admin credentials..." />;
  }

  if (isRegularUser) {
      return (
          <div className="min-h-screen flex items-center justify-center bg-red-50 p-4 text-center">
              <div className="max-w-md">
                  <AlertTriangle className="w-16 h-16 text-red-500 mx-auto mb-4" />
                  <h1 className="text-2xl font-bold text-red-700">Access Denied</h1>
                  <p className="text-red-600 mb-6">You do not have permission to view the Admin Dashboard.</p>
                  <Link to="/" className="bg-red-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-red-700">Return Home</Link>
              </div>
          </div>
      );
  }

  const getSongColorClass = (lang: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-800';
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <div className="bg-slate-900 text-white py-8 px-4">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
            <div>
                <h1 className="text-3xl font-bold flex items-center">
                    Admin Dashboard
                    {isSuperAdmin && <span className="ml-3 text-xs bg-yellow-500 text-black px-2 py-1 rounded font-bold uppercase tracking-wider">Super Admin</span>}
                </h1>
                <p className="text-slate-400">Manage custom content</p>
            </div>
            <button onClick={handleLogout} className="flex items-center text-red-400 hover:text-red-300">
                <LogOut className="w-5 h-5 mr-2" /> Logout
            </button>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 -mt-8">
