export const getCategories = async (): Promise<Category[]> => {
    const { data } = await supabase.from('categories').select('*').order('name');
    if (!data || data.length === 0) {
        return [
            { name: 'Worship' },
            { name: 'Praise' },
            { name: 'Hymn' }
        ];
    }
    return data.map((c: any) => ({
        name: c.name,
        imageUrl: c.image_url
    }));
};

export const addCategory = async (category: string, imageUrl?: string): Promise<{success: boolean, error?: string}> => {
    const payload: any = { 
        name: category
    };
    if (imageUrl && imageUrl.trim()) {
        payload.image_url = imageUrl;
    }

    try {
        const { error } = await supabase.from('categories').insert([payload]);

        if (error) {
            console.error("Failed to add category:", error);
            const msg = error.message || error.details || JSON.stringify(error);
            return { success: false, error: msg };
        }

        window.dispatchEvent(new Event('content-change'));
        return { success: true };
    } catch (err: any) {
        console.error("Unexpected error adding category:", err);
        return { success: false, error: err.message || String(err) };
    }
};

export const updateCategory = async (oldCat: string, newCat: string, imageUrl?: string) => {
    const payload: any = { name: newCat };
    if (imageUrl && imageUrl.trim()) {
        payload.image_url = imageUrl;
    }

    await supabase.from('categories').update(payload).eq('name', oldCat);
    window.dispatchEvent(new Event('content-change'));
};

export const deleteCategory = async (category: string) => {
    await supabase.from('categories').delete().eq('name', category);
    window.dispatchEvent(new Event('content-change'));
};

