export const getSongLyrics = async (artist: string, title: string): Promise<LyricsData | null> => {
  const localData = await getCustomSong(artist, title);
  if (localData) {
    // Views might be outdated in the song doc, fetch fresh view count
    const currentViews = await getViewCount(artist, title);
    return { ...localData, views: currentViews };
  }
  return null;
};

