export const getBanners = async (): Promise<Banner[]> => {
    let { data, error } = await supabase
        .from('banners')
        .select('*')
        .order('order_index', { ascending: true }); 

    if (error) {
        console.warn('Sorting by order_index failed, falling back to created_at', error);
        const res = await supabase.from('banners').select('*').order('created_at', { ascending: true });
        data = res.data;
    }

    return (data || []).map((b: any) => ({
        id: b.id,
        imageUrl: b.image_url,
        title: b.title,
        subtitle: b.subtitle,
        link: b.link,
        orderIndex: b.order_index ?? 0
    }));
};

export const saveBanner = async (banner: Banner) => {
    const basePayload = {
        image_url: banner.imageUrl,
        title: banner.title,
        subtitle: banner.subtitle,
        link: banner.link
    };

    const payloadWithOrder = { ...basePayload, order_index: banner.orderIndex ?? 0 };
    const isUpdate = banner.id && banner.id.length > 20;

    try {
        if (isUpdate) {
            const { error } = await supabase.from('banners').update(payloadWithOrder).eq('id', banner.id);
            if (error) throw error;
        } else {
            const { error } = await supabase.from('banners').insert([payloadWithOrder]);
            if (error) throw error;
        }
    } catch (e: any) {
        console.warn("Banner save failed, attempting fallback without order_index", e);
        if (isUpdate) {
            await supabase.from('banners').update(basePayload).eq('id', banner.id);
        } else {
            await supabase.from('banners').insert([basePayload]);
        }
    }
    window.dispatchEvent(new Event('content-change'));
};

export const updateBannerOrder = async (banners: Banner[]) => {
    const updates = banners.map((b, index) => ({
        id: b.id,
