                    )}
                </div>
            </div>

            {/* Right Col: Top Songs */}
            <div className="lg:col-span-2">
                <h2 className="text-2xl font-bold text-slate-900 mb-6 flex items-center">
                    <Disc className="mr-3 text-primary" /> 
                    {isAutoGenerated ? 'Credited Songs' : 'Popular Tracks'}
                </h2>

                {isEditing && (
                    <div className="mb-4">
                        <label className="block text-sm font-bold text-slate-500 mb-1">Edit Songs (Legacy list, comma separated)</label>
                        <input 
                            type="text" 
                            className="w-full border p-3 rounded"
                            value={topSongsString}
                            onChange={e => setTopSongsString(e.target.value)}
                        />
                        <p className="text-xs text-slate-400 mt-1">Note: Songs added via Admin Dashboard automatically appear below and don't need to be added here.</p>
                    </div>
                )}

                <div className="space-y-3">
                    {displaySongs.length > 0 ? (
                        displaySongs.map((song, idx) => (
                            <Link 
                                key={`${song.title}-${song.mainArtist}-${idx}`}
                                to={`/lyrics/${encodeURIComponent(song.mainArtist)}/${encodeURIComponent(song.title)}`}
                                className="flex items-center justify-between p-4 rounded-xl bg-white hover:bg-slate-50 border border-slate-200 hover:border-primary/50 group transition-all shadow-sm hover:shadow-md"
                            >
                                <div className="flex items-center space-x-4">
                                    <span className="text-slate-400 font-mono w-6 text-center text-lg">{idx + 1}</span>
                                    <div>
                                        <div className="flex items-center flex-wrap gap-2 mb-0.5">
                                            <span className={`font-semibold transition-colors text-lg block ${getSongColorClass(song.language)}`}>{localize(song.title)}</span>
                                            {/* Role Badges */}
                                            {song.roles.filter(r => r !== 'Main Artist').map(role => renderRoleBadge(role))}
                                        </div>

                                        {song.mainArtist.toLowerCase() !== artist.name.toLowerCase() && (
                                            <span className="text-xs text-slate-400">by <span className="font-bold">{localize(song.mainArtist)}</span></span>
                                        )}
                                    </div>
                                </div>
                                <span className="text-xs text-slate-500 px-3 py-1 border border-slate-200 rounded-full group-hover:border-primary/50 group-hover:text-primary transition-colors bg-slate-50">
                                    View Lyrics
                                </span>
                            </Link>
                        ))
                    ) : (
                        <p className="text-slate-500 italic">No songs found for this artist.</p>
                    )}
                </div>

                {/* Ad Unit: Bottom of Song List */}
                {!isEditing && (
                    <div className="mt-8 no-print">
                        <AdSense client={AD_CLIENT_ID} slot={AD_SLOT_ID} className="bg-white rounded-xl shadow-sm border border-slate-100 p-4" />
                    </div>
                )}
            </div>
       </div>
    </div>
  );
};

export default ArtistPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { User, Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, Flag, X, Edit, Trash2, Save, Printer, Tag, Youtube, Mic2 } from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { saveCustomSong, deleteCustomSong, incrementViewCount, setViewCount, saveCustomArtist, getCategories, getAllCustomSongs } from '../utils/dataManager';
import AdSense from '../components/AdSense';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { artist, song } = useParams<{ artist: string; song: string }>();
  const [data, setData] = useState<LyricsData | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(16); // Default font size set to minimum
  const [availableCategories, setAvailableCategories] = useState<string[]>([]);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { localize } = useLanguage();

  // Updated Publisher ID
  const AD_CLIENT_ID = "ca-pub-5650710840100252"; 
  const AD_SLOT_ID = "1234567890"; // TODO: Create an Ad Unit in AdSense console and replace this

  // Auth & Editing
  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const navigate = useNavigate();

  // Extended edit form
  const [editForm, setEditForm] = useState<LyricsData & { artist_bio?: string }>({
      lyrics_nepali: '',
      lyrics_roman: '',
      composer: '',
      composers: [],
      lyricist: '',
      lyricists: [],
      singer: '',
      singers: [],
      views: 0,
      artist_bio: '',
      category: '',
      categories: [],
      youtubeUrl: '',
      isYoutubeVisible: true,
      artist: '', // Main Artist field for editing
      artists: []
  });

  // Feedback Modal State
  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('lyrics');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      if (artist && song) {
        setLoading(true);
        // Await the categories since getCategories is async
        const cats = await getCategories();
        // Map objects to names for the dropdown
        setAvailableCategories(cats.map(c => c.name));

        // Parallel Fetch
        const [lyricsResult, artistResult, allSongs] = await Promise.all([
            getSongLyrics(artist, song),
            getArtistDetails(artist),
            getAllCustomSongs()
        ]);

        setData(lyricsResult);
        setArtistData(artistResult);

        // Calculate Related Songs (Same Artist), EXCLUDING if artist is 'Unknown'
        if (allSongs && artist && artist.toLowerCase() !== 'unknown') {
            const related = allSongs
                .filter(s => (s.artist === artist || (s.artists && s.artists.includes(artist))) && s.title !== song)
                .sort((a, b) => (b.views || 0) - (a.views || 0)) // Sort by popularity
                .slice(0, 5);
            setRelatedSongs(related);
        } else {
            setRelatedSongs([]);
        }

        if (lyricsResult) {
            // Handle legacy category vs new categories array
            let initialCats = lyricsResult.categories || [];
            if (initialCats.length === 0 && lyricsResult.category) {
                initialCats = [lyricsResult.category];
            }

            // Flatten credits for editing if arrays exist, otherwise use string
            const composerStr = lyricsResult.composers && lyricsResult.composers.length > 0 
                ? lyricsResult.composers.join(', ') 
                : lyricsResult.composer || '';

            const lyricistStr = lyricsResult.lyricists && lyricsResult.lyricists.length > 0 
                ? lyricsResult.lyricists.join(', ') 
                : lyricsResult.lyricist || '';

            const singerStr = lyricsResult.singers && lyricsResult.singers.length > 0 
                ? lyricsResult.singers.join(', ') 
                : lyricsResult.singer || '';

            setEditForm({ 
                ...lyricsResult, 
                title: song, // Ensure current title is set
                artist: artist, // Ensure current artist is set
                views: lyricsResult.views || 0,
                artist_bio: artistResult?.bio || '',
                category: lyricsResult.category || 'Worship',
                categories: initialCats,
                composer: composerStr,
                lyricist: lyricistStr,
                singer: singerStr,
                youtubeUrl: lyricsResult.youtubeUrl || '',
                isYoutubeVisible: lyricsResult.isYoutubeVisible !== false // Default true if undefined
            });
        }

        setIsFav(isFavorite(generateId('song', song, artist)));
        setLoading(false);

        // Keep tracking views in background, but don't display
        incrementViewCount(artist, song);
      }
    };
    fetchData();
  }, [artist, song]);

  const handleFavorite = () => {
    if (!data || !artist || !song) return;
    const item = {
        id: generateId('song', song, artist),
        type: 'song' as const,
        name: song,
        subtext: artist,
        language: data.language // Save language to favorites for correct color display
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePrint = () => {
    window.print();
  };

  const handleZoomIn = () => {
    setFontSize(prev => Math.min(prev + 4, 64));
  };

  const handleZoomOut = () => {
    setFontSize(prev => Math.max(prev - 2, 16));
  };

  const submitFeedback = (e: React.FormEvent) => {
    e.preventDefault();
    setTimeout(() => {
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
            setFeedbackType('lyrics');
        }, 2000);
    }, 500);
  };

  // --- Admin Functions ---
  const handleSaveEdit = async () => {
      if (!artist || !song) return;

      const { artist_bio, ...songData } = editForm;

      // Convert inputs to arrays for credits
      const composers = editForm.composer.split(',').map(s => s.trim()).filter(s => s);
      const lyricists = editForm.lyricist.split(',').map(s => s.trim()).filter(s => s);
      const singers = editForm.singer.split(',').map(s => s.trim()).filter(s => s);

      const updatedSongData = {
          ...songData,
          // Ensure main artist is updated if changed in form
          artist: editForm.artist || artist,
          composers: composers.length > 0 ? composers : [],
          lyricists: lyricists.length > 0 ? lyricists : [],
          singers: singers.length > 0 ? singers : [],
          // Ensure display strings are synced
          composer: editForm.composer,
          lyricist: editForm.lyricist,
          singer: editForm.singer,
          // Sync singular category for legacy/mapping consistency
          category: (songData.categories && songData.categories.length > 0) ? songData.categories[0] : songData.category
      };

      // Pass the original artist/song to find record, and new data (potentially with new artist/title) to update
      await saveCustomSong(artist, song, updatedSongData);

      // Check if artist or title changed, if so navigate to new URL
      const newArtist = updatedSongData.artist;
      // editForm does not have a 'title' field input displayed, but we can access `song` (original)
      // Assuming for now user might not be renaming Title via this UI, but we can allow it if we added a title input
      // Let's check `editForm.artist` against param `artist`
      if (newArtist !== artist) {
          setIsEditing(false);
          navigate(`/lyrics/${encodeURIComponent(newArtist)}/${encodeURIComponent(song)}`, { replace: true });
          return;
      }

      // Still allow saving views if they were edited via form state
      if (editForm.views !== undefined) {
         setViewCount(artist, song, editForm.views);
      }

      if (artist_bio && artist_bio !== artistData?.bio && artist.toLowerCase() !== 'unknown') {
          const updatedArtist: ArtistDetails = {
              name: artist,
              bio: artist_bio,
              topSongs: artistData?.topSongs || []
          };
          saveCustomArtist(artist, updatedArtist);
          setArtistData(updatedArtist);
      }

      setData(updatedSongData);
      setIsEditing(false);
  };

  const toggleCategorySelection = (cat: string) => {
      setEditForm(prev => {
          const cats = prev.categories || [];
          if (cats.includes(cat)) {
              return { ...prev, categories: cats.filter(c => c !== cat) };
          } else {
              return { ...prev, categories: [...cats, cat] };
          }
      });
  };

  const handleDeleteSong = () => {
      if (!artist || !song) return;
      if (window.confirm("Are you sure you want to delete this lyrics page?")) {
          deleteCustomSong(artist, song);
          navigate('/');
      }
  };

  // Extract video ID for YouTube Embed
  const getYoutubeId = (url: string) => {
      const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
      const match = url.match(regExp);
      return (match && match[2].length === 11) ? match[2] : null;
  };

  const currentUrl = window.location.href;
  const shareTitle = `Check out "${song}" by ${artist} on SansarPlus`;

  const socialLinks = [
    {
        name: 'WhatsApp',
        url: `https://wa.me/?text=${encodeURIComponent(shareTitle + ' ' + currentUrl)}`,
        color: 'hover:bg-[#25D366] hover:text-white text-[#25D366] bg-[#25D366]/10',
        icon: <svg viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.008-.57-.008-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
    },
    {
        name: 'Facebook',
        url: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(currentUrl)}`,
        color: 'hover:bg-[#1877F2] hover:text-white text-[#1877F2] bg-[#1877F2]/10',
        icon: <svg viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5"><path d="M9.101 23.691v-7.98H6.627v-3.667h2.474v-1.58c0-4.085 1.848-5.978 5.858-5.978.401 0 .955.042 1.468.103a8.68 8.68 0 0 1 1.141.195v3.325a8.623 8.623 0 0 0-.653-.036c-2.148 0-2.971.956-2.971 3.594v.411h3.085l-.005 3.633-3.08 3.667v7.98h-4.843Z"/></svg>
    },
    {
        name: 'X',
        url: `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareTitle)}&url=${encodeURIComponent(currentUrl)}`,
        color: 'hover:bg-black hover:text-white text-black bg-gray-100',
        icon: <svg viewBox="0 0 24 24" fill="currentColor" className="w-4 h-4"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>
    },
  ];

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-900';
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data || !artist || !song) return <div className="text-slate-500 text-center pt-20">Lyrics not found.</div>;

  // Determine categories to show
  const displayCategories = data.categories && data.categories.length > 0 
      ? data.categories 
      : (data.category ? [data.category] : []);

  const youtubeId = data.youtubeUrl ? getYoutubeId(data.youtubeUrl) : null;
  const showYoutube = youtubeId && (data.isYoutubeVisible !== false);

  // Helper for rendering multiple credits
  const renderCredits = (names: string[] | string) => {
      const list = Array.isArray(names) && names.length > 0 ? names : (names ? [names as string] : []);
      if (list.length === 0 || (list.length === 1 && list[0].toLowerCase() === 'unknown')) return <span className="text-slate-400 text-sm italic">Unknown</span>;

      return (
          <div className="flex flex-wrap gap-2">
              {list.map((name, idx) => (
                  <React.Fragment key={idx}>
                      {idx > 0 && <span className="text-slate-300">,</span>}
                      {name.toLowerCase() === 'unknown' ? (
                          <span className="text-slate-900 font-bold">{localize(name)}</span>
                      ) : (
                          <Link to={`/artist/${encodeURIComponent(name)}`} className="text-slate-900 font-bold hover:text-primary transition-colors block">
                              {localize(name)}
                          </Link>
                      )}
                  </React.Fragment>
              ))}
          </div>
      );
  };

  const composersList = data.composers && data.composers.length > 0 ? data.composers : data.composer;
  const lyricistsList = data.lyricists && data.lyricists.length > 0 ? data.lyricists : data.lyricist;
  const singersList = data.singers && data.singers.length > 0 ? data.singers : data.singer;

