  };

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-800';
  };

  // Custom Colors for Top 10 Ranks
  const rankColors = [
    'text-yellow-500', // 1
    'text-slate-400',  // 2
    'text-amber-600',  // 3
    'text-blue-500',   // 4
    'text-emerald-500',// 5
    'text-purple-500', // 6
