                                        className="flex-1 border p-1 rounded text-sm"
                                        value={editForm.instagramUrl || ''}
                                        onChange={e => setEditForm({...editForm, instagramUrl: e.target.value})}
                                        placeholder="Instagram URL"
                                    />
                                    <input 
                                        type="checkbox" 
                                        checked={editForm.isInstagramVisible} 
                                        onChange={e => setEditForm({...editForm, isInstagramVisible: e.target.checked})}
                                    />
                                </div>

                                {/* YT */}
                                <div className="flex items-center gap-2">
                                    <Youtube className="w-4 h-4 text-red-500"/>
                                    <input 
                                        type="text" 
                                        className="flex-1 border p-1 rounded text-sm"
                                        value={editForm.youtubeUrl || ''}
                                        onChange={e => setEditForm({...editForm, youtubeUrl: e.target.value})}
                                        placeholder="YouTube URL"
                                    />
                                    <input 
                                        type="checkbox" 
                                        checked={editForm.isArtistYoutubeVisible} 
                                        onChange={e => setEditForm({...editForm, isArtistYoutubeVisible: e.target.checked})}
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-bold text-slate-500 mb-1">Biography</label>
                                <textarea 
                                    className="w-full h-64 border p-2 rounded"
                                    value={editForm.bio}
                                    onChange={e => setEditForm({...editForm, bio: e.target.value})}
                                />
                            </div>
                        </div>
                    ) : (
                        <p className="text-slate-600 leading-loose text-sm md:text-base mb-4">
                            {artist.bio || "No biography available."}
                        </p>
                    )}
                </div>
            </div>

            {/* Right Col: Top Songs */}
            <div className="lg:col-span-2">
                <h2 className="text-2xl font-bold text-slate-900 mb-6 flex items-center">
                    <Disc className="mr-3 text-primary" /> 
                    {isAutoGenerated ? 'Credited Songs' : 'Popular Tracks'}
                </h2>

                {isEditing && (
                    <div className="mb-4">
                        <label className="block text-sm font-bold text-slate-500 mb-1">Edit Songs (Legacy list, comma separated)</label>
                        <input 
                            type="text" 
                            className="w-full border p-3 rounded"
                            value={topSongsString}
                            onChange={e => setTopSongsString(e.target.value)}
                        />
                        <p className="text-xs text-slate-400 mt-1">Note: Songs added via Admin Dashboard automatically appear below and don't need to be added here.</p>
                    </div>
                )}

                <div className="space-y-3">
                    {displaySongs.length > 0 ? (
                        displaySongs.map((song, idx) => (
                            <Link 
                                key={`${song.title}-${song.mainArtist}-${idx}`}
                                to={`/lyrics/${encodeURIComponent(song.mainArtist)}/${encodeURIComponent(song.title)}`}
                                className="flex items-center justify-between p-4 rounded-xl bg-white hover:bg-slate-50 border border-slate-200 hover:border-primary/50 group transition-all shadow-sm hover:shadow-md"
                            >
