                        </div>
                    </div>

                    {/* Credits Editing */}
                    <div className="col-span-2 md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Composers (comma separated)</label>
                        <input 
                            type="text" 
                            className="w-full border p-2 rounded bg-white text-sm" 
