                        value={searchInput}
                        onChange={(e) => setSearchInput(e.target.value)}
                    />
                    <Search className="absolute left-4 md:left-5 top-3.5 md:top-5 w-5 h-5 md:w-6 md:h-6 text-slate-400 group-focus-within:text-slate-500 transition-colors" />
