// --- SONGS ---
export const getAllCustomSongs = async (): Promise<any[]> => {
    const { data, error } = await supabase
        .from('songs')
        .select('*');

    if (error) {
        console.error('Error fetching songs:', error);
        return [];
    }

    return data.map((s: any) => {
        let cats = s.categories;
        if (!cats) {
            cats = s.category ? [s.category] : [];
        }
        return {
            ...s,
            id: s.id, 
            lyrics_nepali: s.lyrics_nepali,
            lyrics_roman: s.lyrics_roman,
            youtubeUrl: s.youtube_url,
            isYoutubeVisible: s.is_youtube_visible,
            artists: s.artists || [s.artist],
            composers: s.composers || [],
            lyricists: s.lyricists || [],
            singers: s.singers || [],
            categories: cats
        };
    });
};

export const getCustomSong = async (artist: string, title: string): Promise<any | null> => {
    const { data, error } = await supabase
        .from('songs')
        .select('*')
        .ilike('title', title)
        .ilike('artist', artist)
        .maybeSingle();

    if (error || !data) return null;

    return {
        ...data,
        youtubeUrl: data.youtube_url,
        isYoutubeVisible: data.is_youtube_visible,
    };
};

export const saveCustomSong = async (artist: string, title: string, data: LyricsData) => {
    const existing = await getCustomSong(artist, title);

    const newTitle = data.title || title;
    const newArtist = data.artist || artist;

    const payload = {
        title: newTitle,
        artist: newArtist,
        artists: data.artists || [newArtist],
        lyrics_nepali: data.lyrics_nepali,
        lyrics_roman: data.lyrics_roman,
        composer: data.composer,
        composers: data.composers,
        lyricist: data.lyricist,
        lyricists: data.lyricists,
        singer: data.singer,
        singers: data.singers,
        views: data.views,
        category: data.category,
        categories: data.categories,
        youtube_url: data.youtubeUrl,
        is_youtube_visible: data.isYoutubeVisible,
        language: data.language
    };

    if (existing) {
        await supabase.from('songs').update(payload).eq('id', existing.id);
    } else {
        await supabase.from('songs').insert([payload]);
    }
    window.dispatchEvent(new Event('content-change'));
};

export const deleteCustomSong = async (artist: string, title: string) => {
    const existing = await getCustomSong(artist, title);
    if (existing) {
        await supabase.from('songs').delete().eq('id', existing.id);
        window.dispatchEvent(new Event('content-change'));
    }
};

// --- ARTISTS ---
export const getAllCustomArtists = async (): Promise<any[]> => {
    const { data: dbData } = await supabase.from('artists').select('*');

    const dbArtists = (dbData || [])
        .filter((a: any) => a.name.toLowerCase() !== 'unknown')
        .map((a: any) => ({
            ...a,
            imageUrl: a.image_url,
            topSongs: a.top_songs || [],
            facebookUrl: a.facebook_url,
            instagramUrl: a.instagram_url,
            youtubeUrl: a.youtube_url,
            isFacebookVisible: a.is_facebook_visible,
            isInstagramVisible: a.is_instagram_visible,
            isArtistYoutubeVisible: a.is_artist_youtube_visible,
            isRegistered: true 
        }));

    const { data: songs } = await supabase
        .from('songs')
        .select('artist, artists, composers, lyricists, singers, composer, lyricist, singer');

    const registeredNames = new Set(dbArtists.map((a: any) => a.name.toLowerCase()));
    const virtualMap = new Map<string, any>();

    const processName = (rawName: any) => {
        if (!rawName) return;
        const name = String(rawName).trim();
        if (!name || name.toLowerCase() === 'unknown') return;

        if (registeredNames.has(name.toLowerCase())) return;

        const lower = name.toLowerCase();
        if (!virtualMap.has(lower)) {
            virtualMap.set(lower, {
                id: `virtual-${lower}`,
                name: name,
                imageUrl: '',
                topSongs: [],
                isRegistered: false
            });
        }
    };

    songs?.forEach((s: any) => {
        if (Array.isArray(s.artists)) s.artists.forEach(processName);
        if (Array.isArray(s.composers)) s.composers.forEach(processName);
        if (Array.isArray(s.lyricists)) s.lyricists.forEach(processName);
        if (Array.isArray(s.singers)) s.singers.forEach(processName);

        processName(s.artist);
        if ((!s.composers || s.composers.length === 0) && s.composer) s.composer.split(',').forEach(processName);
        if ((!s.lyricists || s.lyricists.length === 0) && s.lyricist) s.lyricist.split(',').forEach(processName);
        if ((!s.singers || s.singers.length === 0) && s.singer) s.singer.split(',').forEach(processName);
    });

    const virtualArtists = Array.from(virtualMap.values());

    return [...dbArtists, ...virtualArtists]
        .sort((a, b) => a.name.localeCompare(b.name));
};

