export const addCategory = async (category: string, imageUrl?: string, hideTitle?: boolean): Promise<{success: boolean, error?: string}> => {
    const payload: any = { 
        name: category,
        image_url: imageUrl || null,
        hide_title: hideTitle || false
    };

    try {
        const { error } = await supabase.from('categories').insert([payload]);

        if (error) {
            console.error("Failed to add category:", error);
            // If the error specifically mentions the missing column, tell the user
            if (error.message.includes("hide_title") || error.code === "42703") {
                return { success: false, error: "Database needs update. Please run: ALTER TABLE categories ADD COLUMN hide_title BOOLEAN DEFAULT FALSE;" };
            }
            return { success: false, error: error.message };
        }

        window.dispatchEvent(new Event('content-change'));
        return { success: true };
    } catch (err: any) {
        console.error("Unexpected error adding category:", err);
        return { success: false, error: err.message };
    }
};

