                                            <p className="text-[10px] text-slate-400 uppercase font-bold tracking-wider">{cat.hideTitle ? 'Title Hidden' : 'Title Visible'}</p>
                                        </div>
                                    </div>

                                    {editingCategory?.original === cat.name ? (
                                        <div className="absolute inset-0 bg-white p-3 z-20 flex flex-col gap-2">
                                            <div className="flex gap-2">
                                                <input className="flex-1 text-sm border p-1 rounded" value={editingCategory.current} onChange={e => setEditingCategory({...editingCategory, current: e.target.value})} />
