export const addCategory = async (category: string, imageUrl?: string, hideTitle?: boolean): Promise<{success: boolean, error?: string}> => {
    try {
        const payload: any = { name: category };
        // Only include optional fields if the table has them
        if (imageUrl !== undefined) payload.image_url = imageUrl || null;
        if (hideTitle !== undefined) payload.hide_title = hideTitle || false;

        const { error } = await supabase.from('categories').insert([payload]);

        if (error) {
            console.error("Supabase Error adding category:", error);
            // Specifically detect column missing error
            if (error.message.includes('hide_title') || error.code === '42703') {
                return { success: false, error: "Database table is missing the 'hide_title' column. Please run the SQL fix in your Supabase dashboard." };
            }
            return { success: false, error: error.message };
        }

        window.dispatchEvent(new Event('content-change'));
        return { success: true };
    } catch (err: any) {
        return { success: false, error: err.message };
    }
};

