  const getSongColorClass = (lang: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-800';
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <div className="bg-slate-900 text-white py-8 px-4">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
            <div>
                <h1 className="text-3xl font-bold flex items-center">Admin Dashboard {isSuperAdmin && <span className="ml-3 text-xs bg-yellow-500 text-black px-2 py-1 rounded font-bold">SUPER ADMIN</span>}</h1>
                <p className="text-slate-400">Manage site content</p>
            </div>
            <button onClick={handleLogout} className="flex items-center text-red-400 hover:text-red-300"><LogOut className="w-5 h-5 mr-2" /> Logout</button>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 -mt-8">
        <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col md:flex-row min-h-[600px]">
            <div className="w-full md:w-64 bg-slate-50 border-r border-slate-200 p-4 space-y-1">
                <button onClick={() => setActiveTab('overview')} className={`w-full flex items-center p-3 rounded-lg text-sm font-bold ${activeTab === 'overview' ? 'bg-indigo-100 text-indigo-800' : 'text-slate-600 hover:bg-slate-200'}`}><Activity className="w-4 h-4 mr-2" /> Analytics</button>
                <div className="pt-4 pb-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest px-3">Content</div>
                <button onClick={() => setActiveTab('songs')} className={`w-full flex items-center justify-between p-3 rounded-lg text-sm font-bold ${activeTab === 'songs' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}><span className="flex items-center"><Music className="w-4 h-4 mr-2" /> Songs</span><span className="text-xs">{customSongs.length}</span></button>
                <button onClick={() => setActiveTab('artists')} className={`w-full flex items-center justify-between p-3 rounded-lg text-sm font-bold ${activeTab === 'artists' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}><span className="flex items-center"><User className="w-4 h-4 mr-2" /> Artists</span><span className="text-xs">{customArtists.length}</span></button>
                <button onClick={() => setActiveTab('banners')} className={`w-full flex items-center justify-between p-3 rounded-lg text-sm font-bold ${activeTab === 'banners' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}><span className="flex items-center"><BannerIcon className="w-4 h-4 mr-2" /> Banners</span><span className="text-xs">{banners.length}</span></button>
                <button onClick={() => setActiveTab('categories')} className={`w-full flex items-center justify-between p-3 rounded-lg text-sm font-bold ${activeTab === 'categories' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}><span className="flex items-center"><Grid className="w-4 h-4 mr-2" /> Categories</span><span className="text-xs">{categories.length}</span></button>
                <button onClick={() => setActiveTab('announcement')} className={`w-full flex items-center p-3 rounded-lg text-sm font-bold ${activeTab === 'announcement' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}><Megaphone className="w-4 h-4 mr-2" /> Popup</button>
                <button onClick={() => setActiveTab('contact')} className={`w-full flex items-center p-3 rounded-lg text-sm font-bold ${activeTab === 'contact' ? 'bg-primary/10 text-primary' : 'text-slate-600 hover:bg-slate-100'}`}><Info className="w-4 h-4 mr-2" /> Info Page</button>
                {isSuperAdmin && (
                    <div className="pt-6">
                        <div className="pb-2 text-[10px] font-bold text-yellow-600 uppercase tracking-widest px-3">System</div>
                        <button onClick={() => setActiveTab('admins')} className={`w-full flex items-center p-3 rounded-lg text-sm font-bold ${activeTab === 'admins' ? 'bg-yellow-50 text-yellow-700' : 'text-slate-600 hover:bg-yellow-50/50'}`}><Shield className="w-4 h-4 mr-2" /> Admins</button>
                        <button onClick={() => setActiveTab('backup')} className={`w-full flex items-center p-3 rounded-lg text-sm font-bold ${activeTab === 'backup' ? 'bg-blue-50 text-blue-700' : 'text-slate-600 hover:bg-blue-50/50'}`}><Database className="w-4 h-4 mr-2" /> Backup</button>
                        <button onClick={() => setActiveTab('settings')} className={`w-full flex items-center p-3 rounded-lg text-sm font-bold ${activeTab === 'settings' ? 'bg-slate-100 text-slate-900' : 'text-slate-600 hover:bg-slate-100'}`}><Settings className="w-4 h-4 mr-2" /> Settings</button>
                    </div>
                )}
                <div className="pt-6">
                    <button onClick={() => setActiveTab('addSong')} className="w-full flex items-center p-3 bg-primary text-white rounded-lg text-sm font-bold shadow-md hover:scale-105 transition-transform mb-2"><Plus className="w-4 h-4 mr-2" /> New Song</button>
                </div>
            </div>

            <div className="flex-1 p-8 overflow-y-auto max-h-[800px]">
                {activeTab === 'overview' && (
                    <div className="space-y-6">
                        <h2 className="text-2xl font-bold text-slate-800">Analytics Overview</h2>
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                            <div className="bg-gradient-to-br from-green-500 to-emerald-600 rounded-xl p-4 text-white shadow-lg"><Activity className="w-6 h-6 mb-2" /><h3 className="text-3xl font-extrabold">{onlineCount}</h3><p className="text-white/80 text-xs font-bold uppercase">Online Now</p></div>
                            <div className="bg-white rounded-xl p-4 border border-slate-200 shadow-sm"><Clock className="w-6 h-6 text-blue-500 mb-2" /><h3 className="text-3xl font-extrabold text-slate-800">{analytics.today}</h3><p className="text-slate-500 text-xs font-bold uppercase">Today's Visits</p></div>
                            <div className="bg-white rounded-xl p-4 border border-slate-200 shadow-sm"><Calendar className="w-6 h-6 text-purple-500 mb-2" /><h3 className="text-3xl font-extrabold text-slate-800">{analytics.thisWeek}</h3><p className="text-slate-500 text-xs font-bold uppercase">This Week</p></div>
                            <div className="bg-white rounded-xl p-4 border border-slate-200 shadow-sm"><Database className="w-6 h-6 text-orange-500 mb-2" /><h3 className="text-3xl font-extrabold text-slate-800">{analytics.lifetime.toLocaleString()}</h3><p className="text-slate-500 text-xs font-bold uppercase">Total Lifetime</p></div>
                        </div>
                    </div>
                )}

                {activeTab === 'songs' && (
                    <div className="space-y-4">
                        <div className="flex items-center justify-between mb-4">
                            <h2 className="text-xl font-bold text-slate-800">Custom Songs</h2>
                            <button onClick={() => setActiveTab('addSong')} className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center"><Plus className="w-4 h-4 mr-1" /> Add New</button>
                        </div>
                        {customSongs.length === 0 ? (
                            <div className="text-center py-12 bg-slate-50 rounded-xl border-2 border-dashed border-slate-200"><Music className="w-12 h-12 text-slate-300 mx-auto mb-2" /><p className="text-slate-500">No custom songs found.</p></div>
