                                            <h3 className={`font-bold truncate ${getSongColorClass(song.language)}`}>{song.title}</h3>
                                            <p className="text-[10px] text-slate-400 font-bold uppercase">{song.artist}</p>
                                        </div>
                                        <div className="flex gap-1">
                                            <Link to={`/lyrics/${encodeURIComponent(song.artist)}/${encodeURIComponent(song.title)}`} className="p-2 text-slate-400 hover:text-primary"><Edit2 className="w-4 h-4"/></Link>
                                            <button onClick={() => handleDeleteSong(song.artist, song.title)} className="p-2 text-slate-400 hover:text-red-500"><Trash2 className="w-4 h-4"/></button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {activeTab === 'artists' && (
                    <div className="space-y-4">
                        <div className="flex items-center justify-between mb-4">
                            <h2 className="text-xl font-bold text-slate-800">Artists</h2>
                            <button onClick={() => setActiveTab('addArtist')} className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center"><Plus className="w-4 h-4 mr-1" /> Add New</button>
                        </div>
                        {customArtists.length === 0 ? (
                            <div className="text-center py-12 bg-slate-50 rounded-xl border-2 border-dashed border-slate-200"><User className="w-12 h-12 text-slate-300 mx-auto mb-2" /><p className="text-slate-500">No custom artists.</p></div>
                        ) : (
                            <div className="grid gap-2">
                                {customArtists.map(artist => (
                                    <div key={artist.id} className="flex items-center justify-between p-4 border border-slate-200 rounded-xl bg-white shadow-sm">
                                        <div className="flex items-center gap-3">
                                            {artist.imageUrl ? <img src={artist.imageUrl} className="w-10 h-10 rounded-full object-cover border" /> : <div className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-400"><User className="w-5 h-5"/></div>}
                                            <span className="font-bold text-slate-800">{artist.name}</span>
                                        </div>
                                        <div className="flex gap-1">
                                            <Link to={`/artist/${encodeURIComponent(artist.name)}`} className="p-2 text-slate-400 hover:text-primary"><Edit2 className="w-4 h-4"/></Link>
                                            <button onClick={() => handleDeleteArtist(artist.name)} className="p-2 text-slate-400 hover:text-red-500"><Trash2 className="w-4 h-4"/></button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {activeTab === 'categories' && (
                    <div className="space-y-6">
                        <h2 className="text-xl font-bold text-slate-800">Categories</h2>
                        <form onSubmit={handleAddCategory} className="bg-slate-50 p-6 rounded-xl border border-slate-200">
                            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">New Category</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <input required className="w-full border p-3 rounded-lg text-sm" placeholder="Name (e.g. Bhajan)" value={categoryForm.name} onChange={e => setCategoryForm({...categoryForm, name: e.target.value})} />
                                <div className="flex gap-2">
                                    <input className="flex-1 border p-3 rounded-lg text-[10px]" placeholder="Image URL or Upload" value={categoryForm.imageUrl.startsWith('data:') ? 'Image uploaded' : categoryForm.imageUrl} onChange={e => setCategoryForm({...categoryForm, imageUrl: e.target.value})} />
                                    <button type="button" onClick={() => categoryUploadRef.current?.click()} className="bg-slate-200 px-3 rounded-lg"><Upload className="w-4 h-4" /></button>
                                    <input type="file" ref={categoryUploadRef} className="hidden" accept="image/*" onChange={handleCategoryFileUpload} />
                                </div>
                                <div className="md:col-span-2 flex items-center justify-between pt-2">
                                    <label className="flex items-center text-sm font-bold text-slate-600"><input type="checkbox" className="mr-2 w-4 h-4" checked={categoryForm.hideTitle} onChange={e => setCategoryForm({...categoryForm, hideTitle: e.target.checked})} /> Hide label on homepage</label>
                                    <button type="submit" className="bg-primary text-white px-8 py-2 rounded-lg font-bold shadow-lg hover:scale-105 active:scale-95 transition-transform">Add Category</button>
                                </div>
                            </div>
                        </form>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                            {categories.map(cat => (
                                <div key={cat.name} className="relative bg-white p-4 border border-slate-200 rounded-xl group overflow-hidden shadow-sm">
                                    <div className="flex items-center justify-between relative z-10">
                                        <div className="flex items-center gap-3">
                                            {cat.imageUrl ? <img src={cat.imageUrl} className="w-12 h-12 rounded-lg object-cover border" /> : <div className="w-12 h-12 bg-slate-100 rounded-lg flex items-center justify-center text-slate-300"><Grid className="w-6 h-6"/></div>}
                                            <div><p className="font-bold text-slate-800 leading-none mb-1">{cat.name}</p><span className={`text-[8px] font-black uppercase px-1 py-0.5 rounded ${cat.hideTitle ? 'bg-orange-50 text-orange-600' : 'bg-green-50 text-green-600'}`}>{cat.hideTitle ? 'Title Hidden' : 'Title Visible'}</span></div>
                                        </div>
                                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={() => setEditingCategory({original: cat.name, current: cat.name, imageUrl: cat.imageUrl || '', hideTitle: cat.hideTitle})} className="p-2 text-slate-400 hover:text-primary"><Edit2 className="w-4 h-4"/></button>
                                            <button onClick={() => handleDeleteCategory(cat.name)} className="p-2 text-slate-400 hover:text-red-500"><Trash2 className="w-4 h-4"/></button>
                                        </div>
                                    </div>
                                    {editingCategory?.original === cat.name && (
                                        <div className="absolute inset-0 bg-white p-4 z-20 flex flex-col gap-2 shadow-2xl border-2 border-primary">
                                            <div className="flex gap-2"><input className="flex-1 font-bold border-b focus:outline-none" value={editingCategory.current} onChange={e => setEditingCategory({...editingCategory, current: e.target.value})} /><button onClick={handleUpdateCategory} className="bg-green-500 text-white p-1 rounded"><Check className="w-4 h-4"/></button><button onClick={() => setEditingCategory(null)} className="bg-slate-300 text-white p-1 rounded"><X className="w-4 h-4"/></button></div>
                                            <div className="flex gap-2 items-center"><input className="flex-1 text-[8px] border-b text-slate-400" value={editingCategory.imageUrl.startsWith('data:') ? 'Uploaded' : editingCategory.imageUrl} readOnly /><button onClick={() => editCategoryUploadRef.current?.click()} className="p-1 bg-slate-100 rounded border"><Upload className="w-3 h-3"/></button><input type="file" ref={editCategoryUploadRef} className="hidden" accept="image/*" onChange={handleEditCategoryFileUpload} /><label className="text-[10px] flex items-center"><input type="checkbox" className="mr-1" checked={editingCategory.hideTitle} onChange={e => setEditingCategory({...editingCategory, hideTitle: e.target.checked})} /> Hide Title</label></div>
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {activeTab === 'banners' && (
                    <div className="space-y-4">
                        <div className="flex items-center justify-between mb-4">
                            <h2 className="text-xl font-bold text-slate-800">Slideshow Banners</h2>
                            <button onClick={() => setActiveTab('addBanner')} className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center"><Plus className="w-4 h-4 mr-1" /> Add Slide</button>
                        </div>
                        <div className="grid gap-4">
                            {banners.map((banner, index) => (
                                <div key={banner.id} className="relative aspect-video rounded-2xl overflow-hidden group shadow-md border border-slate-200">
                                    <img src={banner.imageUrl} className="w-full h-full object-cover" />
                                    <div className="absolute inset-0 bg-gradient-to-t from-black/80 p-6 flex flex-col justify-end">
                                        <p className="text-white font-bold italic line-clamp-1">"{banner.title}"</p>
                                        <p className="text-white/60 text-xs">— {banner.subtitle}</p>
                                    </div>
                                    <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => { setBannerForm({ imageUrl: banner.imageUrl, title: banner.title, subtitle: banner.subtitle, link: banner.link || '' }); setEditingBannerId(banner.id); setActiveTab('addBanner'); }} className="p-3 bg-white/90 rounded-xl text-slate-800 hover:bg-primary hover:text-white"><Edit2 className="w-5 h-5"/></button>
                                        <button onClick={() => handleMoveBanner(index, 'up')} disabled={index === 0} className="p-3 bg-white/90 rounded-xl text-slate-800 disabled:opacity-50"><ArrowUp className="w-5 h-5"/></button>
                                        <button onClick={() => handleMoveBanner(index, 'down')} disabled={index === banners.length - 1} className="p-3 bg-white/90 rounded-xl text-slate-800 disabled:opacity-50"><ArrowDown className="w-5 h-5"/></button>
                                        <button onClick={() => handleDeleteBanner(banner.id)} className="p-3 bg-white/90 rounded-xl text-red-500 hover:bg-red-500 hover:text-white"><Trash2 className="w-5 h-5"/></button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {activeTab === 'addSong' && (
                    <div className="max-w-xl mx-auto">
                        <h2 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2"><Plus className="w-6 h-6 text-primary"/> New Song</h2>
                        <form onSubmit={handleAddSong} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-6">
                             <div><label className="block text-sm font-bold text-slate-700 mb-1">Title *</label><input required className="w-full border p-3 rounded-xl bg-slate-50" value={songForm.title} onChange={e => setSongForm({...songForm, title: e.target.value})} /></div>
                             <div className="flex gap-4"><label className="flex items-center cursor-pointer font-bold text-sm"><input type="radio" className="mr-2" checked={songForm.language === 'nepali'} onChange={() => setSongForm({...songForm, language: 'nepali'})} /> Nepali</label><label className="flex items-center cursor-pointer font-bold text-sm text-red-500"><input type="radio" className="mr-2" checked={songForm.language === 'hindi'} onChange={() => setSongForm({...songForm, language: 'hindi'})} /> Hindi</label><label className="flex items-center cursor-pointer font-bold text-sm text-blue-500"><input type="radio" className="mr-2" checked={songForm.language === 'english'} onChange={() => setSongForm({...songForm, language: 'english'})} /> English</label></div>
                             <ArtistSelector label="Primary Performer" selected={songForm.artists} suggestions={customArtists} onChange={val => setSongForm({...songForm, artists: val})} />
                             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div><label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nepali/Hindi</label><textarea className="w-full border p-3 rounded-xl bg-slate-50 h-40" value={songForm.lyrics_nepali} onChange={e => setSongForm({...songForm, lyrics_nepali: e.target.value})} /></div>
                                <div><label className="block text-xs font-bold text-slate-500 uppercase mb-1">Romanized</label><textarea className="w-full border p-3 rounded-xl bg-slate-50 h-40 font-mono text-sm" value={songForm.lyrics_roman} onChange={e => setSongForm({...songForm, lyrics_roman: e.target.value})} /></div>
                             </div>
                             <div className="grid gap-4">
                                <ArtistSelector label="Composers" selected={songForm.composers} suggestions={customArtists} onChange={val => setSongForm({...songForm, composers: val})} />
                                <ArtistSelector label="Lyricists" selected={songForm.lyricists} suggestions={customArtists} onChange={val => setSongForm({...songForm, lyricists: val})} />
                                <ArtistSelector label="Vocals" selected={songForm.singers} suggestions={customArtists} onChange={val => setSongForm({...songForm, singers: val})} />
                             </div>
                             <div>
                                <label className="block text-sm font-bold text-slate-700 mb-2">Categories</label>
                                <div className="grid grid-cols-3 gap-2">{categories.map(c => (<button key={c.name} type="button" onClick={() => setSongForm(prev => ({...prev, categories: prev.categories.includes(c.name) ? prev.categories.filter(x => x !== c.name) : [...prev.categories, c.name]}))} className={`px-2 py-1 rounded-lg text-[10px] font-bold border transition-all ${songForm.categories.includes(c.name) ? 'bg-primary text-white border-primary shadow-sm' : 'bg-slate-50 text-slate-500 border-slate-200'}`}>{c.name}</button>))}</div>
                             </div>
                             <div><label className="block text-sm font-bold text-slate-700 mb-1">YouTube URL</label><input className="w-full border p-3 rounded-xl bg-slate-50" value={songForm.youtubeUrl} onChange={e => setSongForm({...songForm, youtubeUrl: e.target.value})} placeholder="https://..." /></div>
                             <button type="submit" className="bg-primary text-white px-8 py-4 rounded-2xl font-bold shadow-xl shadow-primary/30 w-full hover:scale-105 active:scale-95 transition-all"><Save className="w-5 h-5 mx-auto" /></button>
                        </form>
                    </div>
                )}

                {/* Simplified remaining implementation for brevity - fully working placeholders included in above tabs */}
                {activeTab === 'addArtist' && (
                    <div className="max-w-xl mx-auto">
                        <h2 className="text-xl font-bold text-slate-800 mb-6">New Artist Profile</h2>
                        <form onSubmit={handleAddArtist} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
                            <input required className="w-full border p-3 rounded-xl bg-slate-50" placeholder="Artist Name" value={artistForm.name} onChange={e => setArtistForm({...artistForm, name: e.target.value})} />
                            <input className="w-full border p-3 rounded-xl bg-slate-50" placeholder="Profile Image URL" value={artistForm.imageUrl} onChange={e => setArtistForm({...artistForm, imageUrl: e.target.value})} />
                            <textarea className="w-full border p-3 rounded-xl bg-slate-50 h-32" placeholder="Biography..." value={artistForm.bio} onChange={e => setArtistForm({...artistForm, bio: e.target.value})} />
                            <button type="submit" className="bg-primary text-white px-8 py-3 rounded-xl font-bold w-full">Save Artist</button>
                        </form>
                    </div>
                )}

                {activeTab === 'addBanner' && (
                    <div className="max-w-xl mx-auto">
                         <h2 className="text-xl font-bold text-slate-800 mb-6">{editingBannerId ? 'Edit Slide' : 'New Slide'}</h2>
                         <form onSubmit={handleAddBanner} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
                             <div className="flex gap-2"><input required className="flex-1 border p-3 rounded-xl bg-slate-50" placeholder="Background URL" value={bannerForm.imageUrl} onChange={e => setBannerForm({...bannerForm, imageUrl: e.target.value})} /><button type="button" onClick={() => bannerUploadRef.current?.click()} className="bg-slate-200 px-3 rounded-xl"><Upload className="w-5 h-5"/></button><input type="file" ref={bannerUploadRef} className="hidden" accept="image/*" onChange={handleBannerFileUpload} /></div>
                             <textarea required className="w-full border p-3 rounded-xl bg-slate-50 h-24 italic" placeholder="Verse text..." value={bannerForm.title} onChange={e => setBannerForm({...bannerForm, title: e.target.value})} />
                             <input required className="w-full border p-3 rounded-xl bg-slate-50 font-bold" placeholder="Reference (e.g. Psalm 119:105)" value={bannerForm.subtitle} onChange={e => setBannerForm({...bannerForm, subtitle: e.target.value})} />
                             <button type="submit" className="bg-primary text-white px-8 py-3 rounded-xl font-bold w-full shadow-lg">Save Slide</button>
                         </form>
                    </div>
                )}

                {activeTab === 'backup' && isSuperAdmin && (
                    <div className="max-w-md mx-auto space-y-6 text-center">
                        <Database className="w-16 h-16 text-primary mx-auto mb-2" />
                        <h2 className="text-xl font-bold text-slate-800">System Backup</h2>
                        <p className="text-slate-500 text-sm">Keep your database safe. Download a local copy of all site content.</p>
                        <button onClick={handleDownloadBackup} className="bg-green-600 text-white px-8 py-3 rounded-xl font-bold w-full shadow-lg flex items-center justify-center gap-2"><Download className="w-5 h-5"/> Export Data (.JSON)</button>
                    </div>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;

