To set up your Supabase database correctly for **SansarPlus**, you need to create the tables, define the user roles, and set up the automatic profile creation trigger.

Copy and paste the following code into your **Supabase SQL Editor** and click **Run**.

```sql
-- 1. Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. Create Custom Types for Roles
DO $$ BEGIN
    CREATE TYPE user_role AS ENUM ('SUPER_ADMIN', 'ADMIN', 'USER');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

-- 3. Create Profiles Table (Syncs with Auth)
CREATE TABLE IF NOT EXISTS profiles (
  id UUID REFERENCES auth.users ON DELETE CASCADE PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  name TEXT,
  role user_role DEFAULT 'USER',
  profile_picture TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Create Songs Table
CREATE TABLE IF NOT EXISTS songs (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  title TEXT NOT NULL,
  artist TEXT NOT NULL,
  artists TEXT[] DEFAULT '{}',
  lyrics_nepali TEXT,
  lyrics_roman TEXT,
  composer TEXT,
  composers TEXT[] DEFAULT '{}',
  lyricist TEXT,
  lyricists TEXT[] DEFAULT '{}',
  singer TEXT,
  singers TEXT[] DEFAULT '{}',
  views INTEGER DEFAULT 0,
  category TEXT,
  categories TEXT[] DEFAULT '{}',
  youtube_url TEXT,
  is_youtube_visible BOOLEAN DEFAULT TRUE,
  language TEXT DEFAULT 'nepali',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. Create Artists Table
CREATE TABLE IF NOT EXISTS artists (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT UNIQUE NOT NULL,
  bio TEXT,
  top_songs TEXT[] DEFAULT '{}',
  image_url TEXT,
  facebook_url TEXT,
  instagram_url TEXT,
  youtube_url TEXT,
  is_facebook_visible BOOLEAN DEFAULT TRUE,
  is_instagram_visible BOOLEAN DEFAULT TRUE,
  is_artist_youtube_visible BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. Create Categories Table
CREATE TABLE IF NOT EXISTS categories (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  name TEXT UNIQUE NOT NULL,
  image_url TEXT,
  hide_title BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 7. Create Banners Table
CREATE TABLE IF NOT EXISTS banners (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  image_url TEXT NOT NULL,
  title TEXT,
  subtitle TEXT,
  link TEXT,
  order_index INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 8. Create Site Settings Table (For Analytics, Logo, Popups)
CREATE TABLE IF NOT EXISTS site_settings (
  key TEXT PRIMARY KEY,
  value JSONB NOT NULL,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 9. Setup Row Level Security (RLS)
-- Enable RLS on all tables
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE songs ENABLE ROW LEVEL SECURITY;
ALTER TABLE artists ENABLE ROW LEVEL SECURITY;
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE banners ENABLE ROW LEVEL SECURITY;
ALTER TABLE site_settings ENABLE ROW LEVEL SECURITY;

-- PUBLIC READ POLICIES
CREATE POLICY "Public Read Songs" ON songs FOR SELECT USING (true);
CREATE POLICY "Public Read Artists" ON artists FOR SELECT USING (true);
CREATE POLICY "Public Read Categories" ON categories FOR SELECT USING (true);
CREATE POLICY "Public Read Banners" ON banners FOR SELECT USING (true);
CREATE POLICY "Public Read Site Settings" ON site_settings FOR SELECT USING (true);
CREATE POLICY "Public Read Profiles" ON profiles FOR SELECT USING (true);

-- ADMIN WRITE POLICIES (Only SUPER_ADMIN and ADMIN can modify)
CREATE POLICY "Admin All Songs" ON songs FOR ALL TO authenticated 
  USING (EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('ADMIN', 'SUPER_ADMIN')));

CREATE POLICY "Admin All Artists" ON artists FOR ALL TO authenticated 
  USING (EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('ADMIN', 'SUPER_ADMIN')));

CREATE POLICY "Admin All Categories" ON categories FOR ALL TO authenticated 
  USING (EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('ADMIN', 'SUPER_ADMIN')));

CREATE POLICY "Admin All Banners" ON banners FOR ALL TO authenticated 
  USING (EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('ADMIN', 'SUPER_ADMIN')));

CREATE POLICY "Admin All Site Settings" ON site_settings FOR ALL TO authenticated 
  USING (EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('ADMIN', 'SUPER_ADMIN')));

-- USER PROFILE POLICY (Users can update their own profile)
CREATE POLICY "Users Update Own Profile" ON profiles FOR UPDATE TO authenticated
  USING (auth.uid() = id);

-- 10. Automatic Profile Creation Trigger
-- This function runs every time a user signs up via Supabase Auth
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger AS $$
BEGIN
  INSERT INTO public.profiles (id, email, name, role)
  VALUES (new.id, new.email, new.raw_user_meta_data->>'name', 'USER');
  RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Trigger the function
CREATE OR REPLACE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- 11. Helper: Promote a user to SUPER_ADMIN (Run this manually after signing up)
-- UPDATE profiles SET role = 'SUPER_ADMIN' WHERE email = 'your-email@gmail.com';
```

### Next Steps:
1. **Sign up**: Go to the app and create an account.
2. **Promote yourself**: Come back to the Supabase SQL editor and run:
   `UPDATE profiles SET role = 'SUPER_ADMIN' WHERE email = 'your-email@example.com';`
3. **Login to Admin**: You can now access the Admin Dashboard to add your content!

