                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="pt-4">
                                <h3 className="font-bold text-slate-800 mb-4 flex items-center uppercase text-xs tracking-widest"><Shield className="w-4 h-4 mr-2" /> Security</h3>
                                <div className="bg-white border border-slate-200 rounded-2xl p-6">
                                    <p className="text-sm text-slate-600 mb-4">Site administration is restricted to authorized users. Only Super Admins can manage database backups and critical system settings.</p>
                                    <div className="flex items-center gap-2 text-xs font-bold text-emerald-600 bg-emerald-50 w-fit px-3 py-1.5 rounded-full border border-emerald-100">
                                        <Lock className="w-3.5 h-3.5" /> All System Connections Secure
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}
                </>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

