                            <button type="submit" className="w-full bg-primary text-white py-4 rounded-2xl font-bold shadow-xl shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center"><Save className="w-5 h-5 mr-2" /> Publish Song</button>
                        </form>
                    </div>
                )}
                </>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

