      try {
        const base64 = await fileToBase64(file);
        if (target === 'banner') setBannerForm(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'announcement') setAnnouncement(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'logo') setSiteLogo(base64);
        else if (target === 'category') setCategoryForm(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'edit-category') setEditingCategory(prev => prev ? { ...prev, imageUrl: base64 } : null);

        // Reset file input value to allow re-uploading same file
        e.target.value = '';
      } catch (err) {
        alert("File conversion failed.");
      }
    }
  };

  const ensureArtistProfile = async (artistName: string, songTitle: string) => {
      const cleanName = artistName.trim();
      if (!cleanName || cleanName.toLowerCase() === 'unknown') return;
      const existingArtist = await getCustomArtist(cleanName);
      const currentSongs = existingArtist?.topSongs || [];
      let updatedSongs = [...currentSongs];
      if (!updatedSongs.includes(songTitle)) updatedSongs.push(songTitle);

      await saveCustomArtist(cleanName, {
          name: cleanName,
          bio: existingArtist?.bio || '',
          topSongs: updatedSongs,
          imageUrl: existingArtist?.imageUrl || '',
          facebookUrl: existingArtist?.facebookUrl || '',
          instagramUrl: existingArtist?.instagramUrl || '',
          youtubeUrl: existingArtist?.youtubeUrl || '',
          isFacebookVisible: existingArtist?.isFacebookVisible ?? true,
          isInstagramVisible: existingArtist?.isInstagramVisible ?? true,
          isArtistYoutubeVisible: existingArtist?.isArtistYoutubeVisible ?? true
      });
  };

