export const saveBanner = async (banner: Banner) => {
    // Determine if this is a new banner or an edit
    const isTempId = banner.id.length > 10; // Simple check: timestamp-based IDs are long strings

    const payload: any = {
        image_url: banner.imageUrl,
        title: banner.title,
        subtitle: banner.subtitle,
        link: banner.link,
        order_index: banner.orderIndex
    };

    if (isTempId) {
        // For new banners, don't send the temporary ID if the DB generates it
        // Or if the DB expects a specific format, ensure it matches.
        // Assuming auto-incrementing ID or UUID in Supabase
        const { error } = await supabase.from('banners').insert([payload]);
        if (error) console.error("Banner insert error:", error);
    } else {
        // Editing existing
        const { error } = await supabase.from('banners').update(payload).eq('id', banner.id);
        if (error) console.error("Banner update error:", error);
    }

    window.dispatchEvent(new Event('content-change'));
};

