export const getBanners = async (): Promise<Banner[]> => {
    const { data } = await supabase.from('banners').select('*').order('order_index');
    return (data || []).map((b: any) => ({
        id: b.id.toString(),
        imageUrl: b.image_url,
        title: b.title,
        subtitle: b.subtitle,
        link: b.link,
        orderIndex: b.order_index
    }));
};

export const saveBanner = async (banner: Banner) => {
    // If ID starts with 'temp_', it's a new banner from the frontend
    const isNew = banner.id.startsWith('temp_');

    const payload: any = {
        image_url: banner.imageUrl,
        title: banner.title,
        subtitle: banner.subtitle,
        link: banner.link,
        order_index: banner.orderIndex || 0
    };

    if (isNew) {
        // Insert new - let Supabase generate the real ID
        const { error } = await supabase.from('banners').insert([payload]);
        if (error) {
            console.error("Banner insert error:", error);
            throw error;
        }
    } else {
        // Update existing using the numeric/string ID from Supabase
        const { error } = await supabase.from('banners').update(payload).eq('id', banner.id);
        if (error) {
            console.error("Banner update error:", error);
            throw error;
        }
    }

    window.dispatchEvent(new Event('content-change'));
};

export const deleteBanner = async (id: string) => {
    await supabase.from('banners').delete().eq('id', id);
    window.dispatchEvent(new Event('content-change'));
};

