    e.preventDefault();
    if (!bannerForm.imageUrl) {
        alert("Banner image is required!");
        return;
    }

    try {
        setLoading(true);
        const id = editingBannerId || `temp_${Date.now()}`;
        const existing = banners.find(b => b.id === editingBannerId);

        await saveBanner({ 
            id, imageUrl: bannerForm.imageUrl, title: bannerForm.title, 
            subtitle: bannerForm.subtitle, link: bannerForm.link, 
            orderIndex: existing?.orderIndex ?? banners.length 
        });

        setBannerForm({ imageUrl: '', title: '', subtitle: '', link: '' });
        setEditingBannerId(null);
        // Dispatching content-change event handles refresh, so we just wait for the alert
        alert("Banner saved successfully!");
    } catch (err: any) {
        console.error("Save banner error details:", err);
        alert("Failed to save banner: " + (err.message || "Please check your Supabase table schema and RLS policies."));
    } finally {
        setLoading(false);
    }
  };

