// --- HELPER: Safe JSON Parse ---
const safeJsonParse = (val: string | null, fallback: any) => {
    if (!val) return fallback;
    try {
        return JSON.parse(val);
    } catch (e) {
        console.error("JSON Parse failed for setting:", e);
        return fallback;
    }
};

// --- SONGS ---
export const getAllCustomSongs = async (): Promise<any[]> => {
    const { data, error } = await supabase.from('songs').select('*');
    if (error) {
        console.error("Fetch songs error:", error.message);
        return [];
    }
    return (data || []).map((s: any) => ({
        ...s,
        youtubeUrl: s.youtube_url,
        isYoutubeVisible: s.is_youtube_visible,
    }));
};

export const getCustomSong = async (artist: string, title: string): Promise<any | null> => {
    const { data, error } = await supabase
        .from('songs')
        .select('*')
        .ilike('title', title)
        .ilike('artist', artist)
        .maybeSingle();
    if (error || !data) return null;
    return {
        ...data,
        youtubeUrl: data.youtube_url,
        isYoutubeVisible: data.is_youtube_visible,
    };
};

export const saveCustomSong = async (artist: string, title: string, data: LyricsData) => {
    const existing = await getCustomSong(artist, title);
    const payload = {
        title: data.title || title,
        artist: data.artist || artist,
        artists: data.artists || [data.artist || artist],
        lyrics_nepali: data.lyrics_nepali,
        lyrics_roman: data.lyrics_roman,
        composer: data.composer,
        composers: data.composers,
        lyricist: data.lyricist,
        lyricists: data.lyricists,
        singer: data.singer,
        singers: data.singers,
        views: data.views,
        category: (data.categories && data.categories.length > 0) ? data.categories[0] : data.category,
        categories: data.categories,
        youtube_url: data.youtubeUrl,
        is_youtube_visible: data.is_youtube_visible,
        language: data.language
    };

    let result;
    if (existing) {
        result = await supabase.from('songs').update(payload).eq('id', existing.id);
    } else {
        result = await supabase.from('songs').insert([payload]);
    }

    if (result.error) throw new Error(result.error.message);
    window.dispatchEvent(new Event('content-change'));
};

export const deleteCustomSong = async (artist: string, title: string) => {
    const existing = await getCustomSong(artist, title);
    if (existing) {
        const { error } = await supabase.from('songs').delete().eq('id', existing.id);
        if (error) throw new Error(error.message);
        window.dispatchEvent(new Event('content-change'));
    }
};

