    const { data, error } = await supabase.from('banners').select('*');
    if (error) {
        console.error("Fetch banners error:", error.message);
        return [];
    }
    return (data || []).map((b: any) => ({
        id: b.id.toString(),
        imageUrl: b.image_url,
        title: b.title,
        subtitle: b.subtitle,
        link: b.link,
        orderIndex: b.order_index || 0
    }));
};

export const saveBanner = async (banner: Banner) => {
    const isNew = banner.id.startsWith('temp_');

    const payload: any = {
        image_url: banner.imageUrl,
        title: banner.title,
        subtitle: banner.subtitle,
        link: banner.link
        // Removed order_index to prevent "column not found" error
    };

    if (isNew) {
        const { error } = await supabase.from('banners').insert([payload]).select();
        if (error) throw new Error(`Insert failed: ${error.message}`);
    } else {
        const numericId = parseInt(banner.id);
        const finalId = isNaN(numericId) ? banner.id : numericId;

        const { error } = await supabase.from('banners').update(payload).eq('id', finalId).select();
        if (error) throw new Error(`Update failed: ${error.message}`);
    }

    window.dispatchEvent(new Event('content-change'));
};

export const deleteBanner = async (id: string) => {
    const numericId = parseInt(id);
    const finalId = isNaN(numericId) ? id : numericId;
    const { error } = await supabase.from('banners').delete().eq('id', finalId);
    if (error) throw new Error(error.message);
    window.dispatchEvent(new Event('content-change'));
};

