export const addCategory = async (name: string, imageUrl: string = '', hideTitle: boolean = false) => {
    const { error } = await supabase.from('categories').insert([{ name, image_url: imageUrl, hide_title: hideTitle }]);
    if (error) return { success: false, error: error.message };
    window.dispatchEvent(new Event('content-change'));
    return { success: true };
};

export const updateCategory = async (oldName: string, newName: string, imageUrl: string = '', hideTitle: boolean = false) => {
    const { error } = await supabase.from('categories').update({ name: newName, image_url: imageUrl, hide_title: hideTitle }).eq('name', oldName);
    if (error) throw new Error(error.message);
    window.dispatchEvent(new Event('content-change'));
};

