import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { getSongsByLetter, getArtistsByLetter, ArtistWithRoles } from '../services/geminiService';
import Loader from '../components/Loader';
import AlphabetNav from '../components/AlphabetNav';
import { Music, Disc, ArrowRight, Mic2, PenTool, Filter, Check } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface BrowseProps {
  mode: 'songs' | 'artists';
}

type RoleFilter = 'all' | 'Singer' | 'Composer' | 'Lyricist';

const Browse: React.FC<BrowseProps> = ({ mode }) => {
  const { letter } = useParams<{ letter: string }>();
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [roleFilter, setRoleFilter] = useState<RoleFilter>('all');
  const { t, language: appLanguage } = useLanguage();

  const fetchData = async () => {
    if (letter) {
      setLoading(true);
      const decodedLetter = decodeURIComponent(letter);
      if (mode === 'songs') {
        const results = await getSongsByLetter(decodedLetter);
        setData(results);
      } else {
        const results = await getArtistsByLetter(decodedLetter);
        setData(results);
      }
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    setRoleFilter('all'); // Reset filter when letter or mode changes

    const handleContentChange = () => fetchData();
    window.addEventListener('content-change', handleContentChange);
    return () => window.removeEventListener('content-change', handleContentChange);
  }, [letter, mode]);

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-800';
  };

  const filteredData = mode === 'artists' && roleFilter !== 'all'
    ? (data as ArtistWithRoles[]).filter(artist => artist.roles.includes(roleFilter))
    : data;

  const displayLetter = decodeURIComponent(letter || '');
  const titleText = mode === 'songs' ? t('Songs') : t('Artists');

  // Explicitly define as React.FC to handle React-specific props like 'key' in sub-components
  const RoleBadge: React.FC<{ role: string }> = ({ role }) => {
    switch(role) {
      case 'Singer': return <span className="bg-pink-50 text-pink-600 px-1.5 py-0.5 rounded text-[9px] font-bold uppercase flex items-center gap-1 border border-pink-100"><Mic2 className="w-2.5 h-2.5" /> Singer</span>;
      case 'Composer': return <span className="bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded text-[9px] font-bold uppercase flex items-center gap-1 border border-indigo-100"><Music className="w-2.5 h-2.5" /> Composer</span>;
      case 'Lyricist': return <span className="bg-purple-50 text-purple-600 px-1.5 py-0.5 rounded text-[9px] font-bold uppercase flex items-center gap-1 border border-purple-100"><PenTool className="w-2.5 h-2.5" /> Lyricist</span>;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <AlphabetNav mode={mode} />

      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="mb-8 flex flex-col md:flex-row md:items-end justify-between border-b border-slate-200 pb-6 gap-6">
            <div>
                <h1 className="text-4xl font-bold text-slate-900 flex items-center gap-3">
                    <span className="bg-primary/10 text-primary p-2 rounded-2xl text-2xl min-w-[3.5rem] text-center shadow-sm">{displayLetter}</span>
                    <span className="capitalize">{titleText}</span>
                </h1>
                <p className="text-slate-500 mt-2 font-medium">{t('Discover popular')} {titleText.toLowerCase()} {t('starting with')} "{displayLetter}"</p>
            </div>

            {/* Artist Role Filter */}
            {mode === 'artists' && !loading && data.length > 0 && (
                <div className="flex flex-wrap items-center gap-2 bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm">
                    <div className="px-3 text-slate-400">
                        <Filter className="w-4 h-4" />
                    </div>
                    {(['all', 'Singer', 'Composer', 'Lyricist'] as RoleFilter[]).map((filter) => (
                        <button
                            key={filter}
                            onClick={() => setRoleFilter(filter)}
                            className={`px-4 py-1.5 rounded-xl text-xs font-bold transition-all flex items-center gap-1.5 ${
                                roleFilter === filter 
                                ? 'bg-primary text-white shadow-lg shadow-primary/20 scale-105' 
                                : 'text-slate-500 hover:bg-slate-50'
                            }`}
                        >
                            {roleFilter === filter && <Check className="w-3 h-3" />}
                            {filter === 'all' ? 'All Roles' : filter + 's'}
                        </button>
                    ))}
                </div>
            )}
        </div>

        {loading ? (
          <Loader text={`Fetching ${mode} starting with ${displayLetter}...`} />
        ) : filteredData.length === 0 ? (
          <div className="text-center py-20 bg-white rounded-3xl border border-slate-200 shadow-sm">
            <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4">
                {mode === 'songs' ? <Music className="text-slate-300 w-10 h-10" /> : <Mic2 className="text-slate-300 w-10 h-10" />}
            </div>
            <h3 className="text-2xl text-slate-400 font-bold mb-2">{t('No')} {titleText.toLowerCase()} {t('found')}</h3>
            <p className="text-slate-500">{roleFilter === 'all' ? t('Try selecting a different letter.') : `No ${roleFilter.toLowerCase()}s found starting with "${displayLetter}".`}</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredData.map((item, idx) => {
              const isSong = mode === 'songs';
              const title = isSong ? ((appLanguage === 'nepali' && item.title_nepali) ? item.title_nepali : item.title) : item.name;
              const subtitle = isSong ? item.artist : undefined;
              const language = isSong ? item.language : undefined;
              const imageUrl = !isSong ? item.imageUrl : undefined;
              const roles = !isSong ? item.roles : [];

              const link = isSong 
                ? `/lyrics/${encodeURIComponent(item.artist)}/${encodeURIComponent(item.title)}`
                : `/artist/${encodeURIComponent(item.name)}`;

              const titleClass = isSong ? getSongColorClass(language) : 'text-slate-800';

              return (
                <Link 
                  key={idx} 
                  to={link}
                  className="group flex items-center justify-between p-4 bg-white hover:bg-slate-50 border border-slate-200 hover:border-primary/30 rounded-2xl transition-all duration-300 shadow-sm hover:shadow-xl hover:-translate-y-1"
                >
                  <div className="flex items-center min-w-0 flex-1">
                    <div className="w-12 h-12 rounded-2xl overflow-hidden flex-shrink-0 mr-4 shadow-inner border border-slate-100 flex items-center justify-center bg-slate-50 group-hover:bg-primary/5 transition-colors">
                        {imageUrl ? (
                            <img src={imageUrl} alt={title} className="w-full h-full object-cover" />
                        ) : (
                            <div className={`w-full h-full flex items-center justify-center text-primary/40 group-hover:text-primary transition-colors ${isSong ? 'bg-primary/10' : 'bg-secondary/10 text-secondary/40 group-hover:text-secondary'}`}>
                                {isSong ? <Disc className="w-6 h-6" /> : <Mic2 className="w-6 h-6" />}
                            </div>
                        )}
                    </div>
                    <div className="min-w-0 pr-4 flex-1">
                      <h3 className={`font-bold truncate transition-colors text-base md:text-lg ${titleClass}`}>{title}</h3>
                      {isSong ? (
                        <p className="text-slate-400 text-xs font-bold uppercase tracking-wider truncate">{subtitle}</p>
                      ) : (
                        <div className="flex flex-wrap gap-1 mt-1">
                          {roles.map((role: string) => <RoleBadge key={role} role={role} />)}
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all transform group-hover:rotate-0 -rotate-45">
                    <ArrowRight className="w-4 h-4" />
                  </div>
                </Link>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default Browse;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { searchMusic } from '../services/geminiService';
import { SearchResult } from '../types';
import Loader from '../components/Loader';
import { Mic2, Disc, Search, Grid } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

const SearchPage: React.FC = () => {
  const { query } = useParams<{ query: string }>();
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchInput, setSearchInput] = useState('');
  const navigate = useNavigate();
  const { language: appLanguage } = useLanguage();

  useEffect(() => {
    const fetchSearch = async () => {
      if (query) {
        setLoading(true);
        const data = await searchMusic(query);
        setResults(data);
        setLoading(false);
      } else {
        setResults([]); // Clear results if no query
      }
    };
    fetchSearch();
  }, [query]);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchInput.trim()) {
      navigate(`/search/${encodeURIComponent(searchInput)}`);
    }
  };

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-900';
  };

  // Search Entry Mode (No Query URL)
  if (!query) {
    return (
      <div className="min-h-screen max-w-7xl mx-auto px-4 py-8 flex flex-col items-center justify-center -mt-20 h-[80vh]">
        <div className="w-full max-w-md text-center space-y-6">
          <div className="mx-auto w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center mb-4">
            <Search className="w-8 h-8 text-primary" />
          </div>
          <h1 className="text-3xl font-bold text-slate-900">Search</h1>
          <p className="text-slate-500">Find your favorite artists, songs, and lyrics.</p>

          <form onSubmit={handleSearchSubmit} className="relative w-full">
            <input
              autoFocus
              type="text"
              placeholder="What do you want to listen to?"
              className="w-full bg-white border border-slate-200 rounded-full py-4 pl-12 pr-6 text-lg text-slate-900 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent shadow-lg shadow-slate-200 transition-all"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
            />
            <Search className="absolute left-4 top-4.5 w-6 h-6 text-slate-400" />
          </form>

          <div className="flex flex-wrap justify-center gap-2 mt-8">
            <span className="text-xs text-slate-400 uppercase font-bold tracking-wider w-full mb-2">Popular Searches</span>
            {['Worship', 'Praise', 'Adrian Dewan', 'Rohit Thapa', 'Lydia Rai', 'Funeral'].map(term => (
              <button 
                key={term}
                onClick={() => navigate(`/search/${term}`)}
                className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded-full text-sm text-slate-600 transition-colors"
              >
                {term}
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // Search Results Mode
  return (
    <div className="min-h-screen max-w-7xl mx-auto px-4 py-8">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-slate-900 mb-4">
          Results for "<span className="text-primary">{query}</span>"
        </h1>
        {/* Quick re-search bar for convenience */}
         <form onSubmit={(e) => { e.preventDefault(); navigate(`/search/${encodeURIComponent(searchInput)}`); }} className="relative md:w-1/2">
            <input
              type="text"
              placeholder="Search again..."
              className="w-full bg-white border border-slate-200 rounded-lg py-2 pl-10 pr-4 text-slate-900 focus:outline-none focus:border-primary shadow-sm"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
            />
            <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
        </form>
      </div>

      {loading ? (
        <Loader text="Searching database..." />
      ) : results.length === 0 ? (
        <div className="text-center py-20 text-slate-400 bg-white rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-xl font-semibold mb-2">No results found</p>
          <p>Try checking for typos or using different keywords.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {results.map((item, idx) => {
            const titleClass = item.type === 'song' ? getSongColorClass(item.language) : 'text-slate-900';
            const displayTitle = (item.type === 'song' && appLanguage === 'nepali' && item.name_nepali) ? item.name_nepali : item.name;

            // Determine Link path based on type
            let linkPath = '';
            if (item.type === 'song') {
                linkPath = `/lyrics/${encodeURIComponent(item.subtext)}/${encodeURIComponent(item.name)}`;
            } else if (item.type === 'artist') {
                linkPath = `/artist/${encodeURIComponent(item.name)}`;
            } else if (item.type === 'category') {
                linkPath = `/category/${encodeURIComponent(item.name)}`;
            }

            // Image/Icon logic
            let thumb = null;
            if (item.type === 'artist') {
                const isUnknownArtist = item.name.toLowerCase() === 'unknown';
                const imageUrl = isUnknownArtist 
                    ? "https://ui-avatars.com/api/?name=Unknown&background=e2e8f0&color=64748b&size=150" 
                    : (item.imageUrl || `https://picsum.photos/seed/${item.name + item.type}/150`);
                thumb = (
                    <div className="w-16 h-16 rounded-lg bg-slate-200 overflow-hidden flex-shrink-0 mr-4 border border-slate-100">
                       <img src={imageUrl} alt={item.name} className="w-full h-full object-cover" />
                    </div>
                );
            } else if (item.type === 'category') {
                thumb = (
                    <div className="w-16 h-16 rounded-lg bg-emerald-100 flex items-center justify-center flex-shrink-0 mr-4 border border-emerald-50 text-emerald-600">
                        {item.imageUrl ? (
                            <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover rounded-lg" />
                        ) : (
                            <Grid className="w-8 h-8" />
                        )}
                    </div>
                );
            } else {
                thumb = (
                    <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0 mr-4 group-hover:bg-primary/20 transition-colors">
                        <Disc className="w-6 h-6 text-primary" />
                    </div>
                );
            }

            return (
            <Link
              key={idx}
              to={linkPath}
              className="flex items-center p-4 bg-white rounded-xl border border-slate-200 hover:border-primary/50 hover:bg-slate-50 transition-all group shadow-sm hover:shadow-md"
            >
              {thumb}

              <div className="flex-1 min-w-0">
                <div className="flex items-center space-x-2 mb-1">
                    {item.type === 'artist' && <Mic2 className="w-3 h-3 text-secondary" />}
                    {item.type === 'song' && <Disc className="w-3 h-3 text-primary" />}
                    {item.type === 'category' && <Grid className="w-3 h-3 text-emerald-500" />}
                    <span className="text-[10px] font-bold uppercase text-slate-400">{item.type}</span>
                </div>
                <h3 className={`text-lg font-bold transition-colors truncate ${titleClass}`}>{displayTitle}</h3>
                <p className="text-slate-500 text-sm truncate">{item.subtext}</p>
              </div>
            </Link>
          )})}
        </div>
      )}
    </div>
  );
};

