import React, { useEffect, useState, useRef } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getArtistDetails } from '../services/geminiService';
import { ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { Disc, ArrowLeft, Edit, Save, X, Trash2, Image as ImageIcon, Facebook, Instagram, Youtube, PenTool, Music, Mic2, Star, User, Upload } from 'lucide-react';
import { useAuth } from '../utils/auth';
import { saveCustomArtist, deleteCustomArtist, getAllCustomSongs } from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

interface DisplaySong {
    id: string;
    title: string;
    title_nepali?: string;
    mainArtist: string;
    language?: string;
    roles: string[]; // e.g., ['Composer', 'Lyricist']
}

// Consistent default image for "Unknown" artists
const DEFAULT_UNKNOWN_IMAGE = "https://ui-avatars.com/api/?name=Unknown&background=e2e8f0&color=64748b&size=512";

const ArtistPage: React.FC = () => {
  const { name } = useParams<{ name: string }>();
  const [artist, setArtist] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const [displaySongs, setDisplaySongs] = useState<DisplaySong[]>([]);
  const [isAutoGenerated, setIsAutoGenerated] = useState(false);
  const { language: appLanguage } = useLanguage();
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Admin / Edit State
  const { isAuth } = useAuth();
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState<ArtistDetails>({
      name: '',
      bio: '',
      topSongs: [],
      imageUrl: '',
      facebookUrl: '',
      instagramUrl: '',
      youtubeUrl: '',
      isFacebookVisible: true,
      isInstagramVisible: true,
      isArtistYoutubeVisible: true
  });
  const [topSongsString, setTopSongsString] = useState('');

  useEffect(() => {
    const fetchArtistAndSongs = async () => {
      if (name) {
        setLoading(true);
        const decodedName = decodeURIComponent(name);
        const lowerName = decodedName.toLowerCase().trim();

        // Block 'Unknown' artist page
        if (lowerName === 'unknown') {
            setArtist(null);
            setLoading(false);
            return;
        }

        // 1. Try to get existing profile
        const dbProfile = await getArtistDetails(decodedName);

        // 2. Get all songs to map credits
        const allSongs = await getAllCustomSongs();

        // 3. Filter and Map Songs with Role Detection
        const matchedSongs: DisplaySong[] = allSongs.reduce((acc: DisplaySong[], s: any) => {
            const roles: string[] = [];

            // Check Main Artist
            if (s.artist.toLowerCase() === lowerName) roles.push('Main Artist');
            if (s.artists && s.artists.some((a: string) => a.toLowerCase() === lowerName && s.artist.toLowerCase() !== lowerName)) roles.push('Feat');

            // Check Credits for regular artists
            const compList = (s.composers || []).concat(s.composer ? [s.composer] : []);
            if (compList.some((c: string) => c.toLowerCase() === lowerName)) roles.push('Composer');

            const lyrList = (s.lyricists || []).concat(s.lyricist ? [s.lyricist] : []);
            if (lyrList.some((l: string) => l.toLowerCase() === lowerName)) roles.push('Lyricist');

            const singList = (s.singers || []).concat(s.singer ? [s.singer] : []);
            if (singList.some((v: string) => v.toLowerCase() === lowerName)) roles.push('Vocals');

            if (roles.length > 0) {
                const existing = acc.find(item => item.title === s.title && item.mainArtist === s.artist);
                if (!existing) {
                    acc.push({
                        id: s.id,
                        title: s.title,
                        title_nepali: s.title_nepali,
                        mainArtist: s.artist,
                        language: s.language,
                        roles: [...new Set(roles)]
                    });
                }
            }
            return acc;
        }, []);

        matchedSongs.sort((a, b) => {
            const aIsMain = a.roles.includes('Main Artist');
            const bIsMain = b.roles.includes('Main Artist');
            if (aIsMain && !bIsMain) return -1;
            if (!aIsMain && bIsMain) return 1;
            return a.title.localeCompare(b.title);
        });

        setDisplaySongs(matchedSongs);

        if (dbProfile) {
            setArtist(dbProfile);
            setIsAutoGenerated(false);
            setTopSongsString(dbProfile.topSongs.join(', '));
            setEditForm({ 
                ...dbProfile, 
                imageUrl: dbProfile.imageUrl || '',
                facebookUrl: dbProfile.facebookUrl || '',
                instagramUrl: dbProfile.instagramUrl || '',
                youtubeUrl: dbProfile.youtubeUrl || '',
                isFacebookVisible: dbProfile.isFacebookVisible !== false,
                isInstagramVisible: dbProfile.isInstagramVisible !== false,
                isArtistYoutubeVisible: dbProfile.isArtistYoutubeVisible !== false
            });
        } else if (matchedSongs.length > 0) {
            const virtualProfile: ArtistDetails = {
                name: decodedName,
                bio: `Profile automatically generated based on credits. ${decodedName} is credited as a ${matchedSongs[0]?.roles.filter(r => r !== 'Main Artist')[0] || 'Contributor'} on SansarPlus.`,
                topSongs: matchedSongs.slice(0, 5).map(s => s.title),
                imageUrl: '',
            };
            setArtist(virtualProfile);
            setIsAutoGenerated(true);
            setEditForm({ ...virtualProfile, 
                facebookUrl: '', instagramUrl: '', youtubeUrl: '', 
                isFacebookVisible: true, isInstagramVisible: true, isArtistYoutubeVisible: true 
            });
        } else {
            setArtist(null);
        }

        setLoading(false);
      }
    };
    fetchArtistAndSongs();
  }, [name]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
          setEditForm(prev => ({ ...prev, imageUrl: event.target?.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveEdit = () => {
      if (!artist) return;

      const updatedArtist = {
          ...editForm,
          topSongs: topSongsString.split(',').map(s => s.trim()).filter(s => s)
      };

      if (editForm.name !== artist.name) {
          if (window.confirm(`Renaming artist from "${artist.name}" to "${editForm.name}". This will create a new profile. Continue?`)) {
             saveCustomArtist(editForm.name, updatedArtist);
             if (!isAutoGenerated) {
                 deleteCustomArtist(artist.name);
             }
             navigate(`/artist/${encodeURIComponent(editForm.name)}`, { replace: true });
          }
      } else {
          saveCustomArtist(artist.name, updatedArtist);
          setArtist(updatedArtist);
          setIsAutoGenerated(false);
          setIsEditing(false);
      }
  };

  const handleDeleteArtist = () => {
      if (!artist) return;
      if (isAutoGenerated) {
          alert("This is an auto-generated profile based on song credits. It cannot be deleted directly. To remove it, remove the credits from the songs.");
          return;
      }
      if (window.confirm('Delete this artist profile? This will revert to AI generation or remove if custom.')) {
          deleteCustomArtist(artist.name);
          navigate('/');
      }
  };

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-800';
  };

  const renderRoleBadge = (role: string) => {
      switch(role) {
          case 'Composer': return <span key={role} className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold bg-indigo-100 text-indigo-700 mr-1"><Music className="w-3 h-3 mr-1"/> Composer</span>;
          case 'Lyricist': return <span key={role} className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold bg-purple-100 text-purple-700 mr-1"><PenTool className="w-3 h-3 mr-1"/> Lyrics</span>;
          case 'Vocals': return <span key={role} className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold bg-pink-100 text-pink-700 mr-1"><Mic2 className="w-3 h-3 mr-1"/> Vocals</span>;
          default: return <span key={role} className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-600 mr-1">{role}</span>;
      }
  };

  if (loading) return <Loader fullScreen text="Loading profile..." />;
  if (!artist) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
        <div className="text-center p-8">
            <h2 className="text-2xl font-bold text-slate-400 mb-2">Artist Not Found</h2>
            <p className="text-slate-500 mb-6">We couldn't find a profile or any songs credited to "{name}".</p>
            <Link to="/" className="text-primary font-bold hover:underline">Return Home</Link>
        </div>
    </div>
  );

  const displayImage = artist.imageUrl || null;

  return (
    <div className="min-h-screen bg-slate-50">
       <div className="bg-white border-b border-slate-200 shadow-sm">
            <div className="max-w-7xl mx-auto px-4 py-8">
                <Link to="/browse/artists/A" className="inline-flex items-center text-slate-500 hover:text-primary mb-6 transition-colors">
                    <ArrowLeft className="w-4 h-4 mr-2" /> Back to Browse
                </Link>

                <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
                    <div className="flex items-center gap-6">
                         {displayImage ? (
                             <div className="w-24 h-24 md:w-32 md:h-32 rounded-full overflow-hidden border-4 border-slate-100 shadow-md flex-shrink-0">
                                 <img src={displayImage} alt={artist.name} className="w-full h-full object-cover" />
                             </div>
                         ) : (
                             <div className="w-24 h-24 md:w-32 md:h-32 rounded-full bg-slate-100 flex items-center justify-center text-slate-300 shadow-inner flex-shrink-0">
                                 <ImageIcon className="w-10 h-10" />
                             </div>
                         )}

                         <div>
                             {isEditing ? (
                                 <input 
                                    type="text" 
                                    className="text-2xl md:text-3xl font-extrabold text-slate-900 border-b-2 border-primary focus:outline-none bg-transparent w-full"
                                    value={editForm.name}
                                    onChange={(e) => setEditForm({...editForm, name: e.target.value})}
                                 />
                             ) : (
                                 <div className="flex flex-col gap-2">
                                     <div className="flex items-center gap-2">
                                        <h1 className="text-4xl md:text-5xl font-extrabold text-slate-900 tracking-tight">{artist.name}</h1>
                                        {isAutoGenerated && <span className="px-2 py-1 bg-slate-100 text-slate-500 text-[10px] font-bold uppercase rounded tracking-wider border border-slate-200">Auto-Generated</span>}
                                     </div>
                                     <div className="flex flex-wrap gap-4 mt-1">
                                         {artist.facebookUrl && artist.isFacebookVisible !== false && (
                                             <a 
                                                href={artist.facebookUrl} 
                                                target="_blank" 
                                                rel="noopener noreferrer"
                                                className="flex items-center text-blue-600 hover:text-blue-700 font-bold transition-colors w-fit bg-blue-50 px-3 py-1 rounded-full text-sm"
                                             >
                                                 <Facebook className="w-4 h-4 mr-2" /> Facebook
                                             </a>
                                         )}
                                         {artist.instagramUrl && artist.isInstagramVisible !== false && (
                                             <a 
                                                href={artist.instagramUrl} 
                                                target="_blank" 
                                                rel="noopener noreferrer"
                                                className="flex items-center text-pink-600 hover:text-pink-700 font-bold transition-colors w-fit bg-pink-50 px-3 py-1 rounded-full text-sm"
                                             >
                                                 <Instagram className="w-4 h-4 mr-2" /> Instagram
                                             </a>
                                         )}
                                         {artist.youtubeUrl && artist.isArtistYoutubeVisible !== false && (
                                             <a 
                                                href={artist.youtubeUrl} 
                                                target="_blank" 
                                                rel="noopener noreferrer"
                                                className="flex items-center text-red-600 hover:text-red-700 font-bold transition-colors w-fit bg-red-50 px-3 py-1 rounded-full text-sm"
                                             >
                                                 <Youtube className="w-4 h-4 mr-2" /> YouTube
                                             </a>
                                         )}
                                     </div>
                                 </div>
                             )}
                         </div>
                    </div>

                    {isAuth && (
                        <div className="flex gap-2 self-start md:self-center">
                            {isEditing ? (
                                    <button onClick={handleSaveEdit} className="p-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors flex items-center">
                                        <Save className="w-5 h-5 mr-2" /> Save
                                    </button>
                            ) : (
                                    <button onClick={() => setIsEditing(true)} className="p-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors flex items-center">
                                        <Edit className="w-5 h-5 mr-2" /> Edit
                                    </button>
                            )}
                            {isEditing && (
                                    <button onClick={() => setIsEditing(false)} className="p-2 bg-slate-500 text-white rounded-lg hover:bg-slate-600 transition-colors">
                                        <X className="w-5 h-5" />
                                    </button>
                            )}
                            {!isEditing && !isAutoGenerated && (
                                    <button onClick={handleDeleteArtist} className="p-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors flex items-center">
                                        <Trash2 className="w-5 h-5 mr-2" /> Delete
                                    </button>
                            )}
                        </div>
                    )}
                </div>
            </div>
       </div>

       <div className="max-w-7xl mx-auto px-4 py-12 grid grid-cols-1 lg:grid-cols-3 gap-12">
            <div className="lg:col-span-1 space-y-8">
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                    <h3 className="text-xl font-bold text-slate-900 mb-4">About</h3>
                    {isEditing ? (
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-bold text-slate-500 mb-1 uppercase">Profile Image</label>
                                <div className="flex flex-col gap-2">
                                    <div className="flex gap-2">
                                        <input 
                                            type="text" 
                                            className="flex-1 border p-2 rounded text-sm outline-none"
                                            value={editForm.imageUrl || ''}
                                            onChange={e => setEditForm({...editForm, imageUrl: e.target.value})}
                                            placeholder="https://..."
                                        />
                                        <button type="button" onClick={() => fileInputRef.current?.click()} className="p-2 bg-slate-100 rounded-lg hover:bg-slate-200" title="Upload Image"><Upload className="w-4 h-4"/></button>
                                        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
                                    </div>
                                    {editForm.imageUrl && (
                                        <div className="flex justify-center mt-2">
                                            <div className="w-20 h-20 rounded-full border-2 border-primary/20 overflow-hidden">
                                                <img src={editForm.imageUrl} className="w-full h-full object-cover" />
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="border-t border-b py-4 my-2 space-y-4">
                                <label className="block text-sm font-bold text-slate-500 mb-2 uppercase tracking-wide">Social Links</label>
                                <div className="space-y-3">
                                    <div className="flex items-center gap-2">
                                        <Facebook className="w-4 h-4 text-blue-500"/>
                                        <input className="flex-1 border p-2 rounded text-sm" value={editForm.facebookUrl || ''} onChange={e => setEditForm({...editForm, facebookUrl: e.target.value})} placeholder="Facebook URL" />
                                        <input type="checkbox" className="rounded" checked={editForm.isFacebookVisible} onChange={e => setEditForm({...editForm, isFacebookVisible: e.target.checked})} title="Visible?" />
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <Instagram className="w-4 h-4 text-pink-500"/>
                                        <input className="flex-1 border p-2 rounded text-sm" value={editForm.instagramUrl || ''} onChange={e => setEditForm({...editForm, instagramUrl: e.target.value})} placeholder="Instagram URL" />
                                        <input type="checkbox" className="rounded" checked={editForm.isInstagramVisible} onChange={e => setEditForm({...editForm, isInstagramVisible: e.target.checked})} title="Visible?" />
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <Youtube className="w-4 h-4 text-red-500"/>
                                        <input className="flex-1 border p-2 rounded text-sm" value={editForm.youtubeUrl || ''} onChange={e => setEditForm({...editForm, youtubeUrl: e.target.value})} placeholder="YouTube URL" />
                                        <input type="checkbox" className="rounded" checked={editForm.isArtistYoutubeVisible} onChange={e => setEditForm({...editForm, isArtistYoutubeVisible: e.target.checked})} title="Visible?" />
                                    </div>
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-bold text-slate-500 mb-1 uppercase">Biography</label>
                                <textarea className="w-full h-64 border p-2 rounded text-sm outline-none focus:ring-1 focus:ring-primary/20" value={editForm.bio} onChange={e => setEditForm({...editForm, bio: e.target.value})} />
                            </div>
                        </div>
                    ) : (
                        <p className="text-slate-600 leading-loose text-sm md:text-base mb-4">
                            {artist.bio || "No biography available."}
                        </p>
                    )}
                </div>
            </div>

            <div className="lg:col-span-2">
                <h2 className="text-2xl font-bold text-slate-900 mb-6 flex items-center">
                    <Disc className="mr-3 text-primary" /> 
                    {isAutoGenerated ? 'Credited Songs' : 'Popular Tracks'}
                </h2>

                {isEditing && (
                    <div className="mb-4">
                        <label className="block text-sm font-bold text-slate-500 mb-1">Edit Songs (Legacy list, comma separated)</label>
                        <input type="text" className="w-full border p-3 rounded" value={topSongsString} onChange={e => setTopSongsString(e.target.value)} />
                    </div>
                )}

                <div className="space-y-3">
                    {displaySongs.length > 0 ? (
                        displaySongs.map((song, idx) => {
                            const displayTitle = (appLanguage === 'nepali' && song.title_nepali) ? song.title_nepali : song.title;
                            return (
                            <Link 
                                key={`${song.title}-${song.mainArtist}-${idx}`}
                                to={`/lyrics/${encodeURIComponent(song.mainArtist)}/${encodeURIComponent(song.title)}`}
                                className="flex items-center justify-between p-4 rounded-xl bg-white hover:bg-slate-50 border border-slate-200 hover:border-primary/50 group transition-all shadow-sm hover:shadow-md"
                            >
                                <div className="flex items-center space-x-4">
                                    <span className="text-slate-400 font-mono w-6 text-center text-lg">{idx + 1}</span>
                                    <div>
                                        <div className="flex items-center flex-wrap gap-2 mb-0.5">
                                            <span className={`font-semibold transition-colors text-lg block ${getSongColorClass(song.language)}`}>{displayTitle}</span>
                                            {song.roles.filter(r => r !== 'Main Artist').map(role => renderRoleBadge(role))}
                                        </div>
                                        {song.mainArtist.toLowerCase() !== artist.name.toLowerCase() && (
                                            <span className="text-xs text-slate-400">by <span className="font-bold">{song.mainArtist}</span></span>
                                        )}
                                    </div>
                                </div>
                                <span className="text-xs text-slate-500 px-3 py-1 border border-slate-200 rounded-full group-hover:border-primary/50 group-hover:text-primary transition-colors bg-slate-50">
                                    View Lyrics
                                </span>
                            </Link>
                        )})
                    ) : (
                        <p className="text-slate-500 italic">No songs found for this artist.</p>
                    )}
                </div>
            </div>
       </div>
    </div>
  );
};

export default ArtistPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { User, Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, Flag, X, Edit, Trash2, Save, Printer, Tag, Youtube, Mic2 } from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { saveCustomSong, deleteCustomSong, incrementViewCount, setViewCount, saveCustomArtist, getCategories, getAllCustomSongs } from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { artist, song } = useParams<{ artist: string; song: string }>();
  const [data, setData] = useState<LyricsData | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(16); // Default font size set to minimum
  const [availableCategories, setAvailableCategories] = useState<string[]>([]);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  // Auth & Editing
  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const navigate = useNavigate();

  // Extended edit form
  const [editForm, setEditForm] = useState<LyricsData & { artist_bio?: string }>({
      lyrics_nepali: '',
      lyrics_roman: '',
      composer: '',
      composers: [],
      lyricist: '',
      lyricists: [],
      singer: '',
      singers: [],
      views: 0,
      artist_bio: '',
      category: '',
      categories: [],
      youtubeUrl: '',
      isYoutubeVisible: true,
      artist: '', // Main Artist field for editing
      artists: [],
      title_nepali: ''
  });

  // Feedback Modal State
  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('lyrics');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      if (artist && song) {
        setLoading(true);
        // Await the categories since getCategories is async
        const cats = await getCategories();
        // Map objects to names for the dropdown
        setAvailableCategories(cats.map(c => c.name));

        // Parallel Fetch
        const [lyricsResult, artistResult, allSongs] = await Promise.all([
            getSongLyrics(artist, song),
            getArtistDetails(artist),
            getAllCustomSongs()
        ]);

        setData(lyricsResult);
        setArtistData(artistResult);

        // Calculate Related Songs (Same Artist), EXCLUDING if artist is 'Unknown'
        if (allSongs && artist && artist.toLowerCase() !== 'unknown') {
            const related = allSongs
                .filter(s => (s.artist === artist || (s.artists && s.artists.includes(artist))) && s.title !== song)
                .sort((a, b) => (b.views || 0) - (a.views || 0)) // Sort by popularity
                .slice(0, 5);
            setRelatedSongs(related);
        } else {
            setRelatedSongs([]);
        }

        if (lyricsResult) {
            // Handle legacy category vs new categories array
            let initialCats = lyricsResult.categories || [];
            if (initialCats.length === 0 && lyricsResult.category) {
                initialCats = [lyricsResult.category];
            }

            // Flatten credits for editing if arrays exist, otherwise use string
            const composerStr = lyricsResult.composers && lyricsResult.composers.length > 0 
                ? lyricsResult.composers.join(', ') 
                : lyricsResult.composer || '';

            const lyricistStr = lyricsResult.lyricists && lyricsResult.lyricists.length > 0 
                ? lyricsResult.lyricists.join(', ') 
                : lyricsResult.lyricist || '';

            const singerStr = lyricsResult.singers && lyricsResult.singers.length > 0 
                ? lyricsResult.singers.join(', ') 
                : lyricsResult.singer || '';

            setEditForm({ 
                ...lyricsResult, 
                title: song, // Ensure current title is set
                artist: artist, // Ensure current artist is set
                views: lyricsResult.views || 0,
                artist_bio: artistResult?.bio || '',
                category: lyricsResult.category || 'Worship',
                categories: initialCats,
                composer: composerStr,
                lyricist: lyricistStr,
                singer: singerStr,
                youtubeUrl: lyricsResult.youtubeUrl || '',
                isYoutubeVisible: lyricsResult.isYoutubeVisible !== false, // Default true if undefined
                title_nepali: lyricsResult.title_nepali || ''
            });
        }

        setIsFav(isFavorite(generateId('song', song, artist)));
        setLoading(false);

        // Keep tracking views in background, but don't display
        incrementViewCount(artist, song);
      }
    };
    fetchData();
  }, [artist, song]);

  const handleFavorite = () => {
    if (!data || !artist || !song) return;
    const item = {
        id: generateId('song', song, artist),
        type: 'song' as const,
        name: song,
        subtext: artist,
        language: data.language // Save language to favorites for correct color display
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePrint = () => {
    window.print();
  };

  const handleZoomIn = () => {
    setFontSize(prev => Math.min(prev + 4, 64));
  };

  const handleZoomOut = () => {
    setFontSize(prev => Math.max(prev - 2, 16));
  };

  const submitFeedback = (e: React.FormEvent) => {
    e.preventDefault();
    setTimeout(() => {
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
            setFeedbackType('lyrics');
        }, 2000);
    }, 500);
  };

  // --- Admin Functions ---
  const handleSaveEdit = async () => {
      if (!artist || !song) return;

      const { artist_bio, ...songData } = editForm;

      // Convert inputs to arrays for credits
      const composers = editForm.composer.split(',').map(s => s.trim()).filter(s => s);
      const lyricists = editForm.lyricist.split(',').map(s => s.trim()).filter(s => s);
      const singers = editForm.singer.split(',').map(s => s.trim()).filter(s => s);

      const updatedSongData = {
          ...songData,
          // Ensure main artist is updated if changed in form
          artist: editForm.artist || artist,
          composers: composers.length > 0 ? composers : [],
          lyricists: lyricists.length > 0 ? lyricists : [],
          singers: singers.length > 0 ? singers : [],
          // Ensure display strings are synced
          composer: editForm.composer,
          lyricist: editForm.lyricist,
          singer: editForm.singer,
          title_nepali: editForm.title_nepali,
          // Sync singular category for legacy/mapping consistency
          category: (songData.categories && songData.categories.length > 0) ? songData.categories[0] : songData.category
      };

      // Pass the original artist/song to find record, and new data (potentially with new artist/title) to update
      await saveCustomSong(artist, song, updatedSongData);

      // Check if artist or title changed, if so navigate to new URL
      const newArtist = updatedSongData.artist;
      if (newArtist !== artist) {
          setIsEditing(false);
          navigate(`/lyrics/${encodeURIComponent(newArtist)}/${encodeURIComponent(song)}`, { replace: true });
          return;
      }

      // Still allow saving views if they were edited via form state
      if (editForm.views !== undefined) {
         setViewCount(artist, song, editForm.views);
      }

      if (artist_bio && artist_bio !== artistData?.bio && artist.toLowerCase() !== 'unknown') {
          const updatedArtist: ArtistDetails = {
              name: artist,
              bio: artist_bio,
              topSongs: artistData?.topSongs || []
          };
          saveCustomArtist(artist, updatedArtist);
          setArtistData(updatedArtist);
      }

      setData(updatedSongData);
      setIsEditing(false);
  };

  const toggleCategorySelection = (cat: string) => {
      setEditForm(prev => {
          const cats = prev.categories || [];
          if (cats.includes(cat)) {
              return { ...prev, categories: cats.filter(c => c !== cat) };
          } else {
              return { ...prev, categories: [...cats, cat] };
          }
      });
  };

  const handleDeleteSong = () => {
      if (!artist || !song) return;
      if (window.confirm("Are you sure you want to delete this lyrics page?")) {
          deleteCustomSong(artist, song);
          navigate('/');
      }
  };

  // Extract video ID for YouTube Embed
  const getYoutubeId = (url: string) => {
      const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
      const match = url.match(regExp);
      return (match && match[2].length === 11) ? match[2] : null;
  };

  const currentUrl = window.location.href;
  const shareTitle = `Check out "${song}" by ${artist} on SansarPlus`;

  const socialLinks = [
    {
        name: 'WhatsApp',
        url: `https://wa.me/?text=${encodeURIComponent(shareTitle + ' ' + currentUrl)}`,
        color: 'hover:bg-[#25D366] hover:text-white text-[#25D366] bg-[#25D366]/10',
        icon: <svg viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.008-.57-.008-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
    },
    {
        name: 'Facebook',
        url: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(currentUrl)}`,
        color: 'hover:bg-[#1877F2] hover:text-white text-[#1877F2] bg-[#1877F2]/10',
        icon: <svg viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5"><path d="M9.101 23.691v-7.98H6.627v-3.667h2.474v-1.58c0-4.085 1.848-5.978 5.858-5.978.401 0 .955.042 1.468.103a8.68 8.68 0 0 1 1.141.195v3.325a8.623 8.623 0 0 0-.653-.036c-2.148 0-2.971.956-2.971 3.594v.411h3.085l-.005 3.633-3.08 3.667v7.98h-4.843Z"/></svg>
    },
    {
        name: 'X',
        url: `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareTitle)}&url=${encodeURIComponent(currentUrl)}`,
        color: 'hover:bg-black hover:text-white text-black bg-gray-100',
        icon: <svg viewBox="0 0 24 24" fill="currentColor" className="w-4 h-4"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>
    },
  ];

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-900';
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data || !artist || !song) return <div className="text-slate-500 text-center pt-20">Lyrics not found.</div>;

  const displayTitle = (appLanguage === 'nepali' && data.title_nepali) ? data.title_nepali : song;

  const youtubeId = data.youtubeUrl ? getYoutubeId(data.youtubeUrl) : null;
  const showYoutube = youtubeId && (data.isYoutubeVisible !== false);

  // Helper for rendering multiple credits
  const renderCredits = (names: string[] | string) => {
      const list = Array.isArray(names) && names.length > 0 ? names : (names ? [names as string] : []);
      if (list.length === 0 || (list.length === 1 && list[0].toLowerCase() === 'unknown')) return <span className="text-slate-400 text-sm italic">Unknown</span>;

      return (
          <div className="flex flex-wrap gap-2">
              {list.map((name, idx) => (
                  <React.Fragment key={idx}>
                      {idx > 0 && <span className="text-slate-300">,</span>}
                      {name.toLowerCase() === 'unknown' ? (
                          <span className="text-slate-900 font-bold">{name}</span>
                      ) : (
                          <Link to={`/artist/${encodeURIComponent(name)}`} className="text-slate-900 font-bold hover:text-primary transition-colors block">
                              {name}
                          </Link>
                      )}
                  </React.Fragment>
              ))}
          </div>
      );
  };

  const composersList = data.composers && data.composers.length > 0 ? data.composers : data.composer;
  const lyricistsList = data.lyricists && data.lyricists.length > 0 ? data.lyricists : data.lyricist;
  const singersList = data.singers && data.singers.length > 0 ? data.singers : data.singer;

  return (
    <div className="min-h-screen bg-slate-50 pb-24 font-sans">

      {/* 1. Immersive Hero Header */}
      <div className="relative bg-slate-900 text-white pb-24 pt-24 md:pt-32 px-4 overflow-hidden shadow-lg no-print">
         <div className="absolute inset-0 bg-gradient-to-br from-indigo-900 via-slate-900 to-black z-0"></div>
         {/* Decorative Abstract blobs */}
         <div className="absolute top-[-20%] right-[-10%] w-[400px] h-[400px] bg-purple-600/20 rounded-full blur-[100px]"></div>
         <div className="absolute bottom-[-20%] left-[-10%] w-[400px] h-[400px] bg-blue-600/20 rounded-full blur-[100px]"></div>

         <div className="relative z-10 max-w-4xl mx-auto text-center">
            <h1 className="text-4xl md:text-6xl lg:text-7xl font-extrabold tracking-tight leading-tight mb-4 drop-shadow-2xl">
                {displayTitle}
            </h1>
         </div>
      </div>

      <div className="max-w-3xl mx-auto px-4 -mt-16 relative z-20 space-y-8">

         {/* Admin Panel */}
         {canEdit && (
            <div className="bg-white rounded-xl shadow-lg p-2 mb-4 flex justify-between items-center no-print">
               <span className="text-xs font-bold text-slate-400 px-3 uppercase">Admin Controls</span>
               <div className="flex gap-2">
                  {isEditing ? (
                      <>
                        <button onClick={handleSaveEdit} className="bg-green-500 text-white p-2 rounded-lg hover:bg-green-600 flex items-center gap-1 text-sm font-bold pr-3"><Save className="w-4 h-4" /> Save</button>
                        <button onClick={() => setIsEditing(false)} className="bg-slate-500 text-white p-2 rounded-lg hover:bg-slate-600"><X className="w-5 h-5" /></button>
                      </>
                  ) : (
                      <>
                        <button onClick={() => setIsEditing(true)} className="bg-primary text-white p-2 rounded-lg hover:bg-primary/90 flex items-center gap-1 text-sm font-bold pr-3"><Edit className="w-4 h-4" /> Edit Page</button>
                        <button onClick={handleDeleteSong} className="bg-red-50 text-white p-2 rounded-lg hover:bg-red-600"><Trash2 className="w-5 h-5" /></button>
                      </>
                  )}
               </div>
            </div>
         )}

         {isEditing && (
             <div className="bg-yellow-50 p-6 rounded-2xl border border-yellow-200 shadow-sm animate-in slide-in-from-top-4">
                <h3 className="font-bold text-yellow-800 mb-4 border-b border-yellow-200 pb-2">Edit Details</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Localized Title Edit */}
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Nepali Title (होसन्ना)</label>
                        <input 
                            type="text" 
                            className="w-full border p-2 rounded bg-white text-sm" 
                            value={editForm.title_nepali || ''} 
                            onChange={e => setEditForm({...editForm, title_nepali: e.target.value})}
                            placeholder="Nepali script title"
                        />
                    </div>
                    {/* Main Artist Edit */}
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Main Artist / Band (Renaming redirects page)</label>
                        <input 
                            type="text" 
                            className="w-full border p-2 rounded bg-white text-sm" 
                            value={editForm.artist || ''} 
                            onChange={e => setEditForm({...editForm, artist: e.target.value})}
                            placeholder="Artist Name"
                        />
                    </div>

                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-2 uppercase">Categories</label>
                        <div className="bg-white border rounded p-2 max-h-32 overflow-y-auto grid grid-cols-2 sm:grid-cols-3 gap-2">
                             {availableCategories.map(cat => (
                                <button 
                                    key={cat}
                                    onClick={() => toggleCategorySelection(cat)}
                                    className={`text-xs px-2 py-1 rounded text-left ${
                                        (editForm.categories || []).includes(cat)
                                        ? 'bg-primary text-white font-bold'
                                        : 'bg-slate-50 hover:bg-slate-100 text-slate-600'
                                    }`}
                                >
                                    {cat}
                                </button>
                             ))}
                        </div>
                    </div>

                    {/* Credits Editing */}
                    <div className="col-span-2 md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Composers (comma separated)</label>
                        <input 
                            type="text" 
                            className="w-full border p-2 rounded bg-white text-sm" 
                            value={editForm.composer} 
                            onChange={e => setEditForm({...editForm, composer: e.target.value})}
                            placeholder="e.g. Composer A, Composer B"
                        />
                    </div>
                    <div className="col-span-2 md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Lyricists (comma separated)</label>
                        <input 
                            type="text" 
                            className="w-full border p-2 rounded bg-white text-sm" 
                            value={editForm.lyricist} 
                            onChange={e => setEditForm({...editForm, lyricist: e.target.value})}
                            placeholder="e.g. Lyricist A, Lyricist B"
                        />
                    </div>
                    <div className="col-span-2 md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Vocals / Singers (comma separated)</label>
                        <input 
                            type="text" 
                            className="w-full border p-2 rounded bg-white text-sm" 
                            value={editForm.singer} 
                            onChange={e => setEditForm({...editForm, singer: e.target.value})}
                            placeholder="e.g. Singer A, Singer B"
                        />
                    </div>

                    {/* YouTube Editing */}
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">YouTube URL</label>
                        <input 
                            type="text" 
                            className="w-full border p-2 rounded bg-white text-sm" 
                            value={editForm.youtubeUrl || ''} 
                            onChange={e => setEditForm({...editForm, youtubeUrl: e.target.value})}
                            placeholder="https://youtube.com/watch?v=..."
                        />
                         <div className="flex items-center mt-2">
                            <input 
                                type="checkbox" 
                                id="ytEditVisible"
                                checked={editForm.isYoutubeVisible}
                                onChange={e => setEditForm({...editForm, isYoutubeVisible: e.target.checked})}
                                className="mr-2"
                            />
                            <label htmlFor="ytEditVisible" className="text-sm text-slate-700">Video Visible to Public</label>
                        </div>
                    </div>

                    {/* Artist Bio Edit */}
                    <div className="col-span-2">
                         <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Artist Biography (Updates Profile)</label>
                         <textarea 
                             className="w-full border p-2 rounded bg-white text-sm h-24"
                             value={editForm.artist_bio || ''}
                             onChange={e => setEditForm({...editForm, artist_bio: e.target.value})}
                         />
                    </div>
                </div>
             </div>
         )}

         {/* 2. Main Lyrics Card (Glassmorphism Effect) */}
         <div className="bg-white/90 backdrop-blur-xl p-6 md:p-12 rounded-3xl shadow-2xl border border-white/50 print:border-none print:shadow-none print:p-0">

             {/* Toolbar */}
             {!isEditing && (
                <div className="flex flex-col sm:flex-row justify-between items-center mb-8 gap-4 border-b border-slate-100 pb-6 no-print">
                    <div className="flex bg-slate-100 p-1.5 rounded-xl shadow-inner w-full sm:w-auto">
                        <button
                            onClick={() => setActiveTab('nepali')}
                            className={`flex-1 sm:flex-none px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'nepali' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                        >
                        Nepali
                        </button>
                        <button
                            onClick={() => setActiveTab('roman')}
                            className={`flex-1 sm:flex-none px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'roman' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                        >
                        Romanized
                        </button>
                    </div>

                    <div className="flex items-center gap-1 bg-white border border-slate-200 p-1 rounded-xl shadow-sm overflow-x-auto max-w-full">
                        <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-primary rounded-lg transition-colors flex-shrink-0" title="Zoom Out"><ZoomOut className="w-5 h-5" /></button>
                        <span className="text-xs font-mono text-slate-300">|</span>
                        <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-primary rounded-lg transition-colors flex-shrink-0" title="Zoom In"><ZoomIn className="w-5 h-5" /></button>
                        <span className="text-xs font-mono text-slate-300">|</span>
                        <button onClick={handlePrint} className="p-2 text-slate-400 hover:text-primary rounded-lg transition-colors flex-shrink-0" title="Print"><Printer className="w-5 h-5" /></button>
                         <span className="text-xs font-mono text-slate-300">|</span>
                         <button 
                            onClick={handleFavorite} 
                            className={`p-2 rounded-lg transition-colors flex-shrink-0 ${isFav ? 'text-red-500 bg-red-50' : 'text-slate-400 hover:text-red-500'}`}
                            title={isFav ? "Saved to Favorites" : "Add to Favorites"}
                        >
                            <Heart className={`w-5 h-5 ${isFav ? 'fill-current' : ''}`} />
                        </button>
                        <span className="text-xs font-mono text-slate-300">|</span>
                        <button onClick={handleCopy} className="p-2 text-slate-400 hover:text-primary rounded-lg transition-colors flex-shrink-0" title="Copy Text">
                            {copied ? <Check className="w-5 h-5 text-green-500" /> : <Copy className="w-5 h-5" />}
                        </button>
                    </div>
                </div>
             )}

             {isEditing ? (
                 <div className="space-y-6">
                     <div>
                         <label className="block text-sm font-bold text-slate-500 mb-1">Nepali Lyrics</label>
                         <textarea className="w-full h-64 p-4 border rounded-xl font-sans bg-slate-50 focus:bg-white transition-colors" value={editForm.lyrics_nepali || ''} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                     </div>
                     <div>
                         <label className="block text-sm font-bold text-slate-500 mb-1">Romanized Lyrics</label>
                         <textarea className="w-full h-64 p-4 border rounded-xl font-sans bg-slate-50 focus:bg-white transition-colors" value={editForm.lyrics_roman || ''} onChange={e => setEditForm({...editForm, lyrics_roman: e.target.value})} />
                     </div>
                 </div>
             ) : (
                <div 
                    className="whitespace-pre-wrap font-sans leading-loose text-slate-800 tracking-wide lyrics-scroll text-center mx-auto max-w-3xl"
                    style={{ fontSize: `${fontSize}px`, lineHeight: 1.8 }}
                >
                    {activeTab === 'nepali' 
                        ? (data.lyrics_nepali || data.lyrics || "Lyrics available in Romanized version only.") 
                        : (data.lyrics_roman || "Romanized lyrics not available.")}
                </div>
             )}
         </div>

         {/* 3. Song Credits Card */}
         <div className="bg-white p-8 rounded-3xl shadow-lg border border-slate-100 no-print">
            <h3 className="text-xs font-extrabold text-slate-400 uppercase tracking-widest mb-6">Production Credits</h3>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="flex items-start space-x-4 p-4 rounded-2xl bg-slate-50 hover:bg-slate-100 transition-colors">
                    <div className="p-3 bg-white rounded-full shadow-sm text-indigo-500"><Music className="w-5 h-5" /></div>
                    <div>
                        <p className="text-xs text-slate-400 font-bold uppercase mb-1">Composer</p>
                        {renderCredits(composersList)}
                    </div>
                </div>
                <div className="flex items-start space-x-4 p-4 rounded-2xl bg-slate-50 hover:bg-slate-100 transition-colors">
                    <div className="p-3 bg-white rounded-full shadow-sm text-purple-500"><PenTool className="w-5 h-5" /></div>
                    <div>
                            <p className="text-xs text-slate-400 font-bold uppercase mb-1">Lyrics By</p>
                            {renderCredits(lyricistsList)}
                    </div>
                </div>
                {(singersList && (Array.isArray(singersList) ? singersList.length > 0 : singersList)) && (
                    <div className="flex items-start space-x-4 p-4 rounded-2xl bg-slate-50 hover:bg-slate-100 transition-colors sm:col-span-2 md:col-span-1">
                        <div className="p-3 bg-white rounded-full shadow-sm text-pink-500"><Mic2 className="w-5 h-5" /></div>
                        <div>
                                <p className="text-xs text-slate-400 font-bold uppercase mb-1">Vocals</p>
                                {renderCredits(singersList)}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* 4. Related Songs (Replaces More From Artist) */}
        {relatedSongs.length > 0 && (
            <div className="bg-white p-6 md:p-8 rounded-3xl shadow-lg border border-slate-100 no-print mt-8">
                <div className="flex justify-between items-center mb-6">
                     <h3 className="text-lg font-bold text-slate-900">More by {artist}</h3>
                     <Link to={`/artist/${encodeURIComponent(artist)}`} className="text-sm font-bold text-primary hover:underline flex items-center">
                         View All <ArrowRight className="w-4 h-4 ml-1" />
                     </Link>
                </div>
                <div className="space-y-2">
                    {relatedSongs.map((s, idx) => {
                        const relTitle = (appLanguage === 'nepali' && s.title_nepali) ? s.title_nepali : s.title;
                        return (
                        <Link 
                            key={idx} 
                            to={`/lyrics/${encodeURIComponent(s.artist)}/${encodeURIComponent(s.title)}`} 
                            className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 transition-all group border border-transparent hover:border-slate-100"
                        >
                            <div className="flex items-center gap-4 overflow-hidden">
                                <div className="w-8 h-8 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center flex-shrink-0 text-xs font-bold shadow-sm">
                                    {idx + 1}
                                </div>
                                <span className={`font-bold text-base truncate transition-colors ${getSongColorClass(s.language)}`}>
                                    {relTitle}
                                </span>
                            </div>
                            <ArrowRight className="w-4 h-4 text-slate-300 group-hover:text-primary transform group-hover:translate-x-1 transition-all" />
                        </Link>
                    )})}
                </div>
            </div>
        )}

        {/* 5. Bottom Actions */}
        <div className="grid grid-cols-1 gap-4 no-print">
            <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-around">
                 {socialLinks.map((link) => (
                    <a 
                        key={link.name}
                        href={link.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className={`w-12 h-12 flex items-center justify-center rounded-full transition-all hover:scale-110 shadow-sm ${link.color}`}
                        title={`Share on ${link.name}`}
                    >
                        {link.icon}
                    </a>
                ))}
                 <button onClick={() => setIsFeedbackOpen(true)} className="w-12 h-12 flex items-center justify-center rounded-full bg-slate-100 text-slate-400 hover:bg-slate-200 hover:text-slate-600 transition-all" title="Report Issue">
                     <Flag className="w-5 h-5" />
                 </button>
            </div>
        </div>

        {/* YouTube Player Section - Moved to Bottom */}
         {!isEditing && showYoutube && youtubeId && (
            <div className="bg-black rounded-3xl overflow-hidden shadow-2xl no-print mt-8">
                 <div className="aspect-w-16 aspect-h-9 relative" style={{ paddingBottom: '56.25%' }}>
                     <iframe 
                        src={`https://www.youtube.com/embed/${youtubeId}`} 
                        title="YouTube video player" 
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                        allowFullScreen
                        className="absolute top-0 left-0 w-full h-full"
                     ></iframe>
                 </div>
            </div>
         )}

      </div>

      {/* Feedback Modal */}
      {isFeedbackOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
            <div className="bg-white rounded-3xl shadow-2xl max-w-md w-full overflow-hidden animate-in fade-in zoom-in duration-200">
                <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <h3 className="font-bold text-slate-800 text-lg">Report Issue</h3>
                    <button onClick={() => setIsFeedbackOpen(false)} className="text-slate-400 hover:text-slate-600 bg-white p-2 rounded-full shadow-sm">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {feedbackSubmitted ? (
                    <div className="p-12 text-center">
                        <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4 animate-bounce">
                            <Check className="w-8 h-8" />
                        </div>
                        <h4 className="font-bold text-xl text-slate-800 mb-2">Thank You!</h4>
                        <p className="text-slate-500">Your feedback helps us improve.</p>
                    </div>
                ) : (
                    <form onSubmit={submitFeedback} className="p-6 space-y-5">
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-2">Issue Type</label>
                            <select 
                                value={feedbackType} 
                                onChange={(e) => setFeedbackType(e.target.value)}
                                className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary focus:border-transparent outline-none bg-slate-50"
                            >
                                <option value="lyrics">Wrong Lyrics</option>
                                <option value="credits">Wrong Credits</option>
                                <option value="typo">Typos / Formatting</option>
                                <option value="other">Other Suggestion</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-2">Details</label>
                            <textarea 
                                value={feedbackText}
                                onChange={(e) => setFeedbackText(e.target.value)}
                                rows={4} 
                                placeholder="Please describe the issue..."
                                className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:ring-2 focus:ring-primary focus:border-transparent outline-none bg-slate-50"
                                required
                            ></textarea>
                        </div>
                        <button 
                            type="submit" 
                            className="w-full py-4 rounded-xl bg-primary text-white font-bold hover:bg-primary/90 transition-all shadow-lg shadow-primary/30 transform active:scale-95"
                        >
                            Submit Report
                        </button>
                    </form>
                )}
            </div>
        </div>
      )}

    </div>
  );
};

