import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { searchMusic } from '../services/geminiService';
import { SearchResult } from '../types';
import Loader from '../components/Loader';
import { Mic2, Disc, Search, Grid } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

const SearchPage: React.FC = () => {
  const { query } = useParams<{ query: string }>();
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchInput, setSearchInput] = useState('');
  const navigate = useNavigate();
  const { language: appLanguage } = useLanguage();

  useEffect(() => {
    const fetchSearch = async () => {
      if (query) {
        setLoading(true);
        const data = await searchMusic(query);
        setResults(data);
        setLoading(false);
      } else {
        setResults([]);
      }
    };
    fetchSearch();
  }, [query]);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchInput.trim()) {
      navigate(`/search/${encodeURIComponent(searchInput)}`);
    }
  };

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-900';
  };

  if (!query) {
    return (
      <div className="min-h-screen max-w-7xl mx-auto px-4 py-8 flex flex-col items-center justify-center -mt-20 h-[80vh]">
        <div className="w-full max-w-md text-center space-y-6">
          <div className="mx-auto w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center mb-4">
            <Search className="w-8 h-8 text-primary" />
          </div>
          <h1 className="text-3xl font-bold text-slate-900">Search</h1>
          <p className="text-slate-500">Find your favorite artists, songs, and lyrics.</p>

          <form onSubmit={handleSearchSubmit} className="relative w-full">
            <input
              autoFocus
              type="text"
              placeholder="What do you want to listen to?"
              className="w-full bg-white border border-slate-200 rounded-full py-4 pl-12 pr-6 text-lg text-slate-900 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-primary shadow-lg transition-all"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
            />
            <Search className="absolute left-4 top-4.5 w-6 h-6 text-slate-400" />
          </form>

          <div className="flex flex-wrap justify-center gap-2 mt-8">
            <span className="text-xs text-slate-400 uppercase font-bold tracking-wider w-full mb-2">Popular Searches</span>
            {['Worship', 'Praise', 'Adrian Dewan', 'Rohit Thapa', 'Lydia Rai', 'Funeral'].map(term => (
              <button 
                key={term}
                onClick={() => navigate(`/search/${term}`)}
                className="px-4 py-2 bg-slate-100 hover:bg-slate-200 rounded-full text-sm text-slate-600 transition-colors"
              >
                {term}
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen max-w-7xl mx-auto px-4 py-8">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-slate-900 mb-4">
          Results for "<span className="text-primary">{query}</span>"
        </h1>
         <form onSubmit={(e) => { e.preventDefault(); navigate(`/search/${encodeURIComponent(searchInput)}`); }} className="relative md:w-1/2">
            <input
              type="text"
              placeholder="Search again..."
              className="w-full bg-white border border-slate-200 rounded-lg py-2 pl-10 pr-4 text-slate-900 focus:outline-none focus:border-primary shadow-sm"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
            />
            <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
        </form>
      </div>

      {loading ? (
        <Loader text="Searching database..." />
      ) : results.length === 0 ? (
        <div className="text-center py-20 text-slate-400 bg-white rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-xl font-semibold mb-2">No results found</p>
          <p>Try checking for typos or using different keywords.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {results.map((item, idx) => {
            const titleClass = item.type === 'song' ? getSongColorClass(item.language) : 'text-slate-900';
            const displayTitle = (item.type === 'song' && appLanguage === 'nepali' && item.name_nepali) ? item.name_nepali : item.name;

            let linkPath = '';
            if (item.type === 'song') {
                linkPath = `/l/${item.id}`; // Updated to short URL
            } else if (item.type === 'artist') {
                linkPath = `/artist/${encodeURIComponent(item.name)}`;
            } else if (item.type === 'category') {
                linkPath = `/category/${encodeURIComponent(item.name)}`;
            }

            let thumb = null;
            if (item.type === 'artist') {
                const isUnknownArtist = item.name.toLowerCase() === 'unknown';
                const imageUrl = isUnknownArtist 
                    ? "https://ui-avatars.com/api/?name=Unknown&background=e2e8f0&color=64748b&size=150" 
                    : (item.imageUrl || `https://picsum.photos/seed/${item.name + item.type}/150`);
                thumb = (
                    <div className="w-16 h-16 rounded-lg bg-slate-200 overflow-hidden flex-shrink-0 mr-4 border border-slate-100">
                       <img src={imageUrl} alt={item.name} className="w-full h-full object-cover" />
                    </div>
                );
            } else if (item.type === 'category') {
                thumb = (
                    <div className="w-16 h-16 rounded-lg bg-emerald-100 flex items-center justify-center flex-shrink-0 mr-4 border border-emerald-50 text-emerald-600">
                        {item.imageUrl ? (
                            <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover rounded-lg" />
                        ) : (
                            <Grid className="w-8 h-8" />
                        )}
                    </div>
                );
            } else {
                thumb = (
                    <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0 mr-4 group-hover:bg-primary/20 transition-colors">
                        <Disc className="w-6 h-6 text-primary" />
                    </div>
                );
            }

            return (
            <Link
              key={idx}
              to={linkPath}
              className="flex items-center p-4 bg-white rounded-xl border border-slate-200 hover:border-primary/50 hover:bg-slate-50 transition-all group shadow-sm hover:shadow-md"
            >
              {thumb}
              <div className="flex-1 min-w-0">
                <div className="flex items-center space-x-2 mb-1">
                    {item.type === 'artist' && <Mic2 className="w-3 h-3 text-secondary" />}
                    {item.type === 'song' && <Disc className="w-3 h-3 text-primary" />}
                    {item.type === 'category' && <Grid className="w-3 h-3 text-emerald-500" />}
                    <span className="text-[10px] font-bold uppercase text-slate-400">{item.type}</span>
                </div>
                <h3 className={`text-lg font-bold transition-colors truncate ${titleClass}`}>{displayTitle}</h3>
                <p className="text-slate-500 text-sm truncate">{item.subtext}</p>
              </div>
            </Link>
          )})}
        </div>
      )}
    </div>
  );
};

export default SearchPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { getAllCustomSongs } from '../utils/dataManager';
import Loader from '../components/Loader';
import { ArrowLeft, Music, Disc, Grid } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface DisplaySong {
  id: string;
  title: string;
  title_nepali?: string;
  artist: string;
  language?: string;
}

const CategoryDetailsPage: React.FC = () => {
  const { category } = useParams<{ category: string }>();
  const [songs, setSongs] = useState<DisplaySong[]>([]);
  const [loading, setLoading] = useState(true);
  const { language: appLanguage } = useLanguage();

  useEffect(() => {
    const fetchSongs = async () => {
      setLoading(true);
      if (!category) {
        setLoading(false);
        return;
      }

      const allSongs = await getAllCustomSongs();
      const decodedCategory = decodeURIComponent(category);

      const filtered = allSongs.filter(song => {
        if (song.categories && song.categories.includes(decodedCategory)) {
            return true;
        }
        if (song.category === decodedCategory) {
            return true;
        }
        return false;
      });

      filtered.sort((a, b) => a.title.localeCompare(b.title));

      setSongs(filtered.map(s => ({ 
          id: s.id,
          title: s.title, 
          title_nepali: s.title_nepali, 
          artist: s.artist, 
          language: s.language 
      })));
      setLoading(false);
    };

    fetchSongs();
  }, [category]);

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-800';
  };

  if (loading) return <Loader fullScreen text="Loading songs..." />;

  const decodedCategory = category ? decodeURIComponent(category) : 'Unknown Category';

  const getGradient = (str: string) => {
    const hash = str.split('').reduce((acc, char) => char.charCodeAt(0) + ((acc << 5) - acc), 0);
    const gradients = [
      'from-pink-500 to-rose-500', 'from-red-500 to-orange-500', 'from-purple-500 to-indigo-500',
      'from-blue-500 to-cyan-500', 'from-amber-500 to-yellow-500', 'from-emerald-500 to-teal-500',
      'from-indigo-500 to-violet-500', 'from-slate-600 to-slate-800', 'from-orange-500 to-amber-500'
    ];
    return gradients[Math.abs(hash) % gradients.length];
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <div className={`bg-gradient-to-r ${getGradient(decodedCategory)} text-white py-12 px-4 shadow-lg`}>
        <div className="max-w-4xl mx-auto">
            <Link to="/categories" className="inline-flex items-center text-white/80 hover:text-white mb-6 transition-colors font-medium">
                <ArrowLeft className="w-5 h-5 mr-2" /> Back to Categories
            </Link>
            <div className="flex items-center gap-6">
                <div className="w-20 h-20 bg-white/20 rounded-2xl flex items-center justify-center backdrop-blur-sm shadow-inner">
                    <Grid className="w-10 h-10 text-white" />
                </div>
                <div>
                    <h1 className="text-4xl md:text-5xl font-extrabold tracking-tight mb-2">{decodedCategory}</h1>
                    <p className="text-white/90 font-medium text-lg">{songs.length} {songs.length === 1 ? 'Song' : 'Songs'}</p>
                </div>
            </div>
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-4 py-8 -mt-8">
        <div className="bg-white rounded-3xl shadow-xl border border-slate-100 overflow-hidden min-h-[400px]">
            {songs.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                    <Music className="w-16 h-16 mb-4 opacity-20" />
                    <p className="text-lg">No songs found in this category yet.</p>
                </div>
            ) : (
                <div className="divide-y divide-slate-100">
                    {songs.map((song, idx) => {
                        const displayTitle = (appLanguage === 'nepali' && song.title_nepali) ? song.title_nepali : song.title;
                        return (
                        <Link 
                            key={idx}
                            to={`/l/${song.id}`} // Updated to short URL
                            className="flex items-center justify-between p-5 hover:bg-slate-50 transition-colors group"
                        >
                            <div className="flex items-center gap-5">
                                <span className="text-slate-300 font-bold text-lg w-6 text-center group-hover:text-primary transition-colors">{idx + 1}</span>
                                <div>
                                    <h3 className={`text-lg font-bold transition-colors ${getSongColorClass(song.language)}`}>{displayTitle}</h3>
                                    <div className="flex items-center text-slate-500 text-sm mt-0.5">
                                        <Disc className="w-3 h-3 mr-1" />
                                        {song.artist}
                                    </div>
                                </div>
                            </div>
                            <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 group-hover:bg-primary group-hover:text-white transition-all transform group-hover:translate-x-1">
                                <ArrowLeft className="w-4 h-4 rotate-180" />
                            </div>
                        </Link>
                    )})}
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default CategoryDetailsPage;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getFavorites, FavoriteItem } from '../utils/storage';
import { getSongLyrics } from '../services/geminiService';
import { LyricsData } from '../types';
import { Heart, Mic2, Disc, ArrowRight, Play, X, ChevronLeft, ChevronRight, Loader2, ZoomIn, ZoomOut, Maximize, Minimize, PlayCircle, PauseCircle, ListOrdered, Circle, SkipBack, SkipForward, Settings, Upload, RefreshCw, Image as ImageIcon } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

const FavoritesPage: React.FC = () => {
  const [favorites, setFavorites] = useState<FavoriteItem[]>([]);
  const navigate = useNavigate();
  const { t } = useLanguage();

  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [presentationQueue, setPresentationQueue] = useState<FavoriteItem[]>([]);

  const [isPresenting, setIsPresenting] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [lyricsData, setLyricsData] = useState<LyricsData | null>(null);
  const [loadingLyrics, setLoadingLyrics] = useState(false);
  const [fontSize, setFontSize] = useState(24);

  const [bgImage, setBgImage] = useState<string>('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
  const [bgBlur, setBgBlur] = useState(4);
  const [bgOpacity, setBgOpacity] = useState(50);
  const [showSettings, setShowSettings] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isBrowserFullscreen, setIsBrowserFullscreen] = useState(false);
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setFavorites(getFavorites());
    const handleContentChange = () => setFavorites(getFavorites());
    window.addEventListener('content-change', handleContentChange);
    return () => window.removeEventListener('content-change', handleContentChange);
  }, []);

  const allFavoriteSongs = favorites.filter(f => f.type === 'song');
  const slidesToPresent = presentationQueue.length > 0 ? presentationQueue : allFavoriteSongs;

  const fetchSlideLyrics = async (index: number) => {
    setLoadingLyrics(true);
    setLyricsData(null);
    setIsAutoScrolling(false);
    if (scrollContainerRef.current) scrollContainerRef.current.scrollTop = 0;

    const item = slidesToPresent[index];
    if (item) {
        const data = await getSongLyrics(item.subtext, item.name);
        setLyricsData(data);
    }
    setLoadingLyrics(false);
  };

  const startPresentation = () => {
    if (slidesToPresent.length === 0) return;
    setCurrentIndex(0);
    setIsPresenting(true);
    fetchSlideLyrics(0);
  };

  const nextSlide = useCallback(() => {
    if (currentIndex < slidesToPresent.length - 1) {
      const newIndex = currentIndex + 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex, slidesToPresent.length]);

  const prevSlide = useCallback(() => {
    if (currentIndex > 0) {
      const newIndex = currentIndex - 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex]);

  const closePresentation = useCallback(() => {
    setIsPresenting(false);
    setLyricsData(null);
    setIsAutoScrolling(false);
    setShowSettings(false);
    if (document.fullscreenElement) document.exitFullscreen().catch(e => console.error(e));
  }, []);

  const handleZoomIn = useCallback(() => setFontSize(prev => Math.min(prev + 4, 120)), []);
  const handleZoomOut = useCallback(() => setFontSize(prev => Math.max(prev - 4, 16)), []);

  const toggleBrowserFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().then(() => setIsBrowserFullscreen(true)).catch(err => console.error(err));
    } else {
        document.exitFullscreen().then(() => setIsBrowserFullscreen(false));
    }
  }, []);

  const toggleAutoScroll = () => setIsAutoScrolling(!isAutoScrolling);
  const toggleSelectionMode = () => {
      setIsSelectionMode(!isSelectionMode);
      setPresentationQueue([]);
  };

  const handleSelectSong = (item: FavoriteItem) => {
      const existsIdx = presentationQueue.findIndex(i => i.id === item.id);
      if (existsIdx >= 0) {
          const newQueue = [...presentationQueue];
          newQueue.splice(existsIdx, 1);
          setPresentationQueue(newQueue);
      } else {
          setPresentationQueue([...presentationQueue, item]);
      }
  };

  const handleBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => setBgImage(reader.result as string);
        reader.readAsDataURL(file);
    }
  };

  const resetSettings = () => {
      setBgImage('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
      setBgBlur(4);
      setBgOpacity(50);
  };

  useEffect(() => {
      const handleFsChange = () => setIsBrowserFullscreen(!!document.fullscreenElement);
      document.addEventListener('fullscreenchange', handleFsChange);
      return () => document.removeEventListener('fullscreenchange', handleFsChange);
  }, []);

  useEffect(() => {
      let interval: ReturnType<typeof setInterval>;
      if (isAutoScrolling && scrollContainerRef.current) {
          interval = setInterval(() => {
              if (scrollContainerRef.current) {
                  scrollContainerRef.current.scrollTop += 1;
                  if (scrollContainerRef.current.scrollHeight - scrollContainerRef.current.scrollTop === scrollContainerRef.current.clientHeight) {
                      setIsAutoScrolling(false);
                  }
              }
          }, 40);
      }
      return () => clearInterval(interval);
  }, [isAutoScrolling]);

  useEffect(() => {
    if (!isPresenting) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight') nextSlide();
      else if (e.key === 'ArrowLeft') prevSlide();
      else if (e.key === 'Escape') if (!document.fullscreenElement) closePresentation();
      else if (e.key === '+' || e.key === '=') handleZoomIn();
      else if (e.key === '-') handleZoomOut();
      else if (e.key === 'f') toggleBrowserFullscreen();
      else if (e.key === ' ') { e.preventDefault(); toggleAutoScroll(); }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPresenting, nextSlide, prevSlide, closePresentation, handleZoomIn, handleZoomOut, toggleBrowserFullscreen, isAutoScrolling]);

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-900';
  };

  if (isPresenting) {
    const hasRoman = lyricsData?.lyrics_roman && lyricsData.lyrics_roman.trim().length > 0;
    return (
      <div className="fixed inset-0 z-50 bg-black text-white flex flex-col overflow-hidden">
        <div className="absolute inset-0 z-0">
           <img src={bgImage} alt="Background" className="w-full h-full object-cover transition-all duration-700" style={{ filter: `blur(${bgBlur}px)` }} />
           <div className="absolute inset-0 bg-black transition-opacity duration-300" style={{ opacity: bgOpacity / 100 }}></div>
        </div>
        <div className="flex justify-between items-center p-3 md:p-4 bg-black/40 backdrop-blur-md z-30 absolute top-0 left-0 right-0 border-b border-white/10 overflow-visible">
           <div className="text-sm font-medium text-white/80 whitespace-nowrap hidden sm:block">{currentIndex + 1} / {slidesToPresent.length}</div>
           <div className="flex items-center space-x-2 md:space-x-3 min-w-max mx-auto sm:mx-0">
               <button onClick={prevSlide} disabled={currentIndex === 0} className="p-2 hover:bg-white/20 rounded-full transition-colors disabled:opacity-30"><SkipBack className="w-5 h-5" /></button>
               <button onClick={nextSlide} disabled={currentIndex === slidesToPresent.length - 1} className="p-2 hover:bg-white/20 rounded-full transition-colors disabled:opacity-30"><SkipForward className="w-5 h-5" /></button>
               <div className="w-px h-6 bg-white/20 mx-1"></div>
               <button onClick={toggleAutoScroll} className={`p-2 rounded-full transition-colors ${isAutoScrolling ? 'bg-primary text-white' : 'hover:bg-white/20'}`}>{isAutoScrolling ? <PauseCircle className="w-5 h-5" /> : <PlayCircle className="w-5 h-5" />}</button>
               <div className="w-px h-6 bg-white/20 mx-1"></div>
               <button onClick={handleZoomOut} className="p-2 hover:bg-white/20 rounded-full transition-colors"><ZoomOut className="w-5 h-5" /></button>
               <button onClick={handleZoomIn} className="p-2 hover:bg-white/20 rounded-full transition-colors"><ZoomIn className="w-5 h-5" /></button>
               <div className="w-px h-6 bg-white/20 mx-1"></div>
               <div className="relative">
                   <button onClick={() => setShowSettings(!showSettings)} className={`p-2 rounded-full transition-colors ${showSettings ? 'bg-white/20' : 'hover:bg-white/20'}`}><Settings className="w-5 h-5" /></button>
                   {showSettings && (
                       <div className="absolute top-full right-0 mt-2 w-72 bg-slate-900/95 backdrop-blur-xl border border-white/10 rounded-2xl p-4 shadow-2xl z-50 text-left">
                           <div className="space-y-4">
                               <div>
                                   <label className="text-xs font-bold text-slate-400 uppercase mb-2 block">Background Image</label>
                                   <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-center gap-2 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-sm transition-colors border border-white/5"><Upload className="w-4 h-4" /> Upload Image</button>
                                   <input type="file" ref={fileInputRef} onChange={handleBgUpload} className="hidden" accept="image/*" />
                               </div>
                               <div>
                                   <div className="flex justify-between text-xs mb-1"><span className="text-slate-400 font-bold uppercase">Blur</span><span className="text-white font-mono">{bgBlur}px</span></div>
                                   <input type="range" min="0" max="20" value={bgBlur} onChange={(e) => setBgBlur(Number(e.target.value))} className="w-full h-1 bg-white/20 rounded-full appearance-none cursor-pointer" />
                               </div>
                               <div>
                                   <div className="flex justify-between text-xs mb-1"><span className="text-slate-400 font-bold uppercase">Overlay</span><span className="text-white font-mono">{bgOpacity}%</span></div>
                                   <input type="range" min="0" max="90" value={bgOpacity} onChange={(e) => setBgOpacity(Number(e.target.value))} className="w-full h-1 bg-white/20 rounded-full appearance-none cursor-pointer" />
                               </div>
                               <div className="pt-2 border-t border-white/10"><button onClick={resetSettings} className="w-full flex items-center justify-center gap-2 py-2 text-xs text-red-400 hover:bg-red-500/10 rounded-lg"><RefreshCw className="w-3 h-3" /> Reset</button></div>
                           </div>
                       </div>
                   )}
               </div>
               <button onClick={toggleBrowserFullscreen} className="p-2 hover:bg-white/20 rounded-full transition-colors">{isBrowserFullscreen ? <Minimize className="w-5 h-5" /> : <Maximize className="w-5 h-5" />}</button>
               <button onClick={closePresentation} className="p-2 hover:bg-red-500/20 rounded-full transition-colors text-red-400"><X className="w-5 h-5" /></button>
           </div>
        </div>
        <div className="absolute inset-y-0 left-0 w-12 md:w-24 z-20 hover:bg-white/5 cursor-pointer flex items-center justify-start group" onClick={prevSlide}><ChevronLeft className="w-6 h-6 md:w-12 md:h-12 text-white/20 group-hover:text-white/50 transition-colors ml-1" /></div>
        <div className="absolute inset-y-0 right-0 w-12 md:w-24 z-20 hover:bg-white/5 cursor-pointer flex items-center justify-end group" onClick={nextSlide}><ChevronRight className="w-6 h-6 md:w-12 md:h-12 text-white/20 group-hover:text-white/50 transition-colors mr-1" /></div>
        <div ref={scrollContainerRef} className="flex-1 flex flex-col items-center p-4 md:p-12 lg:p-24 overflow-y-auto no-scrollbar w-full scroll-smooth z-10 relative mt-12 md:mt-0">
            <div className="w-full max-w-7xl mx-auto py-8 md:py-12">
                {loadingLyrics ? <div className="flex justify-center py-20"><Loader2 className="w-16 h-16 animate-spin text-white/80" /></div> : lyricsData ? (
                   <div className={`w-full pb-24 items-start ${hasRoman ? 'grid grid-cols-2 gap-4 md:gap-16' : 'flex justify-center'}`}>
                       <div className={`text-center ${hasRoman ? 'border-r border-white/20 pr-2 md:pr-8' : 'max-w-3xl'}`}>
                           {hasRoman && <h3 className="text-sm uppercase tracking-[0.2em] text-white/60 mb-4 md:mb-8 font-bold">Nepali</h3>}
                           <div className="whitespace-pre-wrap leading-relaxed font-sans font-bold text-white drop-shadow-[0_4px_6px_rgba(0,0,0,0.9)]" style={{ fontSize: `${fontSize}px` }}>{lyricsData.lyrics_nepali || "N/A"}</div>
                       </div>
                       {hasRoman && (
                           <div className="text-center pl-2 md:pl-8">
                               <h3 className="text-sm uppercase tracking-[0.2em] text-white/60 mb-4 md:mb-8 font-bold">Romanized</h3>
                                <div className="whitespace-pre-wrap leading-relaxed font-sans text-white/95 drop-shadow-[0_4px_6px_rgba(0,0,0,0.9)] font-medium" style={{ fontSize: `${fontSize}px` }}>{lyricsData.lyrics_roman}</div>
                           </div>
                       )}
                   </div>
                ) : <p className="text-center text-white/50 text-xl">N/A</p>}
            </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen max-w-7xl mx-auto px-4 py-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <h1 className="text-3xl font-bold text-slate-900">{t('Favorites')}</h1>
        {allFavoriteSongs.length > 0 && (
           <div className="flex items-center space-x-2 w-full md:w-auto">
               <button onClick={toggleSelectionMode} className={`flex-1 md:flex-none flex items-center justify-center px-4 py-2.5 rounded-full transition-all ${isSelectionMode ? 'bg-slate-200 text-slate-700 font-medium' : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'}`}>{isSelectionMode ? <X className="w-5 h-5 mr-2" /> : <ListOrdered className="w-5 h-5 mr-2" />}{isSelectionMode ? t('Cancel Selection') : t('Select Order')}</button>
               <button onClick={startPresentation} className="flex-1 md:flex-none flex items-center justify-center bg-primary text-white px-5 py-2.5 rounded-full hover:bg-primary/90 transition-all shadow-lg hover:shadow-primary/30 font-medium"><Play className="w-5 h-5 mr-2 fill-current" />{isSelectionMode && presentationQueue.length > 0 ? `${t('Play')} (${presentationQueue.length})` : t('Play All')}</button>
           </div>
        )}
      </div>

      {isSelectionMode && (
          <div className="mb-6 bg-blue-50 border border-blue-100 text-blue-800 p-4 rounded-xl flex items-center"><ListOrdered className="w-5 h-5 mr-3 text-blue-600" /><div><p className="font-bold text-sm">{t('Custom Presentation Mode')}</p><p className="text-xs mt-1 opacity-80">{t('Click songs to add them to your presentation queue.')}</p></div></div>
      )}

      {favorites.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-2xl border border-slate-200 shadow-sm"><Heart className="w-16 h-16 text-slate-200 mx-auto mb-4" /><h3 className="text-2xl font-bold text-slate-900 mb-2">{t('No favorites yet')}</h3><p className="text-slate-500 mb-6">{t('Start browsing songs and artists to add them to your collection.')}</p><Link to="/" className="inline-flex items-center text-primary font-bold hover:underline">{t('Browse Music')} <ArrowRight className="w-4 h-4 ml-1" /></Link></div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {favorites.map((item) => {
            const queueIndex = presentationQueue.findIndex(q => q.id === item.id);
            const isSelected = queueIndex >= 0;
            const titleClass = item.type === 'song' ? getSongColorClass(item.language) : 'text-slate-900';

            const CardContent = (
               <>
                <div className={`w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0 mr-4 transition-colors ${item.type === 'artist' ? 'bg-secondary/10 text-secondary group-hover:bg-secondary group-hover:text-white' : 'bg-primary/10 text-primary group-hover:bg-primary group-hover:text-white'}`}>{item.type === 'artist' ? <Mic2 className="w-6 h-6" /> : <Disc className="w-6 h-6" />}</div>
                <div className="flex-1 min-w-0"><div className="flex items-center space-x-2 mb-1">{item.type === 'artist' ? <Mic2 className="w-3 h-3 text-secondary" /> : <Disc className="w-3 h-3 text-primary" />}<span className="text-[10px] font-bold uppercase text-slate-400">{item.type}</span></div><h3 className={`text-lg font-bold transition-colors truncate ${titleClass}`}>{item.name}</h3><p className="text-slate-500 text-sm truncate">{item.subtext}</p></div>
                {isSelectionMode && item.type === 'song' && (<div className="ml-3">{isSelected ? <div className="w-8 h-8 rounded-full bg-primary text-white flex items-center justify-center font-bold shadow-md transform scale-110 transition-transform">{queueIndex + 1}</div> : <Circle className="w-8 h-8 text-slate-300" />}</div>)}
               </>
            );

            if (isSelectionMode && item.type === 'song') {
                return (<div key={item.id} onClick={() => handleSelectSong(item)} className={`flex items-center p-4 bg-white rounded-xl border cursor-pointer transition-all shadow-sm hover:shadow-md ${isSelected ? 'border-primary ring-1 ring-primary/50' : 'border-slate-200 hover:border-slate-300'}`}>{CardContent}</div>);
            }

            // Extract numeric ID from composite storage ID for short URL if it's a song
            const targetUrl = item.type === 'artist' 
                ? `/artist/${encodeURIComponent(item.name)}` 
                : `/l/${item.id.split('-').pop()}`; // Fallback to mapping if ID isn't simple serial

            return (
                <Link key={item.id} to={targetUrl} className="flex items-center p-4 bg-white rounded-xl border border-slate-200 hover:border-primary/50 hover:bg-slate-50 transition-all group shadow-sm hover:shadow-md">{CardContent}</Link>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default FavoritesPage;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getFavorites, FavoriteItem } from '../utils/storage';
import { getSongLyrics } from '../services/geminiService';
import { LyricsData } from '../types';
import { Heart, Mic2, Disc, ArrowRight, Play, X, ChevronLeft, ChevronRight, Loader2, ZoomIn, ZoomOut, Maximize, Minimize, PlayCircle, PauseCircle, ListOrdered, Circle, SkipBack, SkipForward, Settings, Upload, RefreshCw, Image as ImageIcon } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

const FavoritesPage: React.FC = () => {
  const [favorites, setFavorites] = useState<FavoriteItem[]>([]);
  const navigate = useNavigate();
  const { t } = useLanguage();

  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [presentationQueue, setPresentationQueue] = useState<FavoriteItem[]>([]);

  const [isPresenting, setIsPresenting] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [lyricsData, setLyricsData] = useState<LyricsData | null>(null);
  const [loadingLyrics, setLoadingLyrics] = useState(false);
  const [fontSize, setFontSize] = useState(24);

  const [bgImage, setBgImage] = useState<string>('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
  const [bgBlur, setBgBlur] = useState(4);
  const [bgOpacity, setBgOpacity] = useState(50);
  const [showSettings, setShowSettings] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isBrowserFullscreen, setIsBrowserFullscreen] = useState(false);
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setFavorites(getFavorites());
    const handleContentChange = () => setFavorites(getFavorites());
    window.addEventListener('content-change', handleContentChange);
    return () => window.removeEventListener('content-change', handleContentChange);
  }, []);

  const allFavoriteSongs = favorites.filter(f => f.type === 'song');
  const slidesToPresent = presentationQueue.length > 0 ? presentationQueue : allFavoriteSongs;

  const fetchSlideLyrics = async (index: number) => {
    setLoadingLyrics(true);
    setLyricsData(null);
    setIsAutoScrolling(false);
    if (scrollContainerRef.current) scrollContainerRef.current.scrollTop = 0;

    const item = slidesToPresent[index];
    if (item) {
        const data = await getSongLyrics(item.subtext, item.name);
        setLyricsData(data);
    }
    setLoadingLyrics(false);
  };

  const startPresentation = () => {
    if (slidesToPresent.length === 0) return;
    setCurrentIndex(0);
    setIsPresenting(true);
    fetchSlideLyrics(0);
  };

  const nextSlide = useCallback(() => {
    if (currentIndex < slidesToPresent.length - 1) {
      const newIndex = currentIndex + 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex, slidesToPresent.length]);

  const prevSlide = useCallback(() => {
    if (currentIndex > 0) {
      const newIndex = currentIndex - 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex]);

  const closePresentation = useCallback(() => {
    setIsPresenting(false);
    setLyricsData(null);
    setIsAutoScrolling(false);
    setShowSettings(false);
    if (document.fullscreenElement) document.exitFullscreen().catch(e => console.error(e));
  }, []);

  const handleZoomIn = useCallback(() => setFontSize(prev => Math.min(prev + 4, 120)), []);
  const handleZoomOut = useCallback(() => setFontSize(prev => Math.max(prev - 4, 16)), []);

  const toggleBrowserFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().then(() => setIsBrowserFullscreen(true)).catch(err => console.error(err));
    } else {
        document.exitFullscreen().then(() => setIsBrowserFullscreen(false));
    }
  }, []);

  const toggleAutoScroll = () => setIsAutoScrolling(!isAutoScrolling);
  const toggleSelectionMode = () => {
      setIsSelectionMode(!isSelectionMode);
      setPresentationQueue([]);
  };

  const handleSelectSong = (item: FavoriteItem) => {
      const existsIdx = presentationQueue.findIndex(i => i.id === item.id);
      if (existsIdx >= 0) {
          const newQueue = [...presentationQueue];
          newQueue.splice(existsIdx, 1);
          setPresentationQueue(newQueue);
      } else {
          setPresentationQueue([...presentationQueue, item]);
      }
  };

  const handleBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => setBgImage(reader.result as string);
        reader.readAsDataURL(file);
    }
  };

  const resetSettings = () => {
      setBgImage('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
      setBgBlur(4);
      setBgOpacity(50);
  };

  useEffect(() => {
      const handleFsChange = () => setIsBrowserFullscreen(!!document.fullscreenElement);
      document.addEventListener('fullscreenchange', handleFsChange);
      return () => document.removeEventListener('fullscreenchange', handleFsChange);
  }, []);

  useEffect(() => {
      let interval: ReturnType<typeof setInterval>;
      if (isAutoScrolling && scrollContainerRef.current) {
          interval = setInterval(() => {
              if (scrollContainerRef.current) {
                  scrollContainerRef.current.scrollTop += 1;
                  if (scrollContainerRef.current.scrollHeight - scrollContainerRef.current.scrollTop === scrollContainerRef.current.clientHeight) {
                      setIsAutoScrolling(false);
                  }
              }
          }, 40);
      }
      return () => clearInterval(interval);
  }, [isAutoScrolling]);

  useEffect(() => {
    if (!isPresenting) return;
    // Added braces to handleKeyDown branches to fix dangling else comparison errors
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight') nextSlide();
      else if (e.key === 'ArrowLeft') prevSlide();
      else if (e.key === 'Escape') {
        if (!document.fullscreenElement) closePresentation();
      }
      else if (e.key === '+' || e.key === '=') handleZoomIn();
      else if (e.key === '-') handleZoomOut();
      else if (e.key === 'f') toggleBrowserFullscreen();
      else if (e.key === ' ') { e.preventDefault(); toggleAutoScroll(); }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPresenting, nextSlide, prevSlide, closePresentation, handleZoomIn, handleZoomOut, toggleBrowserFullscreen, isAutoScrolling]);

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-900';
  };

  if (isPresenting) {
    const hasRoman = lyricsData?.lyrics_roman && lyricsData.lyrics_roman.trim().length > 0;
    return (
      <div className="fixed inset-0 z-50 bg-black text-white flex flex-col overflow-hidden">
        <div className="absolute inset-0 z-0">
           <img src={bgImage} alt="Background" className="w-full h-full object-cover transition-all duration-700" style={{ filter: `blur(${bgBlur}px)` }} />
           <div className="absolute inset-0 bg-black transition-opacity duration-300" style={{ opacity: bgOpacity / 100 }}></div>
        </div>
        <div className="flex justify-between items-center p-3 md:p-4 bg-black/40 backdrop-blur-md z-30 absolute top-0 left-0 right-0 border-b border-white/10 overflow-visible">
           <div className="text-sm font-medium text-white/80 whitespace-nowrap hidden sm:block">{currentIndex + 1} / {slidesToPresent.length}</div>
           <div className="flex items-center space-x-2 md:space-x-3 min-w-max mx-auto sm:mx-0">
               <button onClick={prevSlide} disabled={currentIndex === 0} className="p-2 hover:bg-white/20 rounded-full transition-colors disabled:opacity-30"><SkipBack className="w-5 h-5" /></button>
               <button onClick={nextSlide} disabled={currentIndex === slidesToPresent.length - 1} className="p-2 hover:bg-white/20 rounded-full transition-colors disabled:opacity-30"><SkipForward className="w-5 h-5" /></button>
               <div className="w-px h-6 bg-white/20 mx-1"></div>
               <button onClick={toggleAutoScroll} className={`p-2 rounded-full transition-colors ${isAutoScrolling ? 'bg-primary text-white' : 'hover:bg-white/20'}`}>{isAutoScrolling ? <PauseCircle className="w-5 h-5" /> : <PlayCircle className="w-5 h-5" />}</button>
               <div className="w-px h-6 bg-white/20 mx-1"></div>
               <button onClick={handleZoomOut} className="p-2 hover:bg-white/20 rounded-full transition-colors"><ZoomOut className="w-5 h-5" /></button>
               <button onClick={handleZoomIn} className="p-2 hover:bg-white/20 rounded-full transition-colors"><ZoomIn className="w-5 h-5" /></button>
               <div className="w-px h-6 bg-white/20 mx-1"></div>
               <div className="relative">
                   <button onClick={() => setShowSettings(!showSettings)} className={`p-2 rounded-full transition-colors ${showSettings ? 'bg-white/20' : 'hover:bg-white/20'}`}><Settings className="w-5 h-5" /></button>
                   {showSettings && (
                       <div className="absolute top-full right-0 mt-2 w-72 bg-slate-900/95 backdrop-blur-xl border border-white/10 rounded-2xl p-4 shadow-2xl z-50 text-left">
                           <div className="space-y-4">
                               <div>
                                   <label className="text-xs font-bold text-slate-400 uppercase mb-2 block">Background Image</label>
                                   <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center justify-center gap-2 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-sm transition-colors border border-white/5"><Upload className="w-4 h-4" /> Upload Image</button>
                                   <input type="file" ref={fileInputRef} onChange={handleBgUpload} className="hidden" accept="image/*" />
                               </div>
                               <div>
                                   <div className="flex justify-between text-xs mb-1"><span className="text-slate-400 font-bold uppercase">Blur</span><span className="text-white font-mono">{bgBlur}px</span></div>
                                   <input type="range" min="0" max="20" value={bgBlur} onChange={(e) => setBgBlur(Number(e.target.value))} className="w-full h-1 bg-white/20 rounded-full appearance-none cursor-pointer" />
                               </div>
                               <div>
                                   <div className="flex justify-between text-xs mb-1"><span className="text-slate-400 font-bold uppercase">Overlay</span><span className="text-white font-mono">{bgOpacity}%</span></div>
                                   <input type="range" min="0" max="90" value={bgOpacity} onChange={(e) => setBgOpacity(Number(e.target.value))} className="w-full h-1 bg-white/20 rounded-full appearance-none cursor-pointer" />
                               </div>
                               <div className="pt-2 border-t border-white/10"><button onClick={resetSettings} className="w-full flex items-center justify-center gap-2 py-2 text-xs text-red-400 hover:bg-red-500/10 rounded-lg"><RefreshCw className="w-3 h-3" /> Reset</button></div>
                           </div>
                       </div>
                   )}
               </div>
               <button onClick={toggleBrowserFullscreen} className="p-2 hover:bg-white/20 rounded-full transition-colors">{isBrowserFullscreen ? <Minimize className="w-5 h-5" /> : <Maximize className="w-5 h-5" />}</button>
               <button onClick={closePresentation} className="p-2 hover:bg-red-500/20 rounded-full transition-colors text-red-400"><X className="w-5 h-5" /></button>
           </div>
        </div>
        <div className="absolute inset-y-0 left-0 w-12 md:w-24 z-20 hover:bg-white/5 cursor-pointer flex items-center justify-start group" onClick={prevSlide}><ChevronLeft className="w-6 h-6 md:w-12 md:h-12 text-white/20 group-hover:text-white/50 transition-colors ml-1" /></div>
        <div className="absolute inset-y-0 right-0 w-12 md:w-24 z-20 hover:bg-white/5 cursor-pointer flex items-center justify-end group" onClick={nextSlide}><ChevronRight className="w-6 h-6 md:w-12 md:h-12 text-white/20 group-hover:text-white/50 transition-colors mr-1" /></div>
        <div ref={scrollContainerRef} className="flex-1 flex flex-col items-center p-4 md:p-12 lg:p-24 overflow-y-auto no-scrollbar w-full scroll-smooth z-10 relative mt-12 md:mt-0">
            <div className="w-full max-w-7xl mx-auto py-8 md:py-12">
                {loadingLyrics ? <div className="flex justify-center py-20"><Loader2 className="w-16 h-16 animate-spin text-white/80" /></div> : lyricsData ? (
                   <div className={`w-full pb-24 items-start ${hasRoman ? 'grid grid-cols-2 gap-4 md:gap-16' : 'flex justify-center'}`}>
                       <div className={`text-center ${hasRoman ? 'border-r border-white/20 pr-2 md:pr-8' : 'max-w-3xl'}`}>
                           {hasRoman && <h3 className="text-sm uppercase tracking-[0.2em] text-white/60 mb-4 md:mb-8 font-bold">Nepali</h3>}
                           <div className="whitespace-pre-wrap leading-relaxed font-sans font-bold text-white drop-shadow-[0_4px_6px_rgba(0,0,0,0.9)]" style={{ fontSize: `${fontSize}px` }}>{lyricsData.lyrics_nepali || "N/A"}</div>
                       </div>
                       {hasRoman && (
                           <div className="text-center pl-2 md:pl-8">
                               <h3 className="text-sm uppercase tracking-[0.2em] text-white/60 mb-4 md:mb-8 font-bold">Romanized</h3>
                                <div className="whitespace-pre-wrap leading-relaxed font-sans text-white/95 drop-shadow-[0_4px_6px_rgba(0,0,0,0.9)] font-medium" style={{ fontSize: `${fontSize}px` }}>{lyricsData.lyrics_roman}</div>
                           </div>
                       )}
                   </div>
                ) : <p className="text-center text-white/50 text-xl">N/A</p>}
            </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen max-w-7xl mx-auto px-4 py-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <h1 className="text-3xl font-bold text-slate-900">{t('Favorites')}</h1>
        {allFavoriteSongs.length > 0 && (
           <div className="flex items-center space-x-2 w-full md:w-auto">
               <button onClick={toggleSelectionMode} className={`flex-1 md:flex-none flex items-center justify-center px-4 py-2.5 rounded-full transition-all ${isSelectionMode ? 'bg-slate-200 text-slate-700 font-medium' : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'}`}>{isSelectionMode ? <X className="w-5 h-5 mr-2" /> : <ListOrdered className="w-5 h-5 mr-2" />}{isSelectionMode ? t('Cancel Selection') : t('Select Order')}</button>
               <button onClick={startPresentation} className="flex-1 md:flex-none flex items-center justify-center bg-primary text-white px-5 py-2.5 rounded-full hover:bg-primary/90 transition-all shadow-lg hover:shadow-primary/30 font-medium"><Play className="w-5 h-5 mr-2 fill-current" />{isSelectionMode && presentationQueue.length > 0 ? `${t('Play')} (${presentationQueue.length})` : t('Play All')}</button>
           </div>
        )}
      </div>

      {isSelectionMode && (
          <div className="mb-6 bg-blue-50 border border-blue-100 text-blue-800 p-4 rounded-xl flex items-center"><ListOrdered className="w-5 h-5 mr-3 text-blue-600" /><div><p className="font-bold text-sm">{t('Custom Presentation Mode')}</p><p className="text-xs mt-1 opacity-80">{t('Click songs to add them to your presentation queue.')}</p></div></div>
      )}

      {favorites.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-2xl border border-slate-200 shadow-sm"><Heart className="w-16 h-16 text-slate-200 mx-auto mb-4" /><h3 className="text-2xl font-bold text-slate-900 mb-2">{t('No favorites yet')}</h3><p className="text-slate-500 mb-6">{t('Start browsing songs and artists to add them to your collection.')}</p><Link to="/" className="inline-flex items-center text-primary font-bold hover:underline">{t('Browse Music')} <ArrowRight className="w-4 h-4 ml-1" /></Link></div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {favorites.map((item) => {
            const queueIndex = presentationQueue.findIndex(q => q.id === item.id);
            const isSelected = queueIndex >= 0;
            const titleClass = item.type === 'song' ? getSongColorClass(item.language) : 'text-slate-900';

            const CardContent = (
               <>
                <div className={`w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0 mr-4 transition-colors ${item.type === 'artist' ? 'bg-secondary/10 text-secondary group-hover:bg-secondary group-hover:text-white' : 'bg-primary/10 text-primary group-hover:bg-primary group-hover:text-white'}`}>{item.type === 'artist' ? <Mic2 className="w-6 h-6" /> : <Disc className="w-6 h-6" />}</div>
                <div className="flex-1 min-w-0"><div className="flex items-center space-x-2 mb-1">{item.type === 'artist' ? <Mic2 className="w-3 h-3 text-secondary" /> : <Disc className="w-3 h-3 text-primary" />}<span className="text-[10px] font-bold uppercase text-slate-400">{item.type}</span></div><h3 className={`text-lg font-bold transition-colors truncate ${titleClass}`}>{item.name}</h3><p className="text-slate-500 text-sm truncate">{item.subtext}</p></div>
                {isSelectionMode && item.type === 'song' && (<div className="ml-3">{isSelected ? <div className="w-8 h-8 rounded-full bg-primary text-white flex items-center justify-center font-bold shadow-md transform scale-110 transition-transform">{queueIndex + 1}</div> : <Circle className="w-8 h-8 text-slate-300" />}</div>)}
               </>
            );

            if (isSelectionMode && item.type === 'song') {
                return (<div key={item.id} onClick={() => handleSelectSong(item)} className={`flex items-center p-4 bg-white rounded-xl border cursor-pointer transition-all shadow-sm hover:shadow-md ${isSelected ? 'border-primary ring-1 ring-primary/50' : 'border-slate-200 hover:border-slate-300'}`}>{CardContent}</div>);
            }

            // Extract numeric ID from composite storage ID for short URL if it's a song
            const targetUrl = item.type === 'artist' 
                ? `/artist/${encodeURIComponent(item.name)}` 
                : `/l/${item.id.split('-').pop()}`; // Fallback to mapping if ID isn't simple serial

            return (
                <Link key={item.id} to={targetUrl} className="flex items-center p-4 bg-white rounded-xl border border-slate-200 hover:border-primary/50 hover:bg-slate-50 transition-all group shadow-sm hover:shadow-md">{CardContent}</Link>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default FavoritesPage;

import React, { useState, useEffect, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth, logout } from '../utils/auth';
import { 
  getAllCustomSongs, 
  saveCustomSong, 
  saveCustomArtist, 
  getAllCustomArtists, 
  deleteCustomSong, 
  deleteCustomArtist, 
  getCustomArtist, 
  getBanners, 
  saveBanner, 
  deleteBanner, 
  getCategories, 
  addCategory, 
  updateCategory, 
  deleteCategory, 
  reorderCategories,
  exportAllData, 
  importAllData, 
  getSiteLogo, 
  saveSiteLogo, 
  getAnnouncement, 
  saveAnnouncement, 
  getContactInfo, 
  saveContactInfo, 
  getAnalytics, 
  AnalyticsData 
} from '../utils/dataManager';
import { 
  LogOut, Plus, Music, User, Trash2, Edit2, Grid, ImageIcon as BannerIcon, 
  Check, X, Database, Settings, Megaphone, Info, Activity, Calendar, Clock, 
  Save, ExternalLink, Search, Youtube, Globe, Mail, MessageCircle,
  Download, Shield, Upload, Camera, Image as ImageIconRegular,
  Facebook, Instagram, ChevronUp, ChevronDown, GripVertical
} from 'lucide-react';
import { Banner, Announcement, Category, ContactInfo } from '../types';
import Loader from '../components/Loader';
import ArtistSelector from '../components/ArtistSelector';
import { supabase } from '../supabaseClient';

const AdminDashboard: React.FC = () => {
  const { user, isAuth, loading: authLoading } = useAuth();
  const navigate = useNavigate();
  const userRole = user?.role;
  const isSuperAdmin = userRole === 'SUPER_ADMIN';
  const isRegularUser = userRole === 'USER';

  const [activeTab, setActiveTab] = useState<'overview' | 'songs' | 'artists' | 'banners' | 'categories' | 'contact' | 'backup' | 'settings' | 'addSong' | 'addArtist' | 'announcement'>('overview');
  const [loading, setLoading] = useState(true);
  const [customSongs, setCustomSongs] = useState<any[]>([]);
  const [customArtists, setCustomArtists] = useState<any[]>([]);
  const [banners, setBanners] = useState<Banner[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [announcement, setAnnouncement] = useState<Announcement>({ imageUrl: '', link: '', isVisible: false });
  const [contactInfo, setContactInfo] = useState<ContactInfo>({
      missionTitle: '', missionText: '', visionTitle: '', visionText: '',
      email: '', whatsapp: '', facebookUrl: '', footerTitle: '', footerText: ''
  });

  const [analytics, setAnalytics] = useState<AnalyticsData>({ lifetime: 0, today: 0, thisWeek: 0, lastWeek: 0 });
  const [onlineCount, setOnlineCount] = useState(0);

  // Drag and Drop State
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  // Refs for file uploads
  const bannerFileRef = useRef<HTMLInputElement>(null);
  const announcementFileRef = useRef<HTMLInputElement>(null);
  const logoFileRef = useRef<HTMLInputElement>(null);
  const backupFileRef = useRef<HTMLInputElement>(null);
  const categoryFileRef = useRef<HTMLInputElement>(null);
  const editCategoryFileRef = useRef<HTMLInputElement>(null);
  const artistFileRef = useRef<HTMLInputElement>(null);

  // Search/Filter states
  const [songSearch, setSongSearch] = useState('');
  const [artistSearch, setArtistSearch] = useState('');

  // Form States
  const [songForm, setSongForm] = useState({ 
      title: '', title_nepali: '', artist: '', artists: [] as string[], 
      lyrics_nepali: '', lyrics_roman: '', 
      composer: '', composers: [] as string[], 
      lyricist: '', lyricists: [] as string[], 
      singer: '', singers: [] as string[], 
      views: 0, artist_bio: '', categories: [] as string[],
      youtubeUrl: '', isYoutubeVisible: true,
      language: 'nepali' as 'nepali' | 'hindi' | 'english'
  });
  const [artistForm, setArtistForm] = useState({ 
      name: '', bio: '', topSongs: '', imageUrl: '', 
      facebookUrl: '', instagramUrl: '', youtubeUrl: '',
      isFacebookVisible: true, isInstagramVisible: true, isArtistYoutubeVisible: true
  });
  const [bannerForm, setBannerForm] = useState({ imageUrl: '', title: '', subtitle: '', link: '' });
  const [editingBannerId, setEditingBannerId] = useState<string | null>(null);
  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '', hideTitle: false });
  const [siteLogo, setSiteLogo] = useState('');
  const [editingCategory, setEditingCategory] = useState<{original: string, current: string, imageUrl: string, hideTitle: boolean} | null>(null);

  useEffect(() => {
    if (!authLoading) {
      if (!isAuth) {
        navigate('/login');
      } else if (isRegularUser) {
        navigate('/');
      } else {
        refreshData();
        setupPresence();
      }
    }
  }, [isAuth, isRegularUser, authLoading, navigate]);

  const setupPresence = () => {
    const channel = supabase.channel('online_users');
    channel
        .on('presence', { event: 'sync' }, () => {
            const newState = channel.presenceState();
            setOnlineCount(Object.keys(newState).length);
        })
        .subscribe();

    return () => { channel.unsubscribe(); }
  };

  const refreshData = async () => {
    try {
      setLoading(true);
      const [songs, artists, bans, cats, logo, stats, ann, info] = await Promise.all([
        getAllCustomSongs(),
        getAllCustomArtists(),
        getBanners(),
        getCategories(),
        getSiteLogo(),
        getAnalytics(),
        getAnnouncement(),
        getContactInfo()
      ]);

      setCustomSongs(songs);
      setCustomArtists(artists);
      setBanners(bans);
      setCategories(cats);
      setSiteLogo(logo);
      setAnalytics(stats);

      if (ann) setAnnouncement(ann);
      if (info) setContactInfo(prev => ({ ...prev, ...info }));
    } catch (err) {
      console.error("Dashboard refresh failed:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = error => reject(error);
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, target: 'banner' | 'announcement' | 'logo' | 'category' | 'edit-category' | 'artist') => {
    const file = e.target.files?.[0];
    if (file) {
      try {
        const base64 = await fileToBase64(file);
        if (target === 'banner') setBannerForm(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'announcement') setAnnouncement(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'logo') setSiteLogo(base64);
        else if (target === 'category') setCategoryForm(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'edit-category') setEditingCategory(prev => prev ? { ...prev, imageUrl: base64 } : null);
        else if (target === 'artist') setArtistForm(prev => ({ ...prev, imageUrl: base64 }));

        e.target.value = '';
      } catch (err) {
        alert("File conversion failed.");
      }
    }
  };

  const handleAddSong = async (e: React.FormEvent) => {
    e.preventDefault();
    const titleClean = songForm.title.trim();
    if (!titleClean) return;

    const artistList = songForm.artists.length > 0 ? songForm.artists : (songForm.artist ? [songForm.artist] : []);
    const displayArtist = artistList.length > 0 ? artistList.join(', ') : 'Unknown';

    try {
        await saveCustomSong(displayArtist, titleClean, {
            title_nepali: songForm.title_nepali.trim(),
            lyrics_nepali: songForm.lyrics_nepali,
            lyrics_roman: songForm.lyrics_roman,
            composer: songForm.composers.join(', '),
            composers: songForm.composers,
            lyricist: songForm.lyricists.join(', '),
            lyricists: songForm.lyricists,
            singer: songForm.singers.join(', '),
            singers: songForm.singers,
            views: songForm.views,
            categories: songForm.categories.length > 0 ? songForm.categories : ['Worship'],
            youtubeUrl: songForm.youtubeUrl.trim(),
            isYoutubeVisible: songForm.isYoutubeVisible,
            artists: artistList,
            language: songForm.language,
            artist: displayArtist
        });

        setSongForm({ 
            title: '', title_nepali: '', artist: '', artists: [], lyrics_nepali: '', lyrics_roman: '', 
            composer: '', composers: [], lyricist: '', lyricists: [], singer: '', 
            singers: [], views: 0, artist_bio: '', categories: [], youtubeUrl: '', 
            isYoutubeVisible: true, language: 'nepali' 
        });

        setActiveTab('songs');
        refreshData();
    } catch (err: any) {
        alert("Failed to save song: " + (err.message || "Unknown error"));
    }
  };

  const handleAddArtist = async (e: React.FormEvent) => {
    e.preventDefault();
    const nameClean = artistForm.name.trim();
    if (!nameClean) return;
    try {
        await saveCustomArtist(nameClean, {
            name: nameClean,
            bio: artistForm.bio,
            topSongs: artistForm.topSongs.split(',').map(s => s.trim()).filter(s => s),
            imageUrl: artistForm.imageUrl.trim(),
            facebookUrl: artistForm.facebookUrl.trim(),
            instagramUrl: artistForm.instagramUrl.trim(),
            youtubeUrl: artistForm.youtubeUrl.trim(),
            isFacebookVisible: artistForm.isFacebookVisible,
            isInstagramVisible: artistForm.isInstagramVisible,
            isArtistYoutubeVisible: artistForm.isArtistYoutubeVisible
        });
        setArtistForm({ name: '', bio: '', topSongs: '', imageUrl: '', facebookUrl: '', instagramUrl: '', youtubeUrl: '', isFacebookVisible: true, isInstagramVisible: true, isArtistYoutubeVisible: true });
        setActiveTab('artists');
        refreshData();
    } catch (err: any) {
        alert("Failed to create artist: " + (err.message || "Unknown error"));
    }
  };

  const handleAddBanner = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!bannerForm.imageUrl) {
        alert("Banner image is required!");
        return;
    }

    try {
        setLoading(true);
        const id = editingBannerId || `temp_${Date.now()}`;

        await saveBanner({ 
            id, imageUrl: bannerForm.imageUrl, title: bannerForm.title, 
            subtitle: bannerForm.subtitle, link: bannerForm.link
        });

        setBannerForm({ imageUrl: '', title: '', subtitle: '', link: '' });
        setEditingBannerId(null);

        await refreshData();
        alert("Banner saved successfully!");
    } catch (err: any) {
        alert("Failed to save banner: " + (err.message || "Error saving banner."));
    } finally {
        setLoading(false);
    }
  };

  const handleAddCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    const nameClean = categoryForm.name.trim();
    if (!nameClean) return;
    const result = await addCategory(nameClean, categoryForm.imageUrl.trim(), categoryForm.hideTitle);
    if (result.success) {
      setCategoryForm({ name: '', imageUrl: '', hideTitle: false });
      refreshData();
    } else {
      alert("Error adding category: " + result.error);
    }
  };

  const handleUpdateCategory = async () => {
    if (editingCategory && editingCategory.current.trim()) {
      try {
        await updateCategory(editingCategory.original, editingCategory.current.trim(), editingCategory.imageUrl.trim(), editingCategory.hideTitle);
        setEditingCategory(null);
        refreshData();
      } catch (err: any) {
        alert("Update failed: " + err.message);
      }
    }
  };

  // Drag and Drop Handlers
  const handleDragStart = (index: number) => {
    setDraggedIndex(index);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); // Allow drop
  };

  const handleDrop = async (targetIndex: number) => {
    if (draggedIndex === null || draggedIndex === targetIndex) return;

    const newCategories = [...categories];
    const draggedItem = newCategories[draggedIndex];

    // Remove and Insert at new position
    newCategories.splice(draggedIndex, 1);
    newCategories.splice(targetIndex, 0, draggedItem);

    setCategories(newCategories);
    setDraggedIndex(null);

    try {
        await reorderCategories(newCategories);
    } catch (err: any) {
