import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { User, Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, Flag, X, Edit, Trash2, Save, Printer, Tag, Youtube, Mic2, StickyNote } from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { saveCustomSong, deleteCustomSong, incrementViewCount, setViewCount, saveCustomArtist, getCategories, getAllCustomSongs, getSongById } from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  // Now supports id OR artist/song params
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(16);
  const [availableCategories, setAvailableCategories] = useState<string[]>([]);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any, artist_bio?: string }>({
      lyrics_nepali: '',
      lyrics_roman: '',
      composer: '',
      composers: [],
      lyricist: '',
      lyricists: [],
      singer: '',
      singers: [],
      views: 0,
      artist_bio: '',
      category: '',
      categories: [],
      youtubeUrl: '',
      isYoutubeVisible: true,
      artist: '', 
      title: '',
      artists: [],
      title_nepali: '',
      note: '',
      isNoteVisible: true
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('lyrics');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      const cats = await getCategories();
      setAvailableCategories(cats.map(c => c.name));

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult as any);
      setArtistData(artistResult);

      if (allSongs && artistName && artistName.toLowerCase() !== 'unknown') {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      } else {
          setRelatedSongs([]);
      }

      // Populate Edit Form
      let initialCats = lyricsResult.categories || [];
      if (initialCats.length === 0 && lyricsResult.category) {
          initialCats = [lyricsResult.category];
      }

      const composerStr = lyricsResult.composers && lyricsResult.composers.length > 0 
          ? lyricsResult.composers.join(', ') 
          : lyricsResult.composer || '';

      const lyricistStr = lyricsResult.lyricists && lyricsResult.lyricists.length > 0 
          ? lyricsResult.lyricists.join(', ') 
          : lyricsResult.lyricist || '';

      const singerStr = lyricsResult.singers && lyricsResult.singers.length > 0 
          ? lyricsResult.singers.join(', ') 
          : lyricsResult.singer || '';

      setEditForm({ 
          ...lyricsResult, 
          title: lyricsResult.title || songTitle,
          artist: lyricsResult.artist || artistName,
          views: lyricsResult.views || 0,
          artist_bio: artistResult?.bio || '',
          category: lyricsResult.category || 'Worship',
          categories: initialCats,
          composer: composerStr,
          lyricist: lyricistStr,
          singer: singerStr,
          youtubeUrl: lyricsResult.youtubeUrl || '',
          isYoutubeVisible: lyricsResult.isYoutubeVisible !== false,
          title_nepali: lyricsResult.title_nepali || '',
          note: lyricsResult.note || '',
          isNoteVisible: lyricsResult.isNoteVisible !== false
      });

      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePrint = () => {
    window.print();
  };

  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 4, 64));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 16));

  const submitFeedback = (e: React.FormEvent) => {
    e.preventDefault();
    setTimeout(() => {
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
            setFeedbackType('lyrics');
        }, 2000);
    }, 500);
  };

  const handleSaveEdit = async () => {
      if (!data) return;

      try {
          setIsSaving(true);
          const { artist_bio, ...songData } = editForm;

          const composers = editForm.composer.split(',').map(s => s.trim()).filter(s => s);
          const lyricists = editForm.lyricist.split(',').map(s => s.trim()).filter(s => s);
          const singers = editForm.singer.split(',').map(s => s.trim()).filter(s => s);

          const finalTitle = (editForm.title || data.title).trim();
          const finalArtist = (editForm.artist || data.artist).trim();

          const updatedSongData = {
              ...songData,
              id: data.id,
              title: finalTitle,
              artist: finalArtist,
              composers,
              lyricists,
              singers,
              composer: editForm.composer,
              lyricist: editForm.lyricist,
              singer: editForm.singer,
              title_nepali: editForm.title_nepali,
              category: (songData.categories && songData.categories.length > 0) ? songData.categories[0] : songData.category
          };

          await saveCustomSong(data.artist, data.title, updatedSongData);

          if (artist_bio && artist_bio !== artistData?.bio && data.artist.toLowerCase() !== 'unknown') {
              const updatedArtist: ArtistDetails = {
                  name: finalArtist,
                  bio: artist_bio,
                  topSongs: artistData?.topSongs || []
              };
              await saveCustomArtist(data.artist, updatedArtist);
              setArtistData(updatedArtist);
          }

          setData(updatedSongData as any);
          setIsEditing(false);

          if (editForm.views !== undefined && editForm.views !== data.views) {
             await setViewCount(finalArtist, finalTitle, editForm.views);
          }

      } catch (err: any) {
          alert("Failed to save changes: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const toggleCategorySelection = (cat: string) => {
      setEditForm(prev => {
          const cats = prev.categories || [];
          if (cats.includes(cat)) {
              return { ...prev, categories: cats.filter(c => c !== cat) };
          } else {
              return { ...prev, categories: [...cats, cat] };
          }
      });
  };

  const handleDeleteSong = async () => {
      if (!data) return;
      if (window.confirm("Are you sure you want to delete this lyrics page?")) {
          try {
              await deleteCustomSong(data.artist, data.title);
              navigate('/');
          } catch (err: any) {
              alert("Delete failed: " + err.message);
          }
      }
  };

  const getYoutubeId = (url: string) => {
      const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
      const match = url.match(regExp);
      return (match && match[2].length === 11) ? match[2] : null;
  };

  const currentUrl = window.location.href;
  const shareTitle = data ? `Check out "${data.title}" by ${data.artist} on SansarPlus` : '';

  const socialLinks = [
    {
        name: 'WhatsApp',
        url: `https://wa.me/?text=${encodeURIComponent(shareTitle + ' ' + currentUrl)}`,
        color: 'hover:bg-[#25D366] hover:text-white text-[#25D366] bg-[#25D366]/10',
        icon: <svg viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.008-.57-.008-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
    },
    {
        name: 'Facebook',
        url: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(currentUrl)}`,
        color: 'hover:bg-[#1877F2] hover:text-white text-[#1877F2] bg-[#1877F2]/10',
        icon: <svg viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5"><path d="M9.101 23.691v-7.98H6.627v-3.667h2.474v-1.58c0-4.085 1.848-5.978 5.858-5.978.401 0 .955.042 1.468.103a8.68 8.68 0 0 1 1.141.195v3.325a8.623 8.623 0 0 0-.653-.036c-2.148 0-2.971.956-2.971 3.594v.411h3.085l-.005 3.633-3.08 3.667v7.98h-4.843Z"/></svg>
    },
    {
        name: 'X',
        url: `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareTitle)}&url=${encodeURIComponent(currentUrl)}`,
        color: 'hover:bg-black hover:text-white text-black bg-gray-100',
        icon: <svg viewBox="0 0 24 24" fill="currentColor" className="w-4 h-4"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>
    },
  ];

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-900';
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return <div className="text-slate-500 text-center pt-20">Lyrics not found.</div>;

  const displayTitle = (appLanguage === 'nepali' && data.title_nepali) ? data.title_nepali : data.title;
  const youtubeId = data.youtubeUrl ? getYoutubeId(data.youtubeUrl) : null;
  const showYoutube = youtubeId && (data.isYoutubeVisible !== false);
  const showNote = data.note && (data.isNoteVisible !== false);

  const renderCredits = (names: string[] | string) => {
      const list = Array.isArray(names) && names.length > 0 ? names : (names ? [names as string] : []);
      if (list.length === 0 || (list.length === 1 && list[0].toLowerCase() === 'unknown')) return <span className="text-slate-400 text-sm italic">Unknown</span>;

      return (
          <div className="flex flex-wrap gap-2">
              {list.map((name, idx) => (
                  <React.Fragment key={idx}>
                      {idx > 0 && <span className="text-slate-300">,</span>}
                      {name.toLowerCase() === 'unknown' ? (
                          <span className="text-slate-900 font-bold">{name}</span>
                      ) : (
                          <Link to={`/artist/${encodeURIComponent(name)}`} className="text-slate-900 font-bold hover:text-primary transition-colors block">
                              {name}
                          </Link>
                      )}
                  </React.Fragment>
              ))}
          </div>
      );
  };

  const composersList = data.composers && data.composers.length > 0 ? data.composers : data.composer;
  const lyricistsList = data.lyricists && data.lyricists.length > 0 ? data.lyricists : data.lyricist;
  const singersList = data.singers && data.singers.length > 0 ? data.singers : data.singer;

  return (
    <div className="min-h-screen bg-slate-50 pb-24 font-sans">
      <div className="relative bg-slate-900 text-white pb-24 pt-24 md:pt-32 px-4 overflow-hidden shadow-lg no-print">
         <div className="absolute inset-0 bg-gradient-to-br from-indigo-900 via-slate-900 to-black z-0"></div>
         <div className="absolute top-[-20%] right-[-10%] w-[400px] h-[400px] bg-purple-600/20 rounded-full blur-[100px]"></div>
         <div className="absolute bottom-[-20%] left-[-10%] w-[400px] h-[400px] bg-blue-600/20 rounded-full blur-[100px]"></div>

         <div className="relative z-10 max-w-4xl mx-auto text-center">
            <h1 className="text-4xl md:text-6xl lg:text-7xl font-extrabold tracking-tight leading-tight mb-4 drop-shadow-2xl">
                {displayTitle}
            </h1>
            {showNote && !isEditing && (
                <div className="flex items-center justify-center gap-2 text-indigo-200/80 font-medium italic animate-in fade-in slide-in-from-bottom-2">
                    <StickyNote className="w-4 h-4" />
                    <span>{data.note}</span>
                </div>
            )}
         </div>
      </div>

      <div className="max-w-3xl mx-auto px-4 -mt-16 relative z-20 space-y-8">
         {canEdit && (
            <div className="bg-white rounded-xl shadow-lg p-2 mb-4 flex justify-between items-center no-print">
               <span className="text-xs font-bold text-slate-400 px-3 uppercase">Admin Controls</span>
               <div className="flex gap-2">
                  {isEditing ? (
                      <>
                        <button disabled={isSaving} onClick={handleSaveEdit} className="bg-green-500 text-white p-2 rounded-lg hover:bg-green-600 disabled:opacity-50 flex items-center gap-1 text-sm font-bold pr-3"><Save className="w-4 h-4" /> {isSaving ? 'Saving...' : 'Save'}</button>
                        <button disabled={isSaving} onClick={() => setIsEditing(false)} className="bg-slate-500 text-white p-2 rounded-lg hover:bg-slate-600 disabled:opacity-50"><X className="w-5 h-5" /></button>
                      </>
                  ) : (
                      <>
                        <button onClick={() => setIsEditing(true)} className="bg-primary text-white p-2 rounded-lg hover:bg-primary/90 flex items-center gap-1 text-sm font-bold pr-3"><Edit className="w-4 h-4" /> Edit Page</button>
                        <button onClick={handleDeleteSong} className="bg-red-50 text-white p-2 rounded-lg hover:bg-red-600"><Trash2 className="w-5 h-5" /></button>
                      </>
                  )}
               </div>
            </div>
         )}

         {isEditing && (
             <div className="bg-yellow-50 p-6 rounded-2xl border border-yellow-200 shadow-sm animate-in slide-in-from-top-4">
                <h3 className="font-bold text-yellow-800 mb-4 border-b border-yellow-200 pb-2">Edit Details</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Romanized Title</label>
                        <input type="text" className="w-full border p-2 rounded bg-white text-sm" value={editForm.title || ''} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                    </div>
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Nepali Title</label>
                        <input type="text" className="w-full border p-2 rounded bg-white text-sm" value={editForm.title_nepali || ''} onChange={e => setEditForm({...editForm, title_nepali: e.target.value})} />
                    </div>
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Main Artist</label>
                        <input type="text" className="w-full border p-2 rounded bg-white text-sm" value={editForm.artist || ''} onChange={e => setEditForm({...editForm, artist: e.target.value})} />
                    </div>
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-2 uppercase">Categories</label>
                        <div className="bg-white border rounded p-2 max-h-32 overflow-y-auto grid grid-cols-2 sm:grid-cols-3 gap-2">
                             {availableCategories.map(cat => (
                                <button key={cat} onClick={() => toggleCategorySelection(cat)} className={`text-xs px-2 py-1 rounded text-left ${(editForm.categories || []).includes(cat) ? 'bg-primary text-white font-bold' : 'bg-slate-50 hover:bg-slate-100 text-slate-600'}`}>{cat}</button>
                             ))}
                        </div>
                    </div>
                    <div className="col-span-2 md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Composers</label>
                        <input type="text" className="w-full border p-2 rounded bg-white text-sm" value={editForm.composer} onChange={e => setEditForm({...editForm, composer: e.target.value})} />
                    </div>
                    <div className="col-span-2 md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Lyricists</label>
                        <input type="text" className="w-full border p-2 rounded bg-white text-sm" value={editForm.lyricist} onChange={e => setEditForm({...editForm, lyricist: e.target.value})} />
                    </div>
                    <div className="col-span-2 md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Singers</label>
                        <input type="text" className="w-full border p-2 rounded bg-white text-sm" value={editForm.singer} onChange={e => setEditForm({...editForm, singer: e.target.value})} />
                    </div>
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">YouTube URL</label>
                        <input type="text" className="w-full border p-2 rounded bg-white text-sm" value={editForm.youtubeUrl || ''} onChange={e => setEditForm({...editForm, youtubeUrl: e.target.value})} />
                    </div>
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 mb-1 uppercase">Note</label>
                        <input type="text" className="w-full border p-2 rounded bg-white text-sm" value={editForm.note || ''} onChange={e => setEditForm({...editForm, note: e.target.value})} placeholder="e.g. (Female Key)" />
                    </div>
                    <div className="col-span-2 grid grid-cols-2 gap-4 mt-2">
                         <div className="flex items-center">
                            <input type="checkbox" id="ytEditVisible" checked={editForm.isYoutubeVisible} onChange={e => setEditForm({...editForm, isYoutubeVisible: e.target.checked})} className="mr-2" />
                            <label htmlFor="ytEditVisible" className="text-sm text-slate-700">Video Visible</label>
                        </div>
                        <div className="flex items-center">
                            <input type="checkbox" id="noteEditVisible" checked={editForm.isNoteVisible} onChange={e => setEditForm({...editForm, isNoteVisible: e.target.checked})} className="mr-2" />
                            <label htmlFor="noteEditVisible" className="text-sm text-slate-700">Note Visible</label>
                        </div>
                    </div>
                </div>
             </div>
         )}

         <div className="bg-white/90 backdrop-blur-xl p-6 md:p-12 rounded-3xl shadow-2xl border border-white/50 print:border-none print:shadow-none print:p-0">
             {!isEditing && (
                <div className="flex flex-col sm:flex-row justify-between items-center mb-8 gap-4 border-b border-slate-100 pb-6 no-print">
                    <div className="flex bg-slate-100 p-1.5 rounded-xl shadow-inner w-full sm:w-auto">
                        <button onClick={() => setActiveTab('nepali')} className={`flex-1 sm:flex-none px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'nepali' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Nepali</button>
                        <button onClick={() => setActiveTab('roman')} className={`flex-1 sm:flex-none px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'roman' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Romanized</button>
                    </div>

                    <div className="flex items-center gap-1 bg-white border border-slate-200 p-1 rounded-xl shadow-sm overflow-x-auto max-w-full">
                        <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-primary rounded-lg transition-colors flex-shrink-0"><ZoomOut className="w-5 h-5" /></button>
                        <span className="text-xs font-mono text-slate-300">|</span>
                        <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-primary rounded-lg transition-colors flex-shrink-0"><ZoomIn className="w-5 h-5" /></button>
                        <span className="text-xs font-mono text-slate-300">|</span>
                        <button onClick={handlePrint} className="p-2 text-slate-400 hover:text-primary rounded-lg transition-colors flex-shrink-0"><Printer className="w-5 h-5" /></button>
                         <span className="text-xs font-mono text-slate-300">|</span>
                         <button onClick={handleFavorite} className={`p-2 rounded-lg transition-colors flex-shrink-0 ${isFav ? 'text-red-500 bg-red-50' : 'text-slate-400 hover:text-red-500'}`}><Heart className={`w-5 h-5 ${isFav ? 'fill-current' : ''}`} /></button>
                        <span className="text-xs font-mono text-slate-300">|</span>
                        <button onClick={handleCopy} className="p-2 text-slate-400 hover:text-primary rounded-lg transition-colors flex-shrink-0">{copied ? <Check className="w-5 h-5 text-green-500" /> : <Copy className="w-5 h-5" />}</button>
                    </div>
                </div>
             )}

             {isEditing ? (
                 <div className="space-y-6">
                     <div>
                         <label className="block text-sm font-bold text-slate-500 mb-1">Nepali Lyrics</label>
                         <textarea className="w-full h-64 p-4 border rounded-xl font-sans bg-slate-50 focus:bg-white transition-colors" value={editForm.lyrics_nepali || ''} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                     </div>
                     <div>
                         <label className="block text-sm font-bold text-slate-500 mb-1">Romanized Lyrics</label>
                         <textarea className="w-full h-64 p-4 border rounded-xl font-sans bg-slate-50 focus:bg-white transition-colors" value={editForm.lyrics_roman || ''} onChange={e => setEditForm({...editForm, lyrics_roman: e.target.value})} />
                     </div>
                 </div>
             ) : (
                <div className="whitespace-pre-wrap font-sans leading-loose text-slate-800 tracking-wide lyrics-scroll text-center mx-auto max-w-3xl" style={{ fontSize: `${fontSize}px`, lineHeight: 1.8 }}>
                    {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Nepali text N/A") : (data.lyrics_roman || "Romanized text N/A")}
                </div>
             )}
         </div>

         <div className="bg-white p-8 rounded-3xl shadow-lg border border-slate-100 no-print">
            <h3 className="text-xs font-extrabold text-slate-400 uppercase tracking-widest mb-6">Production Credits</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="flex items-start space-x-4 p-4 rounded-2xl bg-slate-50 hover:bg-slate-100 transition-colors">
                    <div className="p-3 bg-white rounded-full shadow-sm text-indigo-500"><Music className="w-5 h-5" /></div>
                    <div><p className="text-xs text-slate-400 font-bold uppercase mb-1">Composer</p>{renderCredits(composersList)}</div>
                </div>
                <div className="flex items-start space-x-4 p-4 rounded-2xl bg-slate-50 hover:bg-slate-100 transition-colors">
                    <div className="p-3 bg-white rounded-full shadow-sm text-purple-500"><PenTool className="w-5 h-5" /></div>
                    <div><p className="text-xs text-slate-400 font-bold uppercase mb-1">Lyrics By</p>{renderCredits(lyricistsList)}</div>
                </div>
                {(singersList && (Array.isArray(singersList) ? singersList.length > 0 : singersList)) && (
                    <div className="flex items-start space-x-4 p-4 rounded-2xl bg-slate-50 hover:bg-slate-100 transition-colors sm:col-span-2 md:col-span-1">
                        <div className="p-3 bg-white rounded-full shadow-sm text-pink-500"><Mic2 className="w-5 h-5" /></div>
                        <div><p className="text-xs text-slate-400 font-bold uppercase mb-1">Vocals</p>{renderCredits(singersList)}</div>
                    </div>
                )}
            </div>
        </div>

        {relatedSongs.length > 0 && (
            <div className="bg-white p-6 md:p-8 rounded-3xl shadow-lg border border-slate-100 no-print mt-8">
                <div className="flex justify-between items-center mb-6">
                     <h3 className="text-lg font-bold text-slate-900">More by {data.artist}</h3>
                     <Link to={`/artist/${encodeURIComponent(data.artist)}`} className="text-sm font-bold text-primary hover:underline flex items-center">View All <ArrowRight className="w-4 h-4 ml-1" /></Link>
                </div>
                <div className="space-y-2">
                    {relatedSongs.map((s, idx) => {
                        const relTitle = (appLanguage === 'nepali' && s.title_nepali) ? s.title_nepali : s.title;
                        return (
                        <Link key={idx} to={`/l/${s.id}`} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 transition-all group border border-transparent hover:border-slate-100">
                            <div className="flex items-center gap-4 overflow-hidden">
                                <div className="w-8 h-8 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center flex-shrink-0 text-xs font-bold shadow-sm">{idx + 1}</div>
                                <span className={`font-bold text-base truncate transition-colors ${getSongColorClass(s.language)}`}>
                                    {relTitle}
                                    {s.note && <span className="ml-1.5 text-xs text-slate-400 font-medium italic">({s.note})</span>}
                                </span>
                            </div>
                            <ArrowRight className="w-4 h-4 text-slate-300 group-hover:text-primary transform group-hover:translate-x-1 transition-all" />
                        </Link>
                    )})}
                </div>
            </div>
        )}

        <div className="grid grid-cols-1 gap-4 no-print">
            <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-around">
                 {socialLinks.map((link) => (
                    <a key={link.name} href={link.url} target="_blank" rel="noopener noreferrer" className={`w-12 h-12 flex items-center justify-center rounded-full transition-all hover:scale-110 shadow-sm ${link.color}`} title={`Share on ${link.name}`}>{link.icon}</a>
                ))}
                 <button onClick={() => setIsFeedbackOpen(true)} className="w-12 h-12 flex items-center justify-center rounded-full bg-slate-100 text-slate-400 hover:bg-slate-200 hover:text-slate-600 transition-all"><Flag className="w-5 h-5" /></button>
            </div>
        </div>

         {!isEditing && showYoutube && youtubeId && (
            <div className="bg-black rounded-3xl overflow-hidden shadow-2xl no-print mt-8">
                 <div className="aspect-w-16 aspect-h-9 relative" style={{ paddingBottom: '56.25%' }}>
                     <iframe src={`https://www.youtube.com/embed/${youtubeId}`} title="YouTube player" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen className="absolute top-0 left-0 w-full h-full"></iframe>
                 </div>
            </div>
         )}
      </div>

      {isFeedbackOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
            <div className="bg-white rounded-3xl shadow-2xl max-w-md w-full overflow-hidden animate-in fade-in zoom-in duration-200">
                <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <h3 className="font-bold text-slate-800 text-lg">Report Issue</h3>
                    <button onClick={() => setIsFeedbackOpen(false)} className="text-slate-400 hover:text-slate-600 bg-white p-2 rounded-full shadow-sm"><X className="w-5 h-5" /></button>
                </div>

                {feedbackSubmitted ? (
                    <div className="p-12 text-center">
                        <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4 animate-bounce"><Check className="w-8 h-8" /></div>
                        <h4 className="font-bold text-xl text-slate-800 mb-2">Thank You!</h4>
                        <p className="text-slate-500">Your feedback helps us improve.</p>
                    </div>
                ) : (
                    <form onSubmit={submitFeedback} className="p-6 space-y-5">
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-2">Issue Type</label>
                            <select value={feedbackType} onChange={(e) => setFeedbackType(e.target.value)} className="w-full border border-slate-200 rounded-xl p-3 text-sm outline-none bg-slate-50">
                                <option value="lyrics">Wrong Lyrics</option>
                                <option value="credits">Wrong Credits</option>
                                <option value="typo">Typos / Formatting</option>
                                <option value="other">Other Suggestion</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-slate-700 mb-2">Details</label>
                            <textarea value={feedbackText} onChange={(e) => setFeedbackText(e.target.value)} rows={4} placeholder="Describe the issue..." className="w-full border border-slate-200 rounded-xl p-3 text-sm outline-none bg-slate-50" required></textarea>
                        </div>
                        <button type="submit" className="w-full py-4 rounded-xl bg-primary text-white font-bold hover:bg-primary/90 transition-all shadow-lg transform active:scale-95">Submit Report</button>
                    </form>
                )}
            </div>
        </div>
      )}
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Search, ChevronRight, Music, Disc, Mic2, ArrowRight, Play, Star, ChevronLeft, Database } from 'lucide-react';
import { getTrendingContent } from '../services/geminiService';
import Loader from '../components/Loader';
import AlphabetNav from '../components/AlphabetNav';
import { HomeData, Banner, Announcement, Category } from '../types';
import { getBanners, getAllCustomSongs, getAnnouncement, getCategories } from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const Home: React.FC = () => {
  const [data, setData] = useState<HomeData | null>(null);
  const [loading, setLoading] = useState(true);
  const [searchInput, setSearchInput] = useState('');
  const [banners, setBanners] = useState<Banner[]>([]);
  const [currentBannerIndex, setCurrentBannerIndex] = useState(0);
  const [totalSongs, setTotalSongs] = useState(0);
  const [announcement, setAnnouncement] = useState<Announcement | null>(null);
  const [categories, setCategories] = useState<Category[]>([]);
  const navigate = useNavigate();
  const { t, language } = useLanguage();

  const fetchData = async () => {
    try {
      setLoading(true);
      const [trendingResult, bannersResult, songsResult, announcementResult, categoriesResult] = await Promise.all([
        getTrendingContent(),
        getBanners(),
        getAllCustomSongs(),
        getAnnouncement(),
        getCategories()
      ]);

      setData(trendingResult);
      setBanners(bannersResult);
      setTotalSongs(songsResult.length);
      setAnnouncement(announcementResult);
      setCategories(categoriesResult);
    } catch (err) {
      console.error("Home page data fetch failed:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    const handleContentChange = () => fetchData();
    window.addEventListener('content-change', handleContentChange);
    return () => window.removeEventListener('content-change', handleContentChange);
  }, []);

  useEffect(() => {
    if (banners.length === 0) return;
    const interval = setInterval(() => {
      setCurrentBannerIndex((prev) => (prev + 1) % banners.length);
    }, 5000);
    return () => clearInterval(interval);
  }, [banners]);

  const nextBanner = () => setCurrentBannerIndex((prev) => (prev + 1) % banners.length);
  const prevBanner = () => setCurrentBannerIndex((prev) => (prev - 1 + banners.length) % banners.length);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchInput.trim()) {
      navigate(`/search/${encodeURIComponent(searchInput)}`);
    }
  };

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-800';
  };

  const rankColors = ['text-yellow-500', 'text-slate-400', 'text-amber-600', 'text-blue-500', 'text-emerald-500', 'text-purple-500', 'text-pink-500', 'text-indigo-500', 'text-teal-500', 'text-orange-500'];
  const rankBgColors = [
    'bg-yellow-50 text-yellow-600 group-hover:bg-yellow-500 group-hover:text-white',
    'bg-slate-100 text-slate-600 group-hover:bg-slate-500 group-hover:text-white',
    'bg-amber-50 text-amber-600 group-hover:bg-amber-600 group-hover:text-white',
    'bg-blue-50 text-blue-600 group-hover:bg-blue-500 group-hover:text-white',
    'bg-emerald-50 text-emerald-600 group-hover:bg-emerald-500 group-hover:text-white',
    'bg-purple-50 text-purple-600 group-hover:bg-purple-500 group-hover:text-white',
    'bg-pink-50 text-pink-600 group-hover:bg-pink-500 group-hover:text-white',
    'bg-indigo-50 text-indigo-600 group-hover:bg-indigo-500 group-hover:text-white',
    'bg-teal-50 text-teal-600 group-hover:bg-teal-500 group-hover:text-white',
    'bg-orange-50 text-orange-600 group-hover:bg-orange-500 group-hover:text-white'
  ];

  if (loading) return <Loader fullScreen text="Loading content..." />;

  // Prepare special categories grid
  const specialNames = ['Bhajan', 'Chorus', 'Praise', 'Worship'];
  const specialCats = specialNames.map(name => {
      const found = (categories || []).find(c => c.name.toLowerCase() === name.toLowerCase());
      return found || { name, imageUrl: '', hideTitle: false };
  });

  const getFallbackGradient = (name: string) => {
    switch(name.toLowerCase()) {
        case 'bhajan': return 'from-orange-500 to-red-600';
        case 'chorus': return 'from-blue-500 to-indigo-600';
        case 'praise': return 'from-emerald-500 to-teal-600';
        case 'worship': return 'from-violet-500 to-purple-700';
        default: return 'from-indigo-500 to-purple-600';
    }
  };

  return (
    <div className="min-h-screen pb-12 bg-slate-50 relative overflow-x-hidden">
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none z-0">
         <div className="absolute top-[-10%] right-[-5%] w-[500px] h-[500px] bg-primary/5 rounded-full blur-3xl opacity-60"></div>
         <div className="absolute top-[20%] left-[-10%] w-[400px] h-[400px] bg-secondary/5 rounded-full blur-3xl opacity-60"></div>
      </div>

      <div className="relative z-10 bg-slate-900 text-white pt-8 md:pt-12 pb-24 md:pb-32 px-4 rounded-b-[2rem] md:rounded-b-[3rem] shadow-2xl overflow-hidden">
          <div className="absolute inset-0 z-0 opacity-20">
             <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-indigo-500 via-slate-900 to-slate-900"></div>
          </div>
          <div className="max-w-4xl mx-auto text-center relative z-10 space-y-4 md:space-y-6">

              <div className="inline-flex items-center justify-center px-3 py-1 md:px-4 md:py-1.5 rounded-full bg-indigo-500/20 text-indigo-200 text-xs md:text-sm font-medium border border-indigo-500/30 mb-2 backdrop-blur-md">
                 <Star className="w-3 h-3 md:w-3.5 md:h-3.5 mr-2 fill-current" /> Largest Nepali Christian Lyrics Platform
              </div>
              <h1 className="text-4xl md:text-6xl font-extrabold tracking-tight leading-tight">Praise & <span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-purple-400">Worship</span></h1>
              <p className="text-base md:text-xl text-slate-300 max-w-2xl mx-auto font-light leading-relaxed px-2">Connect with God through music. Discover the largest collection of Nepali Christian lyrics, hymns, and chords.</p>
              <div className="flex items-center justify-center gap-6 text-sm md:text-base text-slate-400 mt-4">
                  <div className="flex items-center bg-white/5 rounded-full px-4 py-1 border border-white/10">
                      <Database className="w-4 h-4 mr-2 text-indigo-400" /><span className="font-bold text-white mr-1">{totalSongs}</span> {t('Songs')} Added
                  </div>
              </div>
              <div className="max-w-2xl mx-auto mt-6 md:mt-8 relative group">
                <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-500 rounded-full blur opacity-25 group-hover:opacity-50 transition duration-200"></div>
                <form onSubmit={handleSearchSubmit} className="relative">
                    <input type="text" placeholder={`${t('Search')}...`} className="w-full bg-white/10 backdrop-blur-xl border border-white/20 rounded-full py-3 md:py-4 pl-12 md:pl-14 pr-6 text-white placeholder-slate-400 focus:outline-none focus:bg-white focus:text-slate-900 focus:placeholder-slate-400 transition-all shadow-xl text-base md:text-lg" value={searchInput} onChange={(e) => setSearchInput(e.target.value)} />
                    <Search className="absolute left-4 md:left-5 top-3.5 md:top-5 w-5 h-5 md:w-6 md:h-6 text-slate-400 group-focus-within:text-slate-500 transition-colors" />
                </form>
              </div>
          </div>
      </div>

      {announcement && announcement.isVisible && announcement.imageUrl && (
        <div className="relative z-20 -mt-16 mb-4 max-w-7xl mx-auto px-4">
             {announcement.link ? (
                 <a href={announcement.link} target="_blank" rel="noopener noreferrer" className="block w-full overflow-hidden rounded-2xl shadow-xl hover:shadow-2xl transition-shadow border border-white/20">
                     <img src={announcement.imageUrl} alt="Announcement" className="w-full h-auto object-cover max-h-[300px]" />
                 </a>
             ) : (
                 <div className="w-full overflow-hidden rounded-2xl shadow-xl border border-white/20">
                     <img src={announcement.imageUrl} alt="Announcement" className="w-full h-auto object-cover max-h-[300px]" />
                 </div>
             )}
        </div>
      )}

      <div className={`relative z-20 ${announcement?.isVisible ? 'mt-4' : '-mt-12'} mb-8 max-w-7xl mx-auto px-4`}>
         <div className="bg-white rounded-2xl shadow-xl shadow-slate-200/50 p-2 md:p-4 border border-slate-100">
             <AlphabetNav />
         </div>
      </div>

      {/* Featured Category Banner Grid */}
      <div className="max-w-7xl mx-auto px-4 mb-8">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {specialCats.map((cat) => (
                  <Link 
                    key={cat.name} 
                    to={`/category/${encodeURIComponent(cat.name)}`}
                    className="relative group rounded-3xl overflow-hidden aspect-[16/9] md:aspect-[4/3] shadow-lg hover:shadow-2xl transition-all hover:-translate-y-1"
                  >
                      {cat.imageUrl ? (
                          <img src={cat.imageUrl} alt={cat.name} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                      ) : (
                          <div className={`w-full h-full bg-gradient-to-br ${getFallbackGradient(cat.name)} flex items-center justify-center`}>
                              <Music className="w-10 h-10 text-white/30" />
                          </div>
                      )}

                      <div className="absolute inset-0 bg-black/40 group-hover:bg-black/50 transition-colors opacity-100"></div>

                      <div className="absolute bottom-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity">
                          <div className="w-8 h-8 rounded-full bg-white/20 backdrop-blur-md flex items-center justify-center text-white border border-white/20">
                             <ChevronRight className="w-5 h-5" />
                          </div>
                      </div>
                  </Link>
              ))}
          </div>
      </div>

      {/* Verses Slideshow Banner */}
      <div className="relative z-10 max-w-7xl mx-auto px-4 mb-12">
        <div className="relative rounded-3xl overflow-hidden shadow-2xl h-48 sm:h-64 md:h-80 lg:h-96 group">
            {banners.length > 0 && (
                <>
                    {banners.map((banner, idx) => {
                        const hasContent = banner.title || banner.subtitle;
                        const Content = (
                             <>
                                <img src={banner.imageUrl} alt="Banner" className="w-full h-full object-cover" />
                                {hasContent && (
                                    <div className="absolute inset-0 bg-black/40 bg-gradient-to-t from-black/80 to-transparent flex flex-col items-center justify-center text-center p-6 md:p-8">
                                        {banner.title && <p className="text-lg md:text-3xl lg:text-4xl font-serif text-white leading-relaxed max-w-4xl drop-shadow-lg italic line-clamp-4 md:line-clamp-none">"{banner.title}"</p>}
                                        {banner.subtitle && <p className="mt-2 md:mt-4 text-sm md:text-xl font-bold text-white/90 uppercase tracking-widest">— {banner.subtitle}</p>}
                                    </div>
                                )}
                             </>
                        );
                        return (
                            <div key={banner.id} className={`absolute inset-0 transition-opacity duration-1000 ease-in-out ${idx === currentBannerIndex ? 'opacity-100' : 'opacity-0'}`}>
                                {banner.link ? <a href={banner.link} target="_blank" rel="noopener noreferrer" className="block w-full h-full relative cursor-pointer">{Content}</a> : <div className="w-full h-full relative">{Content}</div>}
                            </div>
                        );
                    })}
                    <button onClick={prevBanner} className="absolute left-2 md:left-4 top-1/2 -translate-y-1/2 p-2 md:p-3 rounded-full bg-black/20 hover:bg-black/40 text-white backdrop-blur-sm transition-all opacity-0 group-hover:opacity-100"><ChevronLeft className="w-5 h-5 md:w-6 md:h-6" /></button>
                    <button onClick={nextBanner} className="absolute right-2 md:right-4 top-1/2 -translate-y-1/2 p-2 md:p-3 rounded-full bg-black/20 hover:bg-black/40 text-white backdrop-blur-sm transition-all opacity-0 group-hover:opacity-100"><ChevronRight className="w-5 h-5 md:w-6 md:h-6" /></button>
                    <div className="absolute bottom-4 md:bottom-6 left-1/2 -translate-x-1/2 flex gap-2">
                        {banners.map((_, idx) => <button key={idx} onClick={() => setCurrentBannerIndex(idx)} className={`w-1.5 h-1.5 md:w-2 md:h-2 rounded-full transition-all ${idx === currentBannerIndex ? 'bg-white w-4 md:w-6' : 'bg-white/50 hover:bg-white/80'}`} />)}
                    </div>
                </>
            )}
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 grid grid-cols-1 lg:grid-cols-12 gap-8 relative z-10">
        <div className="lg:col-span-7 space-y-4 md:space-y-6">
          <div className="flex items-center justify-between">
             <h2 className="text-xl md:text-2xl font-bold text-slate-900 flex items-center">
                <div className="w-8 h-8 rounded-lg bg-orange-100 text-orange-600 flex items-center justify-center mr-3"><Music className="w-5 h-5" /></div>{t('Trending Now')}
             </h2>
             <Link to="/browse/songs/A" className="text-sm font-semibold text-primary hover:text-primary/80 flex items-center">{t('View All')} <ChevronRight className="w-4 h-4 ml-1" /></Link>
          </div>
          <div className="bg-white/80 backdrop-blur-lg rounded-3xl shadow-sm border border-slate-200/60 overflow-hidden">
            {data?.trendingSongs.length === 0 ? <p className="p-8 text-center text-slate-400 italic">No trending songs yet.</p> : data?.trendingSongs.map((song: any, idx) => {
                const displayTitle = (language === 'nepali' && song.title_nepali) ? song.title_nepali : song.title;
                return (
                <Link key={idx} to={`/l/${song.id}`} className="relative flex items-center justify-between p-4 md:p-5 hover:bg-white transition-all group border-b border-slate-100 last:border-0">
                   <div className="flex items-center gap-4 md:gap-5 relative z-10">
                      <span className={`text-xl md:text-2xl font-black w-6 md:w-8 text-center ${rankColors[idx] || 'text-slate-200'}`}>{idx + 1}</span>
                      <div>
                         <h3 className={`font-bold text-base md:text-lg transition-colors line-clamp-1 ${getSongColorClass(song.language)}`}>
                            {displayTitle}
                            {song.note && <span className="ml-1.5 text-xs text-slate-400 font-medium italic">({song.note})</span>}
                         </h3>
                         <p className="text-sm text-slate-500 font-medium group-hover:text-slate-600 line-clamp-1">{song.artist}</p>
                      </div>
                   </div>
                   <div className={`flex items-center justify-center w-8 h-8 md:w-10 md:h-10 rounded-full transition-all transform group-hover:scale-110 shadow-sm flex-shrink-0 ${rankBgColors[idx] || 'bg-slate-50 text-slate-300'}`}><Play className="w-3.5 h-3.5 md:w-4 md:h-4 ml-0.5 fill-current" /></div>
                </Link>
            )})}
          </div>
        </div>
        <div className="lg:col-span-5 space-y-4 md:space-y-6">
           <div className="flex items-center justify-between">
              <h2 className="text-xl md:text-2xl font-bold text-slate-900 flex items-center">
                <div className="w-8 h-8 rounded-lg bg-purple-100 text-purple-600 flex items-center justify-center mr-3"><Mic2 className="w-5 h-5" /></div>{t('Top Artists')}
              </h2>
              <Link to="/browse/artists/A" className="text-sm font-semibold text-primary hover:text-primary/80 flex items-center">{t('View All')} <ChevronRight className="w-4 h-4 ml-1" /></Link>
           </div>
           <div className="bg-white/80 backdrop-blur-lg rounded-3xl shadow-sm border border-slate-200/60 overflow-hidden">
              {data?.popularArtists.length === 0 ? <p className="p-8 text-center text-slate-400 italic">No popular artists yet.</p> : data?.popularArtists.map((artist, idx) => (
                   <Link key={idx} to={`/artist/${encodeURIComponent(artist.name)}`} className="relative flex items-center justify-between p-4 hover:bg-white transition-all group border-b border-slate-100 last:border-0">
                       <div className="flex items-center gap-4 relative z-10 min-w-0">
                          <span className={`text-lg md:text-xl font-black w-6 text-center flex-shrink-0 ${rankColors[idx] || 'text-purple-200'}`}>{idx + 1}</span>
                          <div className="w-12 h-12 rounded-full overflow-hidden border border-slate-200 bg-slate-100 flex-shrink-0">
                                {artist.imageUrl ? <img src={artist.imageUrl} alt={artist.name} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-slate-400"><Mic2 className="w-6 h-6" /></div>}
                          </div>
                          <div className="min-w-0">
                              <span className="font-bold text-slate-800 text-base block truncate group-hover:text-purple-600 transition-colors">{artist.name}</span>
                              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1 block">ARTIST</span>
                          </div>
                       </div>
                      <div className="w-8 h-8 rounded-full flex items-center justify-center bg-slate-100 text-slate-400 group-hover:bg-purple-100 group-hover:text-purple-600 transition-colors flex-shrink-0"><ChevronRight className="w-4 h-4" /></div>
                   </Link>
              ))}
           </div>
        </div>
      </div>
    </div>
  );
};

export default Home;

import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { getSongsByLetter, getArtistsByLetter, ArtistWithRoles } from '../services/geminiService';
import Loader from '../components/Loader';
import AlphabetNav from '../components/AlphabetNav';
import { Music, Disc, ArrowRight, Mic2, PenTool, Filter, Check } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface BrowseProps {
  mode: 'songs' | 'artists';
}

type RoleFilter = 'all' | 'Singer' | 'Composer' | 'Lyricist';

const Browse: React.FC<BrowseProps> = ({ mode }) => {
  const { letter } = useParams<{ letter: string }>();
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [roleFilter, setRoleFilter] = useState<RoleFilter>('all');
  const { t, language: appLanguage } = useLanguage();

  const fetchData = async () => {
    if (letter) {
      setLoading(true);
      const decodedLetter = decodeURIComponent(letter);
      if (mode === 'songs') {
        const results = await getSongsByLetter(decodedLetter);
        setData(results);
      } else {
        const results = await getArtistsByLetter(decodedLetter);
        setData(results);
      }
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    setRoleFilter('all');

    const handleContentChange = () => fetchData();
    window.addEventListener('content-change', handleContentChange);
    return () => window.removeEventListener('content-change', handleContentChange);
  }, [letter, mode]);

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-800';
  };

  const filteredData = mode === 'artists' && roleFilter !== 'all'
    ? (data as ArtistWithRoles[]).filter(artist => artist.roles.includes(roleFilter))
    : data;

  const displayLetter = decodeURIComponent(letter || '');
  const titleText = mode === 'songs' ? t('Songs') : t('Artists');

  const RoleBadge: React.FC<{ role: string }> = ({ role }) => {
    switch(role) {
      case 'Singer': return <span className="bg-pink-50 text-pink-600 px-1.5 py-0.5 rounded text-[9px] font-bold uppercase flex items-center gap-1 border border-pink-100"><Mic2 className="w-2.5 h-2.5" /> Singer</span>;
      case 'Composer': return <span className="bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded text-[9px] font-bold uppercase flex items-center gap-1 border border-indigo-100"><Music className="w-2.5 h-2.5" /> Composer</span>;
      case 'Lyricist': return <span className="bg-purple-50 text-purple-600 px-1.5 py-0.5 rounded text-[9px] font-bold uppercase flex items-center gap-1 border border-purple-100"><PenTool className="w-2.5 h-2.5" /> Lyricist</span>;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <AlphabetNav mode={mode} />

      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="mb-8 flex flex-col md:flex-row md:items-end justify-between border-b border-slate-200 pb-6 gap-6">
            <div>
                <h1 className="text-4xl font-bold text-slate-900 flex items-center gap-3">
                    <span className="bg-primary/10 text-primary p-2 rounded-2xl text-2xl min-w-[3.5rem] text-center shadow-sm">{displayLetter}</span>
                    <span className="capitalize">{titleText}</span>
                </h1>
                <p className="text-slate-500 mt-2 font-medium">{t('Discover popular')} {titleText.toLowerCase()} {t('starting with')} "{displayLetter}"</p>
            </div>

            {mode === 'artists' && !loading && data.length > 0 && (
                <div className="flex flex-wrap items-center gap-2 bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm">
                    <div className="px-3 text-slate-400">
                        <Filter className="w-4 h-4" />
                    </div>
                    {(['all', 'Singer', 'Composer', 'Lyricist'] as RoleFilter[]).map((filter) => (
                        <button
                            key={filter}
                            onClick={() => setRoleFilter(filter)}
                            className={`px-4 py-1.5 rounded-xl text-xs font-bold transition-all flex items-center gap-1.5 ${
                                roleFilter === filter 
                                ? 'bg-primary text-white shadow-lg shadow-primary/20 scale-105' 
                                : 'text-slate-500 hover:bg-slate-50'
                            }`}
                        >
                            {roleFilter === filter && <Check className="w-3 h-3" />}
                            {filter === 'all' ? 'All Roles' : filter + 's'}
                        </button>
                    ))}
                </div>
            )}
        </div>

        {loading ? (
          <Loader text={`Fetching ${mode} starting with ${displayLetter}...`} />
        ) : filteredData.length === 0 ? (
          <div className="text-center py-20 bg-white rounded-3xl border border-slate-200 shadow-sm">
            <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4">
                {mode === 'songs' ? <Music className="text-slate-300 w-10 h-10" /> : <Mic2 className="text-slate-300 w-10 h-10" />}
            </div>
            <h3 className="text-2xl text-slate-400 font-bold mb-2">{t('No')} {titleText.toLowerCase()} {t('found')}</h3>
            <p className="text-slate-500">{roleFilter === 'all' ? t('Try selecting a different letter.') : `No ${roleFilter.toLowerCase()}s found starting with "${displayLetter}".`}</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredData.map((item, idx) => {
              const isSong = mode === 'songs';
              const title = isSong ? ((appLanguage === 'nepali' && item.title_nepali) ? item.title_nepali : item.title) : item.name;
              const subtitle = isSong ? item.artist : undefined;
              const language = isSong ? item.language : undefined;
              const imageUrl = !isSong ? item.imageUrl : undefined;
              const roles = !isSong ? item.roles : [];
              const note = isSong ? item.note : undefined;

              const link = isSong 
                ? `/l/${item.id}` // Use ID for short URL
                : `/artist/${encodeURIComponent(item.name)}`;

              const titleClass = isSong ? getSongColorClass(language) : 'text-slate-800';

              return (
                <Link 
                  key={idx} 
                  to={link}
                  className="group flex items-center justify-between p-4 bg-white hover:bg-slate-50 border border-slate-200 hover:border-primary/30 rounded-2xl transition-all duration-300 shadow-sm hover:shadow-xl hover:-translate-y-1"
                >
                  <div className="flex items-center min-w-0 flex-1">
                    <div className="w-12 h-12 rounded-2xl overflow-hidden flex-shrink-0 mr-4 shadow-inner border border-slate-100 flex items-center justify-center bg-slate-50 group-hover:bg-primary/5 transition-colors">
                        {imageUrl ? (
                            <img src={imageUrl} alt={title} className="w-full h-full object-cover" />
                        ) : (
                            <div className={`w-full h-full flex items-center justify-center text-primary/40 group-hover:text-primary transition-colors ${isSong ? 'bg-primary/10' : 'bg-secondary/10 text-secondary/40 group-hover:text-secondary'}`}>
                                {isSong ? <Disc className="w-6 h-6" /> : <Mic2 className="w-6 h-6" />}
                            </div>
                        )}
                    </div>
                    <div className="min-w-0 pr-4 flex-1">
                      <h3 className={`font-bold truncate transition-colors text-base md:text-lg ${titleClass}`}>
                        {title}
                        {note && <span className="ml-1.5 text-xs text-slate-400 font-medium italic">({note})</span>}
                      </h3>
                      {isSong ? (
                        <p className="text-slate-400 text-xs font-bold uppercase tracking-wider truncate">{subtitle}</p>
                      ) : (
                        <div className="flex flex-wrap gap-1 mt-1">
                          {roles.map((role: string) => <RoleBadge key={role} role={role} />)}
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all transform group-hover:rotate-0 -rotate-45">
                    <ArrowRight className="w-4 h-4" />
                  </div>
                </Link>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

