            <button onClick={handleFavorite} className={`p-2.5 rounded-full border transition-all shadow-sm ${isFav ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-slate-400 border-slate-200'}`}>
              <Heart className={`w-6 h-6 ${isFav ? 'fill-current' : ''}`} />
            </button>
            <button onClick={handlePrint} className="p-2.5 bg-white border border-slate-200 rounded-full text-slate-400 hover:text-slate-600 shadow-sm transition-all">
              <Printer className="w-6 h-6" />
            </button>
            <button onClick={() => setIsFeedbackOpen(true)} className="p-2.5 bg-white border border-slate-200 rounded-full text-slate-400 hover:text-red-500 shadow-sm transition-all">
              <Flag className="w-6 h-6" />
            </button>
            {canEdit && (
              <button onClick={() => setIsEditing(!isEditing)} className={`p-2.5 rounded-full transition-all shadow-sm ${isEditing ? 'bg-slate-200 text-slate-600' : 'bg-indigo-500 text-white shadow-indigo-100'}`}>
                {isEditing ? <X className="w-6 h-6" /> : <Edit className="w-6 h-6" />}
              </button>
            )}
          </div>
        </div>

        {isEditing ? (
          <div className="bg-white rounded-3xl p-6 shadow-xl border border-slate-200 space-y-6 animate-in slide-in-from-bottom-4">
            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1 uppercase tracking-widest">Song Title</label>
              <input className="w-full border p-3 rounded-xl bg-slate-50 outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} placeholder="Title" />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1 uppercase tracking-widest">Lyrics (Native Script)</label>
              <textarea className="w-full h-96 border p-4 rounded-xl bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} placeholder="Lyrics (Nepali)" />
            </div>
            <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-4 rounded-xl font-black text-lg shadow-lg shadow-primary/20 transition-all active:scale-[0.98]">{isSaving ? 'Saving...' : 'Save Changes'}</button>
          </div>
        ) : (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="flex border-b border-slate-100 bg-slate-50/50">
              <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-4 font-bold text-xs md:text-sm uppercase tracking-widest transition-all ${activeTab === 'nepali' ? 'text-primary border-b-2 border-primary bg-white' : 'text-slate-400 hover:text-slate-600'}`}>Native Script</button>
              <button onClick={() => setActiveTab('roman')} className={`flex-1 py-4 font-bold text-xs md:text-sm uppercase tracking-widest transition-all ${activeTab === 'roman' ? 'text-primary border-b-2 border-primary bg-white' : 'text-slate-400 hover:text-slate-600'}`}>Romanized</button>
            </div>

            <div className="p-6 md:p-12 relative bg-white">
              <div className="absolute top-4 right-4 flex gap-2 no-print">
                <button onClick={handleZoomOut} className="p-1.5 bg-slate-50 text-slate-400 rounded-lg hover:bg-slate-100 transition-colors"><ZoomOut className="w-4 h-4" /></button>
                <button onClick={handleZoomIn} className="p-1.5 bg-slate-50 text-slate-400 rounded-lg hover:bg-slate-100 transition-colors"><ZoomIn className="w-4 h-4" /></button>
                <button onClick={handleCopy} className="p-1.5 bg-slate-50 text-slate-400 rounded-lg hover:bg-slate-100 transition-colors">
                  {copied ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}
                </button>
              </div>
              <div className="whitespace-pre-wrap leading-[1.8] transition-all font-medium text-slate-800" style={{ fontSize: `${fontSize}px` }}>
                {activeTab === 'nepali' ? data.lyrics_nepali || data.lyrics : data.lyrics_roman}
              </div>
            </div>
          </div>
        )}

        {/* Contributors Info Bar */}
        {!isEditing && (
            <div className="mt-8 flex flex-wrap gap-4 justify-center items-center text-xs md:text-sm font-bold text-slate-400 uppercase tracking-widest bg-white/60 p-4 rounded-2xl border border-slate-100 no-print">
                <div className="flex items-center gap-1"><Disc className="w-3.5 h-3.5" /> Artist: <span className="text-slate-900">{data.artist}</span></div>
                {data.composer && <div className="flex items-center gap-1 border-l pl-4"><PenTool className="w-3.5 h-3.5" /> Music: <span className="text-slate-900">{data.composer}</span></div>}
                {data.lyricist && <div className="flex items-center gap-1 border-l pl-4"><Mic2 className="w-3.5 h-3.5" /> Words: <span className="text-slate-900">{data.lyricist}</span></div>}
            </div>
        )}

        {/* Feedback Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
                    <div className="bg-primary p-6 text-white text-center relative">
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-4 right-4 p-1 rounded-full bg-white/20 hover:bg-white/40 transition-colors"><X className="w-5 h-5"/></button>
                        <Flag className="w-12 h-12 mx-auto mb-3 opacity-80" />
                        <h3 className="text-xl font-black">Report Issue</h3>
                        <p className="text-sm opacity-80">Help us keep the library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-12 text-center space-y-4 animate-in slide-in-from-bottom-4">
                            <div className="w-16 h-16 bg-green-100 text-green-500 rounded-full flex items-center justify-center mx-auto shadow-inner"><Check className="w-8 h-8" /></div>
                            <h4 className="text-lg font-bold text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 text-sm">Your feedback has been submitted successfully.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-6 space-y-5">
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Type of Issue</label>
                                <select 
                                    className="w-full bg-slate-50 border border-slate-200 p-3 rounded-xl font-bold text-sm outline-none focus:ring-2 focus:ring-primary/20"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue</option>
                                    <option>Missing Verses</option>
                                    <option>Wrong Credits</option>
                                    <option>Typo in Title</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Description</label>
                                <textarea 
                                    required
                                    className="w-full h-32 bg-slate-50 border border-slate-200 p-3 rounded-xl text-sm outline-none focus:bg-white focus:ring-2 focus:ring-primary/20"
                                    placeholder="Tell us what's wrong..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-4 rounded-xl font-black shadow-xl shadow-primary/20 hover:bg-primary/90 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Submitting...' : 'Send Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useState, useEffect, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth, logout } from '../utils/auth';
import { 
  getAllCustomSongs, 
  saveCustomSong, 
  saveCustomArtist, 
  getAllCustomArtists, 
  deleteCustomSong, 
  deleteCustomArtist, 
  getCustomArtist, 
  getBanners, 
  saveBanner, 
  deleteBanner, 
  getCategories, 
  addCategory, 
  updateCategory, 
  deleteCategory, 
  reorderCategories,
  exportAllData, 
  importAllData, 
  getSiteLogo, 
  saveSiteLogo, 
  getAnnouncement, 
  saveAnnouncement, 
  getContactInfo, 
  saveContactInfo, 
  getAnalytics, 
  AnalyticsData,
  getReports,
  deleteReport
} from '../utils/dataManager';
import { 
  LogOut, Plus, Music, User, Trash2, Edit2, Grid, ImageIcon as BannerIcon, 
  Check, X, Database, Settings, Megaphone, Info, Activity, Calendar, Clock, 
  Save, ExternalLink, Search, Youtube, Globe, Mail, MessageCircle,
  Download, Shield, Upload, Camera, Image as ImageIconRegular,
  Facebook, Instagram, ChevronUp, ChevronDown, GripVertical, StickyNote,
  MailWarning, Bell
} from 'lucide-react';
import { Banner, Announcement, Category, ContactInfo, Report } from '../types';
import Loader from '../components/Loader';
import ArtistSelector from '../components/ArtistSelector';
import { supabase } from '../supabaseClient';

const AdminDashboard: React.FC = () => {
  const { user, isAuth, loading: authLoading } = useAuth();
  const navigate = useNavigate();
  const userRole = user?.role;
  const isSuperAdmin = userRole === 'SUPER_ADMIN';
  const isRegularUser = userRole === 'USER';

  const [activeTab, setActiveTab] = useState<'overview' | 'songs' | 'artists' | 'banners' | 'categories' | 'contact' | 'backup' | 'settings' | 'addSong' | 'addArtist' | 'announcement' | 'reports'>('overview');
  const [loading, setLoading] = useState(true);
  const [customSongs, setCustomSongs] = useState<any[]>([]);
  const [customArtists, setCustomArtists] = useState<any[]>([]);
  const [banners, setBanners] = useState<Banner[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [reports, setReports] = useState<Report[]>([]);
  const [announcement, setAnnouncement] = useState<Announcement>({ imageUrl: '', link: '', isVisible: false });
  const [contactInfo, setContactInfo] = useState<ContactInfo>({
      missionTitle: '', missionText: '', visionTitle: '', visionText: '',
      email: '', whatsapp: '', facebookUrl: '', footerTitle: '', footerText: ''
  });

  const [analytics, setAnalytics] = useState<AnalyticsData>({ lifetime: 0, today: 0, thisWeek: 0, lastWeek: 0 });
  const [onlineCount, setOnlineCount] = useState(0);

  // Drag and Drop State
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  // Refs for file uploads
  const bannerFileRef = useRef<HTMLInputElement>(null);
  const announcementFileRef = useRef<HTMLInputElement>(null);
  const logoFileRef = useRef<HTMLInputElement>(null);
  const backupFileRef = useRef<HTMLInputElement>(null);
  const categoryFileRef = useRef<HTMLInputElement>(null);
  const editCategoryFileRef = useRef<HTMLInputElement>(null);
  const artistFileRef = useRef<HTMLInputElement>(null);

  // Search/Filter states
  const [songSearch, setSongSearch] = useState('');
  const [artistSearch, setArtistSearch] = useState('');

  // Form States - Refactored to remove confusing singular string fields
  const [songForm, setSongForm] = useState({ 
      title: '', 
      title_nepali: '', 
      artists: [] as string[], 
      lyrics_nepali: '', 
      lyrics_roman: '', 
      composers: [] as string[], 
      lyricists: [] as string[], 
      singers: [] as string[], 
      views: 0, 
      categories: [] as string[],
      youtubeUrl: '', 
      isYoutubeVisible: true,
      language: 'nepali' as 'nepali' | 'hindi' | 'english',
      note: '', 
      isNoteVisible: true
  });

  const [artistForm, setArtistForm] = useState({ 
      name: '', bio: '', topSongs: '', imageUrl: '', 
      facebookUrl: '', instagramUrl: '', youtubeUrl: '',
      isFacebookVisible: true, isInstagramVisible: true, isArtistYoutubeVisible: true
  });
  const [bannerForm, setBannerForm] = useState({ imageUrl: '', title: '', subtitle: '', link: '' });
  const [editingBannerId, setEditingBannerId] = useState<string | null>(null);
  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '', hideTitle: false });
  const [siteLogo, setSiteLogo] = useState('');
  const [editingCategory, setEditingCategory] = useState<{original: string, current: string, imageUrl: string, hideTitle: boolean} | null>(null);

  useEffect(() => {
    if (!authLoading) {
      if (!isAuth) {
        navigate('/login');
      } else if (isRegularUser) {
        navigate('/');
      } else {
        refreshData();
        setupPresence();

        // Listen for report events
        window.addEventListener('new-report', refreshData);
        return () => window.removeEventListener('new-report', refreshData);
      }
    }
  }, [isAuth, isRegularUser, authLoading, navigate]);

  const setupPresence = () => {
    const channel = supabase.channel('online_users');
    channel
        .on('presence', { event: 'sync' }, () => {
            const newState = channel.presenceState();
            setOnlineCount(Object.keys(newState).length);
        })
        .subscribe();

    return () => { channel.unsubscribe(); }
  };

  const refreshData = async () => {
    try {
      setLoading(true);
      const [songs, artists, bans, cats, logo, stats, ann, info, rpts] = await Promise.all([
        getAllCustomSongs(),
        getAllCustomArtists(),
        getBanners(),
        getCategories(),
        getSiteLogo(),
        getAnalytics(),
        getAnnouncement(),
        getContactInfo(),
        getReports()
      ]);

      setCustomSongs(songs);
      setCustomArtists(artists);
      setBanners(bans);
      setCategories(cats);
      setSiteLogo(logo);
      setAnalytics(stats);
      setReports(rpts);

      if (ann) setAnnouncement(ann);
      if (info) setContactInfo(prev => ({ ...prev, ...info }));
    } catch (err) {
      console.error("Dashboard refresh failed:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = error => reject(error);
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, target: 'banner' | 'announcement' | 'logo' | 'category' | 'edit-category' | 'artist') => {
    const file = e.target.files?.[0];
    if (file) {
      try {
        const base64 = await fileToBase64(file);
        if (target === 'banner') setBannerForm(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'announcement') setAnnouncement(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'logo') setSiteLogo(base64);
        else if (target === 'category') setCategoryForm(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'edit-category') setEditingCategory(prev => prev ? { ...prev, imageUrl: base64 } : null);
        else if (target === 'artist') setArtistForm(prev => ({ ...prev, imageUrl: base64 }));

        e.target.value = '';
      } catch (err) {
        alert("File conversion failed.");
      }
    }
  };

  const handleAddSong = async (e: React.FormEvent) => {
    e.preventDefault();
    const titleClean = songForm.title.trim();
    if (!titleClean) {
        alert("Song title is required.");
        return;
    }

    // Defensive check for artist
    const artistList = Array.isArray(songForm.artists) ? songForm.artists : [];
    const displayArtist = artistList.length > 0 ? artistList.join(', ') : 'Unknown';

    try {
        // Build payload ensuring only arrays are called with .join()
        const payloadData = {
            title_nepali: songForm.title_nepali.trim(),
            lyrics_nepali: songForm.lyrics_nepali,
            lyrics_roman: songForm.lyrics_roman,
            composer: songForm.composers.join(', '),
            composers: songForm.composers,
            lyricist: songForm.lyricists.join(', '),
            lyricists: songForm.lyricists,
            singer: songForm.singers.join(', '),
            singers: songForm.singers,
            views: songForm.views,
            categories: songForm.categories.length > 0 ? songForm.categories : ['Worship'],
            youtubeUrl: songForm.youtubeUrl.trim(),
            isYoutubeVisible: songForm.isYoutubeVisible,
            artists: artistList,
            language: songForm.language,
            artist: displayArtist,
            note: songForm.note.trim(),
            isNoteVisible: songForm.isNoteVisible
        };

        await saveCustomSong(displayArtist, titleClean, payloadData);

        // Reset form
        setSongForm({ 
            title: '', 
            title_nepali: '', 
            artists: [], 
            lyrics_nepali: '', 
            lyrics_roman: '', 
            composers: [], 
            lyricists: [], 
            singers: [], 
            views: 0, 
            categories: [], 
            youtubeUrl: '', 
            isYoutubeVisible: true, 
            language: 'nepali', 
            note: '', 
            isNoteVisible: true
        });

        setActiveTab('songs');
        refreshData();
        alert("Song published successfully!");
    } catch (err: any) {
        alert("Failed to save song: " + (err.message || "Unknown error"));
    }
  };

  const handleAddArtist = async (e: React.FormEvent) => {
    e.preventDefault();
    const nameClean = artistForm.name.trim();
    if (!nameClean) return;
    try {
        await saveCustomArtist(nameClean, {
            name: nameClean,
            bio: artistForm.bio,
            topSongs: artistForm.topSongs.split(',').map(s => s.trim()).filter(s => s),
            imageUrl: artistForm.imageUrl.trim(),
            facebookUrl: artistForm.facebookUrl.trim(),
            instagramUrl: artistForm.instagramUrl.trim(),
            youtubeUrl: artistForm.youtubeUrl.trim(),
            isFacebookVisible: artistForm.isFacebookVisible,
            isInstagramVisible: artistForm.isInstagramVisible,
            isArtistYoutubeVisible: artistForm.isArtistYoutubeVisible
        });
        setArtistForm({ name: '', bio: '', topSongs: '', imageUrl: '', facebookUrl: '', instagramUrl: '', youtubeUrl: '', isFacebookVisible: true, isInstagramVisible: true, isArtistYoutubeVisible: true });
        setActiveTab('artists');
        refreshData();
    } catch (err: any) {
        alert("Failed to create artist: " + (err.message || "Unknown error"));
    }
  };

  const handleAddBanner = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!bannerForm.imageUrl) {
        alert("Banner image is required!");
        return;
    }

    try {
        setLoading(true);
        const id = editingBannerId || `temp_${Date.now()}`;

        await saveBanner({ 
            id, imageUrl: bannerForm.imageUrl, title: bannerForm.title, 
            subtitle: bannerForm.subtitle, link: bannerForm.link
        });

        setBannerForm({ imageUrl: '', title: '', subtitle: '', link: '' });
        setEditingBannerId(null);

        await refreshData();
        alert("Banner saved successfully!");
    } catch (err: any) {
        alert("Failed to save banner: " + (err.message || "Error saving banner."));
    } finally {
        setLoading(false);
    }
  };

  const handleAddCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    const nameClean = categoryForm.name.trim();
    if (!nameClean) return;
    const result = await addCategory(nameClean, categoryForm.imageUrl.trim(), categoryForm.hideTitle);
    if (result.success) {
      setCategoryForm({ name: '', imageUrl: '', hideTitle: false });
      refreshData();
    } else {
      alert("Error adding category: " + result.error);
    }
  };

  const handleUpdateCategory = async () => {
    if (editingCategory && editingCategory.current.trim()) {
      try {
        await updateCategory(editingCategory.original, editingCategory.current.trim(), editingCategory.imageUrl.trim(), editingCategory.hideTitle);
        setEditingCategory(null);
        refreshData();
      } catch (err: any) {
        alert("Update failed: " + err.message);
      }
    }
  };

  // Drag and Drop Handlers
  const handleDragStart = (index: number) => {
    setDraggedIndex(index);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); // Allow drop
  };

  const handleDrop = async (targetIndex: number) => {
    if (draggedIndex === null || draggedIndex === targetIndex) return;

    const newCategories = [...categories];
    const draggedItem = newCategories[draggedIndex];

    // Remove and Insert at new position
    newCategories.splice(draggedIndex, 1);
    newCategories.splice(targetIndex, 0, draggedItem);

    setCategories(newCategories);
    setDraggedIndex(null);

    try {
        await reorderCategories(newCategories);
    } catch (err: any) {
        alert("Failed to update order: " + err.message);
        refreshData(); // Revert on failure
    }
  };

  const handleMoveCategory = async (index: number, direction: 'up' | 'down') => {
    const newCategories = [...categories];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;

    if (targetIndex < 0 || targetIndex >= newCategories.length) return;

    // Swap items locally
    [newCategories[index], newCategories[targetIndex]] = [newCategories[targetIndex], newCategories[index]];

    setCategories(newCategories);
    try {
        await reorderCategories(newCategories);
    } catch (err: any) {
        alert("Failed to update order: " + err.message);
        refreshData();
    }
  };

  const handleSaveAnnouncement = async (e: React.FormEvent) => {
      e.preventDefault();
      try {
          await saveAnnouncement(announcement);
          alert("Announcement updated!");
      } catch (err: any) {
          alert("Update failed: " + err.message);
      }
  };

  const handleSaveContact = async (e: React.FormEvent) => {
      e.preventDefault();
      try {
          await saveContactInfo(contactInfo);
          alert("Contact information updated!");
      } catch (err: any) {
          alert("Update failed: " + err.message);
      }
  };

  const handleSaveLogo = async () => {
      try {
          await saveSiteLogo(siteLogo);
          alert("Site logo updated!");
      } catch (err: any) {
          alert("Update failed: " + err.message);
      }
  };

  const handleImportBackup = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = async (event) => {
        try {
          const json = JSON.parse(event.target?.result as string);
          const result = await importAllData(json);
          alert(result.message);
          if (result.success) refreshData();
        } catch (err) {
          alert("Invalid backup file format.");
        }
      };
      reader.readAsText(file);
      e.target.value = '';
    }
  };

  const handleDownloadBackup = async () => {
      const data = await exportAllData();
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `sansarplus_backup_${new Date().toISOString().split('T')[0]}.json`;
      link.click();
  };

  const handleDeleteSong = (artist: string, title: string) => { if (window.confirm('Delete song?')) { deleteCustomSong(artist, title).then(refreshData); } };
  const handleDeleteArtist = (name: string) => { if (window.confirm('Delete artist?')) { deleteCustomArtist(name).then(refreshData); } };
  const handleDeleteBanner = (id: string) => { if (window.confirm('Delete banner?')) { deleteBanner(id).then(refreshData).catch(e => alert(e.message)); } };
  const handleDeleteCategory = async (cat: string) => { if (window.confirm(`Delete category "${cat}"?`)) { await deleteCategory(cat); refreshData(); } };
  const handleDeleteReport = async (id: string | number) => { if (window.confirm('Mark this message as resolved and delete it?')) { await deleteReport(id); refreshData(); } };

  if (authLoading) return <Loader fullScreen text="Verifying admin credentials..." />;

  const filteredSongs = customSongs.filter(s => 
      s.title.toLowerCase().includes(songSearch.toLowerCase()) || 
      s.artist.toLowerCase().includes(songSearch.toLowerCase())
  );

  const filteredArtists = customArtists.filter(a => 
      a.name.toLowerCase().includes(artistSearch.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      {/* Header Section */}
      <div className="bg-slate-900 text-white py-8 px-4">
