export default AdminDashboard;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { User, Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, Flag, X, Edit, Trash2, Save, Printer, Tag, Youtube, Mic2, StickyNote, Globe, Search, Disc } from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { saveCustomSong, deleteCustomSong, incrementViewCount, setViewCount, saveCustomArtist, getCategories, getAllCustomSongs, getSongById, submitReport } from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(16);
  const [availableCategories, setAvailableCategories] = useState<string[]>([]);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any, artist_bio?: string }>({
      lyrics_nepali: '',
      lyrics_roman: '',
      composer: '',
      composers: [],
      lyricist: '',
      lyricists: [],
      singer: '',
      singers: [],
      views: 0,
      artist_bio: '',
      category: '',
      categories: [],
      youtubeUrl: '',
      isYoutubeVisible: true,
      artist: '', 
      title: '',
      artists: [],
      title_nepali: '',
      note: '',
      isNoteVisible: true
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `Lyrics of ${songTitle} | SansarPlus`;

      const cats = await getCategories();
      setAvailableCategories(cats.map(c => c.name));

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult as any);
      setArtistData(artistResult);

      if (allSongs && artistName && artistName.toLowerCase() !== 'unknown') {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      } else {
          setRelatedSongs([]);
      }

      let initialCats = lyricsResult.categories || [];
      if (initialCats.length === 0 && lyricsResult.category) {
          initialCats = [lyricsResult.category];
      }

      const composerStr = lyricsResult.composers && lyricsResult.composers.length > 0 
          ? lyricsResult.composers.join(', ') 
          : lyricsResult.composer || '';

      const lyricistStr = lyricsResult.lyricists && lyricsResult.lyricists.length > 0 
          ? lyricsResult.lyricists.join(', ') 
          : lyricsResult.lyricist || '';

      const singerStr = lyricsResult.singers && lyricsResult.singers.length > 0 
          ? lyricsResult.singers.join(', ') 
          : lyricsResult.singer || '';

      setEditForm({ 
          ...lyricsResult, 
          title: lyricsResult.title || songTitle,
          artist: lyricsResult.artist || artistName,
          views: lyricsResult.views || 0,
          artist_bio: artistResult?.bio || '',
          category: lyricsResult.category || 'Worship',
          categories: initialCats,
          composer: composerStr,
          lyricist: lyricistStr,
          singer: singerStr,
          youtubeUrl: lyricsResult.youtubeUrl || '',
          isYoutubeVisible: lyricsResult.isYoutubeVisible !== false,
          title_nepali: lyricsResult.title_nepali || '',
          note: lyricsResult.note || '',
          isNoteVisible: lyricsResult.isNoteVisible !== false
      });

      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();

    return () => {
      document.title = 'SansarPlus | Nepali Christian Lyrics & Worship';
    };
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePrint = () => {
    window.print();
  };

  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 4, 64));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 16));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;

    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });

        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
            setFeedbackType('Lyrics Issue');
        }, 2500);
    } catch (err: any) {
        alert(`Submission failed: ${err.message}. Please check if 'reports' table exists in Supabase.`);
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;

      try {
          setIsSaving(true);
          const { artist_bio, ...songData } = editForm;

          const composers = editForm.composer.split(',').map(s => s.trim()).filter(s => s);
          const lyricists = editForm.lyricist.split(',').map(s => s.trim()).filter(s => s);
          const singers = editForm.singer.split(',').map(s => s.trim()).filter(s => s);

          const finalTitle = (editForm.title || data.title).trim();
          const finalArtist = (editForm.artist || data.artist).trim();

          const updatedSongData = {
              ...songData,
              title: finalTitle,
              artist: finalArtist,
              composers,
              lyricists,
              singers,
              id: data.id
          };

          await saveCustomSong(finalArtist, finalTitle, updatedSongData as any);

          setData({ ...data, ...updatedSongData });
          setIsEditing(false);
          alert("Song updated successfully!");
      } catch (err: any) {
          alert("Failed to save changes: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4">
        <h2 className="text-2xl font-bold text-slate-400 mb-4">Lyrics Not Found</h2>
        <Link to="/" className="text-primary font-bold hover:underline">Return Home</Link>
    </div>
  );

  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
          <div>
            <div className="flex items-center gap-3 flex-wrap">
                <h1 className="text-3xl md:text-4xl font-black text-slate-900 leading-tight">{displayTitle}</h1>
                {data.note && data.isNoteVisible !== false && <span className="bg-amber-50 text-amber-600 px-3 py-1 rounded-full text-xs font-bold border border-amber-100 flex items-center gap-1 shadow-sm"><StickyNote className="w-3 h-3" /> {data.note}</span>}
            </div>
            <p className="text-slate-500 font-medium text-lg mt-1">by {data.artist}</p>
          </div>
          <div className="flex gap-2 flex-wrap">
            <button onClick={handleFavorite} className={`p-2.5 rounded-full border transition-all shadow-sm ${isFav ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-slate-400 border-slate-200'}`}>
              <Heart className={`w-6 h-6 ${isFav ? 'fill-current' : ''}`} />
            </button>
            <button onClick={handlePrint} className="p-2.5 bg-white border border-slate-200 rounded-full text-slate-400 hover:text-slate-600 shadow-sm transition-all">
              <Printer className="w-6 h-6" />
            </button>
            <button onClick={() => setIsFeedbackOpen(true)} className="p-2.5 bg-white border border-slate-200 rounded-full text-slate-400 hover:text-red-500 shadow-sm transition-all">
              <Flag className="w-6 h-6" />
            </button>
            {canEdit && (
              <button onClick={() => setIsEditing(!isEditing)} className={`p-2.5 rounded-full transition-all shadow-sm ${isEditing ? 'bg-slate-200 text-slate-600' : 'bg-indigo-500 text-white shadow-indigo-100'}`}>
                {isEditing ? <X className="w-6 h-6" /> : <Edit className="w-6 h-6" />}
              </button>
            )}
          </div>
        </div>

        {isEditing ? (
          <div className="bg-white rounded-3xl p-6 shadow-xl border border-slate-200 space-y-6 animate-in slide-in-from-bottom-4">
            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1 uppercase tracking-widest">Song Title</label>
              <input className="w-full border p-3 rounded-xl bg-slate-50 outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} placeholder="Title" />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1 uppercase tracking-widest">Lyrics (Native Script)</label>
              <textarea className="w-full h-96 border p-4 rounded-xl bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} placeholder="Lyrics (Nepali)" />
            </div>
            <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-4 rounded-xl font-black text-lg shadow-lg shadow-primary/20 transition-all active:scale-[0.98]">{isSaving ? 'Saving...' : 'Save Changes'}</button>
          </div>
        ) : (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="flex border-b border-slate-100 bg-slate-50/50">
              <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-4 font-bold text-xs md:text-sm uppercase tracking-widest transition-all ${activeTab === 'nepali' ? 'text-primary border-b-2 border-primary bg-white' : 'text-slate-400 hover:text-slate-600'}`}>Native Script</button>
              <button onClick={() => setActiveTab('roman')} className={`flex-1 py-4 font-bold text-xs md:text-sm uppercase tracking-widest transition-all ${activeTab === 'roman' ? 'text-primary border-b-2 border-primary bg-white' : 'text-slate-400 hover:text-slate-600'}`}>Romanized</button>
            </div>

            <div className="p-6 md:p-12 relative bg-white">
              <div className="absolute top-4 right-4 flex gap-2 no-print">
                <button onClick={handleZoomOut} className="p-1.5 bg-slate-50 text-slate-400 rounded-lg hover:bg-slate-100 transition-colors"><ZoomOut className="w-4 h-4" /></button>
                <button onClick={handleZoomIn} className="p-1.5 bg-slate-50 text-slate-400 rounded-lg hover:bg-slate-100 transition-colors"><ZoomIn className="w-4 h-4" /></button>
                <button onClick={handleCopy} className="p-1.5 bg-slate-50 text-slate-400 rounded-lg hover:bg-slate-100 transition-colors">
                  {copied ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}
                </button>
              </div>
              <div className="whitespace-pre-wrap leading-[1.8] transition-all font-medium text-slate-800" style={{ fontSize: `${fontSize}px` }}>
                {activeTab === 'nepali' ? data.lyrics_nepali || data.lyrics : data.lyrics_roman}
              </div>
            </div>
          </div>
        )}

        {/* Contributors Info Bar */}
        {!isEditing && (
            <div className="mt-8 flex flex-wrap gap-4 justify-center items-center text-xs md:text-sm font-bold text-slate-400 uppercase tracking-widest bg-white/60 p-4 rounded-2xl border border-slate-100 no-print">
                <div className="flex items-center gap-1"><Disc className="w-3.5 h-3.5" /> Artist: <span className="text-slate-900">{data.artist}</span></div>
                {data.composer && <div className="flex items-center gap-1 border-l pl-4"><PenTool className="w-3.5 h-3.5" /> Music: <span className="text-slate-900">{data.composer}</span></div>}
                {data.lyricist && <div className="flex items-center gap-1 border-l pl-4"><Mic2 className="w-3.5 h-3.5" /> Words: <span className="text-slate-900">{data.lyricist}</span></div>}
            </div>
        )}

        {/* Feedback Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
                    <div className="bg-primary p-6 text-white text-center relative">
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-4 right-4 p-1 rounded-full bg-white/20 hover:bg-white/40 transition-colors"><X className="w-5 h-5"/></button>
                        <Flag className="w-12 h-12 mx-auto mb-3 opacity-80" />
                        <h3 className="text-xl font-black">Report Issue</h3>
                        <p className="text-sm opacity-80">Help us keep the library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-12 text-center space-y-4 animate-in slide-in-from-bottom-4">
                            <div className="w-16 h-16 bg-green-100 text-green-500 rounded-full flex items-center justify-center mx-auto shadow-inner"><Check className="w-8 h-8" /></div>
                            <h4 className="text-lg font-bold text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 text-sm">Your feedback has been submitted successfully.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-6 space-y-5">
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Type of Issue</label>
                                <select 
                                    className="w-full bg-slate-50 border border-slate-200 p-3 rounded-xl font-bold text-sm outline-none focus:ring-2 focus:ring-primary/20"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue</option>
                                    <option>Missing Verses</option>
                                    <option>Wrong Credits</option>
                                    <option>Typo in Title</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Description</label>
                                <textarea 
                                    required
                                    className="w-full h-32 bg-slate-50 border border-slate-200 p-3 rounded-xl text-sm outline-none focus:bg-white focus:ring-2 focus:ring-primary/20"
                                    placeholder="Tell us what's wrong..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-4 rounded-xl font-black shadow-xl shadow-primary/20 hover:bg-primary/90 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Submitting...' : 'Send Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  User, Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Trash2, Save, Printer, Tag, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, Eye, Calendar, ChevronRight
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  deleteCustomSong, 
  incrementViewCount, 
  getCategories, 
  getAllCustomSongs, 
  getSongById, 
  submitReport 
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(18);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      composer: '', lyrics_nepali: '', lyrics_roman: '', title: '', artist: ''
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} - ${artistName} Lyrics | SansarPlus`;

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 4);
          setRelatedSongs(related);
      }

      setEditForm({ ...lyricsResult });
      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      // Increment view count in background
      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${data.title} - ${data.artist} Lyrics`,
      text: `Check out the lyrics for "${data.title}" by ${data.artist} on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 48));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 12));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Failed to submit report.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          await saveCustomSong(editForm.artist || data.artist, editForm.title || data.title, editForm as any);
          setData({ ...data, ...editForm });
          setIsEditing(false);
          alert("Updated successfully!");
      } catch (err: any) {
          alert("Failed to save: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  if (loading) return <Loader fullScreen text="Opening library..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4">
        <Disc className="w-16 h-16 text-slate-200 mb-4" />
        <h2 className="text-2xl font-bold text-slate-400 mb-4">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-6 py-2 rounded-full font-bold shadow-lg">Return Home</Link>
    </div>
  );

  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <div className="max-w-5xl mx-auto px-4 py-8">

        {/* Top Header & Actions */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8 no-print">
            <div className="flex-1 min-w-0">
                <div className="flex items-center gap-3 flex-wrap mb-1">
                    <h1 className="text-3xl md:text-5xl font-black text-slate-900 leading-tight truncate">{displayTitle}</h1>
                    {data.note && data.isNoteVisible !== false && (
                        <span className="bg-amber-100 text-amber-700 px-3 py-1 rounded-full text-xs font-bold border border-amber-200 flex items-center gap-1.5 shadow-sm">
                            <StickyNote className="w-3 h-3" /> {data.note}
                        </span>
                    )}
                </div>
                <div className="flex items-center gap-4 text-slate-500 font-medium">
                    <Link to={`/artist/${encodeURIComponent(data.artist || '')}`} className="hover:text-primary transition-colors flex items-center gap-1.5">
                        <Disc className="w-4 h-4" /> {data.artist}
                    </Link>
                    <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
                    <div className="flex items-center gap-1.5">
                        <Eye className="w-4 h-4" /> {data.views?.toLocaleString() || 0} Views
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-2">
                <button onClick={handleFavorite} className={`p-3 rounded-2xl border transition-all shadow-sm ${isFav ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`} title="Add to Favorites">
                    <Heart className={`w-5 h-5 ${isFav ? 'fill-current' : ''}`} />
                </button>
                <button onClick={handleShare} className="p-3 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-primary shadow-sm hover:border-primary/30 transition-all" title="Share Song">
                    <Share2 className="w-5 h-5" />
                </button>
                <button onClick={handlePrint} className="p-3 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-slate-600 shadow-sm transition-all" title="Print Lyrics">
                    <Printer className="w-5 h-5" />
                </button>
                <button onClick={() => setIsFeedbackOpen(true)} className="p-3 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-red-500 shadow-sm transition-all" title="Report Error">
                    <Flag className="w-5 h-5" />
                </button>
                {canEdit && (
                    <button onClick={() => setIsEditing(!isEditing)} className={`p-3 rounded-2xl transition-all shadow-md ${isEditing ? 'bg-slate-200 text-slate-600' : 'bg-indigo-600 text-white shadow-indigo-200'}`}>
                        {isEditing ? <X className="w-5 h-5" /> : <Edit className="w-5 h-5" />}
                    </button>
                )}
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

            {/* Main Lyrics Area */}
            <div className="lg:col-span-8 space-y-6">

                {isEditing ? (
                    <div className="bg-white rounded-[2rem] p-8 shadow-xl border border-slate-200 space-y-6 animate-in slide-in-from-bottom-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1 ml-1">Title</label>
                                <input className="w-full border p-3 rounded-xl bg-slate-50 outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1 ml-1">Artist</label>
                                <input className="w-full border p-3 rounded-xl bg-slate-50 outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.artist} onChange={e => setEditForm({...editForm, artist: e.target.value})} />
                            </div>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1 ml-1">Native Script Lyrics</label>
                            <textarea className="w-full h-96 border p-4 rounded-xl bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                        </div>
                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-primary/20 hover:bg-primary/90 transition-all flex items-center justify-center">
                            {isSaving ? <Loader2 className="w-5 h-5 animate-spin mr-2"/> : <Save className="w-5 h-5 mr-2" />}
                            Save Changes
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-[2rem] shadow-xl overflow-hidden border border-slate-200">
                        {/* Tabs Navigation */}
                        <div className="flex border-b border-slate-100 bg-slate-50/50 no-print">
                            <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-5 font-bold text-sm uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 ${activeTab === 'nepali' ? 'text-primary border-b-2 border-primary bg-white' : 'text-slate-400 hover:text-slate-600'}`}>
                                <Globe className="w-4 h-4" /> Native
                            </button>
                            <button onClick={() => setActiveTab('roman')} className={`flex-1 py-5 font-bold text-sm uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 ${activeTab === 'roman' ? 'text-primary border-b-2 border-primary bg-white' : 'text-slate-400 hover:text-slate-600'}`}>
                                <Search className="w-4 h-4" /> Romanized
                            </button>
                        </div>

                        <div className="p-8 md:p-14 relative bg-white min-h-[400px]">
                            {/* Zoom/Copy Controls */}
                            <div className="absolute top-4 right-6 flex gap-2 no-print">
                                <button onClick={handleZoomOut} className="p-2 bg-slate-50 text-slate-400 rounded-xl hover:bg-slate-100 transition-colors" title="Zoom Out"><ZoomOut className="w-4 h-4" /></button>
                                <button onClick={handleZoomIn} className="p-2 bg-slate-50 text-slate-400 rounded-xl hover:bg-slate-100 transition-colors" title="Zoom In"><ZoomIn className="w-4 h-4" /></button>
                                <button onClick={handleCopy} className={`p-2 rounded-xl transition-all shadow-sm ${copied ? 'bg-green-500 text-white' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`} title="Copy Lyrics">
                                    {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                                </button>
                            </div>

                            {/* Lyrics Display */}
                            <div 
                                className="whitespace-pre-wrap leading-[1.8] transition-all font-medium text-slate-800" 
                                style={{ fontSize: `${fontSize}px` }}
                            >
                                {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Native lyrics not available.") : (data.lyrics_roman || "Romanized lyrics not available.")}
                            </div>
                        </div>

                        {/* Social Footer */}
                        <div className="bg-slate-50/50 p-6 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-4 no-print">
                            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Powered by SansarPlus Library</p>
                            <div className="flex items-center gap-4">
                                <button onClick={handleShare} className="text-sm font-bold text-primary hover:underline flex items-center gap-1.5">
                                    <Share2 className="w-4 h-4" /> Share with friends
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* Related Content / Categories Section */}
                {!isEditing && data.categories && data.categories.length > 0 && (
                    <div className="flex flex-wrap gap-2 no-print">
                        {data.categories.map(cat => (
                            <Link key={cat} to={`/category/${encodeURIComponent(cat)}`} className="px-4 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-500 hover:border-primary/30 hover:text-primary transition-all shadow-sm flex items-center gap-2">
                                <Tag className="w-3 h-3" /> {cat}
                            </Link>
                        ))}
                    </div>
                )}
            </div>

            {/* Sidebar Details */}
            <div className="lg:col-span-4 space-y-8 no-print">

                {/* YouTube Video Card */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2rem] overflow-hidden shadow-xl border border-slate-200 group">
                        <div className="bg-red-600 p-4 text-white flex items-center justify-between">
                            <h3 className="font-bold text-sm uppercase tracking-wider flex items-center gap-2">
                                <Youtube className="w-5 h-5" /> Official Video
                            </h3>
                            <Play className="w-4 h-4 opacity-50" />
                        </div>
                        <div className="aspect-video">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Song Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* Song Credits Card */}
                <div className="bg-white rounded-[2rem] p-6 shadow-xl border border-slate-200 space-y-6">
                    <h3 className="text-xl font-bold text-slate-900 border-b border-slate-50 pb-4">Song Information</h3>

                    <div className="space-y-4">
                        <div className="flex items-start gap-4">
                            <div className="w-10 h-10 bg-indigo-50 text-indigo-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                <Disc className="w-5 h-5" />
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Artist</p>
                                <p className="text-sm font-bold text-slate-800">{data.artist || 'Unknown'}</p>
                            </div>
                        </div>

                        {(data.composers?.length || data.composer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-purple-50 text-purple-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                    <Music className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Music / Composer</p>
                                    <p className="text-sm font-bold text-slate-800">{data.composers?.join(', ') || data.composer}</p>
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                    <PenTool className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Lyrics / Words</p>
                                    <p className="text-sm font-bold text-slate-800">{data.lyricists?.join(', ') || data.lyricist}</p>
                                </div>
                            </div>
                        )}

                        {(data.singers?.length || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Vocals / Singer</p>
                                    <p className="text-sm font-bold text-slate-800">{data.singers?.join(', ') || data.singer}</p>
                                </div>
                            </div>
                        )}

                        <div className="pt-4 mt-4 border-t border-slate-50 grid grid-cols-2 gap-4">
                            <div className="text-center p-3 bg-slate-50 rounded-2xl">
                                <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Language</p>
                                <p className="text-xs font-bold text-slate-700 capitalize">{data.language || 'Nepali'}</p>
                            </div>
                            <div className="text-center p-3 bg-slate-50 rounded-2xl">
                                <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Views</p>
                                <p className="text-xs font-bold text-slate-700">{data.views?.toLocaleString() || 0}</p>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Related Songs Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-4">
                        <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">
                             More from this Artist <ChevronRight className="w-4 h-4 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-3 bg-white rounded-[1.5rem] border border-slate-200 hover:border-primary/40 hover:shadow-md transition-all group"
                                >
                                    <div className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-400 group-hover:bg-primary group-hover:text-white transition-colors">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-bold text-slate-800 text-sm truncate group-hover:text-primary transition-colors">{appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}</p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{song.views?.toLocaleString() || 0} views</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Feedback Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
                    <div className="bg-primary p-8 text-white text-center relative">
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-4 right-6 p-2 rounded-full bg-white/20 hover:bg-white/40 transition-colors"><X className="w-5 h-5"/></button>
                        <Flag className="w-14 h-14 mx-auto mb-4 opacity-80" />
                        <h3 className="text-2xl font-black">Report Issue</h3>
                        <p className="text-sm opacity-80">Help us keep the library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-12 text-center space-y-4">
                            <div className="w-16 h-16 bg-green-100 text-green-500 rounded-full flex items-center justify-center mx-auto shadow-inner"><Check className="w-8 h-8" /></div>
                            <h4 className="text-xl font-bold text-slate-900">Thank You!</h4>
                            <p className="text-slate-500">Your feedback has been submitted successfully.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-8 space-y-6">
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Type of Issue</label>
                                <select 
                                    className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-2xl font-bold text-sm outline-none focus:ring-2 focus:ring-primary/20"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue</option>
                                    <option>Wrong Credits</option>
                                    <option>Missing Video</option>
                                    <option>Typo in Title</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Message Detail</label>
                                <textarea 
                                    required
                                    className="w-full h-32 bg-slate-50 border border-slate-200 p-4 rounded-2xl text-sm outline-none focus:bg-white focus:ring-2 focus:ring-primary/20"
                                    placeholder="Tell us what needs fixing..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-4 rounded-2xl font-black shadow-xl shadow-primary/20 hover:bg-primary/90 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
// Added Loader2 and Play to lucide-react imports
import { 
  User, Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Trash2, Save, Printer, Tag, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, Eye, Calendar, ChevronRight, Loader2, Play
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  deleteCustomSong, 
  incrementViewCount, 
  getCategories, 
  getAllCustomSongs, 
  getSongById, 
  submitReport 
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(18);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      composer: '', lyrics_nepali: '', lyrics_roman: '', title: '', artist: ''
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} - ${artistName} Lyrics | SansarPlus`;

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 4);
          setRelatedSongs(related);
      }

      setEditForm({ ...lyricsResult });
      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      // Increment view count in background
      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${data.title} - ${data.artist} Lyrics`,
      text: `Check out the lyrics for "${data.title}" by ${data.artist} on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 48));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 12));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Failed to submit report.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          await saveCustomSong(editForm.artist || data.artist, editForm.title || data.title, editForm as any);
          setData({ ...data, ...editForm });
          setIsEditing(false);
          alert("Updated successfully!");
      } catch (err: any) {
          alert("Failed to save: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  if (loading) return <Loader fullScreen text="Opening library..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4">
        <Disc className="w-16 h-16 text-slate-200 mb-4" />
        <h2 className="text-2xl font-bold text-slate-400 mb-4">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-6 py-2 rounded-full font-bold shadow-lg">Return Home</Link>
    </div>
  );

  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <div className="max-w-5xl mx-auto px-4 py-8">

        {/* Top Header & Actions */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8 no-print">
            <div className="flex-1 min-w-0">
                <div className="flex items-center gap-3 flex-wrap mb-1">
                    <h1 className="text-3xl md:text-5xl font-black text-slate-900 leading-tight truncate">{displayTitle}</h1>
                    {data.note && data.isNoteVisible !== false && (
                        <span className="bg-amber-100 text-amber-700 px-3 py-1 rounded-full text-xs font-bold border border-amber-200 flex items-center gap-1.5 shadow-sm">
                            <StickyNote className="w-3 h-3" /> {data.note}
                        </span>
                    )}
                </div>
                <div className="flex items-center gap-4 text-slate-500 font-medium">
                    <Link to={`/artist/${encodeURIComponent(data.artist || '')}`} className="hover:text-primary transition-colors flex items-center gap-1.5">
                        <Disc className="w-4 h-4" /> {data.artist}
                    </Link>
                    <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
                    <div className="flex items-center gap-1.5">
                        <Eye className="w-4 h-4" /> {data.views?.toLocaleString() || 0} Views
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-2">
                <button onClick={handleFavorite} className={`p-3 rounded-2xl border transition-all shadow-sm ${isFav ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`} title="Add to Favorites">
                    <Heart className={`w-5 h-5 ${isFav ? 'fill-current' : ''}`} />
                </button>
                <button onClick={handleShare} className="p-3 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-primary shadow-sm hover:border-primary/30 transition-all" title="Share Song">
                    <Share2 className="w-5 h-5" />
                </button>
                <button onClick={handlePrint} className="p-3 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-slate-600 shadow-sm transition-all" title="Print Lyrics">
                    <Printer className="w-5 h-5" />
                </button>
                <button onClick={() => setIsFeedbackOpen(true)} className="p-3 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-red-500 shadow-sm transition-all" title="Report Error">
                    <Flag className="w-5 h-5" />
                </button>
                {canEdit && (
                    <button onClick={() => setIsEditing(!isEditing)} className={`p-3 rounded-2xl transition-all shadow-md ${isEditing ? 'bg-slate-200 text-slate-600' : 'bg-indigo-600 text-white shadow-indigo-200'}`}>
                        {isEditing ? <X className="w-5 h-5" /> : <Edit className="w-5 h-5" />}
                    </button>
                )}
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

            {/* Main Lyrics Area */}
            <div className="lg:col-span-8 space-y-6">

                {isEditing ? (
                    <div className="bg-white rounded-[2rem] p-8 shadow-xl border border-slate-200 space-y-6 animate-in slide-in-from-bottom-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1 ml-1">Title</label>
                                <input className="w-full border p-3 rounded-xl bg-slate-50 outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1 ml-1">Artist</label>
                                <input className="w-full border p-3 rounded-xl bg-slate-50 outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.artist} onChange={e => setEditForm({...editForm, artist: e.target.value})} />
                            </div>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1 ml-1">Native Script Lyrics</label>
                            <textarea className="w-full h-96 border p-4 rounded-xl bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                        </div>
                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-primary/20 hover:bg-primary/90 transition-all flex items-center justify-center">
                            {isSaving ? <Loader2 className="w-5 h-5 animate-spin mr-2"/> : <Save className="w-5 h-5 mr-2" />}
                            Save Changes
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-[2rem] shadow-xl overflow-hidden border border-slate-200">
                        {/* Tabs Navigation */}
                        <div className="flex border-b border-slate-100 bg-slate-50/50 no-print">
                            <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-5 font-bold text-sm uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 ${activeTab === 'nepali' ? 'text-primary border-b-2 border-primary bg-white' : 'text-slate-400 hover:text-slate-600'}`}>
                                <Globe className="w-4 h-4" /> Native
                            </button>
                            <button onClick={() => setActiveTab('roman')} className={`flex-1 py-5 font-bold text-sm uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 ${activeTab === 'roman' ? 'text-primary border-b-2 border-primary bg-white' : 'text-slate-400 hover:text-slate-600'}`}>
                                <Search className="w-4 h-4" /> Romanized
                            </button>
                        </div>

                        <div className="p-8 md:p-14 relative bg-white min-h-[400px]">
                            {/* Zoom/Copy Controls */}
                            <div className="absolute top-4 right-6 flex gap-2 no-print">
                                <button onClick={handleZoomOut} className="p-2 bg-slate-50 text-slate-400 rounded-xl hover:bg-slate-100 transition-colors" title="Zoom Out"><ZoomOut className="w-4 h-4" /></button>
                                <button onClick={handleZoomIn} className="p-2 bg-slate-50 text-slate-400 rounded-xl hover:bg-slate-100 transition-colors" title="Zoom In"><ZoomIn className="w-4 h-4" /></button>
                                <button onClick={handleCopy} className={`p-2 rounded-xl transition-all shadow-sm ${copied ? 'bg-green-500 text-white' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`} title="Copy Lyrics">
                                    {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                                </button>
                            </div>

                            {/* Lyrics Display */}
                            <div 
                                className="whitespace-pre-wrap leading-[1.8] transition-all font-medium text-slate-800" 
                                style={{ fontSize: `${fontSize}px` }}
                            >
                                {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Native lyrics not available.") : (data.lyrics_roman || "Romanized lyrics not available.")}
                            </div>
                        </div>

                        {/* Social Footer */}
                        <div className="bg-slate-50/50 p-6 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-4 no-print">
                            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Powered by SansarPlus Library</p>
                            <div className="flex items-center gap-4">
                                <button onClick={handleShare} className="text-sm font-bold text-primary hover:underline flex items-center gap-1.5">
                                    <Share2 className="w-4 h-4" /> Share with friends
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* Related Content / Categories Section */}
                {!isEditing && data.categories && data.categories.length > 0 && (
                    <div className="flex flex-wrap gap-2 no-print">
                        {data.categories.map(cat => (
                            <Link key={cat} to={`/category/${encodeURIComponent(cat)}`} className="px-4 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-500 hover:border-primary/30 hover:text-primary transition-all shadow-sm flex items-center gap-2">
                                <Tag className="w-3 h-3" /> {cat}
                            </Link>
                        ))}
                    </div>
                )}
            </div>

            {/* Sidebar Details */}
            <div className="lg:col-span-4 space-y-8 no-print">

                {/* YouTube Video Card */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2rem] overflow-hidden shadow-xl border border-slate-200 group">
                        <div className="bg-red-600 p-4 text-white flex items-center justify-between">
                            <h3 className="font-bold text-sm uppercase tracking-wider flex items-center gap-2">
                                <Youtube className="w-5 h-5" /> Official Video
                            </h3>
                            <Play className="w-4 h-4 opacity-50" />
                        </div>
                        <div className="aspect-video">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Song Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* Song Credits Card */}
                <div className="bg-white rounded-[2rem] p-6 shadow-xl border border-slate-200 space-y-6">
                    <h3 className="text-xl font-bold text-slate-900 border-b border-slate-50 pb-4">Song Information</h3>

                    <div className="space-y-4">
                        <div className="flex items-start gap-4">
                            <div className="w-10 h-10 bg-indigo-50 text-indigo-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                <Disc className="w-5 h-5" />
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Artist</p>
                                <p className="text-sm font-bold text-slate-800">{data.artist || 'Unknown'}</p>
                            </div>
                        </div>

                        {(data.composers?.length || data.composer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-purple-50 text-purple-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                    <Music className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Music / Composer</p>
                                    <p className="text-sm font-bold text-slate-800">{data.composers?.join(', ') || data.composer}</p>
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                    <PenTool className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Lyrics / Words</p>
                                    <p className="text-sm font-bold text-slate-800">{data.lyricists?.join(', ') || data.lyricist}</p>
                                </div>
                            </div>
                        )}

                        {(data.singers?.length || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Vocals / Singer</p>
                                    <p className="text-sm font-bold text-slate-800">{data.singers?.join(', ') || data.singer}</p>
                                </div>
                            </div>
                        )}

                        <div className="pt-4 mt-4 border-t border-slate-50 grid grid-cols-2 gap-4">
                            <div className="text-center p-3 bg-slate-50 rounded-2xl">
                                <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Language</p>
                                <p className="text-xs font-bold text-slate-700 capitalize">{data.language || 'Nepali'}</p>
                            </div>
                            <div className="text-center p-3 bg-slate-50 rounded-2xl">
                                <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Views</p>
                                <p className="text-xs font-bold text-slate-700">{data.views?.toLocaleString() || 0}</p>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Related Songs Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-4">
                        <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">
                             More from this Artist <ChevronRight className="w-4 h-4 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-3 bg-white rounded-[1.5rem] border border-slate-200 hover:border-primary/40 hover:shadow-md transition-all group"
                                >
                                    <div className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-400 group-hover:bg-primary group-hover:text-white transition-colors">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-bold text-slate-800 text-sm truncate group-hover:text-primary transition-colors">{appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}</p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{song.views?.toLocaleString() || 0} views</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Feedback Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
                    <div className="bg-primary p-8 text-white text-center relative">
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-4 right-6 p-2 rounded-full bg-white/20 hover:bg-white/40 transition-colors"><X className="w-5 h-5"/></button>
                        <Flag className="w-14 h-14 mx-auto mb-4 opacity-80" />
                        <h3 className="text-2xl font-black">Report Issue</h3>
                        <p className="text-sm opacity-80">Help us keep the library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-12 text-center space-y-4">
                            <div className="w-16 h-16 bg-green-100 text-green-500 rounded-full flex items-center justify-center mx-auto shadow-inner"><Check className="w-8 h-8" /></div>
                            <h4 className="text-xl font-bold text-slate-900">Thank You!</h4>
                            <p className="text-slate-500">Your feedback has been submitted successfully.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-8 space-y-6">
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Type of Issue</label>
                                <select 
                                    className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-2xl font-bold text-sm outline-none focus:ring-2 focus:ring-primary/20"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue</option>
                                    <option>Wrong Credits</option>
                                    <option>Missing Video</option>
                                    <option>Typo in Title</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Message Detail</label>
                                <textarea 
                                    required
                                    className="w-full h-32 bg-slate-50 border border-slate-200 p-4 rounded-2xl text-sm outline-none focus:bg-white focus:ring-2 focus:ring-primary/20"
                                    placeholder="Tell us what needs fixing..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-4 rounded-2xl font-black shadow-xl shadow-primary/20 hover:bg-primary/90 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  User, Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Trash2, Save, Printer, Tag, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, Eye, Calendar, ChevronRight, Play, Loader2
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  deleteCustomSong, 
  incrementViewCount, 
  getCategories, 
  getAllCustomSongs, 
  getSongById, 
  submitReport 
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(18);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      composer: '', lyrics_nepali: '', lyrics_roman: '', title: '', artist: '', lyricist: ''
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} - ${artistName} Lyrics | SansarPlus`;

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 4);
          setRelatedSongs(related);
      }

      setEditForm({ ...lyricsResult });
      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${data.title} - ${data.artist} Lyrics`,
      text: `Check out the lyrics for "${data.title}" by ${data.artist} on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 48));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 12));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Failed to submit report.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          await saveCustomSong(editForm.artist || data.artist, editForm.title || data.title, editForm as any);
          setData({ ...data, ...editForm });
          setIsEditing(false);
          alert("Updated successfully!");
      } catch (err: any) {
          alert("Failed to save: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  if (loading) return <Loader fullScreen text="Opening library..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4">
        <Disc className="w-16 h-16 text-slate-200 mb-4" />
        <h2 className="text-2xl font-bold text-slate-400 mb-4">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-6 py-2 rounded-full font-bold shadow-lg">Return Home</Link>
    </div>
  );

  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <div className="max-w-6xl mx-auto px-4 py-8">

        {/* Top Header & Actions */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8 no-print">
            <div className="flex-1 min-w-0">
                <div className="flex items-center gap-3 flex-wrap mb-1">
                    <h1 className="text-3xl md:text-5xl font-black text-slate-900 leading-tight truncate">{displayTitle}</h1>
                    {data.note && data.isNoteVisible !== false && (
                        <span className="bg-amber-100 text-amber-700 px-3 py-1 rounded-full text-xs font-bold border border-amber-200 flex items-center gap-1.5 shadow-sm">
                            <StickyNote className="w-3 h-3" /> {data.note}
                        </span>
                    )}
                </div>
                <div className="flex items-center gap-4 text-slate-500 font-medium">
                    <Link to={`/artist/${encodeURIComponent(data.artist || '')}`} className="hover:text-primary transition-colors flex items-center gap-1.5">
                        <Disc className="w-4 h-4" /> {data.artist}
                    </Link>
                    <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
                    <div className="flex items-center gap-1.5">
                        <Eye className="w-4 h-4" /> {data.views?.toLocaleString() || 0} Views
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-2">
                <button onClick={handleFavorite} className={`p-3 rounded-2xl border transition-all shadow-sm ${isFav ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`} title="Add to Favorites">
                    <Heart className={`w-5 h-5 ${isFav ? 'fill-current' : ''}`} />
                </button>
                <button onClick={handleShare} className="p-3 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-primary shadow-sm hover:border-primary/30 transition-all" title="Share Song">
                    <Share2 className="w-5 h-5" />
                </button>
                <button onClick={handlePrint} className="p-3 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-slate-600 shadow-sm transition-all" title="Print Lyrics">
                    <Printer className="w-5 h-5" />
                </button>
                <button onClick={() => setIsFeedbackOpen(true)} className="p-3 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-red-500 shadow-sm transition-all" title="Report Error">
                    <Flag className="w-5 h-5" />
                </button>
                {canEdit && (
                    <button onClick={() => setIsEditing(!isEditing)} className={`p-3 rounded-2xl transition-all shadow-md ${isEditing ? 'bg-slate-200 text-slate-600' : 'bg-indigo-600 text-white shadow-indigo-200'}`}>
                        {isEditing ? <X className="w-5 h-5" /> : <Edit className="w-5 h-5" />}
                    </button>
                )}
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

            {/* Main Lyrics Area */}
            <div className="lg:col-span-8 space-y-6">

                {isEditing ? (
                    <div className="bg-white rounded-[2rem] p-8 shadow-xl border border-slate-200 space-y-6 animate-in slide-in-from-bottom-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1 ml-1">Title</label>
                                <input className="w-full border p-3 rounded-xl bg-slate-50 outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1 ml-1">Artist</label>
                                <input className="w-full border p-3 rounded-xl bg-slate-50 outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.artist} onChange={e => setEditForm({...editForm, artist: e.target.value})} />
                            </div>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1 ml-1">Native Script Lyrics</label>
                            <textarea className="w-full h-96 border p-4 rounded-xl bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:ring-2 focus:ring-primary/20" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                        </div>
                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-primary/20 hover:bg-primary/90 transition-all flex items-center justify-center">
                            {isSaving ? <Loader2 className="w-5 h-5 animate-spin mr-2"/> : <Save className="w-5 h-5 mr-2" />}
                            Save Changes
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-[2rem] shadow-xl overflow-hidden border border-slate-200">
                        {/* Tabs Navigation */}
                        <div className="flex border-b border-slate-100 bg-slate-50/50 no-print">
                            <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-5 font-bold text-sm uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 ${activeTab === 'nepali' ? 'text-primary border-b-2 border-primary bg-white' : 'text-slate-400 hover:text-slate-600'}`}>
                                <Globe className="w-4 h-4" /> Native
                            </button>
                            <button onClick={() => setActiveTab('roman')} className={`flex-1 py-5 font-bold text-sm uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 ${activeTab === 'roman' ? 'text-primary border-b-2 border-primary bg-white' : 'text-slate-400 hover:text-slate-600'}`}>
                                <Search className="w-4 h-4" /> Romanized
                            </button>
                        </div>

                        <div className="p-8 md:p-14 relative bg-white min-h-[400px]">
                            {/* Zoom/Copy Controls */}
                            <div className="absolute top-4 right-6 flex gap-2 no-print">
                                <button onClick={handleZoomOut} className="p-2 bg-slate-50 text-slate-400 rounded-xl hover:bg-slate-100 transition-colors" title="Zoom Out"><ZoomOut className="w-4 h-4" /></button>
                                <button onClick={handleZoomIn} className="p-2 bg-slate-50 text-slate-400 rounded-xl hover:bg-slate-100 transition-colors" title="Zoom In"><ZoomIn className="w-4 h-4" /></button>
                                <button onClick={handleCopy} className={`p-2 rounded-xl transition-all shadow-sm ${copied ? 'bg-green-500 text-white' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`} title="Copy Lyrics">
                                    {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                                </button>
                            </div>

                            {/* Lyrics Display */}
                            <div 
                                className="whitespace-pre-wrap leading-[1.8] transition-all font-medium text-slate-800" 
                                style={{ fontSize: `${fontSize}px` }}
                            >
                                {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Native lyrics not available.") : (data.lyrics_roman || "Romanized lyrics not available.")}
                            </div>
                        </div>

                        {/* Social Footer */}
                        <div className="bg-slate-50/50 p-6 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-4 no-print">
                            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Powered by SansarPlus Library</p>
                            <div className="flex items-center gap-4">
                                <button onClick={handleShare} className="text-sm font-bold text-primary hover:underline flex items-center gap-1.5">
                                    <Share2 className="w-4 h-4" /> Share with friends
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* Related Content / Categories Section */}
                {!isEditing && data.categories && data.categories.length > 0 && (
                    <div className="flex flex-wrap gap-2 no-print">
                        {data.categories.map(cat => (
                            <Link key={cat} to={`/category/${encodeURIComponent(cat)}`} className="px-4 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-500 hover:border-primary/30 hover:text-primary transition-all shadow-sm flex items-center gap-2">
                                <Tag className="w-3 h-3" /> {cat}
                            </Link>
                        ))}
                    </div>
                )}
            </div>

            {/* Sidebar Details */}
            <div className="lg:col-span-4 space-y-8 no-print">

                {/* YouTube Video Card */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2rem] overflow-hidden shadow-xl border border-slate-200 group">
                        <div className="bg-red-600 p-4 text-white flex items-center justify-between">
                            <h3 className="font-bold text-sm uppercase tracking-wider flex items-center gap-2">
                                <Youtube className="w-5 h-5" /> Official Video
                            </h3>
                            <Play className="w-4 h-4 opacity-50" />
                        </div>
                        <div className="aspect-video">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Song Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* Song Credits Card */}
                <div className="bg-white rounded-[2rem] p-6 shadow-xl border border-slate-200 space-y-6">
                    <h3 className="text-xl font-bold text-slate-900 border-b border-slate-50 pb-4">Song Information</h3>

                    <div className="space-y-4">
                        <div className="flex items-start gap-4">
                            <div className="w-10 h-10 bg-indigo-50 text-indigo-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                <Disc className="w-5 h-5" />
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Artist</p>
                                <p className="text-sm font-bold text-slate-800">{data.artist || 'Unknown'}</p>
                            </div>
                        </div>

                        {(data.composers?.length || data.composer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-purple-50 text-purple-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                    <Music className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Music / Composer</p>
                                    <p className="text-sm font-bold text-slate-800">{data.composers?.join(', ') || data.composer}</p>
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                    <PenTool className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Lyrics / Words</p>
                                    <p className="text-sm font-bold text-slate-800">{data.lyricists?.join(', ') || data.lyricist}</p>
                                </div>
                            </div>
                        )}

                        {(data.singers?.length || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center flex-shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Vocals / Singer</p>
                                    <p className="text-sm font-bold text-slate-800">{data.singers?.join(', ') || data.singer}</p>
                                </div>
                            </div>
                        )}

                        <div className="pt-4 mt-4 border-t border-slate-50 grid grid-cols-2 gap-4">
                            <div className="text-center p-3 bg-slate-50 rounded-2xl">
                                <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Language</p>
                                <p className="text-xs font-bold text-slate-700 capitalize">{data.language || 'Nepali'}</p>
                            </div>
                            <div className="text-center p-3 bg-slate-50 rounded-2xl">
                                <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Views</p>
                                <p className="text-xs font-bold text-slate-700">{data.views?.toLocaleString() || 0}</p>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Related Songs Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-4">
                        <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">
                             More from this Artist <ChevronRight className="w-4 h-4 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-3 bg-white rounded-[1.5rem] border border-slate-200 hover:border-primary/40 hover:shadow-md transition-all group"
                                >
                                    <div className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-400 group-hover:bg-primary group-hover:text-white transition-colors">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-bold text-slate-800 text-sm truncate group-hover:text-primary transition-colors">{appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}</p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{song.views?.toLocaleString() || 0} views</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Feedback Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
                    <div className="bg-primary p-8 text-white text-center relative">
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-4 right-6 p-2 rounded-full bg-white/20 hover:bg-white/40 transition-colors"><X className="w-5 h-5"/></button>
                        <Flag className="w-14 h-14 mx-auto mb-4 opacity-80" />
                        <h3 className="text-2xl font-black">Report Issue</h3>
                        <p className="text-sm opacity-80">Help us keep the library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-12 text-center space-y-4">
                            <div className="w-16 h-16 bg-green-100 text-green-500 rounded-full flex items-center justify-center mx-auto shadow-inner"><Check className="w-8 h-8" /></div>
                            <h4 className="text-xl font-bold text-slate-900">Thank You!</h4>
                            <p className="text-slate-500">Your feedback has been submitted successfully.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-8 space-y-6">
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Type of Issue</label>
                                <select 
                                    className="w-full bg-slate-50 border border-slate-200 p-3.5 rounded-2xl font-bold text-sm outline-none focus:ring-2 focus:ring-primary/20"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue</option>
                                    <option>Wrong Credits</option>
                                    <option>Missing Video</option>
                                    <option>Typo in Title</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Message Detail</label>
                                <textarea 
                                    required
                                    className="w-full h-32 bg-slate-50 border border-slate-200 p-4 rounded-2xl text-sm outline-none focus:bg-white focus:ring-2 focus:ring-primary/20"
                                    placeholder="Tell us what needs fixing..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-4 rounded-2xl font-black shadow-xl shadow-primary/20 hover:bg-primary/90 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  User, Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Trash2, Save, Printer, Tag, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, Eye, Calendar, ChevronRight, Play, Loader2
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  deleteCustomSong, 
  incrementViewCount, 
  getCategories, 
  getAllCustomSongs, 
  getSongById, 
  submitReport 
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(20);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      composer: '', lyrics_nepali: '', lyrics_roman: '', title: '', artist: '', lyricist: ''
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} - ${artistName} Lyrics | SansarPlus`;

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ ...lyricsResult });
      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${data.title} - ${data.artist} Lyrics`,
      text: `Check out the lyrics for "${data.title}" by ${data.artist} on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 60));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 14));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed. Check connection.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          await saveCustomSong(editForm.artist || data.artist, editForm.title || data.title, editForm as any);
          setData({ ...data, ...editForm });
          setIsEditing(false);
          alert("Successfully updated!");
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  if (loading) return <Loader fullScreen text="Opening library..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found in our archive</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-[#f8fafc] pb-32">
      <div className="max-w-6xl mx-auto px-4 py-8 md:py-12">

        {/* Header Actions Area */}
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-8 mb-10 no-print">
            <div className="flex-1 min-w-0">
                <div className="flex items-center gap-3 flex-wrap mb-3">
                    <h1 className="text-4xl md:text-6xl font-black text-slate-900 leading-none tracking-tight">{displayTitle}</h1>
                    {data.note && data.isNoteVisible !== false && (
                        <span className="bg-amber-100 text-amber-700 px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-wider border border-amber-200 flex items-center gap-2 shadow-sm">
                            <StickyNote className="w-3.5 h-3.5" /> {data.note}
                        </span>
                    )}
                </div>
                <div className="flex items-center gap-5 text-slate-500 font-bold text-lg">
                    <Link to={`/artist/${encodeURIComponent(data.artist || '')}`} className="hover:text-primary transition-colors flex items-center gap-2">
                        <Disc className="w-5 h-5 text-primary" /> {data.artist}
                    </Link>
                    <span className="w-1.5 h-1.5 bg-slate-300 rounded-full"></span>
                    <div className="flex items-center gap-2">
                        <Eye className="w-5 h-5" /> {data.views?.toLocaleString() || 0}
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-3 bg-white/80 backdrop-blur-md p-2 rounded-[2rem] border border-slate-200 shadow-xl self-center lg:self-auto">
                <button onClick={handleFavorite} className={`p-4 rounded-2xl border transition-all ${isFav ? 'bg-red-50 text-red-500 border-red-100 shadow-inner' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`} title="Favorite">
                    <Heart className={`w-6 h-6 ${isFav ? 'fill-current' : ''}`} />
                </button>
                <button onClick={handleShare} className="p-4 bg-white border border-slate-100 rounded-2xl text-slate-400 hover:text-primary hover:border-primary/20 transition-all shadow-sm" title="Share">
                    <Share2 className="w-6 h-6" />
                </button>
                <button onClick={handlePrint} className="p-4 bg-white border border-slate-100 rounded-2xl text-slate-400 hover:text-slate-700 hover:border-slate-300 transition-all shadow-sm" title="Print">
                    <Printer className="w-6 h-6" />
                </button>
                <button onClick={() => setIsFeedbackOpen(true)} className="p-4 bg-white border border-slate-100 rounded-2xl text-slate-400 hover:text-red-500 hover:border-red-100 transition-all shadow-sm" title="Report">
                    <Flag className="w-6 h-6" />
                </button>
                {canEdit && (
                    <button onClick={() => setIsEditing(!isEditing)} className={`p-4 rounded-2xl transition-all shadow-lg ${isEditing ? 'bg-slate-200 text-slate-600' : 'bg-indigo-600 text-white shadow-indigo-200'}`}>
                        {isEditing ? <X className="w-6 h-6" /> : <Edit className="w-6 h-6" />}
                    </button>
                )}
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

            {/* Main Lyrics Column */}
            <div className="lg:col-span-8 space-y-8">

                {isEditing ? (
                    <div className="bg-white rounded-[3rem] p-10 shadow-2xl border border-slate-200 space-y-8 animate-in slide-in-from-bottom-8 duration-500">
                        <h2 className="text-2xl font-black text-slate-800 border-b pb-4">Editing Content</h2>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Song Title</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Main Artist</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.artist} onChange={e => setEditForm({...editForm, artist: e.target.value})} />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Lyrics Content (Native)</label>
                            <textarea className="w-full h-[600px] border-2 border-slate-100 p-6 rounded-[2rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                        </div>
                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-xl shadow-2xl shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center transform active:scale-95">
                            {isSaving ? <Loader2 className="w-7 h-7 animate-spin mr-3"/> : <Save className="w-7 h-7 mr-3" />}
                            Publish Updates
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-slate-100 ring-1 ring-slate-200/50">
                        {/* Tab Navigation */}
                        <div className="flex border-b border-slate-100 bg-slate-50/50 no-print">
                            <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'nepali' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Globe className="w-5 h-5" /> Native Script
                            </button>
                            <button onClick={() => setActiveTab('roman')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'roman' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Search className="w-5 h-5" /> Romanized
                            </button>
                        </div>

                        <div className="p-10 md:p-16 relative bg-white min-h-[500px]">
                            {/* Floating Tool Controls */}
                            <div className="absolute top-6 right-8 flex gap-2 no-print opacity-40 hover:opacity-100 transition-opacity">
                                <button onClick={handleZoomOut} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors" title="Shrink Text"><ZoomOut className="w-5 h-5" /></button>
                                <button onClick={handleZoomIn} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors" title="Enlarge Text"><ZoomIn className="w-5 h-5" /></button>
                                <button onClick={handleCopy} className={`p-3 rounded-xl transition-all shadow-sm ${copied ? 'bg-green-500 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`} title="Copy Text">
                                    {copied ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                </button>
                            </div>

                            {/* Lyrics Container */}
                            <div 
                                className="whitespace-pre-wrap leading-[2] transition-all font-medium text-slate-800 tracking-wide selection:bg-primary/10 selection:text-primary" 
                                style={{ fontSize: `${fontSize}px` }}
                            >
                                {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "No native script lyrics found.") : (data.lyrics_roman || "No romanized lyrics found.")}
                            </div>
                        </div>

                        {/* Lyrics Bottom Info */}
                        <div className="bg-slate-50/50 p-8 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-6 no-print">
                            <div className="flex items-center gap-3 text-slate-400">
                                <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center"><Music className="w-4 h-4" /></div>
                                <p className="text-[11px] font-black uppercase tracking-[0.2em]">SansarPlus Digital Library</p>
                            </div>
                            <div className="flex items-center gap-4">
                                <button onClick={handleShare} className="text-sm font-black text-primary hover:underline flex items-center gap-2 group">
                                    <Share2 className="w-5 h-5 group-hover:rotate-12 transition-transform" /> Share this blessing
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* Categories Pills */}
                {!isEditing && data.categories && data.categories.length > 0 && (
                    <div className="flex flex-wrap gap-3 no-print">
                        {data.categories.map(cat => (
                            <Link key={cat} to={`/category/${encodeURIComponent(cat)}`} className="px-6 py-3 bg-white border border-slate-200 rounded-[1.2rem] text-[11px] font-black uppercase tracking-widest text-slate-500 hover:border-primary/40 hover:text-primary hover:shadow-lg transition-all flex items-center gap-2">
                                <Tag className="w-3.5 h-3.5" /> {cat}
                            </Link>
                        ))}
                    </div>
                )}
            </div>

            {/* Sidebar Column */}
            <div className="lg:col-span-4 space-y-10 no-print">

                {/* YouTube Card */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-100 group transition-all hover:shadow-red-200/40">
                        <div className="bg-red-600 p-5 text-white flex items-center justify-between">
                            <h3 className="font-black text-xs uppercase tracking-[0.2em] flex items-center gap-3">
                                <Youtube className="w-6 h-6" /> Watch Official Video
                            </h3>
                            <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
                        </div>
                        <div className="aspect-video relative">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="YouTube Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* Song Credits Card */}
                <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 space-y-8 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50/50 rounded-full -mr-16 -mt-16 blur-3xl opacity-50"></div>
                    <h3 className="text-2xl font-black text-slate-900 border-b border-slate-50 pb-5 tracking-tight flex items-center gap-3">
                        <Disc className="w-7 h-7 text-primary" /> Credits & Info
                    </h3>

                    <div className="space-y-6">
                        <div className="flex items-start gap-5 group">
                            <div className="w-12 h-12 bg-indigo-50 text-indigo-500 rounded-2xl flex items-center justify-center flex-shrink-0 group-hover:bg-indigo-500 group-hover:text-white transition-all shadow-sm">
                                <Disc className="w-6 h-6" />
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Lead Artist</p>
                                <p className="text-md font-black text-slate-800">{data.artist || 'Independent'}</p>
                            </div>
                        </div>

                        {(data.composers?.length || data.composer) && (
                            <div className="flex items-start gap-5 group">
                                <div className="w-12 h-12 bg-purple-50 text-purple-500 rounded-2xl flex items-center justify-center flex-shrink-0 group-hover:bg-purple-500 group-hover:text-white transition-all shadow-sm">
                                    <Music className="w-6 h-6" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Composer / Music</p>
                                    <p className="text-md font-black text-slate-800">{data.composers?.join(', ') || data.composer}</p>
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && (
                            <div className="flex items-start gap-5 group">
                                <div className="w-12 h-12 bg-blue-50 text-blue-500 rounded-2xl flex items-center justify-center flex-shrink-0 group-hover:bg-blue-500 group-hover:text-white transition-all shadow-sm">
                                    <PenTool className="w-6 h-6" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Words / Lyrics</p>
                                    <p className="text-md font-black text-slate-800">{data.lyricists?.join(', ') || data.lyricist}</p>
                                </div>
                            </div>
                        )}

                        {(data.singers?.length || data.singer) && (
                            <div className="flex items-start gap-5 group">
                                <div className="w-12 h-12 bg-pink-50 text-pink-500 rounded-2xl flex items-center justify-center flex-shrink-0 group-hover:bg-pink-500 group-hover:text-white transition-all shadow-sm">
                                    <Mic2 className="w-6 h-6" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Vocals / Performed By</p>
                                    <p className="text-md font-black text-slate-800">{data.singers?.join(', ') || data.singer}</p>
                                </div>
                            </div>
                        )}

                        <div className="pt-6 mt-6 border-t border-slate-50 grid grid-cols-2 gap-4">
                            <div className="bg-slate-50 rounded-3xl p-4 text-center border border-slate-100">
                                <p className="text-[9px] font-black text-slate-400 uppercase mb-1 tracking-widest">Language</p>
                                <p className="text-xs font-black text-slate-700 capitalize">{data.language || 'Nepali'}</p>
                            </div>
                            <div className="bg-slate-50 rounded-3xl p-4 text-center border border-slate-100">
                                <p className="text-[9px] font-black text-slate-400 uppercase mb-1 tracking-widest">Global Views</p>
                                <p className="text-xs font-black text-slate-700">{data.views?.toLocaleString() || 0}</p>
                            </div>
                        </div>
                    </div>
                </div>

                {/* More From Artist */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 px-2">
                             More from {data.artist} <ChevronRight className="w-5 h-5 text-primary" />
                        </h3>
                        <div className="space-y-4">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-5 p-4 bg-white rounded-[2rem] border border-slate-100 hover:border-primary/30 hover:shadow-xl hover:-translate-y-1 transition-all group shadow-sm"
                                >
                                    <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                        <Music className="w-6 h-6" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-sm truncate group-hover:text-primary transition-colors">{appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}</p>
                                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-0.5">{song.views?.toLocaleString() || 0} views</p>
                                    </div>
                                    <ArrowRight className="w-4 h-4 text-slate-200 group-hover:text-primary transition-colors mr-2" />
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Improved Feedback Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/20">
                    <div className="bg-primary p-10 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <Flag className="w-16 h-16 mx-auto mb-5 opacity-80" />
                        <h3 className="text-3xl font-black tracking-tight">Report Issue</h3>
                        <p className="text-sm font-medium opacity-80 mt-2">Help us keep the library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-5">
                            <div className="w-20 h-20 bg-green-100 text-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-10 h-10" /></div>
                            <h4 className="text-2xl font-black text-slate-900">Submitted!</h4>
                            <p className="text-slate-500 font-medium">Thank you for your contribution to the community.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-10 space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Type of Issue</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl font-black text-sm outline-none focus:border-primary transition-all cursor-pointer"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue</option>
                                    <option>Wrong Credits</option>
                                    <option>Missing Video Link</option>
                                    <option>Typo in Title</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Message Detail</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-5 rounded-[1.5rem] text-sm font-medium outline-none focus:bg-white focus:border-primary transition-all resize-none"
                                    placeholder="Please describe the error clearly..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Report'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  User, Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Trash2, Save, Printer, Tag, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, Eye, Calendar, ChevronRight, Play, Loader2
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  deleteCustomSong, 
  incrementViewCount, 
  getCategories, 
  getAllCustomSongs, 
  getSongById, 
  submitReport 
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(22);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      composer: '', lyrics_nepali: '', lyrics_roman: '', title: '', artist: '', lyricist: ''
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} - ${artistName} Lyrics | SansarPlus`;

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ ...lyricsResult });
      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${data.title} - ${data.artist} Lyrics`,
      text: `Check out the lyrics for "${data.title}" by ${data.artist} on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 64));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 14));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed. Check connection.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          await saveCustomSong(editForm.artist || data.artist, editForm.title || data.title, editForm as any);
          setData({ ...data, ...editForm });
          setIsEditing(false);
          alert("Successfully updated!");
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  if (loading) return <Loader fullScreen text="Opening library..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-slate-50 pb-32 selection:bg-primary/10 selection:text-primary">
      {/* Dynamic Background Header */}
      <div className="bg-gradient-to-b from-indigo-50 to-slate-50 pt-12 md:pt-20 pb-12 border-b border-indigo-100/50 no-print">
        <div className="max-w-4xl mx-auto px-4 text-center">
            <div className="flex flex-col items-center gap-4 mb-4">
                {data.note && data.isNoteVisible !== false && (
                    <span className="bg-amber-100 text-amber-700 px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest border border-amber-200 flex items-center gap-2 shadow-sm">
                        <StickyNote className="w-3.5 h-3.5" /> {data.note}
                    </span>
                )}
                <h1 className="text-4xl md:text-6xl font-black text-slate-900 leading-tight tracking-tight drop-shadow-sm">{displayTitle}</h1>
            </div>

            <div className="flex flex-wrap items-center justify-center gap-6 text-slate-500 font-bold text-lg">
                <Link to={`/artist/${encodeURIComponent(data.artist || '')}`} className="hover:text-primary transition-colors flex items-center gap-2">
                    <Disc className="w-5 h-5 text-primary" /> {data.artist}
                </Link>
                <div className="flex items-center gap-2">
                    <Eye className="w-5 h-5 text-indigo-400" /> {data.views?.toLocaleString() || 0} <span className="text-xs font-black uppercase tracking-widest text-slate-300">Views</span>
                </div>
            </div>

            <div className="flex items-center justify-center gap-3 mt-10">
                <button onClick={handleFavorite} className={`p-4 rounded-2xl border transition-all ${isFav ? 'bg-red-50 text-red-500 border-red-100 shadow-md' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300 hover:text-slate-600 shadow-sm'}`} title="Add to Favorites">
                    <Heart className={`w-6 h-6 ${isFav ? 'fill-current' : ''}`} />
                </button>
                <button onClick={handleShare} className="p-4 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-primary hover:border-primary/20 transition-all shadow-sm" title="Share Song">
                    <Share2 className="w-6 h-6" />
                </button>
                <button onClick={handlePrint} className="p-4 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-slate-700 hover:border-slate-300 transition-all shadow-sm" title="Print Chords & Lyrics">
                    <Printer className="w-6 h-6" />
                </button>
                <button onClick={() => setIsFeedbackOpen(true)} className="p-4 bg-white border border-slate-200 rounded-2xl text-slate-400 hover:text-red-500 hover:border-red-100 transition-all shadow-sm" title="Report Issue">
                    <Flag className="w-6 h-6" />
                </button>
                {canEdit && (
                    <button onClick={() => setIsEditing(!isEditing)} className={`p-4 rounded-2xl transition-all shadow-lg ${isEditing ? 'bg-slate-200 text-slate-600' : 'bg-indigo-600 text-white shadow-indigo-200 hover:bg-indigo-700'}`}>
                        {isEditing ? <X className="w-6 h-6" /> : <Edit className="w-6 h-6" />}
                    </button>
                )}
            </div>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 py-12">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* Main Content: Lyrics Section */}
            <div className="lg:col-span-8 space-y-8">

                {isEditing ? (
                    <div className="bg-white rounded-[3rem] p-8 md:p-12 shadow-2xl border border-slate-200 space-y-8 animate-in slide-in-from-bottom-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Romanized Title</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Lead Artist</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.artist} onChange={e => setEditForm({...editForm, artist: e.target.value})} />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Lyrics Content (Native Script)</label>
                            <textarea className="w-full h-[600px] border-2 border-slate-100 p-6 rounded-[2rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                        </div>
                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-xl shadow-2xl shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center transform active:scale-95">
                            {isSaving ? <Loader2 className="w-7 h-7 animate-spin mr-3"/> : <Save className="w-7 h-7 mr-3" />}
                            Save & Sync Updates
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-slate-100 ring-1 ring-slate-200/50">
                        {/* Tab Switcher */}
                        <div className="flex border-b border-slate-100 bg-slate-50/50 no-print">
                            <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'nepali' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Globe className="w-5 h-5" /> Native
                            </button>
                            <button onClick={() => setActiveTab('roman')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'roman' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Search className="w-5 h-5" /> Romanized
                            </button>
                        </div>

                        <div className="p-10 md:p-20 relative bg-white min-h-[600px]">
                            {/* Centered Controls Overlay */}
                            <div className="absolute top-6 right-8 flex gap-2 no-print opacity-20 hover:opacity-100 transition-opacity">
                                <button onClick={handleZoomOut} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomOut className="w-5 h-5" /></button>
                                <button onClick={handleZoomIn} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomIn className="w-5 h-5" /></button>
                                <button onClick={handleCopy} className={`p-3 rounded-xl transition-all shadow-sm ${copied ? 'bg-green-500 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                                    {copied ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                </button>
                            </div>

                            {/* Centered Lyrics Container */}
                            <div 
                                className="whitespace-pre-wrap leading-[2.2] transition-all font-medium text-slate-800 tracking-wide text-center selection:bg-indigo-100" 
                                style={{ fontSize: `${fontSize}px` }}
                            >
                                {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Native lyrics not available.") : (data.lyrics_roman || "Romanized lyrics not available.")}
                            </div>
                        </div>

                        {/* Branding Footer */}
                        <div className="bg-slate-900/5 p-8 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-6 no-print">
                            <div className="flex items-center gap-3 text-slate-400">
                                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center"><Music className="w-5 h-5 text-indigo-400" /></div>
                                <p className="text-[11px] font-black uppercase tracking-[0.2em]">SansarPlus Verified Library</p>
                            </div>
                            <button onClick={handleShare} className="text-sm font-black text-primary hover:underline flex items-center gap-2 group">
                                <Share2 className="w-5 h-5 group-hover:scale-110 transition-transform" /> Invite others to worship
                            </button>
                        </div>
                    </div>
                )}

                {/* Genres/Categories */}
                {!isEditing && data.categories && data.categories.length > 0 && (
                    <div className="flex flex-wrap gap-2.5 no-print">
                        {data.categories.map(cat => (
                            <Link key={cat} to={`/category/${encodeURIComponent(cat)}`} className="px-5 py-2.5 bg-white border border-slate-200 rounded-2xl text-[11px] font-black uppercase tracking-widest text-slate-500 hover:border-primary/40 hover:text-primary transition-all flex items-center gap-2 shadow-sm">
                                <Tag className="w-3.5 h-3.5" /> {cat}
                            </Link>
                        ))}
                    </div>
                )}
            </div>

            {/* Sidebar Columns */}
            <div className="lg:col-span-4 space-y-10 no-print">

                {/* Official Video Player */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-100 group">
                        <div className="bg-red-600 px-6 py-4 text-white flex items-center justify-between">
                            <h3 className="font-black text-xs uppercase tracking-widest flex items-center gap-3">
                                <Youtube className="w-6 h-6" /> YouTube Video
                            </h3>
                            <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
                        </div>
                        <div className="aspect-video relative">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Music Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* Metadata Card */}
                <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 space-y-8 relative overflow-hidden">
                    <h3 className="text-2xl font-black text-slate-900 border-b border-slate-50 pb-5 tracking-tight flex items-center gap-3">
                        <Disc className="w-7 h-7 text-primary" /> Song Information
                    </h3>

                    <div className="space-y-6">
                        <div className="flex items-start gap-4">
                            <div className="w-10 h-10 bg-indigo-50 text-indigo-500 rounded-xl flex items-center justify-center shrink-0">
                                <Disc className="w-5 h-5" />
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Lead Artist</p>
                                <p className="text-sm font-bold text-slate-800">{data.artist || 'Independent'}</p>
                            </div>
                        </div>

                        {(data.composers?.length || data.composer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-purple-50 text-purple-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Music className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Composition</p>
                                    <p className="text-sm font-bold text-slate-800">{data.composers?.join(', ') || data.composer}</p>
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center shrink-0">
                                    <PenTool className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Words / Lyrics</p>
                                    <p className="text-sm font-bold text-slate-800">{data.lyricists?.join(', ') || data.lyricist}</p>
                                </div>
                            </div>
                        )}

                        {(data.singers?.length || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Vocals By</p>
                                    <p className="text-sm font-bold text-slate-800">{data.singers?.join(', ') || data.singer}</p>
                                </div>
                            </div>
                        )}

                        <div className="pt-6 border-t border-slate-50 grid grid-cols-2 gap-4">
                            <div className="bg-slate-50 rounded-2xl p-4 text-center">
                                <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Origin</p>
                                <p className="text-xs font-black text-slate-700 capitalize">{data.language || 'Nepali'}</p>
                            </div>
                            <div className="bg-slate-50 rounded-2xl p-4 text-center">
                                <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Archive</p>
                                <p className="text-xs font-black text-slate-700">SP-{data.id || 'N/A'}</p>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Related Artists Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 px-2">
                             More from {data.artist} <ChevronRight className="w-5 h-5 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-4 bg-white rounded-3xl border border-slate-100 hover:border-primary/30 hover:shadow-xl transition-all group shadow-sm"
                                >
                                    <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-sm truncate group-hover:text-primary transition-colors">{appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}</p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{song.views?.toLocaleString() || 0} views</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Feedback/Report Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/10">
                    <div className="bg-primary p-10 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <Flag className="w-16 h-16 mx-auto mb-5 opacity-80" />
                        <h3 className="text-3xl font-black tracking-tight">Report Error</h3>
                        <p className="text-sm font-medium opacity-80 mt-2">Help keep our library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-5">
                            <div className="w-20 h-20 bg-green-100 text-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-10 h-10" /></div>
                            <h4 className="text-2xl font-black text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 font-medium">Your report has been received and will be reviewed by our team.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-10 space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Category of issue</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl font-black text-sm outline-none focus:border-primary transition-all cursor-pointer"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue (Typo/Error)</option>
                                    <option>Wrong Credits (Artist/Music)</option>
                                    <option>Video Link broken or missing</option>
                                    <option>Missing Verse/Stanza</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Issue Description</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-5 rounded-[1.5rem] text-sm font-medium outline-none focus:bg-white focus:border-primary transition-all resize-none"
                                    placeholder="Please provide details..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Save, Printer, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, ChevronRight, Play, Loader2
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  incrementViewCount, 
  getAllCustomSongs, 
  getSongById, 
  submitReport 
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(24);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      composer: '', lyrics_nepali: '', lyrics_roman: '', title: '', artist: '', lyricist: ''
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} Lyrics | SansarPlus`;

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ ...lyricsResult });
      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${data.title} Lyrics`,
      text: `Check out the lyrics for "${data.title}" on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 72));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 14));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          await saveCustomSong(editForm.artist || data.artist, editForm.title || data.title, editForm as any);
          setData({ ...data, ...editForm });
          setIsEditing(false);
          alert("Updated successfully!");
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-white pb-32 selection:bg-primary/10 selection:text-primary">
      {/* Centered Header: Pure Title & Notes Only */}
      <div className="pt-16 pb-12 no-print">
        <div className="max-w-4xl mx-auto px-4 text-center">
            <div className="flex flex-col items-center gap-4">
                {data.note && data.isNoteVisible !== false && (
                    <span className="bg-amber-50 text-amber-600 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-amber-100 flex items-center gap-2">
                        <StickyNote className="w-3.5 h-3.5" /> {data.note}
                    </span>
                )}
                <h1 className="text-4xl md:text-6xl font-black text-slate-900 leading-tight tracking-tight">{displayTitle}</h1>
            </div>

            {/* Admin Edit Trigger (Always Floating/Top Right for Admin) */}
            {canEdit && (
                <div className="fixed top-20 right-6 z-30">
                    <button onClick={() => setIsEditing(!isEditing)} className={`p-4 rounded-2xl transition-all shadow-xl border ${isEditing ? 'bg-slate-100 text-slate-600 border-slate-200' : 'bg-indigo-600 text-white border-indigo-500 shadow-indigo-200 hover:bg-indigo-700'}`}>
                        {isEditing ? <X className="w-6 h-6" /> : <Edit className="w-6 h-6" />}
                    </button>
                </div>
            )}
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* Main Content: Lyrics Section (Centered Content) */}
            <div className="lg:col-span-8 space-y-10">

                {isEditing ? (
                    <div className="bg-white rounded-[3rem] p-8 md:p-12 shadow-2xl border border-slate-200 space-y-8 animate-in slide-in-from-bottom-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Romanized Title</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Artist Name</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.artist} onChange={e => setEditForm({...editForm, artist: e.target.value})} />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Lyrics Content (Native Script)</label>
                            <textarea className="w-full h-[600px] border-2 border-slate-100 p-6 rounded-[2rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                        </div>
                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-xl shadow-2xl shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center transform active:scale-95">
                            {isSaving ? <Loader2 className="w-7 h-7 animate-spin mr-3"/> : <Save className="w-7 h-7 mr-3" />}
                            Save & Sync Updates
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-slate-100 ring-1 ring-slate-200/50">
                        {/* Renamed Tab Switcher */}
                        <div className="flex border-b border-slate-100 bg-slate-50/50 no-print">
                            <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'nepali' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Globe className="w-5 h-5" /> Nepali
                            </button>
                            <button onClick={() => setActiveTab('roman')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'roman' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Search className="w-5 h-5" /> Roman Nepali
                            </button>
                        </div>

                        <div className="p-10 md:p-20 relative bg-white min-h-[600px]">
                            {/* Floating Zoom Controls */}
                            <div className="absolute top-6 right-8 flex gap-2 no-print opacity-20 hover:opacity-100 transition-opacity">
                                <button onClick={handleZoomOut} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomOut className="w-5 h-5" /></button>
                                <button onClick={handleZoomIn} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomIn className="w-5 h-5" /></button>
                                <button onClick={handleCopy} className={`p-3 rounded-xl transition-all shadow-sm ${copied ? 'bg-green-500 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                                    {copied ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                </button>
                            </div>

                            {/* Centered Lyrics Text */}
                            <div 
                                className="whitespace-pre-wrap leading-[2.2] transition-all font-medium text-slate-800 tracking-wide text-center selection:bg-indigo-100" 
                                style={{ fontSize: `${fontSize}px` }}
                            >
                                {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Lyrics not available in Nepali.") : (data.lyrics_roman || "Lyrics not available in Roman Nepali.")}
                            </div>

                            {/* Moved Tools Strip: Below Lyrics */}
                            <div className="flex items-center justify-center gap-4 mt-16 pt-10 border-t border-slate-50 no-print">
                                <button onClick={handleFavorite} className={`p-4 rounded-2xl border transition-all ${isFav ? 'bg-red-50 text-red-500 border-red-100 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-200 hover:border-slate-300 shadow-sm'}`} title="Add to Favorites">
                                    <Heart className={`w-6 h-6 ${isFav ? 'fill-current' : ''}`} />
                                </button>
                                <button onClick={handleShare} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-primary transition-all shadow-sm" title="Share Song">
                                    <Share2 className="w-6 h-6" />
                                </button>
                                <button onClick={handlePrint} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-slate-700 transition-all shadow-sm" title="Print Lyrics">
                                    <Printer className="w-6 h-6" />
                                </button>
                                <button onClick={() => setIsFeedbackOpen(true)} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-red-500 transition-all shadow-sm" title="Report Issue">
                                    <Flag className="w-6 h-6" />
                                </button>
                            </div>
                        </div>

                        {/* Branding Footer */}
                        <div className="bg-slate-900/5 p-8 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-6 no-print">
                            <div className="flex items-center gap-3 text-slate-400">
                                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center"><Music className="w-5 h-5 text-indigo-400" /></div>
                                <p className="text-[11px] font-black uppercase tracking-[0.2em]">SansarPlus Verified Library</p>
                            </div>
                            <p className="text-[11px] font-black text-slate-300 uppercase tracking-widest">Worship with us globally</p>
                        </div>
                    </div>
                )}
            </div>

            {/* Sidebar Columns */}
            <div className="lg:col-span-4 space-y-10 no-print">

                {/* Official Video Player */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-100 group">
                        <div className="bg-red-600 px-6 py-4 text-white flex items-center justify-between">
                            <h3 className="font-black text-xs uppercase tracking-widest flex items-center gap-3">
                                <Youtube className="w-6 h-6" /> Official Video
                            </h3>
                            <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
                        </div>
                        <div className="aspect-video relative">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Song Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* Song Credits Card (Cleaned Version) */}
                <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 space-y-8 relative overflow-hidden">
                    <h3 className="text-2xl font-black text-slate-900 border-b border-slate-50 pb-5 tracking-tight flex items-center gap-3">
                        <Disc className="w-7 h-7 text-primary" /> Credits & Info
                    </h3>

                    <div className="space-y-6">
                        <div className="flex items-start gap-4">
                            <div className="w-10 h-10 bg-indigo-50 text-indigo-500 rounded-xl flex items-center justify-center shrink-0">
                                <Disc className="w-5 h-5" />
                            </div>
                            <div>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Lead Artist</p>
                                <Link to={`/artist/${encodeURIComponent(data.artist || '')}`} className="text-sm font-bold text-slate-800 hover:text-primary transition-colors">{data.artist || 'Independent'}</Link>
                            </div>
                        </div>

                        {(data.composers?.length || data.composer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-purple-50 text-purple-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Music className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Composition</p>
                                    <p className="text-sm font-bold text-slate-800">{data.composers?.join(', ') || data.composer}</p>
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center shrink-0">
                                    <PenTool className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Words / Lyrics</p>
                                    <p className="text-sm font-bold text-slate-800">{data.lyricists?.join(', ') || data.lyricist}</p>
                                </div>
                            </div>
                        )}

                        {(data.singers?.length || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Vocals By</p>
                                    <p className="text-sm font-bold text-slate-800">{data.singers?.join(', ') || data.singer}</p>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                {/* More From Artist Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 px-2">
                             More tracks <ChevronRight className="w-5 h-5 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-4 bg-white rounded-3xl border border-slate-100 hover:border-primary/30 hover:shadow-xl transition-all group shadow-sm"
                                >
                                    <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-sm truncate group-hover:text-primary transition-colors">{appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}</p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">View Lyrics</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Report Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/10">
                    <div className="bg-primary p-10 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <Flag className="w-16 h-16 mx-auto mb-5 opacity-80" />
                        <h3 className="text-3xl font-black tracking-tight">Report Error</h3>
                        <p className="text-sm font-medium opacity-80 mt-2">Help keep our library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-5">
                            <div className="w-20 h-20 bg-green-100 text-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-10 h-10" /></div>
                            <h4 className="text-2xl font-black text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 font-medium">Your report has been received.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-10 space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Category of issue</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl font-black text-sm outline-none focus:border-primary cursor-pointer"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue (Typo/Error)</option>
                                    <option>Wrong Credits</option>
                                    <option>Video Link broken</option>
                                    <option>Missing Verse</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Details</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-5 rounded-[1.5rem] text-sm font-medium outline-none focus:bg-white focus:border-primary transition-all resize-none"
                                    placeholder="Describe the problem..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Save, Printer, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, ChevronRight, Play, Loader2
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  incrementViewCount, 
  getAllCustomSongs, 
  getSongById, 
  submitReport 
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(24);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      composer: '', lyrics_nepali: '', lyrics_roman: '', title: '', artist: '', lyricist: ''
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} Lyrics | SansarPlus`;

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ ...lyricsResult });
      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${data.title} Lyrics`,
      text: `Check out the lyrics for "${data.title}" on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 72));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 14));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          await saveCustomSong(editForm.artist || data.artist, editForm.title || data.title, editForm as any);
          setData({ ...data, ...editForm });
          setIsEditing(false);
          alert("Updated successfully!");
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  const renderContributorLinks = (names: string[] | string | undefined) => {
      if (!names) return null;
      const nameList = Array.isArray(names) ? names : names.split(',').map(s => s.trim()).filter(s => s);
      return (
          <span className="text-sm font-bold text-slate-800">
              {nameList.map((name, i) => (
                  <React.Fragment key={name}>
                      <Link 
                        to={`/artist/${encodeURIComponent(name)}`} 
                        className="hover:text-primary transition-colors underline decoration-slate-200 underline-offset-4 hover:decoration-primary"
                      >
                        {name}
                      </Link>
                      {i < nameList.length - 1 ? ', ' : ''}
                  </React.Fragment>
              ))}
          </span>
      );
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  // Sync title with active language tab
  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-white pb-32 selection:bg-primary/10 selection:text-primary">
      {/* Centered Header: Pure Title & Notes Only */}
      <div className="pt-16 pb-12 no-print">
        <div className="max-w-4xl mx-auto px-4 text-center">
            <div className="flex flex-col items-center gap-4">
                {data.note && data.isNoteVisible !== false && (
                    <span className="bg-amber-50 text-amber-600 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-amber-100 flex items-center gap-2">
                        <StickyNote className="w-3.5 h-3.5" /> {data.note}
                    </span>
                )}
                {/* Reduced font size slightly from 4xl/6xl to 3xl/5xl */}
                <h1 className="text-3xl md:text-5xl font-black text-slate-900 leading-tight tracking-tight">{displayTitle}</h1>
            </div>

            {/* Admin Edit Trigger */}
            {canEdit && (
                <div className="fixed top-20 right-6 z-30">
                    <button onClick={() => setIsEditing(!isEditing)} className={`p-4 rounded-2xl transition-all shadow-xl border ${isEditing ? 'bg-slate-100 text-slate-600 border-slate-200' : 'bg-indigo-600 text-white border-indigo-500 shadow-indigo-200 hover:bg-indigo-700'}`}>
                        {isEditing ? <X className="w-6 h-6" /> : <Edit className="w-6 h-6" />}
                    </button>
                </div>
            )}
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* Main Content: Lyrics Section */}
            <div className="lg:col-span-8 space-y-10">

                {isEditing ? (
                    <div className="bg-white rounded-[3rem] p-8 md:p-12 shadow-2xl border border-slate-200 space-y-8 animate-in slide-in-from-bottom-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Romanized Title</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Artist Name</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.artist} onChange={e => setEditForm({...editForm, artist: e.target.value})} />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Lyrics Content (Native Script)</label>
                            <textarea className="w-full h-[600px] border-2 border-slate-100 p-6 rounded-[2rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                        </div>
                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-xl shadow-2xl shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center transform active:scale-95">
                            {isSaving ? <Loader2 className="w-7 h-7 animate-spin mr-3"/> : <Save className="w-7 h-7 mr-3" />}
                            Save & Sync Updates
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-slate-100 ring-1 ring-slate-200/50">
                        {/* Renamed Tab Switcher */}
                        <div className="flex border-b border-slate-100 bg-slate-50/50 no-print">
                            <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'nepali' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Globe className="w-5 h-5" /> Nepali
                            </button>
                            <button onClick={() => setActiveTab('roman')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'roman' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Search className="w-5 h-5" /> Roman Nepali
                            </button>
                        </div>

                        <div className="p-10 md:p-20 relative bg-white min-h-[600px]">
                            {/* Floating Zoom Controls */}
                            <div className="absolute top-6 right-8 flex gap-2 no-print opacity-20 hover:opacity-100 transition-opacity">
                                <button onClick={handleZoomOut} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomOut className="w-5 h-5" /></button>
                                <button onClick={handleZoomIn} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomIn className="w-5 h-5" /></button>
                                <button onClick={handleCopy} className={`p-3 rounded-xl transition-all shadow-sm ${copied ? 'bg-green-500 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                                    {copied ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                </button>
                            </div>

                            {/* Centered Lyrics Text */}
                            <div 
                                className="whitespace-pre-wrap leading-[2.2] transition-all font-medium text-slate-800 tracking-wide text-center selection:bg-indigo-100" 
                                style={{ fontSize: `${fontSize}px` }}
                            >
                                {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Lyrics not available in Nepali.") : (data.lyrics_roman || "Lyrics not available in Roman Nepali.")}
                            </div>

                            {/* Moved Tools Strip: Below Lyrics */}
                            <div className="flex items-center justify-center gap-4 mt-16 pt-10 border-t border-slate-50 no-print">
                                <button onClick={handleFavorite} className={`p-4 rounded-2xl border transition-all ${isFav ? 'bg-red-50 text-red-500 border-red-100 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-200 hover:border-slate-300 shadow-sm'}`} title="Add to Favorites">
                                    <Heart className={`w-6 h-6 ${isFav ? 'fill-current' : ''}`} />
                                </button>
                                <button onClick={handleShare} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-primary transition-all shadow-sm" title="Share Song">
                                    <Share2 className="w-6 h-6" />
                                </button>
                                <button onClick={handlePrint} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-slate-700 transition-all shadow-sm" title="Print Lyrics">
                                    <Printer className="w-6 h-6" />
                                </button>
                                <button onClick={() => setIsFeedbackOpen(true)} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-red-500 transition-all shadow-sm" title="Report Issue">
                                    <Flag className="w-6 h-6" />
                                </button>
                            </div>
                        </div>

                        {/* Branding Footer */}
                        <div className="bg-slate-900/5 p-8 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-6 no-print">
                            <div className="flex items-center gap-3 text-slate-400">
                                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center"><Music className="w-5 h-5 text-indigo-400" /></div>
                                <p className="text-[11px] font-black uppercase tracking-[0.2em]">SansarPlus Verified Library</p>
                            </div>
                            <p className="text-[11px] font-black text-slate-300 uppercase tracking-widest">Worship with us globally</p>
                        </div>
                    </div>
                )}
            </div>

            {/* Sidebar Column */}
            <div className="lg:col-span-4 space-y-10 no-print">

                {/* Song Credits Card (Lead Artist Hidden from here too) */}
                <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 space-y-8 relative overflow-hidden">
                    <h3 className="text-2xl font-black text-slate-900 border-b border-slate-50 pb-5 tracking-tight flex items-center gap-3">
                        <Disc className="w-7 h-7 text-primary" /> Credits & Info
                    </h3>

                    <div className="space-y-6">
                        {(data.composers?.length || data.composer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-purple-50 text-purple-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Music className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Composition</p>
                                    {renderContributorLinks(data.composers || data.composer)}
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center shrink-0">
                                    <PenTool className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Words / Lyrics</p>
                                    {renderContributorLinks(data.lyricists || data.lyricist)}
                                </div>
                            </div>
                        )}

                        {(data.singers?.length || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Vocals By</p>
                                    {renderContributorLinks(data.singers || data.singer)}
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                {/* Official Video Player: Now BELOW Credits Card */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-100 group">
                        <div className="bg-red-600 px-6 py-4 text-white flex items-center justify-between">
                            <h3 className="font-black text-xs uppercase tracking-widest flex items-center gap-3">
                                <Youtube className="w-6 h-6" /> Official Video
                            </h3>
                            <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
                        </div>
                        <div className="aspect-video relative">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Song Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* More Tracks Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 px-2">
                             More tracks <ChevronRight className="w-5 h-5 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-4 bg-white rounded-3xl border border-slate-100 hover:border-primary/30 hover:shadow-xl transition-all group shadow-sm"
                                >
                                    <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-sm truncate group-hover:text-primary transition-colors">
                                            {appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}
                                        </p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">View Lyrics</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Report Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/10">
                    <div className="bg-primary p-10 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <Flag className="w-16 h-16 mx-auto mb-5 opacity-80" />
                        <h3 className="text-3xl font-black tracking-tight">Report Error</h3>
                        <p className="text-sm font-medium opacity-80 mt-2">Help keep our library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-5">
                            <div className="w-20 h-20 bg-green-100 text-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-10 h-10" /></div>
                            <h4 className="text-2xl font-black text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 font-medium">Your report has been received.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-10 space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Category of issue</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl font-black text-sm outline-none focus:border-primary cursor-pointer"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue (Typo/Error)</option>
                                    <option>Wrong Credits</option>
                                    <option>Video Link broken</option>
                                    <option>Missing Verse</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Details</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-5 rounded-[1.5rem] text-sm font-medium outline-none focus:bg-white focus:border-primary transition-all resize-none"
                                    placeholder="Describe the problem..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Save, Printer, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, ChevronRight, Play, Loader2
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  incrementViewCount, 
  getAllCustomSongs, 
  getSongById, 
  submitReport 
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(24);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      composer: '', lyrics_nepali: '', lyrics_roman: '', title: '', artist: '', lyricist: ''
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} Lyrics | SansarPlus`;

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ ...lyricsResult });
      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${activeTab === 'nepali' ? data.title_nepali || data.title : data.title} Lyrics`,
      text: `Check out the lyrics for "${activeTab === 'nepali' ? data.title_nepali || data.title : data.title}" on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 72));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 14));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          await saveCustomSong(editForm.artist || data.artist, editForm.title || data.title, editForm as any);
          setData({ ...data, ...editForm });
          setIsEditing(false);
          alert("Updated successfully!");
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  const renderContributorLinks = (names: string[] | string | undefined) => {
      if (!names) return null;
      const nameList = (Array.isArray(names) ? names : names.split(','))
        .map(s => s.trim())
        .filter(s => s && s.toLowerCase() !== 'unknown');

      if (nameList.length === 0) return null;

      return (
          <span className="text-sm font-bold text-slate-800">
              {nameList.map((name, i) => (
                  <React.Fragment key={name}>
                      <Link 
                        to={`/artist/${encodeURIComponent(name)}`} 
                        className="hover:text-primary transition-colors underline decoration-slate-200 underline-offset-4 hover:decoration-primary"
                      >
                        {name}
                      </Link>
                      {i < nameList.length - 1 ? ', ' : ''}
                  </React.Fragment>
              ))}
          </span>
      );
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  // Sync title with active language tab
  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-white pb-32 selection:bg-primary/10 selection:text-primary">
      {/* Centered Header: Pure Title & Notes Only */}
      <div className="pt-16 pb-12 no-print">
        <div className="max-w-4xl mx-auto px-4 text-center">
            <div className="flex flex-col items-center gap-4">
                {data.note && data.isNoteVisible !== false && (
                    <span className="bg-amber-50 text-amber-600 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-amber-100 flex items-center gap-2">
                        <StickyNote className="w-3.5 h-3.5" /> {data.note}
                    </span>
                )}
                {/* Even smaller title font size for a cleaner look */}
                <h1 className="text-2xl md:text-4xl font-black text-slate-900 leading-tight tracking-tight">{displayTitle}</h1>
            </div>

            {/* Admin Edit Trigger */}
            {canEdit && (
                <div className="fixed top-20 right-6 z-30">
                    <button onClick={() => setIsEditing(!isEditing)} className={`p-4 rounded-2xl transition-all shadow-xl border ${isEditing ? 'bg-slate-100 text-slate-600 border-slate-200' : 'bg-indigo-600 text-white border-indigo-500 shadow-indigo-200 hover:bg-indigo-700'}`}>
                        {isEditing ? <X className="w-6 h-6" /> : <Edit className="w-6 h-6" />}
                    </button>
                </div>
            )}
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* Main Content: Lyrics Section (Centered Text) */}
            <div className="lg:col-span-8 space-y-10">

                {isEditing ? (
                    <div className="bg-white rounded-[3rem] p-8 md:p-12 shadow-2xl border border-slate-200 space-y-8 animate-in slide-in-from-bottom-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Romanized Title</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Artist Name</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.artist} onChange={e => setEditForm({...editForm, artist: e.target.value})} />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Lyrics Content (Nepali Script)</label>
                            <textarea className="w-full h-[600px] border-2 border-slate-100 p-6 rounded-[2rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                        </div>
                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-xl shadow-2xl shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center transform active:scale-95">
                            {isSaving ? <Loader2 className="w-7 h-7 animate-spin mr-3"/> : <Save className="w-7 h-7 mr-3" />}
                            Save & Sync Updates
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-slate-100 ring-1 ring-slate-200/50">
                        {/* Tab Switcher */}
                        <div className="flex border-b border-slate-100 bg-slate-50/50 no-print">
                            <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'nepali' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Globe className="w-5 h-5" /> Nepali
                            </button>
                            <button onClick={() => setActiveTab('roman')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'roman' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Search className="w-5 h-5" /> Roman Nepali
                            </button>
                        </div>

                        <div className="p-10 md:p-20 relative bg-white min-h-[600px]">
                            {/* Floating Zoom Controls */}
                            <div className="absolute top-6 right-8 flex gap-2 no-print opacity-20 hover:opacity-100 transition-opacity">
                                <button onClick={handleZoomOut} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomOut className="w-5 h-5" /></button>
                                <button onClick={handleZoomIn} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomIn className="w-5 h-5" /></button>
                                <button onClick={handleCopy} className={`p-3 rounded-xl transition-all shadow-sm ${copied ? 'bg-green-500 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                                    {copied ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                </button>
                            </div>

                            {/* Centered Lyrics Text */}
                            <div 
                                className="whitespace-pre-wrap leading-[2.2] transition-all font-medium text-slate-800 tracking-wide text-center selection:bg-indigo-100" 
                                style={{ fontSize: `${fontSize}px` }}
                            >
                                {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Lyrics not available in Nepali.") : (data.lyrics_roman || "Lyrics not available in Roman Nepali.")}
                            </div>

                            {/* Moved Tools Strip: Below Lyrics */}
                            <div className="flex items-center justify-center gap-4 mt-16 pt-10 border-t border-slate-50 no-print">
                                <button onClick={handleFavorite} className={`p-4 rounded-2xl border transition-all ${isFav ? 'bg-red-50 text-red-500 border-red-100 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-200 hover:border-slate-300 shadow-sm'}`} title="Add to Favorites">
                                    <Heart className={`w-6 h-6 ${isFav ? 'fill-current' : ''}`} />
                                </button>
                                <button onClick={handleShare} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-primary transition-all shadow-sm" title="Share Song">
                                    <Share2 className="w-6 h-6" />
                                </button>
                                <button onClick={handlePrint} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-slate-700 transition-all shadow-sm" title="Print Lyrics">
                                    <Printer className="w-6 h-6" />
                                </button>
                                <button onClick={() => setIsFeedbackOpen(true)} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-red-500 transition-all shadow-sm" title="Report Issue">
                                    <Flag className="w-6 h-6" />
                                </button>
                            </div>
                        </div>

                        {/* Branding Footer */}
                        <div className="bg-slate-900/5 p-8 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-6 no-print">
                            <div className="flex items-center gap-3 text-slate-400">
                                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center"><Music className="w-5 h-5 text-indigo-400" /></div>
                                <p className="text-[11px] font-black uppercase tracking-[0.2em]">SansarPlus Verified Library</p>
                            </div>
                            <p className="text-[11px] font-black text-slate-300 uppercase tracking-widest">Worship with us globally</p>
                        </div>
                    </div>
                )}
            </div>

            {/* Sidebar Column */}
            <div className="lg:col-span-4 space-y-10 no-print">

                {/* Song Credits Card */}
                <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 space-y-8 relative overflow-hidden">
                    <h3 className="text-2xl font-black text-slate-900 border-b border-slate-50 pb-5 tracking-tight flex items-center gap-3">
                        <Disc className="w-7 h-7 text-primary" /> Credits & Info
                    </h3>

                    <div className="space-y-6">
                        {/* Lead Artist hidden from credits as requested */}

                        {(data.composers?.length || data.composer) && renderContributorLinks(data.composers || data.composer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-purple-50 text-purple-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Music className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Composition</p>
                                    {renderContributorLinks(data.composers || data.composer)}
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && renderContributorLinks(data.lyricists || data.lyricist) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center shrink-0">
                                    <PenTool className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Words / Lyrics</p>
                                    {renderContributorLinks(data.lyricists || data.lyricist)}
                                </div>
                            </div>
                        )}

                        {(data.singers?.length || data.singer) && renderContributorLinks(data.singers || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Vocals By</p>
                                    {renderContributorLinks(data.singers || data.singer)}
                                </div>
                            </div>
                        )}

                        {/* Fallback if no specific credits exist */}
                        {!(renderContributorLinks(data.composers || data.composer) || 
                           renderContributorLinks(data.lyricists || data.lyricist) || 
                           renderContributorLinks(data.singers || data.singer)) && (
                            <p className="text-xs text-slate-400 italic">No detailed credits available.</p>
                        )}
                    </div>
                </div>

                {/* Official Video Player: Now BELOW Credits Card */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-100 group">
                        <div className="bg-red-600 px-6 py-4 text-white flex items-center justify-between">
                            <h3 className="font-black text-xs uppercase tracking-widest flex items-center gap-3">
                                <Youtube className="w-6 h-6" /> Official Video
                            </h3>
                            <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
                        </div>
                        <div className="aspect-video relative">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Song Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* More Tracks Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 px-2">
                             More tracks <ChevronRight className="w-5 h-5 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-4 bg-white rounded-3xl border border-slate-100 hover:border-primary/30 hover:shadow-xl transition-all group shadow-sm"
                                >
                                    <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-sm truncate group-hover:text-primary transition-colors">
                                            {appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}
                                        </p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">View Lyrics</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Report Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/10">
                    <div className="bg-primary p-10 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <Flag className="w-16 h-16 mx-auto mb-5 opacity-80" />
                        <h3 className="text-3xl font-black tracking-tight">Report Error</h3>
                        <p className="text-sm font-medium opacity-80 mt-2">Help keep our library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-5">
                            <div className="w-20 h-20 bg-green-100 text-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-10 h-10" /></div>
                            <h4 className="text-2xl font-black text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 font-medium">Your report has been received.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-10 space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Category of issue</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl font-black text-sm outline-none focus:border-primary cursor-pointer"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue (Typo/Error)</option>
                                    <option>Wrong Credits</option>
                                    <option>Video Link broken</option>
                                    <option>Missing Verse</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Details</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-5 rounded-[1.5rem] text-sm font-medium outline-none focus:bg-white focus:border-primary transition-all resize-none"
                                    placeholder="Describe the problem..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Save, Printer, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, ChevronRight, Play, Loader2
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  incrementViewCount, 
  getAllCustomSongs, 
  getSongById, 
  submitReport 
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  // Reduced default font size from 24 to 18 for a smaller look
  const [fontSize, setFontSize] = useState(18);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      composer: '', lyrics_nepali: '', lyrics_roman: '', title: '', artist: '', lyricist: ''
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} Lyrics | SansarPlus`;

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ ...lyricsResult });
      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${activeTab === 'nepali' ? data.title_nepali || data.title : data.title} Lyrics`,
      text: `Check out the lyrics for "${activeTab === 'nepali' ? data.title_nepali || data.title : data.title}" on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 72));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 10));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          await saveCustomSong(editForm.artist || data.artist, editForm.title || data.title, editForm as any);
          setData({ ...data, ...editForm });
          setIsEditing(false);
          alert("Updated successfully!");
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  const renderContributorLinks = (names: string[] | string | undefined) => {
      if (!names) return null;
      const nameList = (Array.isArray(names) ? names : names.split(','))
        .map(s => s.trim())
        .filter(s => s && s.toLowerCase() !== 'unknown');

      if (nameList.length === 0) return null;

      return (
          <span className="text-sm font-bold text-slate-800">
              {nameList.map((name, i) => (
                  <React.Fragment key={name}>
                      <Link 
                        to={`/artist/${encodeURIComponent(name)}`} 
                        className="hover:text-primary transition-colors underline decoration-slate-200 underline-offset-4 hover:decoration-primary"
                      >
                        {name}
                      </Link>
                      {i < nameList.length - 1 ? ', ' : ''}
                  </React.Fragment>
              ))}
          </span>
      );
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-white pb-32 selection:bg-primary/10 selection:text-primary">
      {/* Centered Header: Pure Title & Notes Only */}
      <div className="pt-16 pb-12 no-print">
        <div className="max-w-4xl mx-auto px-4 text-center">
            <div className="flex flex-col items-center gap-4">
                {data.note && data.isNoteVisible !== false && (
                    <span className="bg-amber-50 text-amber-600 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-amber-100 flex items-center gap-2">
                        <StickyNote className="w-3.5 h-3.5" /> {data.note}
                    </span>
                )}
                {/* Compact title font size: text-xl md:text-3xl */}
                <h1 className="text-xl md:text-3xl font-black text-slate-900 leading-tight tracking-tight">{displayTitle}</h1>
            </div>

            {/* Admin Edit Trigger */}
            {canEdit && (
                <div className="fixed top-20 right-6 z-30">
                    <button onClick={() => setIsEditing(!isEditing)} className={`p-4 rounded-2xl transition-all shadow-xl border ${isEditing ? 'bg-slate-100 text-slate-600 border-slate-200' : 'bg-indigo-600 text-white border-indigo-500 shadow-indigo-200 hover:bg-indigo-700'}`}>
                        {isEditing ? <X className="w-6 h-6" /> : <Edit className="w-6 h-6" />}
                    </button>
                </div>
            )}
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* Main Content: Lyrics Section (Centered Text) */}
            <div className="lg:col-span-8 space-y-10">

                {isEditing ? (
                    <div className="bg-white rounded-[3rem] p-8 md:p-12 shadow-2xl border border-slate-200 space-y-8 animate-in slide-in-from-bottom-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Romanized Title</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Artist Name</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.artist} onChange={e => setEditForm({...editForm, artist: e.target.value})} />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Lyrics Content (Nepali Script)</label>
                            <textarea className="w-full h-[600px] border-2 border-slate-100 p-6 rounded-[2rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                        </div>
                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-xl shadow-2xl shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center transform active:scale-95">
                            {isSaving ? <Loader2 className="w-7 h-7 animate-spin mr-3"/> : <Save className="w-7 h-7 mr-3" />}
                            Save & Sync Updates
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-slate-100 ring-1 ring-slate-200/50">
                        {/* Tab Switcher */}
                        <div className="flex border-b border-slate-100 bg-slate-50/50 no-print">
                            <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'nepali' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Globe className="w-5 h-5" /> Nepali
                            </button>
                            <button onClick={() => setActiveTab('roman')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'roman' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Search className="w-5 h-5" /> Roman Nepali
                            </button>
                        </div>

                        <div className="p-10 md:p-20 relative bg-white min-h-[500px]">
                            {/* Floating Zoom Controls */}
                            <div className="absolute top-6 right-8 flex gap-2 no-print opacity-20 hover:opacity-100 transition-opacity">
                                <button onClick={handleZoomOut} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomOut className="w-5 h-5" /></button>
                                <button onClick={handleZoomIn} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomIn className="w-5 h-5" /></button>
                                <button onClick={handleCopy} className={`p-3 rounded-xl transition-all shadow-sm ${copied ? 'bg-green-500 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                                    {copied ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                </button>
                            </div>

                            {/* Centered Lyrics Text: font-size linked to state (default 18) */}
                            <div 
                                className="whitespace-pre-wrap leading-[2.2] transition-all font-medium text-slate-800 tracking-wide text-center selection:bg-indigo-100" 
                                style={{ fontSize: `${fontSize}px` }}
                            >
                                {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Lyrics not available in Nepali.") : (data.lyrics_roman || "Lyrics not available in Roman Nepali.")}
                            </div>

                            {/* Moved Tools Strip: Below Lyrics */}
                            <div className="flex items-center justify-center gap-4 mt-16 pt-10 border-t border-slate-50 no-print">
                                <button onClick={handleFavorite} className={`p-4 rounded-2xl border transition-all ${isFav ? 'bg-red-50 text-red-500 border-red-100 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-200 hover:border-slate-300 shadow-sm'}`} title="Add to Favorites">
                                    <Heart className={`w-6 h-6 ${isFav ? 'fill-current' : ''}`} />
                                </button>
                                <button onClick={handleShare} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-primary transition-all shadow-sm" title="Share Song">
                                    <Share2 className="w-6 h-6" />
                                </button>
                                <button onClick={handlePrint} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-slate-700 transition-all shadow-sm" title="Print Lyrics">
                                    <Printer className="w-6 h-6" />
                                </button>
                                <button onClick={() => setIsFeedbackOpen(true)} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-red-500 transition-all shadow-sm" title="Report Issue">
                                    <Flag className="w-6 h-6" />
                                </button>
                            </div>
                        </div>

                        {/* Branding Footer */}
                        <div className="bg-slate-900/5 p-8 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-6 no-print">
                            <div className="flex items-center gap-3 text-slate-400">
                                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center"><Music className="w-5 h-5 text-indigo-400" /></div>
                                <p className="text-[11px] font-black uppercase tracking-[0.2em]">SansarPlus Verified Library</p>
                            </div>
                            <p className="text-[11px] font-black text-slate-300 uppercase tracking-widest">Worship with us globally</p>
                        </div>
                    </div>
                )}
            </div>

            {/* Sidebar Column */}
            <div className="lg:col-span-4 space-y-10 no-print">

                {/* Song Credits Card */}
                <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 space-y-8 relative overflow-hidden">
                    <h3 className="text-2xl font-black text-slate-900 border-b border-slate-50 pb-5 tracking-tight flex items-center gap-3">
                        <Disc className="w-7 h-7 text-primary" /> Credits & Info
                    </h3>

                    <div className="space-y-6">
                        {/* Lead Artist hidden as requested */}

                        {(data.composers?.length || data.composer) && renderContributorLinks(data.composers || data.composer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-purple-50 text-purple-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Music className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Composition</p>
                                    {renderContributorLinks(data.composers || data.composer)}
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && renderContributorLinks(data.lyricists || data.lyricist) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center shrink-0">
                                    <PenTool className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Words / Lyrics</p>
                                    {renderContributorLinks(data.lyricists || data.lyricist)}
                                </div>
                            </div>
                        )}

                        {(data.singers?.length || data.singer) && renderContributorLinks(data.singers || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Vocals By</p>
                                    {renderContributorLinks(data.singers || data.singer)}
                                </div>
                            </div>
                        )}

                        {/* Fallback if no specific credits exist */}
                        {!(renderContributorLinks(data.composers || data.composer) || 
                           renderContributorLinks(data.lyricists || data.lyricist) || 
                           renderContributorLinks(data.singers || data.singer)) && (
                            <p className="text-xs text-slate-400 italic">No detailed credits available.</p>
                        )}
                    </div>
                </div>

                {/* Official Video Player: Now BELOW Credits Card */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-100 group">
                        <div className="bg-red-600 px-6 py-4 text-white flex items-center justify-between">
                            <h3 className="font-black text-xs uppercase tracking-widest flex items-center gap-3">
                                <Youtube className="w-6 h-6" /> Official Video
                            </h3>
                            <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
                        </div>
                        <div className="aspect-video relative">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Song Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* More Tracks Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 px-2">
                             More tracks <ChevronRight className="w-5 h-5 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-4 bg-white rounded-3xl border border-slate-100 hover:border-primary/30 hover:shadow-xl transition-all group shadow-sm"
                                >
                                    <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-sm truncate group-hover:text-primary transition-colors">
                                            {appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}
                                        </p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">View Lyrics</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Report Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/10">
                    <div className="bg-primary p-10 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <Flag className="w-16 h-16 mx-auto mb-5 opacity-80" />
                        <h3 className="text-3xl font-black tracking-tight">Report Error</h3>
                        <p className="text-sm font-medium opacity-80 mt-2">Help keep our library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-5">
                            <div className="w-20 h-20 bg-green-100 text-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-10 h-10" /></div>
                            <h4 className="text-2xl font-black text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 font-medium">Your report has been received.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-10 space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Category of issue</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl font-black text-sm outline-none focus:border-primary cursor-pointer"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue (Typo/Error)</option>
                                    <option>Wrong Credits</option>
                                    <option>Video Link broken</option>
                                    <option>Missing Verse</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Details</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-5 rounded-[1.5rem] text-sm font-medium outline-none focus:bg-white focus:border-primary transition-all resize-none"
                                    placeholder="Describe the problem..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Save, Printer, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, ChevronRight, Play, Loader2
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  incrementViewCount, 
  getAllCustomSongs, 
  getSongById, 
  submitReport 
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  // Default font size reduced further from 18 to 15 for a "more small" look
  const [fontSize, setFontSize] = useState(15);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      composer: '', lyrics_nepali: '', lyrics_roman: '', title: '', artist: '', lyricist: ''
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} Lyrics | SansarPlus`;

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ ...lyricsResult });
      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${activeTab === 'nepali' ? data.title_nepali || data.title : data.title} Lyrics`,
      text: `Check out the lyrics for "${activeTab === 'nepali' ? data.title_nepali || data.title : data.title}" on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 72));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 8));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          await saveCustomSong(editForm.artist || data.artist, editForm.title || data.title, editForm as any);
          setData({ ...data, ...editForm });
          setIsEditing(false);
          alert("Updated successfully!");
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  const renderContributorLinks = (names: string[] | string | undefined) => {
      if (!names) return null;
      const nameList = (Array.isArray(names) ? names : names.split(','))
        .map(s => s.trim())
        .filter(s => s && s.toLowerCase() !== 'unknown');

      if (nameList.length === 0) return null;

      return (
          <span className="text-sm font-bold text-slate-800">
              {nameList.map((name, i) => (
                  <React.Fragment key={name}>
                      <Link 
                        to={`/artist/${encodeURIComponent(name)}`} 
                        className="hover:text-primary transition-colors underline decoration-slate-200 underline-offset-4 hover:decoration-primary"
                      >
                        {name}
                      </Link>
                      {i < nameList.length - 1 ? ', ' : ''}
                  </React.Fragment>
              ))}
          </span>
      );
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-white pb-32 selection:bg-primary/10 selection:text-primary">
      {/* Centered Header: Pure Title & Notes Only */}
      <div className="pt-16 pb-12 no-print">
        <div className="max-w-4xl mx-auto px-4 text-center">
            <div className="flex flex-col items-center gap-4">
                {data.note && data.isNoteVisible !== false && (
                    <span className="bg-amber-50 text-amber-600 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-amber-100 flex items-center gap-2">
                        <StickyNote className="w-3.5 h-3.5" /> {data.note}
                    </span>
                )}
                {/* Compact title font size */}
                <h1 className="text-xl md:text-3xl font-black text-slate-900 leading-tight tracking-tight">{displayTitle}</h1>
            </div>

            {/* Admin Edit Trigger */}
            {canEdit && (
                <div className="fixed top-20 right-6 z-30">
                    <button onClick={() => setIsEditing(!isEditing)} className={`p-4 rounded-2xl transition-all shadow-xl border ${isEditing ? 'bg-slate-100 text-slate-600 border-slate-200' : 'bg-indigo-600 text-white border-indigo-500 shadow-indigo-200 hover:bg-indigo-700'}`}>
                        {isEditing ? <X className="w-6 h-6" /> : <Edit className="w-6 h-6" />}
                    </button>
                </div>
            )}
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* Main Content: Lyrics Section (Centered Text) */}
            <div className="lg:col-span-8 space-y-10">

                {isEditing ? (
                    <div className="bg-white rounded-[3rem] p-8 md:p-12 shadow-2xl border border-slate-200 space-y-8 animate-in slide-in-from-bottom-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Romanized Title</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Artist Name</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.artist} onChange={e => setEditForm({...editForm, artist: e.target.value})} />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Lyrics Content (Nepali Script)</label>
                            <textarea className="w-full h-[600px] border-2 border-slate-100 p-6 rounded-[2rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                        </div>
                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-xl shadow-2xl shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center transform active:scale-95">
                            {isSaving ? <Loader2 className="w-7 h-7 animate-spin mr-3"/> : <Save className="w-7 h-7 mr-3" />}
                            Save & Sync Updates
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-slate-100 ring-1 ring-slate-200/50">
                        {/* Tab Switcher */}
                        <div className="flex border-b border-slate-100 bg-slate-50/50 no-print">
                            <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'nepali' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Globe className="w-5 h-5" /> Nepali
                            </button>
                            <button onClick={() => setActiveTab('roman')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'roman' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Search className="w-5 h-5" /> Roman Nepali
                            </button>
                        </div>

                        <div className="p-10 md:p-20 relative bg-white min-h-[500px]">
                            {/* Floating Zoom Controls */}
                            <div className="absolute top-6 right-8 flex gap-2 no-print opacity-20 hover:opacity-100 transition-opacity">
                                <button onClick={handleZoomOut} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomOut className="w-5 h-5" /></button>
                                <button onClick={handleZoomIn} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomIn className="w-5 h-5" /></button>
                                <button onClick={handleCopy} className={`p-3 rounded-xl transition-all shadow-sm ${copied ? 'bg-green-500 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                                    {copied ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                </button>
                            </div>

                            {/* Centered Lyrics Text: font-size linked to state (default 15) */}
                            <div 
                                className="whitespace-pre-wrap leading-[2.0] transition-all font-medium text-slate-800 tracking-wide text-center selection:bg-indigo-100" 
                                style={{ fontSize: `${fontSize}px` }}
                            >
                                {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Lyrics not available in Nepali.") : (data.lyrics_roman || "Lyrics not available in Roman Nepali.")}
                            </div>

                            {/* Tools Strip: Below Lyrics */}
                            <div className="flex items-center justify-center gap-4 mt-16 pt-10 border-t border-slate-50 no-print">
                                <button onClick={handleFavorite} className={`p-4 rounded-2xl border transition-all ${isFav ? 'bg-red-50 text-red-500 border-red-100 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-200 hover:border-slate-300 shadow-sm'}`} title="Add to Favorites">
                                    <Heart className={`w-6 h-6 ${isFav ? 'fill-current' : ''}`} />
                                </button>
                                <button onClick={handleShare} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-primary transition-all shadow-sm" title="Share Song">
                                    <Share2 className="w-6 h-6" />
                                </button>
                                <button onClick={handlePrint} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-slate-700 transition-all shadow-sm" title="Print Lyrics">
                                    <Printer className="w-6 h-6" />
                                </button>
                                <button onClick={() => setIsFeedbackOpen(true)} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-red-500 transition-all shadow-sm" title="Report Issue">
                                    <Flag className="w-6 h-6" />
                                </button>
                            </div>
                        </div>

                        {/* Branding Footer */}
                        <div className="bg-slate-900/5 p-8 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-6 no-print">
                            <div className="flex items-center gap-3 text-slate-400">
                                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center"><Music className="w-5 h-5 text-indigo-400" /></div>
                                <p className="text-[11px] font-black uppercase tracking-[0.2em]">SansarPlus Verified Library</p>
                            </div>
                            <p className="text-[11px] font-black text-slate-300 uppercase tracking-widest">Worship with us globally</p>
                        </div>
                    </div>
                )}
            </div>

            {/* Sidebar Column */}
            <div className="lg:col-span-4 space-y-10 no-print">

                {/* Song Credits Card */}
                <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 space-y-8 relative overflow-hidden">
                    <h3 className="text-2xl font-black text-slate-900 border-b border-slate-50 pb-5 tracking-tight flex items-center gap-3">
                        <Disc className="w-7 h-7 text-primary" /> Credits & Info
                    </h3>

                    <div className="space-y-6">
                        {(data.composers?.length || data.composer) && renderContributorLinks(data.composers || data.composer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-purple-50 text-purple-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Music className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Composition</p>
                                    {renderContributorLinks(data.composers || data.composer)}
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && renderContributorLinks(data.lyricists || data.lyricist) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center shrink-0">
                                    <PenTool className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Words / Lyrics</p>
                                    {renderContributorLinks(data.lyricists || data.lyricist)}
                                </div>
                            </div>
                        )}

                        {(data.singers?.length || data.singer) && renderContributorLinks(data.singers || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Vocals By</p>
                                    {renderContributorLinks(data.singers || data.singer)}
                                </div>
                            </div>
                        )}

                        {/* Fallback if no specific credits exist */}
                        {!(renderContributorLinks(data.composers || data.composer) || 
                           renderContributorLinks(data.lyricists || data.lyricist) || 
                           renderContributorLinks(data.singers || data.singer)) && (
                            <p className="text-xs text-slate-400 italic">No detailed credits available.</p>
                        )}
                    </div>
                </div>

                {/* Official Video Player: BELOW Credits Card */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-100 group">
                        <div className="bg-red-600 px-6 py-4 text-white flex items-center justify-between">
                            <h3 className="font-black text-xs uppercase tracking-widest flex items-center gap-3">
                                <Youtube className="w-6 h-6" /> Official Video
                            </h3>
                            <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
                        </div>
                        <div className="aspect-video relative">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Song Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* More Tracks Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 px-2">
                             More tracks <ChevronRight className="w-5 h-5 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-4 bg-white rounded-3xl border border-slate-100 hover:border-primary/30 hover:shadow-xl transition-all group shadow-sm"
                                >
                                    <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-sm truncate group-hover:text-primary transition-colors">
                                            {appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}
                                        </p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">View Lyrics</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Report Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/10">
                    <div className="bg-primary p-10 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <Flag className="w-16 h-16 mx-auto mb-5 opacity-80" />
                        <h3 className="text-3xl font-black tracking-tight">Report Error</h3>
                        <p className="text-sm font-medium opacity-80 mt-2">Help keep our library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-5">
                            <div className="w-20 h-20 bg-green-100 text-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-10 h-10" /></div>
                            <h4 className="text-2xl font-black text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 font-medium">Your report has been received.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-10 space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Category of issue</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl font-black text-sm outline-none focus:border-primary cursor-pointer"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue (Typo/Error)</option>
                                    <option>Wrong Credits</option>
                                    <option>Video Link broken</option>
                                    <option>Missing Verse</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Details</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-5 rounded-[1.5rem] text-sm font-medium outline-none focus:bg-white focus:border-primary transition-all resize-none"
                                    placeholder="Describe the problem..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Save, Printer, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, ChevronRight, Play, Loader2
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  incrementViewCount, 
  getAllCustomSongs, 
  getSongById, 
  submitReport 
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  // Default font size reduced further from 18 to 15 for a "more small" look
  const [fontSize, setFontSize] = useState(15);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      composer: '', lyrics_nepali: '', lyrics_roman: '', title: '', artist: '', lyricist: ''
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} Lyrics | SansarPlus`;

      const [artistResult, allSongs] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ ...lyricsResult });
      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${activeTab === 'nepali' ? data.title_nepali || data.title : data.title} Lyrics`,
      text: `Check out the lyrics for "${activeTab === 'nepali' ? data.title_nepali || data.title : data.title}" on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 72));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 8));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          await saveCustomSong(editForm.artist || data.artist, editForm.title || data.title, editForm as any);
          setData({ ...data, ...editForm });
          setIsEditing(false);
          alert("Updated successfully!");
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  const renderContributorLinks = (names: string[] | string | undefined) => {
      if (!names) return null;
      const nameList = (Array.isArray(names) ? names : names.split(','))
        .map(s => s.trim())
        .filter(s => s && s.toLowerCase() !== 'unknown');

      if (nameList.length === 0) return null;

      return (
          <span className="text-sm font-bold text-slate-800">
              {nameList.map((name, i) => (
                  <React.Fragment key={name}>
                      <Link 
                        to={`/artist/${encodeURIComponent(name)}`} 
                        className="hover:text-primary transition-colors underline decoration-slate-200 underline-offset-4 hover:decoration-primary"
                      >
                        {name}
                      </Link>
                      {i < nameList.length - 1 ? ', ' : ''}
                  </React.Fragment>
              ))}
          </span>
      );
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-white pb-32 selection:bg-primary/10 selection:text-primary">
      {/* Centered Header: Pure Title & Notes Only */}
      <div className="pt-16 pb-12 no-print">
        <div className="max-w-4xl mx-auto px-4 text-center">
            <div className="flex flex-col items-center gap-4">
                {data.note && data.isNoteVisible !== false && (
                    <span className="bg-amber-50 text-amber-600 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-amber-100 flex items-center gap-2">
                        <StickyNote className="w-3.5 h-3.5" /> {data.note}
                    </span>
                )}
                {/* Compact title font size */}
                <h1 className="text-xl md:text-3xl font-black text-slate-900 leading-tight tracking-tight">{displayTitle}</h1>
            </div>

            {/* Admin Edit Trigger */}
            {canEdit && (
                <div className="fixed top-20 right-6 z-30">
                    <button onClick={() => setIsEditing(!isEditing)} className={`p-4 rounded-2xl transition-all shadow-xl border ${isEditing ? 'bg-slate-100 text-slate-600 border-slate-200' : 'bg-indigo-600 text-white border-indigo-500 shadow-indigo-200 hover:bg-indigo-700'}`}>
                        {isEditing ? <X className="w-6 h-6" /> : <Edit className="w-6 h-6" />}
                    </button>
                </div>
            )}
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* Main Content: Lyrics Section (Centered Text) */}
            <div className="lg:col-span-8 space-y-10">

