                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Words / Lyrics</p>
                                    {renderContributorLinks(data.lyricists || data.lyricist)}
                                </div>
                            </div>
                        )}

                        {(data.singers?.length || data.singer) && renderContributorLinks(data.singers || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Vocals By</p>
                                    {renderContributorLinks(data.singers || data.singer)}
                                </div>
                            </div>
                        )}

                        {/* Fallback if no specific credits exist */}
                        {!(renderContributorLinks(data.composers || data.composer) || 
                           renderContributorLinks(data.lyricists || data.lyricist) || 
                           renderContributorLinks(data.singers || data.singer)) && (
                            <p className="text-xs text-slate-400 italic">No detailed credits available.</p>
                        )}
                    </div>
                </div>

                {/* Official Video Player: BELOW Credits Card */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-100 group">
                        <div className="bg-red-600 px-6 py-4 text-white flex items-center justify-between">
                            <h3 className="font-black text-xs uppercase tracking-widest flex items-center gap-3">
                                <Youtube className="w-6 h-6" /> Official Video
                            </h3>
                            <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
                        </div>
                        <div className="aspect-video relative">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Song Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* More Tracks Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 px-2">
                             More tracks <ChevronRight className="w-5 h-5 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-4 bg-white rounded-3xl border border-slate-100 hover:border-primary/30 hover:shadow-xl transition-all group shadow-sm"
                                >
                                    <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-sm truncate group-hover:text-primary transition-colors">
                                            {appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}
                                        </p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">View Lyrics</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Report Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/10">
                    <div className="bg-primary p-10 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <Flag className="w-16 h-16 mx-auto mb-5 opacity-80" />
                        <h3 className="text-3xl font-black tracking-tight">Report Error</h3>
                        <p className="text-sm font-medium opacity-80 mt-2">Help keep our library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-5">
                            <div className="w-20 h-20 bg-green-100 text-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-10 h-10" /></div>
                            <h4 className="text-2xl font-black text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 font-medium">Your report has been received.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-10 space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Category of issue</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl font-black text-sm outline-none focus:border-primary cursor-pointer"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue (Typo/Error)</option>
                                    <option>Wrong Credits</option>
                                    <option>Video Link broken</option>
                                    <option>Missing Verse</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Details</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-5 rounded-[1.5rem] text-sm font-medium outline-none focus:bg-white focus:border-primary transition-all resize-none"
                                    placeholder="Describe the problem..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useState, useEffect, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth, logout } from '../utils/auth';
import { 
  getAllCustomSongs, 
  saveCustomSong, 
  saveCustomArtist, 
  getAllCustomArtists, 
  deleteCustomSong, 
  deleteCustomArtist, 
  getCustomArtist, 
  getBanners, 
  saveBanner, 
  deleteBanner, 
  getCategories, 
  addCategory, 
  updateCategory, 
  deleteCategory, 
  reorderCategories,
  exportAllData, 
  importAllData, 
  getSiteLogo, 
  saveSiteLogo, 
  getAnnouncement, 
  saveAnnouncement, 
  getContactInfo, 
  saveContactInfo, 
  getAnalytics, 
  AnalyticsData,
  getReports,
  deleteReport
} from '../utils/dataManager';
import { 
  LogOut, Plus, Music, User, Trash2, Edit2, Grid, ImageIcon as BannerIcon, 
  Check, X, Database, Settings, Megaphone, Info, Activity, Calendar, Clock, 
  Save, ExternalLink, Search, Youtube, Globe, Mail, MessageCircle,
  Download, Shield, Upload, Camera, Image as ImageIconRegular,
  Facebook, Instagram, ChevronUp, ChevronDown, GripVertical, StickyNote,
  MailWarning, Bell
} from 'lucide-react';
import { Banner, Announcement, Category, ContactInfo, Report } from '../types';
import Loader from '../components/Loader';
import ArtistSelector from '../components/ArtistSelector';
import { supabase } from '../supabaseClient';

const AdminDashboard: React.FC = () => {
  const { user, isAuth, loading: authLoading } = useAuth();
  const navigate = useNavigate();
  const userRole = user?.role;
  const isSuperAdmin = userRole === 'SUPER_ADMIN';
  const isRegularUser = userRole === 'USER';

  const [activeTab, setActiveTab] = useState<'overview' | 'songs' | 'artists' | 'banners' | 'categories' | 'contact' | 'backup' | 'settings' | 'addSong' | 'addArtist' | 'announcement' | 'reports'>('overview');
  const [loading, setLoading] = useState(true);
  const [customSongs, setCustomSongs] = useState<any[]>([]);
  const [customArtists, setCustomArtists] = useState<any[]>([]);
  const [banners, setBanners] = useState<Banner[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [reports, setReports] = useState<Report[]>([]);
  const [announcement, setAnnouncement] = useState<Announcement>({ imageUrl: '', link: '', isVisible: false });
  const [contactInfo, setContactInfo] = useState<ContactInfo>({
      missionTitle: '', missionText: '', visionTitle: '', visionText: '',
      email: '', whatsapp: '', facebookUrl: '', footerTitle: '', footerText: ''
  });

  const [analytics, setAnalytics] = useState<AnalyticsData>({ lifetime: 0, today: 0, thisWeek: 0, lastWeek: 0 });
  const [onlineCount, setOnlineCount] = useState(0);

  // Drag and Drop State
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  // Refs for file uploads
  const bannerFileRef = useRef<HTMLInputElement>(null);
  const announcementFileRef = useRef<HTMLInputElement>(null);
  const logoFileRef = useRef<HTMLInputElement>(null);
  const backupFileRef = useRef<HTMLInputElement>(null);
  const categoryFileRef = useRef<HTMLInputElement>(null);
  const editCategoryFileRef = useRef<HTMLInputElement>(null);
  const artistFileRef = useRef<HTMLInputElement>(null);

  // Search/Filter states
  const [songSearch, setSongSearch] = useState('');
  const [artistSearch, setArtistSearch] = useState('');

  // Form States
  const [songForm, setSongForm] = useState({ 
      title: '', title_nepali: '', artist: '', artists: [] as string[], 
      lyrics_nepali: '', lyrics_roman: '', 
      composer: '', composers: [] as string[], 
      lyricist: '', lyricists: [] as string[], 
      singer: '', singers: [] as string[], 
      views: 0, artist_bio: '', categories: [] as string[],
      youtubeUrl: '', isYoutubeVisible: true,
      language: 'nepali' as 'nepali' | 'hindi' | 'english',
      note: '', isNoteVisible: true
  });
  const [artistForm, setArtistForm] = useState({ 
      name: '', bio: '', topSongs: '', imageUrl: '', 
      facebookUrl: '', instagramUrl: '', youtubeUrl: '',
      isFacebookVisible: true, isInstagramVisible: true, isArtistYoutubeVisible: true
  });
  const [bannerForm, setBannerForm] = useState({ imageUrl: '', title: '', subtitle: '', link: '' });
  const [editingBannerId, setEditingBannerId] = useState<string | null>(null);
  const [categoryForm, setCategoryForm] = useState({ name: '', imageUrl: '', hideTitle: false });
  const [siteLogo, setSiteLogo] = useState('');
  const [editingCategory, setEditingCategory] = useState<{original: string, current: string, imageUrl: string, hideTitle: boolean} | null>(null);

  useEffect(() => {
    if (!authLoading) {
      if (!isAuth) {
        navigate('/login');
      } else if (isRegularUser) {
        navigate('/');
      } else {
        refreshData();
        setupPresence();

        // Listen for report events
        window.addEventListener('new-report', refreshData);
        return () => window.removeEventListener('new-report', refreshData);
      }
    }
  }, [isAuth, isRegularUser, authLoading, navigate]);

  const setupPresence = () => {
    const channel = supabase.channel('online_users');
    channel
        .on('presence', { event: 'sync' }, () => {
            const newState = channel.presenceState();
            setOnlineCount(Object.keys(newState).length);
        })
        .subscribe();

    return () => { channel.unsubscribe(); }
  };

  const refreshData = async () => {
    try {
      setLoading(true);
      const [songs, artists, bans, cats, logo, stats, ann, info, rpts] = await Promise.all([
        getAllCustomSongs(),
        getAllCustomArtists(),
        getBanners(),
        getCategories(),
        getSiteLogo(),
        getAnalytics(),
        getAnnouncement(),
        getContactInfo(),
        getReports()
      ]);

      setCustomSongs(songs);
      setCustomArtists(artists);
      setBanners(bans);
      setCategories(cats);
      setSiteLogo(logo);
      setAnalytics(stats);
      setReports(rpts);

      if (ann) setAnnouncement(ann);
      if (info) setContactInfo(prev => ({ ...prev, ...info }));
    } catch (err) {
      console.error("Dashboard refresh failed:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = error => reject(error);
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, target: 'banner' | 'announcement' | 'logo' | 'category' | 'edit-category' | 'artist') => {
    const file = e.target.files?.[0];
    if (file) {
      try {
        const base64 = await fileToBase64(file);
        if (target === 'banner') setBannerForm(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'announcement') setAnnouncement(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'logo') setSiteLogo(base64);
        else if (target === 'category') setCategoryForm(prev => ({ ...prev, imageUrl: base64 }));
        else if (target === 'edit-category') setEditingCategory(prev => prev ? { ...prev, imageUrl: base64 } : null);
        else if (target === 'artist') setArtistForm(prev => ({ ...prev, imageUrl: base64 }));

        e.target.value = '';
      } catch (err) {
        alert("File conversion failed.");
      }
    }
  };

  const handleAddSong = async (e: React.FormEvent) => {
    e.preventDefault();
    const titleClean = songForm.title.trim();
    if (!titleClean) return;

    const artistList = songForm.artists.length > 0 ? songForm.artists : (songForm.artist ? [songForm.artist] : []);
    const displayArtist = artistList.length > 0 ? artistList.join(', ') : 'Unknown';

    try {
        await saveCustomSong(displayArtist, titleClean, {
            title_nepali: songForm.title_nepali.trim(),
            lyrics_nepali: songForm.lyrics_nepali,
            lyrics_roman: songForm.lyrics_roman,
            composer: songForm.composers.join(', '),
            composers: songForm.composers,
            lyricist: songForm.lyricist.join(', '),
            lyricists: songForm.lyricists,
            singer: songForm.singers.join(', '),
            singers: songForm.singers,
            views: songForm.views,
            categories: songForm.categories.length > 0 ? songForm.categories : ['Worship'],
            youtubeUrl: songForm.youtubeUrl.trim(),
            isYoutubeVisible: songForm.isYoutubeVisible,
            artists: artistList,
            language: songForm.language,
            artist: displayArtist,
            note: songForm.note.trim(),
            isNoteVisible: songForm.isNoteVisible
        });

        setSongForm({ 
            title: '', title_nepali: '', artist: '', artists: [], lyrics_nepali: '', lyrics_roman: '', 
            composer: '', composers: [], lyricist: '', lyricists: [], singer: '', 
            singers: [], views: 0, artist_bio: '', categories: [], youtubeUrl: '', 
            isYoutubeVisible: true, language: 'nepali', note: '', isNoteVisible: true
        });

        setActiveTab('songs');
        refreshData();
    } catch (err: any) {
        alert("Failed to save song: " + (err.message || "Unknown error"));
    }
  };

  const handleAddArtist = async (e: React.FormEvent) => {
    e.preventDefault();
    const nameClean = artistForm.name.trim();
    if (!nameClean) return;
    try {
        await saveCustomArtist(nameClean, {
            name: nameClean,
            bio: artistForm.bio,
