                                    <Flag className="w-6 h-6" />
                                </button>
                            </div>
                        </div>

                        {/* Branding Footer */}
                        <div className="bg-slate-900/5 p-8 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-6 no-print">
                            <div className="flex items-center gap-3 text-slate-400">
                                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center"><Music className="w-5 h-5 text-indigo-400" /></div>
                                <p className="text-[11px] font-black uppercase tracking-[0.2em]">SansarPlus Verified Library</p>
                            </div>
                            <p className="text-[11px] font-black text-slate-300 uppercase tracking-widest">Worship with us globally</p>
                        </div>
                    </div>
                )}
            </div>

            {/* Sidebar Column */}
            <div className="lg:col-span-4 space-y-10 no-print">

                {/* Song Credits Card */}
                <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 space-y-8 relative overflow-hidden">
                    <h3 className="text-2xl font-black text-slate-900 border-b border-slate-50 pb-5 tracking-tight flex items-center gap-3">
                        <Disc className="w-7 h-7 text-primary" /> Credits & Info
                    </h3>

                    <div className="space-y-6">
                        {(data.singers?.length || data.singer) && renderContributorLinks(data.singers || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Vocals By</p>
                                    {renderContributorLinks(data.singers || data.singer)}
                                </div>
                            </div>
                        )}

                        {(data.composers?.length || data.composer) && renderContributorLinks(data.composers || data.composer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-purple-50 text-purple-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Music className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Composition</p>
                                    {renderContributorLinks(data.composers || data.composer)}
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && renderContributorLinks(data.lyricists || data.lyricist) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center shrink-0">
                                    <PenTool className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Words / Lyrics</p>
                                    {renderContributorLinks(data.lyricists || data.lyricist)}
                                </div>
                            </div>
                        )}

                        {/* Fallback if no specific credits exist */}
                        {!(renderContributorLinks(data.composers || data.composer) || 
                           renderContributorLinks(data.lyricists || data.lyricist) || 
                           renderContributorLinks(data.singers || data.singer)) && (
                            <p className="text-xs text-slate-400 italic">No detailed credits available.</p>
                        )}
                    </div>
                </div>

                {/* Official Video Player: BELOW Credits Card */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-100 group">
                        <div className="bg-red-600 px-6 py-4 text-white flex items-center justify-between">
                            <h3 className="font-black text-xs uppercase tracking-widest flex items-center gap-3">
                                <Youtube className="w-6 h-6" /> Official Video
                            </h3>
                            <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
                        </div>
                        <div className="aspect-video relative">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Song Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* More Tracks Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 px-2">
                             More tracks <ChevronRight className="w-5 h-5 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-4 bg-white rounded-3xl border border-slate-100 hover:border-primary/30 hover:shadow-xl transition-all group shadow-sm"
                                >
                                    <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-sm truncate group-hover:text-primary transition-colors">
                                            {appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}
                                        </p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">View Lyrics</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Report Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/10">
                    <div className="bg-primary p-10 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <Flag className="w-16 h-16 mx-auto mb-5 opacity-80" />
                        <h3 className="text-3xl font-black tracking-tight">Report Error</h3>
                        <p className="text-sm font-medium opacity-80 mt-2">Help keep our library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-5">
                            <div className="w-20 h-20 bg-green-100 text-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-10 h-10" /></div>
                            <h4 className="text-2xl font-black text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 font-medium">Your report has been received.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-10 space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Category of issue</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl font-black text-sm outline-none focus:border-primary cursor-pointer"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue (Typo/Error)</option>
                                    <option>Wrong Credits</option>
                                    <option>Video Link broken</option>
                                    <option>Missing Verse</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Details</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-5 rounded-[1.5rem] text-sm font-medium outline-none focus:bg-white focus:border-primary transition-all resize-none"
                                    placeholder="Describe the problem..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Save, Printer, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, ChevronRight, Play, Loader2,
  Eye, EyeOff, Trash2, Settings
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  incrementViewCount, 
  getAllCustomSongs, 
  getSongById, 
  submitReport,
  getAllCustomArtists
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';
import ArtistSelector from '../components/ArtistSelector';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [allArtists, setAllArtists] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(15);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      title: '',
      title_nepali: '',
      artist: '',
      artists: [],
      composer: '',
      composers: [],
      lyricist: '',
      lyricists: [],
      singer: '',
      singers: [],
      lyrics_nepali: '',
      lyrics_roman: '',
      youtubeUrl: '',
      isYoutubeVisible: true,
      note: '',
      isNoteVisible: true,
      language: 'nepali'
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} Lyrics | SansarPlus`;

      const [artistResult, allSongs, artistsList] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs(),
          getAllCustomArtists()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);
      setAllArtists(artistsList);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ 
        ...lyricsResult,
        artists: lyricsResult.artists || [lyricsResult.artist],
        composers: lyricsResult.composers || (lyricsResult.composer ? [lyricsResult.composer] : []),
        lyricists: lyricsResult.lyricists || (lyricsResult.lyricist ? [lyricsResult.lyricist] : []),
        singers: lyricsResult.singers || (lyricsResult.singer ? [lyricsResult.singer] : []),
        isYoutubeVisible: lyricsResult.isYoutubeVisible ?? true,
        isNoteVisible: lyricsResult.isNoteVisible ?? true
      });

      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);

      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${activeTab === 'nepali' ? data.title_nepali || data.title : data.title} Lyrics`,
      text: `Check out the lyrics for "${activeTab === 'nepali' ? data.title_nepali || data.title : data.title}" on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 72));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 8));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          const finalArtist = editForm.artists && editForm.artists.length > 0 ? editForm.artists.join(', ') : (editForm.artist || data.artist);

          await saveCustomSong(finalArtist, editForm.title || data.title, {
              ...editForm,
              artist: finalArtist
          });

          setData({ ...data, ...editForm, artist: finalArtist });
          setIsEditing(false);
          alert("Song updated successfully!");

          // If title or artist changed significantly, we might need to reload or redirect
          if (editForm.title !== data.title || finalArtist !== data.artist) {
              window.location.reload();
          }
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  const renderContributorLinks = (names: string[] | string | undefined) => {
      if (!names) return null;
      const nameList = (Array.isArray(names) ? names : names.split(','))
        .map(s => s.trim())
        .filter(s => s && s.toLowerCase() !== 'unknown');

      if (nameList.length === 0) return null;

      return (
          <span className="text-sm font-bold text-slate-800">
              {nameList.map((name, i) => (
                  <React.Fragment key={name}>
                      <Link 
                        to={`/artist/${encodeURIComponent(name)}`} 
                        className="hover:text-primary transition-colors underline decoration-slate-200 underline-offset-4 hover:decoration-primary"
                      >
                        {name}
                      </Link>
                      {i < nameList.length - 1 ? ', ' : ''}
                  </React.Fragment>
              ))}
          </span>
      );
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  const displayTitle = activeTab === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  return (
    <div className="min-h-screen bg-white pb-32 selection:bg-primary/10 selection:text-primary">
      {/* Centered Header: Pure Title & Notes Only */}
      <div className="pt-16 pb-12 no-print">
        <div className="max-w-4xl mx-auto px-4 text-center">
            <div className="flex flex-col items-center gap-4">
                {data.note && data.isNoteVisible !== false && (
                    <span className="bg-amber-50 text-amber-600 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-amber-100 flex items-center gap-2">
                        <StickyNote className="w-3.5 h-3.5" /> {data.note}
                    </span>
                )}
                {/* Compact title font size */}
                <h1 className="text-xl md:text-3xl font-black text-slate-900 leading-tight tracking-tight">{displayTitle}</h1>
            </div>

            {/* Admin Edit Trigger */}
            {canEdit && (
                <div className="fixed top-20 right-6 z-30 flex flex-col gap-3">
                    <button 
                      onClick={() => setIsEditing(!isEditing)} 
                      className={`p-4 rounded-2xl transition-all shadow-xl border ${isEditing ? 'bg-slate-800 text-white border-slate-700 shadow-slate-200' : 'bg-indigo-600 text-white border-indigo-500 shadow-indigo-200 hover:bg-indigo-700'}`}
                      title={isEditing ? "Close Editor" : "Edit Song Details"}
                    >
                        {isEditing ? <X className="w-6 h-6" /> : <Edit className="w-6 h-6" />}
                    </button>
                    {isEditing && (
                      <button 
                        onClick={handleSaveEdit}
                        disabled={isSaving}
                        className="p-4 rounded-2xl bg-emerald-600 text-white border-emerald-500 shadow-xl shadow-emerald-200 hover:bg-emerald-700 transition-all disabled:opacity-50"
                        title="Save Changes"
                      >
                        {isSaving ? <Loader2 className="w-6 h-6 animate-spin" /> : <Save className="w-6 h-6" />}
                      </button>
                    )}
                </div>
            )}
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* Main Content: Lyrics Section (Centered Text) */}
            <div className="lg:col-span-8 space-y-10">

                {isEditing ? (
                    <div className="bg-white rounded-[3rem] p-8 md:p-12 shadow-2xl border border-slate-200 space-y-10 animate-in slide-in-from-bottom-4">
                        <div className="flex items-center gap-3 border-b border-slate-100 pb-4">
                          {/* Added: Imported Settings icon from lucide-react */}
                          <Settings className="w-6 h-6 text-primary" />
                          <h2 className="text-2xl font-black text-slate-800">Edit Song Library</h2>
                        </div>

                        {/* Section 1: Basic Info */}
                        <div className="space-y-6">
                          <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-l-4 border-primary pl-3">Basic Information</h3>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                              <div className="space-y-2">
                                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-2">Romanized Title</label>
                                  <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                              </div>
                              <div className="space-y-2">
                                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-2">Nepali Title</label>
                                  <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title_nepali} onChange={e => setEditForm({...editForm, title_nepali: e.target.value})} placeholder="Title in native script..." />
                              </div>
                              <div className="md:col-span-2">
                                <ArtistSelector label="Main Artist(s)" selected={editForm.artists || []} onChange={arts => setEditForm({...editForm, artists: arts})} suggestions={allArtists} />
                              </div>
                          </div>
                        </div>

                        {/* Section 2: Credits */}
                        <div className="space-y-6">
                          <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-l-4 border-secondary pl-3">Credits & Contributors</h3>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="md:col-span-2">
                              <ArtistSelector label="Singers / Vocals" selected={editForm.singers || []} onChange={v => setEditForm({...editForm, singers: v})} suggestions={allArtists} />
                            </div>
                            <ArtistSelector label="Composers" selected={editForm.composers || []} onChange={v => setEditForm({...editForm, composers: v})} suggestions={allArtists} />
                            <ArtistSelector label="Lyricists" selected={editForm.lyricists || []} onChange={v => setEditForm({...editForm, lyricists: v})} suggestions={allArtists} />
                          </div>
                        </div>

                        {/* Section 3: Media & Notes */}
                        <div className="space-y-6">
                          <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-l-4 border-amber-500 pl-3">Media & Settings</h3>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-2">YouTube URL</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.youtubeUrl} onChange={e => setEditForm({...editForm, youtubeUrl: e.target.value})} placeholder="https://youtube.com/watch?v=..." />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-2">Song Note</label>
                                <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.note} onChange={e => setEditForm({...editForm, note: e.target.value})} placeholder="e.g. (Worship Mix)" />
                            </div>

                            <div className="flex items-center gap-6 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                                <div className="flex-1">
                                  <p className="text-xs font-black text-slate-800 uppercase tracking-wider">Video Visibility</p>
                                  <p className="text-[10px] text-slate-500">Show player on page</p>
                                </div>
                                <button onClick={() => setEditForm({...editForm, isYoutubeVisible: !editForm.isYoutubeVisible})} className={`p-2 rounded-xl transition-all ${editForm.isYoutubeVisible ? 'bg-primary text-white' : 'bg-slate-200 text-slate-500'}`}>
                                  {editForm.isYoutubeVisible ? <Eye className="w-5 h-5" /> : <EyeOff className="w-5 h-5" />}
                                </button>
                            </div>

                            <div className="flex items-center gap-6 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                                <div className="flex-1">
                                  <p className="text-xs font-black text-slate-800 uppercase tracking-wider">Note Visibility</p>
                                  <p className="text-[10px] text-slate-500">Show note next to title</p>
                                </div>
                                <button onClick={() => setEditForm({...editForm, isNoteVisible: !editForm.isNoteVisible})} className={`p-2 rounded-xl transition-all ${editForm.isNoteVisible ? 'bg-amber-500 text-white' : 'bg-slate-200 text-slate-500'}`}>
                                  {editForm.isNoteVisible ? <Eye className="w-5 h-5" /> : <EyeOff className="w-5 h-5" />}
                                </button>
                            </div>
                          </div>
                        </div>

                        {/* Section 4: Lyrics */}
                        <div className="space-y-6">
                          <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-l-4 border-indigo-500 pl-3">Lyrics Content</h3>
                          <div className="space-y-4">
                              <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-2">Nepali Script</label>
                              <textarea className="w-full h-[400px] border-2 border-slate-100 p-6 rounded-[2rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                          </div>
                          <div className="space-y-4">
                              <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-2">Romanized Version</label>
                              <textarea className="w-full h-[400px] border-2 border-slate-100 p-6 rounded-[2rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all" value={editForm.lyrics_roman} onChange={e => setEditForm({...editForm, lyrics_roman: e.target.value})} />
                          </div>
                        </div>

                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-6 rounded-[2.5rem] font-black text-xl shadow-2xl shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center transform active:scale-95">
                            {isSaving ? <Loader2 className="w-7 h-7 animate-spin mr-3"/> : <Save className="w-7 h-7 mr-3" />}
                            Publish Updates to Library
                        </button>
                    </div>
                ) : (
                    <div className="bg-white rounded-[3rem] shadow-2xl overflow-hidden border border-slate-100 ring-1 ring-slate-200/50">
                        {/* Tab Switcher */}
                        <div className="flex border-b border-slate-100 bg-slate-50/50 no-print">
                            <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'nepali' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Globe className="w-5 h-5" /> Nepali
                            </button>
                            <button onClick={() => setActiveTab('roman')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${activeTab === 'roman' ? 'text-primary border-b-[3px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                <Search className="w-5 h-5" /> Roman Nepali
                            </button>
                        </div>

                        <div className="p-10 md:p-20 relative bg-white min-h-[500px]">
                            {/* Floating Zoom Controls */}
                            <div className="absolute top-6 right-8 flex gap-2 no-print opacity-20 hover:opacity-100 transition-opacity">
                                <button onClick={handleZoomOut} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomOut className="w-5 h-5" /></button>
                                <button onClick={handleZoomIn} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-colors"><ZoomIn className="w-5 h-5" /></button>
                                <button onClick={handleCopy} className={`p-3 rounded-xl transition-all shadow-sm ${copied ? 'bg-green-500 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                                    {copied ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                </button>
                            </div>

                            {/* Centered Lyrics Text */}
                            <div className="max-w-2xl mx-auto">
                                <div 
                                    className="whitespace-pre-wrap leading-[2.2] transition-all font-medium text-slate-800 tracking-wide text-center selection:bg-indigo-100" 
                                    style={{ fontSize: `${fontSize}px` }}
                                >
                                    {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Lyrics not available in Nepali.") : (data.lyrics_roman || "Lyrics not available in Roman Nepali.")}
                                </div>
                            </div>

                            {/* Tools Strip: BELOW Lyrics */}
                            <div className="flex items-center justify-center gap-4 mt-16 pt-10 border-t border-slate-50 no-print">
                                <button onClick={handleFavorite} className={`p-4 rounded-2xl border transition-all ${isFav ? 'bg-red-50 text-red-500 border-red-100 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-200 hover:border-slate-300 shadow-sm'}`} title="Add to Favorites">
                                    <Heart className={`w-6 h-6 ${isFav ? 'fill-current' : ''}`} />
                                </button>
                                <button onClick={handleShare} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-primary transition-all shadow-sm" title="Share Song">
                                    <Share2 className="w-6 h-6" />
                                </button>
                                <button onClick={handlePrint} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-slate-700 transition-all shadow-sm" title="Print Lyrics">
                                    <Printer className="w-6 h-6" />
                                </button>
                                <button onClick={() => setIsFeedbackOpen(true)} className="p-4 bg-slate-50 border border-slate-200 rounded-2xl text-slate-400 hover:text-red-500 transition-all shadow-sm" title="Report Issue">
                                    <Flag className="w-6 h-6" />
                                </button>
                            </div>
                        </div>

                        {/* Branding Footer */}
                        <div className="bg-slate-900/5 p-8 border-t border-slate-100 flex flex-col md:flex-row justify-between items-center gap-6 no-print">
                            <div className="flex items-center gap-3 text-slate-400">
                                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center"><Music className="w-5 h-5 text-indigo-400" /></div>
                                <p className="text-[11px] font-black uppercase tracking-[0.2em]">SansarPlus Verified Library</p>
                            </div>
                            <p className="text-[11px] font-black text-slate-300 uppercase tracking-widest">Worship with us globally</p>
                        </div>
                    </div>
                )}
            </div>

            {/* Sidebar Column */}
            <div className="lg:col-span-4 space-y-10 no-print">

                {/* Song Credits Card */}
                <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 space-y-8 relative overflow-hidden">
                    <h3 className="text-2xl font-black text-slate-900 border-b border-slate-50 pb-5 tracking-tight flex items-center gap-3">
                        <Disc className="w-7 h-7 text-primary" /> Credits & Info
                    </h3>

                    <div className="space-y-6">
                        {(data.singers?.length || data.singer) && renderContributorLinks(data.singers || data.singer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-pink-50 text-pink-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Mic2 className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Vocals By</p>
                                    {renderContributorLinks(data.singers || data.singer)}
                                </div>
                            </div>
                        )}

                        {(data.composers?.length || data.composer) && renderContributorLinks(data.composers || data.composer) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-purple-50 text-purple-500 rounded-xl flex items-center justify-center shrink-0">
                                    <Music className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Composition</p>
                                    {renderContributorLinks(data.composers || data.composer)}
                                </div>
                            </div>
                        )}

                        {(data.lyricists?.length || data.lyricist) && renderContributorLinks(data.lyricists || data.lyricist) && (
                            <div className="flex items-start gap-4">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 rounded-xl flex items-center justify-center shrink-0">
                                    <PenTool className="w-5 h-5" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Words / Lyrics</p>
                                    {renderContributorLinks(data.lyricists || data.lyricist)}
                                </div>
                            </div>
                        )}

                        {/* Fallback if no specific credits exist */}
                        {!(renderContributorLinks(data.composers || data.composer) || 
                           renderContributorLinks(data.lyricists || data.lyricist) || 
                           renderContributorLinks(data.singers || data.singer)) && (
                            <p className="text-xs text-slate-400 italic">No detailed credits available.</p>
                        )}
                    </div>
                </div>

                {/* Official Video Player: BELOW Credits Card */}
                {data.isYoutubeVisible !== false && embedUrl && (
                    <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-100 group">
                        <div className="bg-red-600 px-6 py-4 text-white flex items-center justify-between">
                            <h3 className="font-black text-xs uppercase tracking-widest flex items-center gap-3">
                                <Youtube className="w-6 h-6" /> Official Video
                            </h3>
                            <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
                        </div>
                        <div className="aspect-video relative">
                            <iframe 
                                className="w-full h-full"
                                src={embedUrl}
                                title="Song Video"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                allowFullScreen
                            ></iframe>
                        </div>
                    </div>
                )}

                {/* More Tracks Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 px-2">
                             More tracks <ChevronRight className="w-5 h-5 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-4 bg-white rounded-3xl border border-slate-100 hover:border-primary/30 hover:shadow-xl transition-all group shadow-sm"
                                >
                                    <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-sm truncate group-hover:text-primary transition-colors">
                                            {appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}
                                        </p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">View Lyrics</p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Report Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/10">
                    <div className="bg-primary p-10 text-white text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <Flag className="w-16 h-16 mx-auto mb-5 opacity-80" />
                        <h3 className="text-3xl font-black tracking-tight">Report Error</h3>
                        <p className="text-sm font-medium opacity-80 mt-2">Help keep our library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-5">
                            <div className="w-20 h-20 bg-green-100 text-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-10 h-10" /></div>
                            <h4 className="text-2xl font-black text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 font-medium">Your report has been received.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-10 space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Category of issue</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl font-black text-sm outline-none focus:border-primary cursor-pointer"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue (Typo/Error)</option>
                                    <option>Wrong Credits</option>
                                    <option>Video Link broken</option>
                                    <option>Missing Verse</option>
                                    <option>Other Feedback</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Details</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-5 rounded-[1.5rem] text-sm font-medium outline-none focus:bg-white focus:border-primary transition-all resize-none"
                                    placeholder="Describe the problem..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl shadow-primary/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  Heart, Music, PenTool, Copy, Check, ArrowRight, ZoomIn, ZoomOut, 
  Flag, X, Edit, Save, Printer, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, ChevronRight, Play, Loader2,
  Eye, EyeOff, Trash2, Settings, ChevronDown, ChevronUp, Info, PlayCircle
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  incrementViewCount, 
  getAllCustomSongs, 
  getSongById, 
  submitReport,
  getAllCustomArtists
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';
import ArtistSelector from '../components/ArtistSelector';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [artistData, setArtistData] = useState<ArtistDetails | null>(null);
  const [allArtists, setAllArtists] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(18);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage } = useLanguage();

  // Collapsible sections state
  const [isCreditsOpen, setIsCreditsOpen] = useState(false);
  const [isVideoOpen, setIsVideoOpen] = useState(false);

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const navigate = useNavigate();

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      title: '',
      title_nepali: '',
      artist: '',
      artists: [],
      composer: '',
      composers: [],
      lyricist: '',
      lyricists: [],
      singer: '',
      singers: [],
      lyrics_nepali: '',
      lyrics_roman: '',
      youtubeUrl: '',
      isYoutubeVisible: true,
      note: '',
      isNoteVisible: true,
      language: 'nepali'
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} Lyrics | SansarPlus`;

      const [artistResult, allSongs, artistsList] = await Promise.all([
          getArtistDetails(artistName),
          getAllCustomSongs(),
          getAllCustomArtists()
      ]);

      setData(lyricsResult);
      setArtistData(artistResult);
      setAllArtists(artistsList);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ 
        ...lyricsResult,
        artists: lyricsResult.artists || [lyricsResult.artist],
        composers: lyricsResult.composers || (lyricsResult.composer ? [lyricsResult.composer] : []),
        lyricists: lyricsResult.lyricists || (lyricsResult.lyricist ? [lyricsResult.lyricist] : []),
        singers: lyricsResult.singers || (lyricsResult.singer ? [lyricsResult.singer] : []),
        isYoutubeVisible: lyricsResult.isYoutubeVisible ?? true,
        isNoteVisible: lyricsResult.isNoteVisible ?? true
      });

      setIsFav(isFavorite(generateId('song', songTitle, artistName)));

      // Auto-open video if it exists and is visible
      if (lyricsResult.youtubeUrl && lyricsResult.isYoutubeVisible !== false) {
          setIsVideoOpen(true);
      }

      setLoading(false);
      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${activeTab === 'nepali' ? data.title_nepali || data.title : data.title} Lyrics`,
      text: `Check out the lyrics for "${activeTab === 'nepali' ? data.title_nepali || data.title : data.title}" on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 72));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 8));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          const finalArtist = editForm.artists && editForm.artists.length > 0 ? editForm.artists.join(', ') : (editForm.artist || data.artist);

          await saveCustomSong(finalArtist, editForm.title || data.title, {
              ...editForm,
              artist: finalArtist
          });

          setData({ ...data, ...editForm, artist: finalArtist });
          setIsEditing(false);
          alert("Song updated successfully!");

          if (editForm.title !== data.title || finalArtist !== data.artist) {
              window.location.reload();
          }
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

