                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                                        <div className="space-y-4">
                                            <div className="flex items-center gap-3 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-50 pb-2">
                                                <Mic2 className="w-3.5 h-3.5" /> Vocalists
                                            </div>
                                            <div>{renderContributorLinks(data.singers || data.singer) || <span className="text-sm text-slate-400 italic">Unknown</span>}</div>
