                                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-2">Romanized Title</label>
                                  <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                              </div>
                              <div className="space-y-2">
                                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-2">Nepali Title</label>
                                  <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title_nepali} onChange={e => setEditForm({...editForm, title_nepali: e.target.value})} placeholder="Title in native script..." />
