                                <button onClick={() => setActiveTab('roman')} className={`flex-1 py-6 font-black text-xs md:text-sm uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3 ${activeTab === 'roman' ? 'text-primary border-b-[4px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
