                                        <Printer className="w-4 h-4" /> Print PDF
                                    </button>
                                    <button onClick={() => setIsFeedbackOpen(true)} className="flex items-center gap-2 px-6 py-3 bg-red-50/30 text-red-400 rounded-2xl font-bold text-sm hover:bg-red-50 transition-all border border-red-100/50">
                                        <Flag className="w-4 h-4" /> Report Issue
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* Collapsible Video Section */}
                        {data.isYoutubeVisible !== false && embedUrl && (
