                                  className="flex flex-col items-center justify-center gap-3 p-6 rounded-3xl bg-slate-50 text-slate-600 hover:bg-slate-600 hover:text-white transition-all group border border-slate-200 shadow-sm"
                                >
                                    <LinkIcon className="w-8 h-8 group-hover:scale-110 transition-transform" />
                                    <span className="text-xs font-bold uppercase tracking-wider">Copy Link</span>
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* Sidebar Column */}
            <div className="lg:col-span-4 space-y-10 no-print">
                {/* Related Tracks Section */}
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-xl font-black text-slate-900 flex items-center gap-3 px-2">
                             More tracks <ChevronRight className="w-5 h-5 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-4 p-4 bg-white rounded-[2rem] border border-slate-200 hover:border-primary/40 hover:shadow-xl transition-all group shadow-sm"
                                >
                                    <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                        <Music className="w-5 h-5" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-sm truncate group-hover:text-primary transition-colors">
                                            {appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}
                                        </p>
                                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest flex items-center gap-1">
                                            <PlayCircle className="w-3 h-3" /> View Lyrics
                                        </p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Feedback Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
                    <div className="bg-primary p-10 text-white text-center relative">
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-2 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <h3 className="text-3xl font-black tracking-tight">Report Issue</h3>
                        <p className="text-sm font-medium opacity-80 mt-2">Help keep our library accurate</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-5">
                            <div className="w-20 h-20 bg-green-100 text-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-10 h-10" /></div>
                            <h4 className="text-2xl font-black text-slate-900">Thank You!</h4>
                            <p className="text-slate-500 font-medium">Your message was received.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-10 space-y-8">
                            <select 
                                className="w-full bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl font-black text-sm outline-none focus:border-primary"
                                value={feedbackType}
                                onChange={(e) => setFeedbackType(e.target.value)}
                            >
                                <option>Lyrics Issue</option>
                                <option>Wrong Credits</option>
                                <option>Broken Video</option>
                                <option>Other Feedback</option>
                            </select>
                            <textarea 
                                required
                                className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-5 rounded-[1.5rem] text-sm font-medium outline-none focus:bg-white focus:border-primary"
                                placeholder="Details..."
                                value={feedbackText}
                                onChange={(e) => setFeedbackText(e.target.value)}
                            ></textarea>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-5 rounded-[2rem] font-black text-lg shadow-2xl hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Sending...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

