  getAllCustomArtists
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';
import ArtistSelector from '../components/ArtistSelector';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [allArtists, setAllArtists] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(20);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage, t } = useLanguage();

  const [isCreditsOpen, setIsCreditsOpen] = useState(true);
  const [isVideoOpen, setIsVideoOpen] = useState(false);

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      title: '',
      title_nepali: '',
      artist: '',
      artists: [],
      composer: '',
      composers: [],
      lyricist: '',
      lyricists: [],
      singer: '',
      singers: [],
      lyrics_nepali: '',
      lyrics_roman: '',
      youtubeUrl: '',
      isYoutubeVisible: true,
      note: '',
      isNoteVisible: true,
      language: 'nepali'
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} Lyrics | SansarPlus`;

      const [allSongs, artistsList] = await Promise.all([
          getAllCustomSongs(),
          getAllCustomArtists()
      ]);

      setData(lyricsResult);
      setAllArtists(artistsList);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ 
        ...lyricsResult,
        artists: lyricsResult.artists || [lyricsResult.artist],
        composers: lyricsResult.composers || (lyricsResult.composer ? [lyricsResult.composer] : []),
        lyricists: lyricsResult.lyricists || (lyricsResult.lyricist ? [lyricsResult.lyricist] : []),
        singers: lyricsResult.singers || (lyricsResult.singer ? [lyricsResult.singer] : []),
        isYoutubeVisible: lyricsResult.isYoutubeVisible ?? true,
        isNoteVisible: lyricsResult.isNoteVisible ?? true
      });

      setIsFav(isFavorite(generateId('song', songTitle, artistName)));

      if (lyricsResult.youtubeUrl && lyricsResult.isYoutubeVisible !== false) {
          setIsVideoOpen(true);
      }

      setLoading(false);
      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const shareToFB = () => {
    window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(window.location.href)}`, '_blank');
  };

  const shareToWA = () => {
    const text = `Check out the lyrics for "${appLanguage === 'nepali' ? data?.title_nepali || data?.title : data?.title}" on SansarPlus: ${window.location.href}`;
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${appLanguage === 'nepali' ? data.title_nepali || data.title : data.title} Lyrics`,
      text: `Check out the lyrics for "${appLanguage === 'nepali' ? data.title_nepali || data.title : data.title}" on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 72));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 10));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          const finalArtist = editForm.artists && editForm.artists.length > 0 ? editForm.artists.join(', ') : (editForm.artist || data.artist);

          await saveCustomSong(finalArtist, editForm.title || data.title, {
              ...editForm,
              artist: finalArtist
          });

          setData({ ...data, ...editForm, artist: finalArtist });
          setIsEditing(false);
          alert("Song updated successfully!");

          if (editForm.title !== data.title || finalArtist !== data.artist) {
              window.location.reload();
          }
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  const renderContributorLinks = (names: string[] | string | undefined) => {
      if (!names) return null;
      const nameList = (Array.isArray(names) ? names : names.split(','))
        .map(s => s.trim())
        .filter(s => s && s.toLowerCase() !== 'unknown');

      if (nameList.length === 0) return null;

      return (
          <div className="flex flex-wrap gap-2">
              {nameList.map((name, i) => (
                  <React.Fragment key={name}>
                      <Link 
                        to={`/artist/${encodeURIComponent(name)}`} 
                        className="text-sm font-bold text-slate-800 hover:text-primary transition-colors bg-slate-50 px-3 py-1 rounded-lg border border-slate-100 hover:border-primary/20"
                      >
                        {name}
                      </Link>
                  </React.Fragment>
              ))}
          </div>
      );
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  const displayTitle = appLanguage === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  const singersContent = renderContributorLinks(data.singers || data.singer);
  const composersContent = renderContributorLinks(data.composers || data.composer);
  const lyricistsContent = renderContributorLinks(data.lyricists || data.lyricist);
  const hasCredits = !!(singersContent || composersContent || lyricistsContent);

  return (
    <div className="min-h-screen bg-slate-50 pb-32 selection:bg-primary/10 selection:text-primary">
      {/* Distraction-free Hero Section */}
      <div className="bg-white border-b border-slate-200 pt-20 pb-16 no-print overflow-hidden relative">
        <div className="absolute top-0 right-0 w-64 h-64 bg-primary/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="max-w-4xl mx-auto px-4 text-center relative z-10 space-y-6">
            {data.note && data.isNoteVisible !== false && (
                <div className="flex justify-center">
                    <span className="bg-amber-50 text-amber-600 px-5 py-2 rounded-full text-[11px] font-black uppercase tracking-[0.15em] border border-amber-100 flex items-center gap-2 shadow-sm animate-in slide-in-from-top-2">
                        <StickyNote className="w-4 h-4" /> {data.note}
                    </span>
                </div>
            )}
            <h1 className="text-4xl md:text-6xl font-black text-slate-900 leading-[1.1] tracking-tight">{displayTitle}</h1>

            <div className="flex items-center justify-center gap-3 pt-4">
                {canEdit && (
                    <button 
                      onClick={() => setIsEditing(!isEditing)} 
                      className={`p-4 rounded-2xl transition-all shadow-xl border flex items-center gap-2 font-bold ${isEditing ? 'bg-slate-800 text-white border-slate-700' : 'bg-white text-slate-700 border-slate-200 hover:border-primary/30'}`}
                    >
                        {isEditing ? <><X className="w-5 h-5" /> Finish</> : <><Edit className="w-5 h-5" /> Edit Song</>}
                    </button>
                )}
            </div>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 mt-12">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* Main Content Area */}
            <div className="lg:col-span-8 space-y-10">

                {isEditing ? (
                    <div className="bg-white rounded-[3rem] p-8 md:p-12 shadow-2xl border border-slate-200 space-y-12 animate-in slide-in-from-bottom-4">
                        <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                          <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center shadow-inner"><Settings className="w-6 h-6" /></div>
                          <h2 className="text-3xl font-black text-slate-800">Song Editor</h2>
                        </div>

                        {/* Informational Sections */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                            <div className="space-y-6">
                              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-l-4 border-primary pl-3">Lyrics Header</h3>
                              <div className="space-y-4">
                                  <div className="space-y-1.5">
                                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Roman Title</label>
                                      <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                                  </div>
                                  <div className="space-y-1.5">
                                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Nepali Title</label>
                                      <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title_nepali} onChange={e => setEditForm({...editForm, title_nepali: e.target.value})} placeholder="Title in native script..." />
                                  </div>
                                  <div className="pt-2">
                                    <ArtistSelector label="Main Artist(s)" selected={editForm.artists || []} onChange={arts => setEditForm({...editForm, artists: arts})} suggestions={allArtists} />
                                  </div>
                              </div>
                            </div>

                            <div className="space-y-6">
                              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-l-4 border-amber-500 pl-3">Media & Settings</h3>
                              <div className="space-y-4">
                                  <div className="space-y-1.5">
                                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">YouTube URL</label>
                                      <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.youtubeUrl} onChange={e => setEditForm({...editForm, youtubeUrl: e.target.value})} placeholder="https://..." />
                                  </div>
                                  <div className="space-y-1.5">
                                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Song Note</label>
                                      <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.note} onChange={e => setEditForm({...editForm, note: e.target.value})} placeholder="e.g. (Worship Mix)" />
                                  </div>
                                  <div className="grid grid-cols-2 gap-3">
                                      <button onClick={() => setEditForm({...editForm, isYoutubeVisible: !editForm.isYoutubeVisible})} className={`flex items-center justify-center gap-2 p-4 rounded-2xl border transition-all font-bold text-xs uppercase tracking-widest ${editForm.isYoutubeVisible ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>
                                          {editForm.isYoutubeVisible ? <><Eye className="w-4 h-4" /> Video On</> : <><EyeOff className="w-4 h-4" /> Video Off</>}
                                      </button>
                                      <button onClick={() => setEditForm({...editForm, isNoteVisible: !editForm.isNoteVisible})} className={`flex items-center justify-center gap-2 p-4 rounded-2xl border transition-all font-bold text-xs uppercase tracking-widest ${editForm.isNoteVisible ? 'bg-amber-50 text-amber-600 border-amber-100' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>
                                          {editForm.isNoteVisible ? <><Eye className="w-4 h-4" /> Note On</> : <><EyeOff className="w-4 h-4" /> Note Off</>}
                                      </button>
                                  </div>
                              </div>
                            </div>
                        </div>

                        {/* Contributor Grids */}
                        <div className="space-y-6">
                          <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-l-4 border-emerald-500 pl-3">Credits & Contributors</h3>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <ArtistSelector label="Singers / Vocals" selected={editForm.singers || []} onChange={v => setEditForm({...editForm, singers: v})} suggestions={allArtists} />
                            <ArtistSelector label="Composers" selected={editForm.composers || []} onChange={v => setEditForm({...editForm, composers: v})} suggestions={allArtists} />
                            <ArtistSelector label="Lyricists" selected={editForm.lyricists || []} onChange={v => setEditForm({...editForm, lyricists: v})} suggestions={allArtists} />
                          </div>
                        </div>

                        {/* Lyrics Body */}
                        <div className="space-y-8">
                          <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-l-4 border-slate-900 pl-3">Lyrics Content</h3>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                              <div className="space-y-3">
                                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-2">Native Script (Nepali)</label>
                                  <textarea className="w-full h-[500px] border-2 border-slate-100 p-6 rounded-[2.5rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all shadow-inner" value={editForm.lyrics_nepali} onChange={e => setEditForm({...editForm, lyrics_nepali: e.target.value})} />
                              </div>
                              <div className="space-y-3">
                                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-2">Romanized Script</label>
                                  <textarea className="w-full h-[500px] border-2 border-slate-100 p-6 rounded-[2.5rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all shadow-inner" value={editForm.lyrics_roman} onChange={e => setEditForm({...editForm, lyrics_roman: e.target.value})} />
                              </div>
                          </div>
                        </div>

                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-6 rounded-[2.5rem] font-black text-2xl shadow-2xl shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center transform active:scale-[0.98]">
                            {isSaving ? <Loader2 className="w-8 h-8 animate-spin mr-3"/> : <Save className="w-8 h-8 mr-3" />}
                            Publish Song Updates
                        </button>
                    </div>
                ) : (
                    <div className="space-y-8">
                        {/* Interactive Lyrics Card */}
                        <div className="bg-white rounded-[3rem] shadow-xl overflow-hidden border border-slate-200">
                            {/* Toolbar & Tabs */}
                            <div className="flex flex-col md:flex-row border-b border-slate-100">
                                <div className="flex-1 flex bg-slate-50/50 no-print">
                                    <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-6 font-black text-xs uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3 ${activeTab === 'nepali' ? 'text-primary border-b-[4px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                        <Globe className="w-5 h-5" /> Nepali
                                    </button>
                                    <button onClick={() => setActiveTab('roman')} className={`flex-1 py-6 font-black text-xs uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3 ${activeTab === 'roman' ? 'text-primary border-b-[4px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                        <Search className="w-5 h-5" /> Roman Nepali
                                    </button>
                                </div>
                                <div className="p-3 md:p-4 bg-white flex items-center justify-center gap-2 border-t md:border-t-0 md:border-l border-slate-100 no-print">
                                    <div className="flex items-center bg-slate-50 rounded-2xl p-1 border border-slate-200">
                                        <button onClick={handleZoomOut} className="p-2.5 text-slate-400 hover:text-primary transition-colors"><ZoomOut className="w-5 h-5" /></button>
                                        <span className="text-[10px] font-black text-slate-300 mx-2">{fontSize}</span>
                                        <button onClick={handleZoomIn} className="p-2.5 text-slate-400 hover:text-primary transition-colors"><ZoomIn className="w-5 h-5" /></button>
                                    </div>
                                    <button 
                                      onClick={handleFavorite} 
                                      className={`p-3.5 rounded-2xl transition-all shadow-sm border ${isFav ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-slate-400 border-slate-200 hover:border-red-200 hover:text-red-400'}`}
                                      title="Add to Favorites"
                                    >
                                        <Heart className={`w-5 h-5 ${isFav ? 'fill-current' : ''}`} />
                                    </button>
                                    <button 
                                      onClick={handleCopy} 
                                      className={`p-3.5 rounded-2xl transition-all shadow-sm border ${copied ? 'bg-emerald-500 text-white border-emerald-400 shadow-emerald-200' : 'bg-white text-slate-400 border-slate-200 hover:border-primary/30 hover:text-primary'}`}
                                      title="Copy Lyrics"
                                    >
                                        {copied ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                                    </button>
                                </div>
                            </div>

                            <div className="p-10 md:p-24 relative bg-white min-h-[500px]">
                                {/* Lyrics Body */}
                                <div className="max-w-2xl mx-auto">
                                    <div 
                                        className="whitespace-pre-wrap leading-[2.2] transition-all font-medium text-slate-800 tracking-wide text-center selection:bg-primary/10" 
                                        style={{ fontSize: `${fontSize}px` }}
                                    >
                                        {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Nepali lyrics unavailable.") : (data.lyrics_roman || "Romanized lyrics unavailable.")}
                                    </div>
                                </div>

                                {/* Action Buttons Footer */}
                                <div className="mt-24 pt-12 border-t border-slate-50 flex flex-wrap justify-center gap-5 no-print">
                                    <button onClick={handlePrint} className="flex items-center gap-3 px-8 py-4 bg-slate-50 text-slate-600 rounded-[1.5rem] font-bold text-sm hover:bg-slate-100 transition-all border border-slate-200 shadow-sm group">
                                        <Printer className="w-5 h-5 group-hover:scale-110 transition-transform" /> Print to PDF
                                    </button>
                                    <button onClick={() => setIsFeedbackOpen(true)} className="flex items-center gap-3 px-8 py-4 bg-red-50/30 text-red-500 rounded-[1.5rem] font-bold text-sm hover:bg-red-50 transition-all border border-red-100/50 group">
                                        <Flag className="w-5 h-5 group-hover:rotate-12 transition-transform" /> Report Issue
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* High-Impact Credits Section */}
                        {hasCredits && (
                            <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-lg border border-slate-200 no-print transition-all">
                                <button 
                                    onClick={() => setIsCreditsOpen(!isCreditsOpen)}
                                    className="w-full flex items-center justify-between p-8 hover:bg-slate-50 transition-colors group"
                                >
                                    <div className="flex items-center gap-5">
                                        <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${isCreditsOpen ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'bg-slate-50 text-slate-400'}`}>
                                            <Info className="w-7 h-7" />
                                        </div>
                                        <div className="text-left">
                                            <h3 className="text-xl font-black text-slate-800 tracking-tight">Song Credits</h3>
                                            <p className="text-xs text-slate-500 font-bold uppercase tracking-wider">Vocals, Composition & Words</p>
                                        </div>
                                    </div>
                                    <div className={`w-10 h-10 rounded-full bg-slate-50 flex items-center justify-center transition-transform duration-300 ${isCreditsOpen ? 'rotate-180' : ''}`}>
                                        <ChevronDown className="w-5 h-5 text-slate-400" />
                                    </div>
                                </button>

                                {isCreditsOpen && (
                                    <div className="px-10 pb-12 animate-in fade-in slide-in-from-top-2">
                                        <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                                            {singersContent && (
                                                <div className="space-y-5">
                                                    <div className="flex items-center gap-3 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b border-slate-50 pb-3">
                                                        <Mic2 className="w-4 h-4 text-primary" /> Vocalists
