                                            <Youtube className="w-7 h-7" />
                                        </div>
                                        <div className="text-left">
                                            <h3 className="text-xl font-black text-slate-800 tracking-tight">Watch Official Video</h3>
                                            <p className="text-xs text-slate-500 font-bold uppercase tracking-wider">Follow with music</p>
