                                {isVideoOpen && (
                                    <div className="p-4 md:p-10 pt-0 animate-in zoom-in-95 duration-300">
                                        <div className="aspect-video rounded-[2.5rem] overflow-hidden shadow-2xl bg-slate-900 border-8 border-slate-50">
                                            <iframe 
                                                className="w-full h-full"
                                                src={`${embedUrl}?autoplay=0&rel=0`}
