                            <div className="grid grid-cols-2 md:grid-cols-4 gap-5">
                                <button onClick={shareToFB} className="flex flex-col items-center gap-3 p-6 rounded-3xl bg-blue-50 text-blue-600 hover:bg-blue-600 hover:text-white transition-all group border border-blue-100 shadow-sm active:scale-95">
