                                <button onClick={() => { navigator.clipboard.writeText(window.location.href); alert("Link copied!"); }} className="flex flex-col items-center gap-3 p-6 rounded-3xl bg-slate-50 text-slate-600 hover:bg-slate-800 hover:text-white transition-all group border border-slate-200 shadow-sm active:scale-95">
                                    <LinkIcon className="w-8 h-8 group-hover:scale-110 transition-transform" />
                                    <span className="text-[10px] font-black uppercase tracking-widest">Copy Link</span>
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* Premium Sidebar */}
            <div className="lg:col-span-4 space-y-10 no-print">
                {relatedSongs.length > 0 && (
                    <div className="space-y-6">
                        <h3 className="text-2xl font-black text-slate-900 flex items-center gap-3 px-2 tracking-tight">
                             Artist Tracks <ChevronRight className="w-6 h-6 text-primary" />
                        </h3>
                        <div className="space-y-3">
                            {relatedSongs.map((song) => (
                                <Link 
                                    key={song.id} 
                                    to={`/l/${song.id}`}
                                    className="flex items-center gap-5 p-5 bg-white rounded-[2rem] border border-slate-200 hover:border-primary/40 hover:shadow-xl transition-all group shadow-sm"
                                >
                                    <div className="w-14 h-14 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300 group-hover:bg-primary/10 group-hover:text-primary transition-all shadow-inner">
                                        <Music className="w-6 h-6" />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="font-black text-slate-800 text-base truncate group-hover:text-primary transition-colors">
                                            {appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}
                                        </p>
                                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1 flex items-center gap-1.5">
                                            <PlayCircle className="w-3.5 h-3.5" /> Read Lyrics
                                        </p>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                )}

                {/* Visual Accent Box */}
                <div className="bg-gradient-to-br from-indigo-600 to-purple-700 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-10 -mt-10 blur-2xl group-hover:bg-white/20 transition-all"></div>
                    <Disc className="w-12 h-12 text-white/20 mb-6 group-hover:rotate-90 transition-transform duration-700" />
                    <h4 className="text-xl font-black mb-2 tracking-tight">Support Library</h4>
                    <p className="text-indigo-100 text-sm leading-relaxed font-medium">Your contributions and reports help us build the most accurate archive for worship.</p>
                </div>
            </div>
        </div>

        {/* Improved Feedback Modal */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-300">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
                    <div className="bg-primary p-12 text-white text-center relative overflow-hidden">
                        <div className="absolute inset-0 bg-gradient-to-br from-white/10 to-transparent"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-3 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <h3 className="text-4xl font-black tracking-tight relative z-10">Report Issue</h3>
                        <p className="text-sm font-bold uppercase tracking-widest opacity-80 mt-3 relative z-10">Maintain Database Quality</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-6">
                            <div className="w-24 h-24 bg-emerald-50 text-emerald-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><Check className="w-12 h-12" /></div>
                            <h4 className="text-3xl font-black text-slate-900">Message Sent!</h4>
                            <p className="text-slate-500 font-medium">Our moderation team will review this shortly.</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-12 space-y-8">
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Issue Category</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-5 rounded-2xl font-black text-sm outline-none focus:border-primary appearance-none cursor-pointer"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue</option>
                                    <option>Wrong Credits</option>
                                    <option>Broken Video</option>
                                    <option>Typo Error</option>
                                </select>
                            </div>
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Describe the Error</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-6 rounded-[2rem] text-sm font-medium outline-none focus:bg-white focus:border-primary shadow-inner resize-none"
                                    placeholder="Please be specific about what needs fixing..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-primary text-white py-6 rounded-[2.2rem] font-black text-xl shadow-2xl hover:bg-indigo-700 active:scale-95 transition-all disabled:opacity-50"
                            >
                                {isSubmittingFeedback ? 'Processing...' : 'Submit Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  Heart, Music, PenTool, Copy, Check, ZoomIn, ZoomOut, 
  Flag, X, Edit, Save, Printer, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, ChevronRight, Loader2,
  Eye, EyeOff, Settings, ChevronDown, ChevronUp, Info, PlayCircle,
  Facebook, MessageCircle, Link as LinkIcon, Send
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  incrementViewCount, 
  getAllCustomSongs, 
  getSongById, 
  submitReport,
  getAllCustomArtists
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';
import ArtistSelector from '../components/ArtistSelector';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [allArtists, setAllArtists] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(20);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage, t } = useLanguage();

  const [isCreditsOpen, setIsCreditsOpen] = useState(true);
  const [isVideoOpen, setIsVideoOpen] = useState(false);

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      title: '',
      title_nepali: '',
      artist: '',
      artists: [],
      composer: '',
      composers: [],
      lyricist: '',
      lyricists: [],
      singer: '',
      singers: [],
      lyrics_nepali: '',
      lyrics_roman: '',
      youtubeUrl: '',
      isYoutubeVisible: true,
      note: '',
      isNoteVisible: true,
      language: 'nepali'
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} Lyrics | SansarPlus`;

      const [allSongs, artistsList] = await Promise.all([
          getAllCustomSongs(),
          getAllCustomArtists()
      ]);

      setData(lyricsResult);
      setAllArtists(artistsList);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ 
        ...lyricsResult,
        artists: lyricsResult.artists || [lyricsResult.artist],
        composers: lyricsResult.composers || (lyricsResult.composer ? [lyricsResult.composer] : []),
        lyricists: lyricsResult.lyricists || (lyricsResult.lyricist ? [lyricsResult.lyricist] : []),
        singers: lyricsResult.singers || (lyricsResult.singer ? [lyricsResult.singer] : []),
        isYoutubeVisible: lyricsResult.isYoutubeVisible ?? true,
        isNoteVisible: lyricsResult.isNoteVisible ?? true
      });

      setIsFav(isFavorite(generateId('song', songTitle, artistName)));

      if (lyricsResult.youtubeUrl && lyricsResult.isYoutubeVisible !== false) {
          setIsVideoOpen(true);
      }

      setLoading(false);
      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const shareToFB = () => {
    window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(window.location.href)}`, '_blank');
  };

  const shareToWA = () => {
    const text = `Check out the lyrics for "${appLanguage === 'nepali' ? data?.title_nepali || data?.title : data?.title}" on SansarPlus: ${window.location.href}`;
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${appLanguage === 'nepali' ? data.title_nepali || data.title : data.title} Lyrics`,
      text: `Check out the lyrics for "${appLanguage === 'nepali' ? data.title_nepali || data.title : data.title}" on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 72));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 10));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          const finalArtist = editForm.artists && editForm.artists.length > 0 ? editForm.artists.join(', ') : (editForm.artist || data.artist);

          await saveCustomSong(finalArtist, editForm.title || data.title, {
              ...editForm,
              artist: finalArtist
          });

          setData({ ...data, ...editForm, artist: finalArtist });
          setIsEditing(false);
          alert("Song updated successfully!");

          if (editForm.title !== data.title || finalArtist !== data.artist) {
              window.location.reload();
          }
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  const renderContributorLinks = (names: string[] | string | undefined) => {
      if (!names) return null;
      const nameList = (Array.isArray(names) ? names : names.split(','))
        .map(s => s.trim())
        .filter(s => s && s.toLowerCase() !== 'unknown');

      if (nameList.length === 0) return null;

      return (
          <div className="flex flex-wrap gap-2">
              {nameList.map((name, i) => (
                  <React.Fragment key={name}>
                      <Link 
                        to={`/artist/${encodeURIComponent(name)}`} 
                        className="text-sm font-bold text-slate-800 hover:text-primary transition-colors bg-slate-50 px-3 py-1 rounded-lg border border-slate-100 hover:border-primary/20"
                      >
                        {name}
                      </Link>
                  </React.Fragment>
              ))}
          </div>
      );
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  const displayTitle = appLanguage === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  const singersContent = renderContributorLinks(data.singers || data.singer);
  const composersContent = renderContributorLinks(data.composers || data.composer);
  const lyricistsContent = renderContributorLinks(data.lyricists || data.lyricist);
  const hasCredits = !!(singersContent || composersContent || lyricistsContent);

  return (
    <div className="min-h-screen bg-slate-50 pb-32 selection:bg-primary/10 selection:text-primary">
      {/* Distraction-free Hero Section - Reduced padding and gaps */}
      <div className="bg-white border-b border-slate-200 pt-10 pb-8 no-print overflow-hidden relative">
        <div className="absolute top-0 right-0 w-64 h-64 bg-primary/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="max-w-4xl mx-auto px-4 text-center relative z-10 space-y-3">
            {data.note && data.isNoteVisible !== false && (
                <div className="flex justify-center">
                    <span className="bg-amber-50 text-amber-600 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-[0.12em] border border-amber-100 flex items-center gap-1.5 shadow-sm animate-in slide-in-from-top-2">
                        <StickyNote className="w-3.5 h-3.5" /> {data.note}
                    </span>
                </div>
            )}
            <h1 className="text-3xl md:text-5xl lg:text-6xl font-black text-slate-900 leading-[1.1] tracking-tight">{displayTitle}</h1>

            <div className="flex items-center justify-center gap-3 pt-2">
                {canEdit && (
                    <button 
                      onClick={() => setIsEditing(!isEditing)} 
                      className={`p-3 md:p-4 rounded-2xl transition-all shadow-xl border flex items-center gap-2 font-bold text-sm ${isEditing ? 'bg-slate-800 text-white border-slate-700' : 'bg-white text-slate-700 border-slate-200 hover:border-primary/30'}`}
                    >
                        {isEditing ? <><X className="w-4 h-4" /> Finish</> : <><Edit className="w-4 h-4" /> Edit Song</>}
                    </button>
                )}
            </div>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 mt-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

            {/* Main Content Area */}
            <div className="lg:col-span-8 space-y-10">

                {isEditing ? (
                    <div className="bg-white rounded-[3rem] p-8 md:p-12 shadow-2xl border border-slate-200 space-y-12 animate-in slide-in-from-bottom-4">
                        <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                          <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center shadow-inner"><Settings className="w-6 h-6" /></div>
                          <h2 className="text-3xl font-black text-slate-800">Song Editor</h2>
                        </div>

                        {/* Informational Sections */}
