                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* Sidebar: Integrated Player & Recommendations */}
            <div className="lg:col-span-4 space-y-10 no-print">
                {/* Modern Media Hub Sticky Sidebar */}
                <div className="sticky top-24 space-y-10">

                    {/* Integrated YouTube Player Card */}
                    {data.isYoutubeVisible !== false && embedUrl ? (
                        <div className="bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-800 ring-4 ring-white shadow-indigo-900/10 group/player">
                            <div className="p-5 flex items-center justify-between border-b border-white/5 bg-slate-900/50 backdrop-blur-md">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 bg-red-600 text-white rounded-xl flex items-center justify-center shadow-lg shadow-red-600/20">
                                        <Youtube className="w-5 h-5" />
