        isYoutubeVisible: lyricsResult.isYoutubeVisible ?? true,
        isNoteVisible: lyricsResult.isNoteVisible ?? true
      });

      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);
      incrementViewCount(artistName, songTitle);
    };

    fetchData();
