                                  <textarea className="w-full h-[600px] border-2 border-slate-100 p-6 rounded-[2.5rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all shadow-inner" value={editForm.lyrics_nepali} onChange={e => setEditForm(prev => ({...prev, lyrics_nepali: e.target.value}))} />
