// A lightweight phonetic mapper for Roman to Nepali Unicode and vice-versa

const VOWELS: Record<string, string> = {
  'a': 'अ', 'aa': 'आ', 'i': 'इ', 'ee': 'ई', 'u': 'उ', 'oo': 'ऊ',
  'e': 'ए', 'ai': 'ऐ', 'o': 'ओ', 'au': 'औ', 'am': 'अं', 'an': 'अँ', 'ri': 'ऋ'
};

const MATRAS: Record<string, string> = {
  'a': '', 'aa': 'ा', 'i': 'ि', 'ee': 'ी', 'u': 'ु', 'oo': 'ू',
  'e': 'े', 'ai': 'ै', 'o': 'ो', 'au': 'ौ', 'am': 'ं', 'an': 'ँ', 'ri': 'ृ'
};

const CONSONANTS: Record<string, string> = {
  'k': 'क', 'kh': 'ख', 'g': 'ग', 'gh': 'घ', 'ng': 'ङ',
  'ch': 'च', 'chh': 'छ', 'j': 'ज', 'jh': 'झ', 'yn': 'ञ',
  't': 'ट', 'th': 'ठ', 'd': 'ड', 'dh': 'ढ', 'n': 'ण',
  'T': 'त', 'Th': 'थ', 'D': 'द', 'Dh': 'ध', 'N': 'न',
  'p': 'प', 'ph': 'फ', 'f': 'फ', 'b': 'ब', 'bh': 'भ', 'm': 'म',
  'y': 'य', 'r': 'र', 'l': 'ल', 'v': 'व', 'w': 'व',
  'sh': 'श', 'Sh': 'ष', 's': 'स', 'h': 'ह',
  'gy': 'ज्ञ', 'tr': 'त्र', 'ksh': 'क्ष'
};

// Reverse Mappings for Romanization
const ROMAN_CONSONANTS: Record<string, string> = {
  'क': 'ka', 'ख': 'kha', 'ग': 'ga', 'घ': 'gha', 'ङ': 'nga',
  'च': 'cha', 'छ': 'chha', 'ज': 'ja', 'झ': 'jha', 'ञ': 'yna',
  'ट': 'Ta', 'ठ': 'Tha', 'ड': 'Da', 'ढ': 'Dha', 'ण': 'Na',
  'त': 'ta', 'थ': 'tha', 'द': 'da', 'ध': 'dha', 'न': 'na',
  'प': 'pa', 'फ': 'pha', 'ब': 'ba', 'भ': 'bha', 'म': 'ma',
  'य': 'ya', 'र': 'ra', 'ल': 'la', 'व': 'va',
  'श': 'sha', 'ष': 'Sha', 'स': 'sa', 'ह': 'ha',
  'ज्ञ': 'gya', 'त्र': 'tra', 'क्ष': 'ksha'
};

const ROMAN_MATRAS: Record<string, string> = {
  'ा': 'aa', 'ि': 'i', 'ी': 'ee', 'ु': 'u', 'ू': 'oo',
  'े': 'e', 'ै': 'ai', 'ो': 'o', 'ौ': 'au', 'ं': 'am', 'ँ': 'an', 'ृ': 'ri'
};

const ROMAN_VOWELS: Record<string, string> = {
  'अ': 'a', 'आ': 'aa', 'इ': 'i', 'ई': 'ee', 'उ': 'u', 'ऊ': 'oo',
  'ए': 'e', 'ऐ': 'ai', 'ओ': 'o', 'औ': 'au', 'अं': 'am', 'अँ': 'an', 'ऋ': 'ri'
};

// Reverse map to check if a char is a Nepali consonant
const NEPALI_CONSONANTS = new Set(Object.keys(ROMAN_CONSONANTS));

export const convertToNepali = (text: string): string => {
  if (!text) return "";

  let result = "";
  let i = 0;

  while (i < text.length) {
    let handled = false;
    const char = text[i];

    if (!/[a-zA-Z]/.test(char)) {
        if (char === '|') result += '।';
        else result += char;
        i++;
        continue;
    }

    let consonant = "";
    let cLen = 0;

    for (let len = 3; len > 0; len--) {
        const sub = text.substring(i, i + len).toLowerCase();
        let found = '';
        if (len === 1) {
             if (text[i] === 't') found = 'त';
             else if (text[i] === 'T') found = 'ट';
             else if (text[i] === 'd') found = 'द';
             else if (text[i] === 'D') found = 'ड';
             else if (text[i] === 'n') found = 'न';
             else if (text[i] === 'N') found = 'ण';
             else if (text[i] === 's') found = 'स';
             else if (text[i] === 'S') found = 'ष';
        } 
        if (!found) found = CONSONANTS[sub]; 
        if (found) {
            consonant = found;
            cLen = len;
            break;
        }
    }

    if (consonant) {
        i += cLen;
        let matra = "";
        let mLen = 0;
        let hasVowel = false;

        for (let len = 2; len > 0; len--) {
            if (i + len <= text.length) {
                const sub = text.substring(i, i + len).toLowerCase();
                if (MATRAS[sub] !== undefined) {
                    matra = MATRAS[sub];
                    mLen = len;
                    hasVowel = true;
                    break;
                }
            }
        }

        if (hasVowel) {
            result += consonant + matra;
            i += mLen;
        } else {
            let nextIsConsonant = false;
            if (i < text.length) {
                const nextChar = text[i];
                if (/[a-zA-Z]/.test(nextChar) && !VOWELS[nextChar.toLowerCase()]) {
                     nextIsConsonant = true;
                }
            }
            if (nextIsConsonant) {
                result += consonant + '्';
            } else {
                result += consonant; 
            }
        }
        handled = true;
    } 

    if (!handled) {
        let vowel = "";
        let matra = "";
        let vLen = 0;
        for (let len = 2; len > 0; len--) {
            const sub = text.substring(i, i + len).toLowerCase();
            if (VOWELS[sub]) {
                vowel = VOWELS[sub];
                matra = MATRAS[sub] !== undefined ? MATRAS[sub] : "";
                vLen = len;
                break;
            }
        }
        if (vLen > 0) {
            const lastChar = result.slice(-1);
            let effectiveLastChar = lastChar;
            if (lastChar === '्') {
                effectiveLastChar = result.slice(-2, -1);
            }
            if (NEPALI_CONSONANTS.has(effectiveLastChar)) {
                result += matra;
            } else {
                result += vowel;
            }
            i += vLen;
            handled = true;
        }
    }

    if (!handled) {
        result += text[i];
        i++;
    }
  }
  return result;
};

export const convertToRoman = (text: string): string => {
  if (!text) return "";
  let result = "";
  let i = 0;

  while (i < text.length) {
    const char = text[i];
    const nextChar = text[i+1];

    // 1. Standalone Vowels
    if (ROMAN_VOWELS[char]) {
      result += ROMAN_VOWELS[char];
      i++;
      continue;
    }

    // 2. Consonants
    if (NEPALI_CONSONANTS.has(char)) {
      let romanConsonant = ROMAN_CONSONANTS[char];
      i++;

      // Look ahead for matras or halant
      if (ROMAN_MATRAS[nextChar]) {
        // Replace implicit 'a' with the matra sound
        result += romanConsonant.slice(0, -1) + ROMAN_MATRAS[nextChar];
        i++;
      } else if (nextChar === '्') {
        // Remove implicit 'a' for halant
        result += romanConsonant.slice(0, -1);
        i++;
      } else {
        // Normal implicit 'a' (but skip at end of words usually, though for worship songs 'ka' is often preserved)
        // For simplicity, keep the implicit 'a'
        result += romanConsonant;
      }
      continue;
    }

    // 3. Punctuation and others
    if (char === '।') result += '.';
    else result += char;
    i++;
  }

  return result;
}

