        console.warn("Categories: Falling back to alphabetical sort as order_index might be missing.");
        const { data: fallbackData } = await supabase.from('categories').select('*').order('name');
        return (fallbackData || []).map((c: any) => ({
            name: c.name,
            imageUrl: c.image_url,
            hideTitle: c.hide_title,
            orderIndex: c.order_index || 0
        }));
    }
    return (data || []).map((c: any) => ({
        name: c.name,
        imageUrl: c.image_url,
        hideTitle: c.hide_title,
        orderIndex: c.order_index || 0
    }));
};

