  const refreshData = async () => {
    try {
      setLoading(true);
      const [songs, artists, bans, cats, logo, stats, ann, info, rpts] = await Promise.all([
        getAllCustomSongs(),
        getAllCustomArtists(),
        getBanners(),
        getCategories(),
        getSiteLogo(),
        getAnalytics(),
        getAnnouncement(),
        getContactInfo(),
        getReports()
