// Improved phonetic mapper for Nepali Unicode to Roman (and vice-versa)
// Optimized for lyrics style (Standard Roman Nepali)

const ROMAN_VOWELS_MAP: Record<string, string> = {
  'अ': 'a', 'आ': 'aa', 'इ': 'i', 'ई': 'i', 'उ': 'u', 'ऊ': 'u',
  'ए': 'e', 'ऐ': 'ai', 'ओ': 'o', 'औ': 'au', 'ऋ': 'ri', 'अं': 'am', 'अँ': 'an'
};

const ROMAN_MATRAS_MAP: Record<string, string> = {
  'ा': 'aa', 'ि': 'i', 'ी': 'i', 'ु': 'u', 'ू': 'u',
  'े': 'e', 'ै': 'ai', 'ो': 'o', 'ौ': 'au', 'ृ': 'ri',
  'ं': 'n', 'ँ': 'n', 'ः': 'ah'
};

const ROMAN_CONSONANTS_MAP: Record<string, string> = {
  'क': 'k', 'ख': 'kh', 'ग': 'g', 'घ': 'gh', 'ङ': 'ng',
  'च': 'ch', 'छ': 'chh', 'ज': 'j', 'झ': 'jh', 'ञ': 'ny',
  'ट': 't', 'ठ': 'th', 'ड': 'd', 'ढ': 'dh', 'ण': 'n',
  'त': 't', 'थ': 'th', 'द': 'd', 'ध': 'dh', 'न': 'n',
  'प': 'p', 'फ': 'ph', 'ब': 'b', 'भ': 'bh', 'म': 'm',
  'य': 'y', 'र': 'r', 'ल': 'l', 'व': 'w',
  'श': 's', 'ष': 's', 'स': 's', 'ह': 'h',
  'क्ष': 'ksh', 'त्र': 'tr', 'ज्ञ': 'gya'
};

const NEPALI_CONSONANTS = new Set(Object.keys(ROMAN_CONSONANTS_MAP));

export const convertToRoman = (text: string): string => {
  if (!text) return "";
  let result = "";
  const chars = Array.from(text);

  for (let i = 0; i < chars.length; i++) {
    const char = chars[i];
    const nextChar = chars[i + 1];

    // 1. Standalone Vowels
    if (ROMAN_VOWELS_MAP[char]) {
      result += ROMAN_VOWELS_MAP[char];
      continue;
    }

    // 2. Consonants
    if (NEPALI_CONSONANTS.has(char)) {
      let roman = ROMAN_CONSONANTS_MAP[char];

      // Lookahead logic for vowels/halant
      if (nextChar === '्') {
        // Halant: No implicit vowel
        result += roman;
        i++; // skip halant
      } else if (ROMAN_MATRAS_MAP[nextChar]) {
        // Matra: Append the matra sound (Except for Anusvara/Chandrabindu which are nasal)
        if (nextChar === 'ं' || nextChar === 'ँ') {
            result += roman + 'a' + ROMAN_MATRAS_MAP[nextChar];
        } else {
            result += roman + ROMAN_MATRAS_MAP[nextChar];
        }
        i++; // skip matra
      } else {
        // Schwa deletion logic (standard for Nepali lyrics)
        // If it's the end of a word or followed by punctuation/space, drop the 'a'
        // Unless it's a short word like "Ma" or "Na"
        const isEndOfWord = !nextChar || /[\s।.,!?;:()|]/.test(nextChar);

        if (isEndOfWord) {
            // Exceptions for single-letter words common in lyrics
            if (char === 'म' || char === 'न' || char === 'त' || char === 'छ') {
                result += roman + 'a';
            } else {
                result += roman;
            }
        } else {
            result += roman + 'a';
        }
      }
      continue;
    }

    // 3. Punctuation and Others
    if (char === '।') result += '.';
    else if (char === 'ड़') result += 'd'; // Safeguard: map non-standard to standard 'd'
    else result += char;
  }

  // Clean up double vowels that might occur (like aaa -> aa)
  return result.replace(/aaa/g, 'aa').replace(/ii/g, 'i').replace(/uu/g, 'u');
};

// Reverse: Roman to Nepali (Standard mapping)
export const convertToNepali = (text: string): string => {
  if (!text) return "";

  // Mappings for back-conversion
  const VOWELS: Record<string, string> = {
    'a': 'अ', 'aa': 'आ', 'i': 'इ', 'ee': 'ई', 'u': 'उ', 'oo': 'ऊ',
    'e': 'ए', 'ai': 'ऐ', 'o': 'ओ', 'au': 'औ'
  };

  const MATRAS: Record<string, string> = {
    'a': '', 'aa': 'ा', 'i': 'ि', 'ee': 'ी', 'u': 'ु', 'oo': 'ू',
    'e': 'े', 'ai': 'ै', 'o': 'ो', 'au': 'ौ'
  };

  const CONSONANTS: Record<string, string> = {
    'k': 'क', 'kh': 'ख', 'g': 'ग', 'gh': 'घ', 'ng': 'ङ',
    'ch': 'च', 'chh': 'छ', 'j': 'ज', 'jh': 'झ', 'ny': 'ञ',
    't': 'त', 'th': 'थ', 'd': 'द', 'dh': 'ध', 'n': 'न',
    'T': 'ट', 'Th': 'ठ', 'D': 'ड', 'Dh': 'ढ', 'N': 'ण',
    'p': 'प', 'ph': 'ph', 'f': 'फ', 'b': 'ब', 'bh': 'भ', 'm': 'म',
    'y': 'य', 'r': 'र', 'l': 'ल', 'v': 'व', 'w': 'व',
    'sh': 'श', 's': 'स', 'h': 'ह'
  };

  let result = "";
  let i = 0;

  while (i < text.length) {
    let char = text[i].toLowerCase();

    // Non-alphabetic skip
    if (!/[a-z]/.test(char)) {
        result += text[i] === '|' ? '।' : text[i];
        i++;
        continue;
    }

    // Try to find longest consonant match (up to 3 chars like 'chh')
    let foundConsonant = "";
    let cLen = 0;
    for (let len = 3; len > 0; len--) {
        let sub = text.substring(i, i + len).toLowerCase();
        if (CONSONANTS[sub]) {
            foundConsonant = CONSONANTS[sub];
            cLen = len;
            break;
        }
    }

    if (foundConsonant) {
        i += cLen;
        // Check for following vowel
        let foundMatra = "";
        let mLen = 0;
        for (let len = 2; len > 0; len--) {
            let sub = text.substring(i, i + len).toLowerCase();
            if (MATRAS[sub] !== undefined) {
                foundMatra = MATRAS[sub];
                mLen = len;
                break;
            }
        }

        if (mLen > 0) {
            result += foundConsonant + foundMatra;
            i += mLen;
        } else {
            // Check if next is a consonant or end of string for halant
            let nextChar = text[i]?.toLowerCase();
            if (nextChar && /[a-z]/.test(nextChar) && !VOWELS[nextChar]) {
                result += foundConsonant + '्';
            } else if (!nextChar || !/[a-z]/.test(nextChar)) {
                // End of word often has halant in strict phonetic, 
                // but for lyrics we usually keep the consonant whole
                result += foundConsonant;
            } else {
                result += foundConsonant;
            }
        }
    } else {
        // Try standalone vowel
        let foundVowel = "";
        let vLen = 0;
        for (let len = 2; len > 0; len--) {
            let sub = text.substring(i, i + len).toLowerCase();
            if (VOWELS[sub]) {
                foundVowel = VOWELS[sub];
                vLen = len;
                break;
            }
        }
        if (foundVowel) {
            result += foundVowel;
            i += vLen;
        } else {
            result += text[i];
            i++;
        }
    }
  }
  return result;
};

import React, { useEffect, useState } from 'react';
