                                    </div>
                                    <button type="button" onClick={triggerManualRomanization} className="text-[9px] font-black text-primary hover:underline uppercase flex items-center gap-1"><Sparkles className="w-2.5 h-2.5"/> Force Re-generate</button>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-[10px] font-bold text-slate-400 mb-1 uppercase">Native Text (Nepali/Hindi)</label>
