                    ) : (
                        <div className="bg-gradient-to-br from-slate-800 to-slate-950 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group border border-slate-800">
                            <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 rounded-full -mr-10 -mt-10 blur-2xl group-hover:bg-primary/20 transition-all duration-700"></div>
                            <Music className="w-10 h-10 text-slate-700 mb-6 group-hover:rotate-12 transition-transform" />
                            <h4 className="text-lg font-black mb-2 tracking-tight">Audio Unavailable</h4>
                            <p className="text-slate-400 text-xs leading-relaxed font-medium">An official audio or video session for this track hasn't been linked yet. You can contribute by reporting it.</p>
