      const [allSongs, artistsList] = await Promise.all([
          getAllCustomSongs(),
          getAllCustomArtists()
      ]);

      setData(lyricsResult);
      setAllArtists(artistsList);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ 
        ...lyricsResult,
        artists: lyricsResult.artists || [lyricsResult.artist],
        composers: lyricsResult.composers || (lyricsResult.composer ? [lyricsResult.composer] : []),
