                                        <span className="text-[9px] font-black text-slate-300 mx-1">{fontSize}</span>
                                        <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-primary"><ZoomIn className="w-4 h-4" /></button>
                                    </div>
                                    <button 
