                                    <Volume2 className="w-4 h-4" />
                                </div>
                                <div className="min-w-0 flex-1">
                                    <p className="text-slate-500 text-[8px] font-black uppercase tracking-[0.2em]">Now Reading</p>
                                    <p className="text-white text-xs font-bold truncate pr-2">{displayTitle}</p>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="bg-gradient-to-br from-slate-800 to-slate-950 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group border border-slate-800">
                            <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 rounded-full -mr-10 -mt-10 blur-2xl group-hover:bg-primary/20 transition-all duration-700"></div>
                            <Music className="w-10 h-10 text-slate-700 mb-6 group-hover:rotate-12 transition-transform" />
                            <h4 className="text-lg font-black mb-2 tracking-tight">Audio Unavailable</h4>
                            <p className="text-slate-400 text-xs leading-relaxed font-medium">An official audio or video session for this track hasn't been linked yet. You can contribute by reporting it.</p>
                        </div>
                    )}

                    {/* Explore More Section */}
                    {relatedSongs.length > 0 && (
                        <div className="space-y-6">
                            <h3 className="text-2xl font-black text-slate-900 flex items-center gap-3 px-2 tracking-tighter">
                                 Explore More <ChevronRight className="w-6 h-6 text-primary" />
                            </h3>
                            <div className="space-y-3">
                                {relatedSongs.map((song) => (
                                    <Link 
                                        key={song.id} 
                                        to={`/l/${song.id}`}
                                        className="flex items-center gap-4 p-4 bg-white rounded-[1.8rem] border border-slate-200 hover:border-primary/40 hover:shadow-xl transition-all group shadow-sm"
                                    >
                                        <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                            <Play className="w-5 h-5 fill-current" />
                                        </div>
                                        <div className="min-w-0 flex-1">
                                            <p className="font-bold text-slate-800 text-sm truncate group-hover:text-primary transition-colors">
                                                {appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}
                                            </p>
                                            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-0.5 flex items-center gap-1.5">
                                                Lyrics Available
                                            </p>
                                        </div>
                                    </Link>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>

        {/* Feedback Modal (Hidden during print) */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-md animate-in fade-in duration-300 print:hidden">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/20">
                    <div className="bg-slate-900 p-12 text-white text-center relative overflow-hidden">
                        <div className="absolute inset-0 bg-gradient-to-br from-primary/20 to-transparent"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-3 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <h3 className="text-4xl font-black tracking-tighter relative z-10">Report Issue</h3>
                        <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mt-3 relative z-10">Help Us Maintain Accuracy</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-6">
                            <div className="w-24 h-24 bg-emerald-50 text-emerald-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner border border-emerald-100"><Check className="w-12 h-12" /></div>
                            <h4 className="text-3xl font-black text-slate-900">Message Received</h4>
                            <p className="text-slate-500 font-medium">Thank you for helping the community!</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-12 space-y-8">
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Subject</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-5 rounded-2xl font-black text-sm outline-none focus:border-primary appearance-none cursor-pointer shadow-inner"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue</option>
                                    <option>Wrong Credits</option>
                                    <option>Broken Video</option>
                                    <option>Typo Error</option>
                                </select>
                            </div>
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Details</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-6 rounded-[2rem] text-sm font-medium outline-none focus:bg-white focus:border-primary shadow-inner resize-none"
                                    placeholder="Explain the correction needed..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-slate-900 text-white py-6 rounded-[2.2rem] font-black text-lg shadow-xl hover:bg-black active:scale-95 transition-all disabled:opacity-50 uppercase tracking-widest"
                            >
                                {isSubmittingFeedback ? 'Submitting...' : 'Send Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getFavorites, FavoriteItem, toggleFavorite } from '../utils/storage';
import { getSongLyrics } from '../services/geminiService';
import { LyricsData } from '../types';
import { Heart, Mic2, Disc, ArrowRight, Play, X, ChevronLeft, ChevronRight, Loader2, ZoomIn, ZoomOut, Maximize, Minimize, PlayCircle, PauseCircle, ListOrdered, Circle, SkipBack, SkipForward, Settings, Upload, RefreshCw, Check, Trash2 } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

const FavoritesPage: React.FC = () => {
  const [favorites, setFavorites] = useState<FavoriteItem[]>([]);
  const navigate = useNavigate();
  const { t } = useLanguage();

  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [presentationQueue, setPresentationQueue] = useState<FavoriteItem[]>([]);

  const [isPresenting, setIsPresenting] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [lyricsData, setLyricsData] = useState<LyricsData | null>(null);
  const [loadingLyrics, setLoadingLyrics] = useState(false);
  const [fontSize, setFontSize] = useState(24);

  const [bgImage, setBgImage] = useState<string>('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
  const [bgBlur, setBgBlur] = useState(4);
  const [bgOpacity, setBgOpacity] = useState(50);
  const [showSettings, setShowSettings] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isBrowserFullscreen, setIsBrowserFullscreen] = useState(false);
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setFavorites(getFavorites());
    const handleContentChange = () => setFavorites(getFavorites());
    window.addEventListener('content-change', handleContentChange);
    return () => window.removeEventListener('content-change', handleContentChange);
  }, []);

  const allFavoriteSongs = favorites.filter(f => f.type === 'song');
  const slidesToPresent = presentationQueue.length > 0 ? presentationQueue : allFavoriteSongs;

  const fetchSlideLyrics = async (index: number) => {
    setLoadingLyrics(true);
    setLyricsData(null);
    setIsAutoScrolling(false);
    if (scrollContainerRef.current) scrollContainerRef.current.scrollTop = 0;

    const item = slidesToPresent[index];
    if (item) {
        // Correctly fetch lyrics using artist (subtext) and name (title)
        const data = await getSongLyrics(item.subtext, item.name);
        setLyricsData(data);
    }
    setLoadingLyrics(false);
  };

  const startPresentation = () => {
    if (slidesToPresent.length === 0) return;
    setCurrentIndex(0);
    setIsPresenting(true);
    fetchSlideLyrics(0);
  };

  const nextSlide = useCallback(() => {
    if (currentIndex < slidesToPresent.length - 1) {
      const newIndex = currentIndex + 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex, slidesToPresent.length]);

  const prevSlide = useCallback(() => {
    if (currentIndex > 0) {
      const newIndex = currentIndex - 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex]);

  const closePresentation = useCallback(() => {
    setIsPresenting(false);
    setLyricsData(null);
    setIsAutoScrolling(false);
    setShowSettings(false);
    if (document.fullscreenElement) document.exitFullscreen().catch(e => console.error(e));
  }, []);

  const handleZoomIn = useCallback(() => setFontSize(prev => Math.min(prev + 4, 120)), []);
  const handleZoomOut = useCallback(() => setFontSize(prev => Math.max(prev - 4, 16)), []);

  const toggleBrowserFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().then(() => setIsBrowserFullscreen(true)).catch(err => console.error(err));
    } else {
        document.exitFullscreen().then(() => setIsBrowserFullscreen(false));
    }
  }, []);

  const toggleAutoScroll = () => setIsAutoScrolling(!isAutoScrolling);
  const toggleSelectionMode = () => {
      setIsSelectionMode(!isSelectionMode);
      setPresentationQueue([]);
  };

  const handleSelectSong = (item: FavoriteItem) => {
      const existsIdx = presentationQueue.findIndex(i => i.id === item.id);
      if (existsIdx >= 0) {
          const newQueue = [...presentationQueue];
          newQueue.splice(existsIdx, 1);
          setPresentationQueue(newQueue);
      } else {
          setPresentationQueue([...presentationQueue, item]);
      }
  };

  const handleRemoveFavorite = (e: React.MouseEvent, item: FavoriteItem) => {
      e.preventDefault();
      e.stopPropagation();
      if (window.confirm(`${t('Remove')} "${item.name}" ${t('from favorites')}?`)) {
          toggleFavorite(item);
          // Manually trigger refresh since the storage util doesn't dispatch by default
          window.dispatchEvent(new Event('content-change'));
      }
  };

  const handleBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => setBgImage(reader.result as string);
        reader.readAsDataURL(file);
    }
  };

  const resetSettings = () => {
      setBgImage('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
      setBgBlur(4);
      setBgOpacity(50);
  };

  useEffect(() => {
      const handleFsChange = () => setIsBrowserFullscreen(!!document.fullscreenElement);
      document.addEventListener('fullscreenchange', handleFsChange);
      return () => document.removeEventListener('fullscreenchange', handleFsChange);
  }, []);

  useEffect(() => {
      let interval: ReturnType<typeof setInterval>;
      if (isAutoScrolling && scrollContainerRef.current) {
          interval = setInterval(() => {
              if (scrollContainerRef.current) {
                  scrollContainerRef.current.scrollTop += 1;
                  if (scrollContainerRef.current.scrollHeight - scrollContainerRef.current.scrollTop === scrollContainerRef.current.clientHeight) {
                      setIsAutoScrolling(false);
                  }
              }
          }, 40);
      }
      return () => clearInterval(interval);
  }, [isAutoScrolling]);

  useEffect(() => {
    if (!isPresenting) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight') nextSlide();
      else if (e.key === 'ArrowLeft') prevSlide();
      else if (e.key === 'Escape') {
        if (!document.fullscreenElement) closePresentation();
      }
      else if (e.key === '+' || e.key === '=') handleZoomIn();
      else if (e.key === '-' || e.key === '_') handleZoomOut();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPresenting, nextSlide, prevSlide, closePresentation, handleZoomIn, handleZoomOut]);

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
          <div>
            <h1 className="text-3xl font-bold text-slate-900">{t('Favorites')}</h1>
            <p className="text-slate-500">{favorites.length} {t('Items saved')}</p>
          </div>

          <div className="flex gap-2 w-full md:w-auto">
            <button 
              onClick={toggleSelectionMode}
              className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2 rounded-xl font-bold text-sm transition-all ${isSelectionMode ? 'bg-primary text-white' : 'bg-white text-slate-600 border border-slate-200'}`}
            >
              {isSelectionMode ? <X className="w-4 h-4" /> : <ListOrdered className="w-4 h-4" />}
              {isSelectionMode ? t('Cancel Selection') : t('Select Order')}
            </button>
            <button 
              disabled={slidesToPresent.length === 0}
              onClick={startPresentation}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-2 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200 disabled:opacity-50 disabled:shadow-none"
            >
              <Play className="w-4 h-4" />
              {t('Present')}
            </button>
          </div>
        </div>

        {isSelectionMode && (
          <div className="mb-6 p-4 bg-indigo-50 border border-indigo-100 rounded-2xl text-indigo-700 text-sm font-medium animate-in slide-in-from-top-4">
            {t('Click songs to add them to your presentation queue.')} ({presentationQueue.length} {t('selected')})
          </div>
        )}

        {favorites.length === 0 ? (
          <div className="bg-white rounded-3xl p-12 text-center border border-slate-200 shadow-sm">
            <Heart className="w-16 h-16 text-slate-200 mx-auto mb-4" />
            <h3 className="text-xl font-bold text-slate-400 mb-2">{t('No favorites yet')}</h3>
            <p className="text-slate-500 mb-6">{t('Start browsing songs and artists to add them to your collection.')}</p>
            <Link to="/" className="inline-flex items-center text-primary font-bold hover:underline">
              {t('Browse Music')} <ArrowRight className="w-4 h-4 ml-1" />
            </Link>
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-3">
            {favorites.map((item) => {
              const isSong = item.type === 'song';
              const isSelected = presentationQueue.some(i => i.id === item.id);

              // Handle link logic with fallback for legacy favorites without dbId
              const linkPath = isSong 
                ? (item.dbId ? `/l/${item.dbId}` : `/lyrics/${encodeURIComponent(item.subtext)}/${encodeURIComponent(item.name)}`)
                : `/artist/${encodeURIComponent(item.name)}`;

              return (
                <div 
                  key={item.id}
                  onClick={() => isSelectionMode && isSong ? handleSelectSong(item) : null}
                  className={`group relative flex items-center p-4 bg-white rounded-2xl border transition-all ${isSelectionMode && isSong ? 'cursor-pointer' : ''} ${isSelected ? 'border-primary ring-2 ring-primary/20 bg-primary/5' : 'border-slate-200 hover:border-slate-300 shadow-sm'}`}
                >
                  {isSelectionMode && isSong && (
                    <div className={`mr-4 w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${isSelected ? 'bg-primary border-primary text-white' : 'border-slate-300 bg-white'}`}>
                      {isSelected ? <Check className="w-3.5 h-3.5" /> : null}
                    </div>
                  )}

                  <div className="w-12 h-12 rounded-xl bg-slate-100 flex items-center justify-center text-slate-400 mr-4 shrink-0">
                    {isSong ? <Disc className="w-6 h-6" /> : <Mic2 className="w-6 h-6" />}
                  </div>

                  <div className="min-w-0 flex-1">
                    <h3 className="font-bold text-slate-900 truncate">
                      {item.name}
                      {item.note && <span className="ml-1.5 text-xs text-slate-400 font-medium italic">({item.note})</span>}
                    </h3>
                    <p className="text-sm text-slate-500 truncate">{item.subtext}</p>
                  </div>

                  {!isSelectionMode && (
                    <div className="flex items-center gap-2">
                       <Link 
                        to={linkPath}
                        className="p-2 text-slate-400 hover:text-primary transition-colors"
                       >
                        <ArrowRight className="w-5 h-5" />
                       </Link>
                       <button 
                        onClick={(e) => handleRemoveFavorite(e, item)}
                        className="p-2 text-slate-300 hover:text-red-500 transition-colors"
                       >
                        <Trash2 className="w-5 h-5" />
                       </button>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Presentation Overlay */}
      {isPresenting && (
        <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center text-white overflow-hidden animate-in fade-in duration-300">
           {/* Background Layer */}
           <div className="absolute inset-0 z-0">
              <img src={bgImage} alt="" className="w-full h-full object-cover" style={{ filter: `blur(${bgBlur}px)`, opacity: bgOpacity / 100 }} />
           </div>

           {/* Toolbar */}
           <div className="absolute top-0 left-0 right-0 z-20 p-4 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent">
              <div className="flex items-center gap-4">
                <button onClick={closePresentation} className="p-2 bg-white/10 hover:bg-white/20 rounded-full backdrop-blur-md transition-all">
                  <X className="w-6 h-6" />
                </button>
                <div className="hidden md:block">
                  <h2 className="font-bold text-lg">{slidesToPresent[currentIndex].name}</h2>
                  <p className="text-xs text-white/60 uppercase tracking-widest">{currentIndex + 1} / {slidesToPresent.length}</p>
                </div>
              </div>

              <div className="flex items-center gap-2">
                <button onClick={handleZoomOut} className="p-2 bg-white/10 hover:bg-white/20 rounded-full transition-all"><ZoomOut className="w-5 h-5"/></button>
                <button onClick={handleZoomIn} className="p-2 bg-white/10 hover:bg-white/20 rounded-full transition-all"><ZoomIn className="w-5 h-5"/></button>
                <div className="w-px h-6 bg-white/20 mx-1"></div>
                <button onClick={toggleAutoScroll} className={`p-2 rounded-full transition-all ${isAutoScrolling ? 'bg-primary text-white' : 'bg-white/10 hover:bg-white/20'}`}>
                  {isAutoScrolling ? <PauseCircle className="w-5 h-5"/> : <PlayCircle className="w-5 h-5"/>}
                </button>
                <button onClick={toggleBrowserFullscreen} className="p-2 bg-white/10 hover:bg-white/20 rounded-full transition-all">
                  {isBrowserFullscreen ? <Minimize className="w-5 h-5"/> : <Maximize className="w-5 h-5"/>}
                </button>
                <button onClick={() => setShowSettings(!showSettings)} className="p-2 bg-white/10 hover:bg-white/20 rounded-full transition-all">
                  <Settings className="w-5 h-5" />
                </button>
              </div>
           </div>

           {/* Settings Panel */}
           {showSettings && (
             <div className="absolute top-20 right-4 z-30 bg-slate-900/90 backdrop-blur-xl border border-white/10 p-6 rounded-3xl w-80 shadow-2xl animate-in slide-in-from-right-4">
                <div className="flex justify-between items-center mb-6">
                  <h3 className="font-bold">Display Settings</h3>
                  <button onClick={resetSettings} className="text-xs text-white/50 hover:text-white flex items-center gap-1"><RefreshCw className="w-3 h-3"/> Reset</button>
                </div>

                <div className="space-y-6">
                  <div>
                    <label className="block text-xs font-bold text-white/40 uppercase mb-2">Background Image</label>
                    <div className="flex gap-2">
                      <input className="flex-1 bg-white/10 border-none rounded-lg text-xs p-2 outline-none" value={bgImage} onChange={e => setBgImage(e.target.value)} placeholder="Image URL..." />
                      <button onClick={() => fileInputRef.current?.click()} className="p-2 bg-primary rounded-lg"><Upload className="w-4 h-4"/></button>
                      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleBgUpload} />
                    </div>
                  </div>
                  <div>
                    <label className="flex justify-between text-xs font-bold text-white/40 uppercase mb-2">Blur Level <span>{bgBlur}px</span></label>
                    <input type="range" min="0" max="20" value={bgBlur} onChange={e => setBgBlur(parseInt(e.target.value))} className="w-full accent-primary" />
                  </div>
                  <div>
                    <label className="flex justify-between text-xs font-bold text-white/40 uppercase mb-2">Background Opacity <span>{bgOpacity}%</span></label>
                    <input type="range" min="0" max="100" value={bgOpacity} onChange={e => setBgOpacity(parseInt(e.target.value))} className="w-full accent-primary" />
                  </div>
                </div>
             </div>
           )}

           {/* Content Area */}
           <div 
             ref={scrollContainerRef}
             className="relative z-10 w-full h-full flex items-center justify-center p-8 md:p-24 overflow-y-auto"
           >
              {loadingLyrics ? (
                <div className="text-center">
                  <Loader2 className="w-12 h-12 animate-spin text-white/20 mx-auto mb-4" />
                  <p className="text-white/40 font-bold uppercase tracking-widest text-sm">Fetching Lyrics...</p>
                </div>
              ) : lyricsData ? (
                <div className="max-w-5xl w-full text-center whitespace-pre-wrap leading-relaxed transition-all duration-500 animate-in slide-in-from-bottom-8" style={{ fontSize: `${fontSize}px` }}>
                  {lyricsData.lyrics_nepali || lyricsData.lyrics_roman || lyricsData.lyrics || "No lyrics content available."}
                </div>
              ) : (
                <p className="text-white/40 italic">Unable to load lyrics.</p>
              )}
           </div>

           {/* Navigation Controls */}
           <div className="absolute bottom-0 left-0 right-0 z-20 p-8 flex justify-between items-center bg-gradient-to-t from-black/80 to-transparent">
              <div className="flex gap-2">
                <button onClick={prevSlide} disabled={currentIndex === 0} className="p-4 bg-white/10 hover:bg-white/20 rounded-2xl backdrop-blur-md transition-all disabled:opacity-10">
                  <SkipBack className="w-6 h-6" />
                </button>
                <button onClick={nextSlide} disabled={currentIndex === slidesToPresent.length - 1} className="p-4 bg-white/10 hover:bg-white/20 rounded-2xl backdrop-blur-md transition-all disabled:opacity-10">
                  <SkipForward className="w-6 h-6" />
                </button>
              </div>
              <div className="text-xs font-bold text-white/30 uppercase tracking-[0.2em]">
                SansarPlus Presentation Mode
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default FavoritesPage;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { getFavorites, FavoriteItem, toggleFavorite, generateId } from '../utils/storage';
import { getSongLyrics, getSongById } from '../services/geminiService';
import { LyricsData } from '../types';
import { 
  Heart, Mic2, Disc, ArrowRight, Play, X, ChevronLeft, 
  ChevronRight, Loader2, ZoomIn, ZoomOut, Maximize, 
  Minimize, PlayCircle, PauseCircle, ListOrdered, Circle, 
  SkipBack, SkipForward, Settings, Upload, RefreshCw, 
  Check, Trash2, Share2, Save, Copy, MessageCircle, Send
} from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import Loader from '../components/Loader';

const FavoritesPage: React.FC = () => {
  const [favorites, setFavorites] = useState<FavoriteItem[]>([]);
  const [isSharedView, setIsSharedView] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const navigate = useNavigate();
  const location = useLocation();
  const { t } = useLanguage();

  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [presentationQueue, setPresentationQueue] = useState<FavoriteItem[]>([]);

  const [isPresenting, setIsPresenting] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [lyricsData, setLyricsData] = useState<LyricsData | null>(null);
  const [loadingLyrics, setLoadingLyrics] = useState(false);
  const [fontSize, setFontSize] = useState(24);

  const [bgImage, setBgImage] = useState<string>('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
  const [bgBlur, setBgBlur] = useState(4);
  const [bgOpacity, setBgOpacity] = useState(50);
  const [showSettings, setShowSettings] = useState(false);
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [isBrowserFullscreen, setIsBrowserFullscreen] = useState(false);
  const [isAutoScrolling, setIsAutoScrolling] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const sharedIds = params.get('list');

    if (sharedIds) {
      setIsSharedView(true);
      loadSharedCollection(sharedIds);
    } else {
      setIsSharedView(false);
      setFavorites(getFavorites());
    }

    const handleContentChange = () => {
      if (!new URLSearchParams(window.location.search).get('list')) {
        setFavorites(getFavorites());
      }
    };
    window.addEventListener('content-change', handleContentChange);
    return () => window.removeEventListener('content-change', handleContentChange);
  }, [location.search]);

  const loadSharedCollection = async (idsString: string) => {
    setIsLoadingShared(true);
    const ids = idsString.split(',').filter(id => id.trim());
    const sharedItems: FavoriteItem[] = [];

    for (const id of ids) {
      try {
        const song = await getSongById(id);
        if (song) {
          sharedItems.push({
            id: generateId('song', song.title, song.artist),
            dbId: song.id,
            type: 'song',
            name: song.title,
            subtext: song.artist,
            language: song.language,
            note: song.note
          });
        }
      } catch (e) {
        console.error("Failed to load shared song ID:", id);
      }
    }
    setFavorites(sharedItems);
    setIsLoadingShared(false);
  };

  const saveSharedToLocal = () => {
    favorites.forEach(item => {
      toggleFavorite(item);
    });
    alert("Collection saved to your favorites!");
    navigate('/favorites');
  };

  const generateShareLink = () => {
    const songIds = favorites.filter(f => f.type === 'song').map(f => f.dbId).join(',');
    if (!songIds) return window.location.origin + window.location.pathname;
    const url = new URL(window.location.origin + window.location.pathname);
    url.searchParams.set('list', songIds);
    return url.toString();
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(generateShareLink());
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const shareWhatsApp = () => {
    const text = `Check out this worship song collection on SansarPlus: ${generateShareLink()}`;
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
  };

  const allFavoriteSongs = favorites.filter(f => f.type === 'song');
  const slidesToPresent = presentationQueue.length > 0 ? presentationQueue : allFavoriteSongs;

  const fetchSlideLyrics = async (index: number) => {
    setLoadingLyrics(true);
    setLyricsData(null);
    setIsAutoScrolling(false);
    if (scrollContainerRef.current) scrollContainerRef.current.scrollTop = 0;

    const item = slidesToPresent[index];
    if (item) {
        const data = await getSongLyrics(item.subtext, item.name);
        setLyricsData(data);
    }
    setLoadingLyrics(false);
  };

  const startPresentation = () => {
    if (slidesToPresent.length === 0) return;
    setCurrentIndex(0);
    setIsPresenting(true);
    fetchSlideLyrics(0);
  };

  const nextSlide = useCallback(() => {
    if (currentIndex < slidesToPresent.length - 1) {
      const newIndex = currentIndex + 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex, slidesToPresent.length]);

  const prevSlide = useCallback(() => {
    if (currentIndex > 0) {
      const newIndex = currentIndex - 1;
      setCurrentIndex(newIndex);
      fetchSlideLyrics(newIndex);
    }
  }, [currentIndex]);

  const closePresentation = useCallback(() => {
    setIsPresenting(false);
    setLyricsData(null);
    setIsAutoScrolling(false);
    setShowSettings(false);
    if (document.fullscreenElement) document.exitFullscreen().catch(e => console.error(e));
  }, []);

  const handleZoomIn = useCallback(() => setFontSize(prev => Math.min(prev + 4, 120)), []);
  const handleZoomOut = useCallback(() => setFontSize(prev => Math.max(prev - 4, 16)), []);

  const toggleBrowserFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().then(() => setIsBrowserFullscreen(true)).catch(err => console.error(err));
    } else {
        document.exitFullscreen().then(() => setIsBrowserFullscreen(false));
    }
  }, []);

  const toggleAutoScroll = () => setIsAutoScrolling(!isAutoScrolling);
  const toggleSelectionMode = () => {
      setIsSelectionMode(!isSelectionMode);
      setPresentationQueue([]);
  };

  const handleSelectSong = (item: FavoriteItem) => {
      const existsIdx = presentationQueue.findIndex(i => i.id === item.id);
      if (existsIdx >= 0) {
          const newQueue = [...presentationQueue];
          newQueue.splice(existsIdx, 1);
          setPresentationQueue(newQueue);
      } else {
          setPresentationQueue([...presentationQueue, item]);
      }
  };

  const handleRemoveFavorite = (e: React.MouseEvent, item: FavoriteItem) => {
      e.preventDefault();
      e.stopPropagation();
      if (window.confirm(`${t('Remove')} "${item.name}" ${t('from favorites')}?`)) {
          toggleFavorite(item);
          window.dispatchEvent(new Event('content-change'));
      }
  };

  const handleBgUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => setBgImage(reader.result as string);
        reader.readAsDataURL(file);
    }
  };

  const resetSettings = () => {
      setBgImage('https://images.unsplash.com/photo-1510915361894-db8b60106cb1?q=80&w=2070&auto=format&fit=crop');
      setBgBlur(4);
      setBgOpacity(50);
  };

  useEffect(() => {
      const handleFsChange = () => setIsBrowserFullscreen(!!document.fullscreenElement);
      document.addEventListener('fullscreenchange', handleFsChange);
      return () => document.removeEventListener('fullscreenchange', handleFsChange);
  }, []);

  useEffect(() => {
      let interval: ReturnType<typeof setInterval>;
      if (isAutoScrolling && scrollContainerRef.current) {
          interval = setInterval(() => {
              if (scrollContainerRef.current) {
                  scrollContainerRef.current.scrollTop += 1;
                  if (scrollContainerRef.current.scrollHeight - scrollContainerRef.current.scrollTop === scrollContainerRef.current.clientHeight) {
                      setIsAutoScrolling(false);
                  }
              }
          }, 40);
      }
      return () => clearInterval(interval);
  }, [isAutoScrolling]);

  useEffect(() => {
    if (!isPresenting) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight') nextSlide();
      else if (e.key === 'ArrowLeft') prevSlide();
      else if (e.key === 'Escape') {
        if (!document.fullscreenElement) closePresentation();
      }
      else if (e.key === '+' || e.key === '=') handleZoomIn();
      else if (e.key === '-' || e.key === '_') handleZoomOut();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPresenting, nextSlide, prevSlide, closePresentation, handleZoomIn, handleZoomOut]);

  if (isLoadingShared) return <Loader fullScreen text="Opening Shared Collection..." />;

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-6">
          <div className="text-center md:text-left">
            <h1 className="text-4xl font-black text-slate-900 tracking-tight">
              {isSharedView ? 'Shared Collection' : t('Favorites')}
            </h1>
            <p className="text-slate-500 font-medium">
              {favorites.length} {t('Items')} {isSharedView ? 'in this list' : 'saved'}
            </p>
          </div>

          <div className="flex flex-wrap justify-center gap-2 w-full md:w-auto">
            {!isSharedView && (
              <button 
                onClick={() => setIsShareModalOpen(true)}
                disabled={favorites.length === 0}
                className="flex items-center gap-2 px-4 py-2 bg-white text-slate-700 border border-slate-200 rounded-xl font-bold text-sm hover:bg-slate-50 transition-all shadow-sm disabled:opacity-50"
              >
                <Share2 className="w-4 h-4" /> Share Collection
              </button>
            )}

            {isSharedView && (
              <button 
                onClick={saveSharedToLocal}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-50 text-emerald-600 border border-emerald-100 rounded-xl font-bold text-sm hover:bg-emerald-100 transition-all shadow-sm"
              >
                <Save className="w-4 h-4" /> Save to My List
              </button>
            )}

            <button 
              onClick={toggleSelectionMode}
              disabled={favorites.length === 0}
              className={`flex items-center justify-center gap-2 px-4 py-2 rounded-xl font-bold text-sm transition-all shadow-sm ${isSelectionMode ? 'bg-primary text-white' : 'bg-white text-slate-600 border border-slate-200'}`}
            >
              {isSelectionMode ? <X className="w-4 h-4" /> : <ListOrdered className="w-4 h-4" />}
              {isSelectionMode ? t('Cancel Selection') : t('Select Order')}
            </button>

            <button 
              disabled={slidesToPresent.length === 0}
              onClick={startPresentation}
              className="flex items-center justify-center gap-2 px-6 py-2 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100 disabled:opacity-50 disabled:shadow-none"
            >
              <Play className="w-4 h-4 fill-current" />
              {t('Present')}
            </button>
          </div>
        </div>

        {isSelectionMode && (
          <div className="mb-6 p-4 bg-indigo-50 border border-indigo-100 rounded-2xl text-indigo-700 text-sm font-bold animate-in slide-in-from-top-4 flex items-center gap-3">
            <div className="w-8 h-8 bg-white rounded-lg flex items-center justify-center shadow-sm"><Check className="w-5 h-5" /></div>
            {t('Click songs to add them to your presentation queue.')} ({presentationQueue.length} {t('selected')})
          </div>
        )}

        {favorites.length === 0 ? (
          <div className="bg-white rounded-[2.5rem] p-16 text-center border border-slate-200 shadow-xl shadow-slate-200/50">
            <div className="w-24 h-24 bg-slate-50 text-slate-200 rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner">
               <Heart className="w-12 h-12" />
            </div>
            <h3 className="text-2xl font-black text-slate-900 mb-2">{t('No favorites yet')}</h3>
            <p className="text-slate-500 mb-8 max-w-sm mx-auto">{t('Start browsing songs and artists to add them to your collection.')}</p>
            <Link to="/" className="inline-flex items-center gap-2 bg-primary text-white px-8 py-3 rounded-2xl font-bold hover:bg-primary/90 transition-all shadow-lg shadow-primary/20">
              {t('Browse Music')} <ArrowRight className="w-5 h-5" />
            </Link>
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-4">
            {favorites.map((item, idx) => {
              const isSong = item.type === 'song';
              const isSelected = presentationQueue.some(i => i.id === item.id);

              const linkPath = isSong 
                ? (item.dbId ? `/l/${item.dbId}` : `/lyrics/${encodeURIComponent(item.subtext)}/${encodeURIComponent(item.name)}`)
                : `/artist/${encodeURIComponent(item.name)}`;

              return (
                <div 
                  key={item.id}
                  onClick={() => isSelectionMode && isSong ? handleSelectSong(item) : null}
                  className={`group relative flex items-center p-4 md:p-6 bg-white rounded-[2rem] border transition-all ${isSelectionMode && isSong ? 'cursor-pointer active:scale-[0.98]' : ''} ${isSelected ? 'border-primary ring-4 ring-primary/10 bg-primary/5' : 'border-slate-200 hover:border-primary/30 shadow-sm hover:shadow-md'}`}
                >
                  {isSelectionMode && isSong && (
                    <div className={`mr-5 w-8 h-8 rounded-xl border-2 flex items-center justify-center transition-all ${isSelected ? 'bg-primary border-primary text-white shadow-lg shadow-primary/20' : 'border-slate-200 bg-slate-50 text-transparent'}`}>
                      <Check className="w-5 h-5" />
                    </div>
                  )}

                  {!isSelectionMode && (
                    <div className="mr-5 w-10 text-center font-black text-slate-200 text-xl group-hover:text-primary transition-colors">
                        {idx + 1}
                    </div>
                  )}

                  <div className="w-14 h-14 rounded-2xl bg-slate-50 flex items-center justify-center text-slate-400 mr-5 shrink-0 shadow-inner group-hover:bg-primary/10 group-hover:text-primary transition-colors">
                    {isSong ? <Disc className="w-7 h-7" /> : <Mic2 className="w-7 h-7" />}
                  </div>

                  <div className="min-w-0 flex-1">
                    <h3 className="text-lg font-bold text-slate-900 truncate">
                      {item.name}
                      {item.note && <span className="ml-2 text-xs text-slate-400 font-normal italic">({item.note})</span>}
                    </h3>
                    <p className="text-sm font-bold text-slate-400 uppercase tracking-widest mt-0.5 truncate">{item.subtext}</p>
                  </div>

                  {!isSelectionMode && (
                    <div className="flex items-center gap-2">
                       <Link 
                        to={linkPath}
                        className="p-3 text-slate-400 hover:text-primary hover:bg-primary/5 rounded-xl transition-all"
                       >
                        <ArrowRight className="w-6 h-6" />
                       </Link>
                       {!isSharedView && (
                         <button 
                          onClick={(e) => handleRemoveFavorite(e, item)}
                          className="p-3 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                         >
                          <Trash2 className="w-6 h-6" />
                         </button>
                       )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Share Modal */}
      {isShareModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-md animate-in fade-in duration-300">
           <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95">
              <div className="p-8 bg-primary text-white relative">
                 <button onClick={() => setIsShareModalOpen(false)} className="absolute top-6 right-6 p-2 rounded-full bg-white/20 hover:bg-white/30 transition-all">
                    <X className="w-5 h-5" />
                 </button>
                 <Share2 className="w-10 h-10 mb-4 opacity-50" />
                 <h3 className="text-3xl font-black tracking-tight">Share Collection</h3>
                 <p className="text-primary-100 text-sm font-medium mt-1">Send your favorites to church or worship team</p>
              </div>
              <div className="p-8 space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Collection Link</label>
                    <div className="flex gap-2">
                       <input 
                        readOnly 
                        className="flex-1 bg-slate-50 border-2 border-slate-100 p-4 rounded-2xl text-xs font-bold text-slate-600 truncate focus:outline-none" 
                        value={generateShareLink()} 
                       />
                       <button 
                        onClick={handleCopyLink}
                        className={`p-4 rounded-2xl transition-all shadow-sm border ${copySuccess ? 'bg-emerald-500 text-white border-emerald-500' : 'bg-white text-slate-600 border-slate-200 hover:border-primary/30'}`}
                       >
                         {copySuccess ? <Check className="w-5 h-5" /> : <Copy className="w-5 h-5" />}
                       </button>
                    </div>
                 </div>
                 <div className="grid grid-cols-2 gap-3">
                    <button onClick={shareWhatsApp} className="flex flex-col items-center gap-2 p-6 rounded-[2rem] bg-emerald-50 text-emerald-600 hover:bg-emerald-600 hover:text-white transition-all border border-emerald-100">
                       <MessageCircle className="w-8 h-8" />
                       <span className="text-[10px] font-black uppercase tracking-widest">WhatsApp</span>
                    </button>
                    <button onClick={() => { navigator.share?.({ title: 'My Worship List', url: generateShareLink() }); }} className="flex flex-col items-center gap-2 p-6 rounded-[2rem] bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white transition-all border border-indigo-100">
                       <Send className="w-8 h-8" />
                       <span className="text-[10px] font-black uppercase tracking-widest">Team Share</span>
                    </button>
                 </div>
                 <p className="text-center text-[10px] text-slate-400 font-medium italic">Anyone with this link can view and save your collection.</p>
              </div>
           </div>
        </div>
      )}

      {/* Presentation Overlay */}
      {isPresenting && (
        <div className="fixed inset-0 z-[120] bg-black flex flex-col items-center justify-center text-white overflow-hidden animate-in fade-in duration-300">
           {/* Background Layer */}
           <div className="absolute inset-0 z-0">
              <img src={bgImage} alt="" className="w-full h-full object-cover" style={{ filter: `blur(${bgBlur}px)`, opacity: bgOpacity / 100 }} />
           </div>

           {/* Toolbar */}
           <div className="absolute top-0 left-0 right-0 z-20 p-4 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent backdrop-blur-sm">
              <div className="flex items-center gap-4">
                <button onClick={closePresentation} className="p-3 bg-white/10 hover:bg-white/20 rounded-full backdrop-blur-md transition-all">
                  <X className="w-6 h-6" />
                </button>
                <div className="hidden md:block">
                  <h2 className="font-black text-xl tracking-tight">{slidesToPresent[currentIndex].name}</h2>
                  <p className="text-[10px] text-white/60 font-black uppercase tracking-[0.2em]">{currentIndex + 1} / {slidesToPresent.length}</p>
                </div>
              </div>

              <div className="flex items-center gap-2">
                <button onClick={handleZoomOut} className="p-3 bg-white/10 hover:bg-white/20 rounded-full transition-all"><ZoomOut className="w-5 h-5"/></button>
                <button onClick={handleZoomIn} className="p-3 bg-white/10 hover:bg-white/20 rounded-full transition-all"><ZoomIn className="w-5 h-5"/></button>
                <div className="w-px h-8 bg-white/20 mx-2"></div>
                <button onClick={toggleAutoScroll} className={`p-3 rounded-full transition-all ${isAutoScrolling ? 'bg-primary text-white shadow-lg shadow-primary/40' : 'bg-white/10 hover:bg-white/20'}`}>
                  {isAutoScrolling ? <PauseCircle className="w-6 h-6"/> : <PlayCircle className="w-6 h-6"/>}
                </button>
                <button onClick={toggleBrowserFullscreen} className="p-3 bg-white/10 hover:bg-white/20 rounded-full transition-all">
                  {isBrowserFullscreen ? <Minimize className="w-5 h-5"/> : <Maximize className="w-5 h-5"/>}
                </button>
                <button onClick={() => setShowSettings(!showSettings)} className="p-3 bg-white/10 hover:bg-white/20 rounded-full transition-all">
                  <Settings className="w-5 h-5" />
                </button>
              </div>
           </div>

           {/* Settings Panel */}
           {showSettings && (
             <div className="absolute top-24 right-6 z-30 bg-slate-950/90 backdrop-blur-2xl border border-white/10 p-8 rounded-[2.5rem] w-80 shadow-2xl animate-in slide-in-from-right-4">
                <div className="flex justify-between items-center mb-8">
                  <h3 className="font-black text-sm uppercase tracking-widest text-white/40">Visual Settings</h3>
                  <button onClick={resetSettings} className="text-[10px] font-black uppercase tracking-widest text-white/30 hover:text-white flex items-center gap-1.5"><RefreshCw className="w-3.5 h-3.5"/> Reset</button>
                </div>

                <div className="space-y-8">
                  <div>
                    <label className="block text-[10px] font-black text-white/20 uppercase tracking-widest mb-3">Background Mood</label>
                    <div className="flex gap-2">
                      <input className="flex-1 bg-white/5 border border-white/10 rounded-xl text-[10px] p-3 outline-none text-white/60 font-mono" value={bgImage} onChange={e => setBgImage(e.target.value)} placeholder="Image URL..." />
                      <button onClick={() => fileInputRef.current?.click()} className="p-3 bg-primary text-white rounded-xl shadow-lg shadow-primary/20"><Upload className="w-4 h-4"/></button>
                      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleBgUpload} />
                    </div>
                  </div>
                  <div>
                    <label className="flex justify-between text-[10px] font-black text-white/20 uppercase tracking-widest mb-3">Blur Intensity <span>{bgBlur}px</span></label>
                    <input type="range" min="0" max="20" value={bgBlur} onChange={e => setBgBlur(parseInt(e.target.value))} className="w-full accent-primary bg-white/10 rounded-lg h-1 appearance-none" />
                  </div>
                  <div>
                    <label className="flex justify-between text-[10px] font-black text-white/20 uppercase tracking-widest mb-3">Atmosphere Dimmer <span>{bgOpacity}%</span></label>
                    <input type="range" min="0" max="100" value={bgOpacity} onChange={e => setBgOpacity(parseInt(e.target.value))} className="w-full accent-primary bg-white/10 rounded-lg h-1 appearance-none" />
                  </div>
                </div>
             </div>
           )}

           {/* Content Area */}
           <div 
             ref={scrollContainerRef}
             className="relative z-10 w-full h-full flex items-center justify-center p-8 md:p-24 overflow-y-auto lyrics-scroll"
           >
              {loadingLyrics ? (
                <div className="text-center space-y-6">
                  <Loader2 className="w-16 h-16 animate-spin text-primary mx-auto opacity-40" />
                  <p className="text-white/20 font-black uppercase tracking-[0.3em] text-xs">Fetching Worship Data...</p>
                </div>
              ) : lyricsData ? (
                <div className="max-w-5xl w-full text-center whitespace-pre-wrap leading-relaxed transition-all duration-700 animate-in slide-in-from-bottom-12" style={{ fontSize: `${fontSize}px` }}>
                  <div className="mb-16 print:hidden">
                    <h4 className="text-[10px] font-black uppercase tracking-[0.4em] text-white/20 mb-2">Song Intro</h4>
                    <div className="w-20 h-1 bg-primary/30 mx-auto rounded-full"></div>
                  </div>
                  <div className="font-medium text-white drop-shadow-xl selection:bg-primary/40">
                    {lyricsData.lyrics_nepali || lyricsData.lyrics_roman || lyricsData.lyrics || "No lyrics content available."}
                  </div>
                  <div className="mt-20 opacity-10 font-black tracking-tighter text-4xl">SANSARPLUS</div>
                </div>
              ) : (
                <div className="text-center space-y-4">
                  <Disc className="w-20 h-20 text-white/5 mx-auto animate-spin-slow" />
                  <p className="text-white/20 font-bold uppercase tracking-widest italic">Awaiting Lyrics Loading...</p>
                </div>
              )}
           </div>

           {/* Navigation Controls */}
           <div className="absolute bottom-0 left-0 right-0 z-20 p-8 flex justify-between items-center bg-gradient-to-t from-black/80 to-transparent">
              <div className="flex gap-3">
                <button onClick={prevSlide} disabled={currentIndex === 0} className="p-5 bg-white/10 hover:bg-white/20 text-white rounded-[2rem] backdrop-blur-md transition-all disabled:opacity-5 disabled:scale-95 transform active:scale-90 shadow-xl border border-white/5">
                  <SkipBack className="w-8 h-8" />
                </button>
                <button onClick={nextSlide} disabled={currentIndex === slidesToPresent.length - 1} className="p-5 bg-primary hover:bg-primary/90 text-white rounded-[2rem] backdrop-blur-md transition-all disabled:opacity-5 disabled:scale-95 transform active:scale-90 shadow-xl shadow-primary/20 border border-primary/20">
                  <SkipForward className="w-8 h-8" />
                </button>
              </div>
              <div className="text-[10px] font-black text-white/10 uppercase tracking-[0.5em] hidden sm:block">
                PRESENTATION ENGINE v1.2
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default FavoritesPage;

import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { getSongsByLetter, getArtistsByLetter, ArtistWithRoles } from '../services/geminiService';
import Loader from '../components/Loader';
import AlphabetNav from '../components/AlphabetNav';
import { Music, Disc, ArrowRight, Mic2, PenTool, Filter, Check } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface BrowseProps {
  mode: 'songs' | 'artists';
}

type RoleFilter = 'all' | 'Singer' | 'Composer' | 'Lyricist';

const Browse: React.FC<BrowseProps> = ({ mode }) => {
  const { letter } = useParams<{ letter: string }>();
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [roleFilter, setRoleFilter] = useState<RoleFilter>('all');
  const { t, language: appLanguage } = useLanguage();

  const fetchData = async () => {
    if (letter) {
      setLoading(true);
      const decodedLetter = decodeURIComponent(letter);
      if (mode === 'songs') {
        const results = await getSongsByLetter(decodedLetter);
        setData(results);
      } else {
        const results = await getArtistsByLetter(decodedLetter);
        setData(results);
      }
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    setRoleFilter('all');

    const handleContentChange = () => fetchData();
    window.addEventListener('content-change', handleContentChange);
    return () => window.removeEventListener('content-change', handleContentChange);
  }, [letter, mode]);

  const getSongColorClass = (lang?: string) => {
      if (lang === 'hindi') return 'text-red-600';
      if (lang === 'english') return 'text-blue-600';
      return 'text-slate-800';
  };

  const filteredData = mode === 'artists' && roleFilter !== 'all'
    ? (data as ArtistWithRoles[]).filter(artist => artist.roles.includes(roleFilter))
    : data;

  const displayLetter = decodeURIComponent(letter || '');
  const titleText = mode === 'songs' ? t('Songs') : t('Artists');

  const RoleBadge: React.FC<{ role: string }> = ({ role }) => {
    switch(role) {
      case 'Singer': return <span className="bg-pink-50 text-pink-600 px-1.5 py-0.5 rounded text-[9px] font-bold uppercase flex items-center gap-1 border border-pink-100"><Mic2 className="w-2.5 h-2.5" /> Singer</span>;
      case 'Composer': return <span className="bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded text-[9px] font-bold uppercase flex items-center gap-1 border border-indigo-100"><Music className="w-2.5 h-2.5" /> Composer</span>;
      case 'Lyricist': return <span className="bg-purple-50 text-purple-600 px-1.5 py-0.5 rounded text-[9px] font-bold uppercase flex items-center gap-1 border border-purple-100"><PenTool className="w-2.5 h-2.5" /> Lyricist</span>;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50">
      <AlphabetNav mode={mode} />

      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="mb-8 flex flex-col md:flex-row md:items-end justify-between border-b border-slate-200 pb-6 gap-6">
            <div>
                <h1 className="text-4xl font-bold text-slate-900 flex items-center gap-3">
                    <span className="bg-primary/10 text-primary p-2 rounded-2xl text-2xl min-w-[3.5rem] text-center shadow-sm">{displayLetter}</span>
                    <span className="capitalize">{titleText}</span>
                </h1>
                <p className="text-slate-500 mt-2 font-medium">{t('Discover popular')} {titleText.toLowerCase()} {t('starting with')} "{displayLetter}"</p>
            </div>

            {mode === 'artists' && !loading && data.length > 0 && (
                <div className="flex flex-wrap items-center gap-2 bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm">
                    <div className="px-3 text-slate-400">
                        <Filter className="w-4 h-4" />
                    </div>
                    {(['all', 'Singer', 'Composer', 'Lyricist'] as RoleFilter[]).map((filter) => (
                        <button
                            key={filter}
                            onClick={() => setRoleFilter(filter)}
                            className={`px-4 py-1.5 rounded-xl text-xs font-bold transition-all flex items-center gap-1.5 ${
                                roleFilter === filter 
                                ? 'bg-primary text-white shadow-lg shadow-primary/20 scale-105' 
                                : 'text-slate-500 hover:bg-slate-50'
                            }`}
                        >
                            {roleFilter === filter && <Check className="w-3 h-3" />}
                            {filter === 'all' ? 'All Roles' : filter + 's'}
                        </button>
                    ))}
                </div>
            )}
        </div>

        {loading ? (
          <Loader text={`Fetching ${mode} starting with ${displayLetter}...`} />
        ) : filteredData.length === 0 ? (
          <div className="text-center py-20 bg-white rounded-3xl border border-slate-200 shadow-sm">
            <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4">
                {mode === 'songs' ? <Music className="text-slate-300 w-10 h-10" /> : <Mic2 className="text-slate-300 w-10 h-10" />}
            </div>
            <h3 className="text-2xl text-slate-400 font-bold mb-2">{t('No')} {titleText.toLowerCase()} {t('found')}</h3>
            <p className="text-slate-500">{roleFilter === 'all' ? t('Try selecting a different letter.') : `No ${roleFilter.toLowerCase()}s found starting with "${displayLetter}".`}</p>
          </div>
        ) : (
          <div className={mode === 'songs' ? "grid grid-cols-1 gap-2 max-w-4xl mx-auto" : "grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4"}>
            {filteredData.map((item, idx) => {
              const isSong = mode === 'songs';
              const title = isSong ? ((appLanguage === 'nepali' && item.title_nepali) ? item.title_nepali : item.title) : item.name;
              const subtitle = isSong ? item.artist : undefined;
              const language = isSong ? item.language : undefined;
              const imageUrl = !isSong ? item.imageUrl : undefined;
              const roles = !isSong ? item.roles : [];
              const note = isSong ? item.note : undefined;

              const link = isSong 
                ? `/l/${item.id}` 
                : `/artist/${encodeURIComponent(item.name)}`;

              const titleClass = isSong ? getSongColorClass(language) : 'text-slate-800';

              return (
                <Link 
                  key={idx} 
                  to={link}
                  className={`group flex items-center justify-between bg-white hover:bg-slate-50 border border-slate-200 hover:border-primary/30 rounded-2xl transition-all duration-300 shadow-sm hover:shadow-md ${isSong ? 'p-3 md:p-4' : 'p-4 hover:-translate-y-1'}`}
                >
                  <div className="flex items-center min-w-0 flex-1">
                    {/* Index Number for List View */}
                    {isSong && (
                        <span className="text-slate-300 font-bold w-6 text-xs mr-2 text-right group-hover:text-primary transition-colors">{idx + 1}</span>
                    )}

                    <div className={`rounded-2xl overflow-hidden flex-shrink-0 mr-4 shadow-inner border border-slate-100 flex items-center justify-center bg-slate-50 group-hover:bg-primary/5 transition-colors ${isSong ? 'w-10 h-10' : 'w-12 h-12'}`}>
                        {imageUrl ? (
                            <img src={imageUrl} alt={title} className="w-full h-full object-cover" />
                        ) : (
                            <div className={`w-full h-full flex items-center justify-center text-primary/40 group-hover:text-primary transition-colors ${isSong ? 'bg-primary/10' : 'bg-secondary/10 text-secondary/40 group-hover:text-secondary'}`}>
                                {isSong ? <Disc className="w-5 h-5" /> : <Mic2 className="w-6 h-6" />}
                            </div>
                        )}
                    </div>
                    <div className="min-w-0 pr-4 flex-1">
                      <h3 className={`font-bold truncate transition-colors text-base md:text-lg flex items-center gap-2 ${titleClass}`}>
                        {title}
                        {isSong && note && (
                            <span className="text-[10px] md:text-xs text-slate-400 font-normal italic shrink-0">({note})</span>
                        )}
                      </h3>
                      {isSong ? (
                        <p className="text-slate-400 text-xs font-bold uppercase tracking-wider truncate">{subtitle}</p>
                      ) : (
                        <div className="flex flex-wrap gap-1 mt-1">
                          {roles.map((role: string) => <RoleBadge key={role} role={role} />)}
                        </div>
                      )}
                    </div>
                  </div>
                  <div className={`rounded-full bg-slate-50 flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all transform group-hover:rotate-0 -rotate-45 shrink-0 ${isSong ? 'w-7 h-7' : 'w-8 h-8'}`}>
                    <ArrowRight className={isSong ? 'w-3.5 h-3.5' : 'w-4 h-4'} />
                  </div>
                </Link>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default Browse;

import React, { useEffect, useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getSongLyrics, getArtistDetails } from '../services/geminiService';
import { LyricsData, ArtistDetails } from '../types';
import Loader from '../components/Loader';
import { 
  Heart, Music, PenTool, Copy, Check, ZoomIn, ZoomOut, 
  Flag, X, Edit, Save, Printer, Youtube, Mic2, StickyNote, 
  Globe, Search, Disc, Share2, ChevronRight, Loader2,
  Eye, EyeOff, Settings, ChevronDown, ChevronUp, Info, PlayCircle,
  Facebook, MessageCircle, Link as LinkIcon, Send, Play, ExternalLink,
  Volume2, Sparkles, RefreshCw
} from 'lucide-react';
import { isFavorite, toggleFavorite, generateId } from '../utils/storage';
import { useAuth } from '../utils/auth';
import { 
  saveCustomSong, 
  incrementViewCount, 
  getAllCustomSongs, 
  getSongById, 
  submitReport,
  getAllCustomArtists
} from '../utils/dataManager';
import { useLanguage } from '../contexts/LanguageContext';
import ArtistSelector from '../components/ArtistSelector';
import { convertToRoman } from '../utils/nepaliConverter';

const LyricsPage: React.FC = () => {
  const { id, artist: artistParam, song: songParam } = useParams<{ id?: string; artist?: string; song?: string }>();
  const [data, setData] = useState<(LyricsData & { id?: any }) | null>(null);
  const [allArtists, setAllArtists] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isFav, setIsFav] = useState(false);
  const [activeTab, setActiveTab] = useState<'nepali' | 'roman'>('nepali');
  const [copied, setCopied] = useState(false);
  const [fontSize, setFontSize] = useState(16);
  const [relatedSongs, setRelatedSongs] = useState<any[]>([]);
  const { language: appLanguage, t } = useLanguage();

  const { user, isAuth: isAuthenticated } = useAuth();
  const canEdit = isAuthenticated && (user?.role === 'ADMIN' || user?.role === 'SUPER_ADMIN');
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [editForm, setEditForm] = useState<LyricsData & { id?: any }>({
      title: '',
      title_nepali: '',
      artist: '',
      artists: [],
      composer: '',
      composers: [],
      lyricist: '',
      lyricists: [],
      singer: '',
      singers: [],
      lyrics_nepali: '',
      lyrics_roman: '',
      youtubeUrl: '',
      isYoutubeVisible: true,
      note: '',
      isNoteVisible: true,
      language: 'nepali'
  });

  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);
  const [feedbackType, setFeedbackType] = useState('Lyrics Issue');
  const [feedbackText, setFeedbackText] = useState('');
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);
  const [isSubmittingFeedback, setIsSubmittingFeedback] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      let lyricsResult = null;
      if (id) {
          lyricsResult = await getSongById(id);
      } else if (artistParam && songParam) {
          lyricsResult = await getSongLyrics(decodeURIComponent(artistParam), decodeURIComponent(songParam));
      }

      if (!lyricsResult) {
          setData(null);
          setLoading(false);
          return;
      }

      // AUTO-ROMANIZATION LOGIC: If Nepali exists but Roman is blank, fix it permanently.
      if (lyricsResult.lyrics_nepali && (!lyricsResult.lyrics_roman || lyricsResult.lyrics_roman.trim() === "")) {
          const autoRoman = convertToRoman(lyricsResult.lyrics_nepali);
          lyricsResult.lyrics_roman = autoRoman;
          // Background update to persist the missing Roman lyrics
          saveCustomSong(lyricsResult.artist, lyricsResult.title, { ...lyricsResult, lyrics_roman: autoRoman }).catch(console.error);
      }

      const songTitle = lyricsResult.title || songParam || '';
      const artistName = lyricsResult.artist || artistParam || '';

      document.title = `${songTitle} Lyrics | SansarPlus`;

      const [allSongs, artistsList] = await Promise.all([
          getAllCustomSongs(),
          getAllCustomArtists()
      ]);

      setData(lyricsResult);
      setAllArtists(artistsList);

      if (allSongs && artistName) {
          const related = allSongs
              .filter(s => (s.artist === artistName || (s.artists && s.artists.includes(artistName))) && s.id !== lyricsResult.id)
              .sort((a, b) => (b.views || 0) - (a.views || 0))
              .slice(0, 5);
          setRelatedSongs(related);
      }

      setEditForm({ 
        ...lyricsResult,
        artists: lyricsResult.artists || [lyricsResult.artist],
        composers: lyricsResult.composers || (lyricsResult.composer ? [lyricsResult.composer] : []),
        lyricists: lyricsResult.lyricists || (lyricsResult.lyricist ? [lyricsResult.lyricist] : []),
        singers: lyricsResult.singers || (lyricsResult.singer ? [lyricsResult.singer] : []),
        isYoutubeVisible: lyricsResult.isYoutubeVisible ?? true,
        isNoteVisible: lyricsResult.isNoteVisible ?? true
      });

      setIsFav(isFavorite(generateId('song', songTitle, artistName)));
      setLoading(false);
      incrementViewCount(artistName, songTitle);
    };

    fetchData();
  }, [id, artistParam, songParam]);

  const handleFavorite = () => {
    if (!data) return;
    const item = {
        id: generateId('song', data.title || '', data.artist || ''),
        dbId: data.id, // Store actual database ID for Short URL redirection from favorites
        type: 'song' as const,
        name: data.title || '',
        subtext: data.artist || '',
        language: data.language,
        note: data.note
    };
    const added = toggleFavorite(item);
    setIsFav(added);
  };

  const handleCopy = () => {
    if (!data) return;
    const textToCopy = activeTab === 'nepali' 
        ? (data.lyrics_nepali || data.lyrics || "") 
        : (data.lyrics_roman || "");

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const shareToFB = () => {
    window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(window.location.href)}`, '_blank');
  };

  const shareToWA = () => {
    const text = `Check out the lyrics for "${appLanguage === 'nepali' ? data?.title_nepali || data?.title : data?.title}" on SansarPlus: ${window.location.href}`;
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleShare = async () => {
    if (!data) return;
    const shareData = {
      title: `${appLanguage === 'nepali' ? data.title_nepali || data.title : data.title} Lyrics`,
      text: `Check out the lyrics for "${appLanguage === 'nepali' ? data.title_nepali || data.title : data.title}" on SansarPlus!`,
      url: window.location.href,
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert("Link copied to clipboard!");
      }
    } catch (err) {
      console.log("Share failed", err);
    }
  };

  const handlePrint = () => window.print();
  const handleZoomIn = () => setFontSize(prev => Math.min(prev + 2, 72));
  const handleZoomOut = () => setFontSize(prev => Math.max(prev - 2, 10));

  const submitFeedback = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!data) return;
    setIsSubmittingFeedback(true);
    try {
        await submitReport({
            type: feedbackType,
            text: feedbackText,
            song_id: data.id?.toString(),
            song_title: data.title,
            artist: data.artist
        });
        setFeedbackSubmitted(true);
        setTimeout(() => {
            setFeedbackSubmitted(false);
            setIsFeedbackOpen(false);
            setFeedbackText('');
        }, 2000);
    } catch (err: any) {
        alert("Submission failed.");
    } finally {
        setIsSubmittingFeedback(false);
    }
  };

  const handleSaveEdit = async () => {
      if (!data) return;
      try {
          setIsSaving(true);
          const finalArtist = editForm.artists && editForm.artists.length > 0 ? editForm.artists.join(', ') : (editForm.artist || data.artist);

          await saveCustomSong(finalArtist, editForm.title || data.title, {
              ...editForm,
              artist: finalArtist
          });

          setData({ ...data, ...editForm, artist: finalArtist });
          setIsEditing(false);
          alert("Song updated successfully!");

          if (editForm.title !== data.title || finalArtist !== data.artist) {
              window.location.reload();
          }
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const getYouTubeEmbedUrl = (url?: string) => {
      if (!url) return null;
      let videoId = '';
      if (url.includes('v=')) videoId = url.split('v=')[1].split('&')[0];
      else if (url.includes('youtu.be/')) videoId = url.split('youtu.be/')[1].split('?')[0];
      return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  };

  const renderContributorLinks = (names: string[] | string | undefined) => {
      if (!names) return null;
      const nameList = (Array.isArray(names) ? names : names.split(','))
        .map(s => s.trim())
        .filter(s => s && s.toLowerCase() !== 'unknown');

      if (nameList.length === 0) return null;

      return (
          <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
              {nameList.map((name, i) => (
                  <React.Fragment key={name}>
                      <Link 
                        to={`/artist/${encodeURIComponent(name)}`} 
                        className="text-[17px] font-bold text-slate-700 hover:text-primary transition-all no-underline print:hidden"
                      >
                        {name}
                      </Link>
                      {i < nameList.length - 1 && <span className="text-slate-400 font-medium print:hidden">,</span>}
                  </React.Fragment>
              ))}
              {/* Visible during print as static text */}
              <div className="hidden print:block text-sm font-bold text-slate-800">
                {nameList.join(', ')}
              </div>
          </div>
      );
  };

  const handleEditLyricsChange = (val: string) => {
      setEditForm(prev => {
          const newState = { ...prev, lyrics_nepali: val };
          // Real-time Roman Nepali conversion if Romanized field is empty or manually reset
          if (!prev.lyrics_roman || prev.lyrics_roman.trim() === "") {
              newState.lyrics_roman = convertToRoman(val);
          }
          return newState;
      });
  };

  if (loading) return <Loader fullScreen text="Loading lyrics..." />;
  if (!data) return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-50">
        <Disc className="w-20 h-20 text-slate-200 mb-4 animate-spin-slow" />
        <h2 className="text-2xl font-bold text-slate-400 mb-6">Lyrics not found</h2>
        <Link to="/" className="bg-primary text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-primary/20 hover:scale-105 transition-transform">Back to Home</Link>
    </div>
  );

  const displayTitle = appLanguage === 'nepali' ? data.title_nepali || data.title : data.title;
  const embedUrl = getYouTubeEmbedUrl(data.youtubeUrl);

  const singersContent = renderContributorLinks(data.singers || data.singer);
  const composersContent = renderContributorLinks(data.composers || data.composer);
  const lyricistsContent = renderContributorLinks(data.lyricists || data.lyricist);
  const hasCredits = !!(singersContent || composersContent || lyricistsContent);

  return (
    <div className="min-h-screen bg-slate-50 pb-32 selection:bg-primary/10 selection:text-primary">
      {/* Song Hero */}
      <div className="bg-white border-b border-slate-100 pt-4 md:pt-8 pb-2 relative overflow-hidden">
        <div className="max-w-6xl mx-auto px-4 relative z-10">
            <div className="flex flex-col items-center text-center space-y-0.5">
                {data.note && data.isNoteVisible !== false && (
                    <span className="bg-amber-50 text-amber-600 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border border-amber-100 flex items-center gap-1 shadow-sm mb-1">
                        <StickyNote className="w-3 h-3" /> {data.note}
                    </span>
                )}
                <h1 className="text-3xl md:text-5xl lg:text-6xl font-black text-slate-900 leading-tight tracking-tighter drop-shadow-sm">{displayTitle}</h1>

                <div className="flex items-center justify-center gap-3 pt-2 print:hidden">
                    {canEdit && (
                        <button 
                          onClick={() => setIsEditing(!isEditing)} 
                          className={`flex items-center gap-2 px-3 py-1.5 rounded-xl transition-all shadow-sm border font-black text-[9px] uppercase tracking-widest ${isEditing ? 'bg-slate-900 text-white border-slate-800' : 'bg-white text-slate-600 border-slate-200 hover:border-primary/40'}`}
                        >
                            {isEditing ? <><X className="w-3 h-3" /> Exit Editor</> : <><Edit className="w-3 h-3" /> Edit Metadata</>}
                        </button>
                    )}
                </div>
            </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 mt-6 md:mt-10">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

            {/* Main Content: Lyrics & Credits */}
            <div className="lg:col-span-8 space-y-10">

                {isEditing ? (
                    <div className="bg-white rounded-[2.5rem] p-8 md:p-12 shadow-2xl border border-slate-200 space-y-10 animate-in slide-in-from-bottom-4">
                        <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                          <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center shadow-inner"><Settings className="w-6 h-6" /></div>
                          <h2 className="text-3xl font-black text-slate-800">Song Editor</h2>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                            <div className="space-y-6">
                              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-l-4 border-primary pl-3">Header Info</h3>
                              <div className="space-y-4">
                                  <div className="space-y-1.5">
                                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Roman Title</label>
                                      <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title} onChange={e => setEditForm({...editForm, title: e.target.value})} />
                                  </div>
                                  <div className="space-y-1.5">
                                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Nepali Title</label>
                                      <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.title_nepali} onChange={e => setEditForm({...editForm, title_nepali: e.target.value})} placeholder="native text..." />
                                  </div>
                                  <ArtistSelector label="Main Artist(s)" selected={editForm.artists || []} onChange={arts => setEditForm({...editForm, artists: arts})} suggestions={allArtists} />
                              </div>
                            </div>

                            <div className="space-y-6">
                              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-l-4 border-amber-500 pl-3">Settings</h3>
                              <div className="space-y-4">
                                  <div className="space-y-1.5">
                                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">YouTube URL</label>
                                      <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.youtubeUrl} onChange={e => setEditForm({...editForm, youtubeUrl: e.target.value})} placeholder="https://..." />
                                  </div>
                                  <div className="space-y-1.5">
                                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Song Note</label>
                                      <input className="w-full border-2 border-slate-100 p-4 rounded-2xl bg-slate-50 focus:bg-white focus:border-primary outline-none transition-all font-bold" value={editForm.note} onChange={e => setEditForm({...editForm, note: e.target.value})} placeholder="e.g. (Chords Attached)" />
                                  </div>
                                  <div className="grid grid-cols-2 gap-3 pt-2">
                                      <button onClick={() => setEditForm({...editForm, isYoutubeVisible: !editForm.isYoutubeVisible})} className={`flex items-center justify-center gap-2 p-3 rounded-xl border transition-all font-bold text-[10px] uppercase tracking-widest ${editForm.isYoutubeVisible ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>
                                          {editForm.isYoutubeVisible ? <><Eye className="w-3.5 h-3.5" /> Video On</> : <><EyeOff className="w-3.5 h-3.5" /> Video Off</>}
                                      </button>
                                      <button onClick={() => setEditForm({...editForm, isNoteVisible: !editForm.isNoteVisible})} className={`flex items-center justify-center gap-2 p-3 rounded-xl border transition-all font-bold text-[10px] uppercase tracking-widest ${editForm.isNoteVisible ? 'bg-amber-50 text-amber-600 border-amber-100' : 'bg-slate-50 text-slate-400 border-slate-200'}`}>
                                          {editForm.isNoteVisible ? <><Eye className="w-3.5 h-3.5" /> Note On</> : <><EyeOff className="w-3.5 h-3.5" /> Note Off</>}
                                      </button>
                                  </div>
                              </div>
                            </div>
                        </div>

                        <div className="space-y-6">
                          <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest border-l-4 border-emerald-500 pl-3">Contributor Roles</h3>
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                            <ArtistSelector label="Singers" selected={editForm.singers || []} onChange={v => setEditForm({...editForm, singers: v})} suggestions={allArtists} />
                            <ArtistSelector label="Composers" selected={editForm.composers || []} onChange={v => setEditForm({...editForm, composers: v})} suggestions={allArtists} />
                            <ArtistSelector label="Lyricists" selected={editForm.lyricists || []} onChange={v => setEditForm({...editForm, lyricists: v})} suggestions={allArtists} />
                          </div>
                        </div>

                        <div className="space-y-6">
                          <div className="flex items-center justify-between border-l-4 border-slate-900 pl-3">
                              <div className="flex items-center gap-3">
                                  <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">Lyrics Body</h3>
                                  <span className="text-[9px] text-primary font-bold flex items-center gap-1 bg-primary/5 px-2 py-1 rounded-full border border-primary/10 animate-pulse"><RefreshCw className="w-2.5 h-2.5"/> Auto-Romanizing Enabled</span>
                              </div>
                          </div>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                              <div className="space-y-2">
                                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Nepali Script</label>
                                  <textarea className="w-full h-[600px] border-2 border-slate-100 p-6 rounded-[2.5rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all shadow-inner" value={editForm.lyrics_nepali} onChange={e => handleEditLyricsChange(e.target.value)} />
                              </div>
                              <div className="space-y-2">
                                  <div className="flex justify-between items-center ml-2">
                                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Romanized</label>
                                      <button type="button" onClick={() => setEditForm(prev => ({...prev, lyrics_roman: convertToRoman(prev.lyrics_nepali || '')}))} className="text-[9px] font-black text-primary hover:underline uppercase flex items-center gap-1"><Sparkles className="w-2.5 h-2.5"/> Reset to Auto</button>
                                  </div>
                                  <textarea className="w-full h-[600px] border-2 border-slate-100 p-6 rounded-[2.5rem] bg-slate-50 font-sans leading-relaxed outline-none focus:bg-white focus:border-primary transition-all shadow-inner" value={editForm.lyrics_roman} onChange={e => setEditForm(prev => ({...prev, lyrics_roman: e.target.value}))} />
                              </div>
                          </div>
                        </div>

                        <button onClick={handleSaveEdit} disabled={isSaving} className="w-full bg-primary text-white py-6 rounded-[2rem] font-black text-xl shadow-2xl shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center transform active:scale-95">
                            {isSaving ? <Loader2 className="w-7 h-7 animate-spin mr-3"/> : <Save className="w-7 h-7 mr-3" />}
                            Publish Updates
                        </button>
                    </div>
                ) : (
                    <div className="space-y-8">
                        {/* Interactive Lyrics Card (Only visible on screen) */}
                        <div className="bg-white rounded-[2.5rem] shadow-xl overflow-hidden border border-slate-200 group/lyrics print:hidden">
                            <div className="flex flex-col md:flex-row border-b border-slate-100">
                                <div className="flex-1 flex bg-slate-50/50">
                                    <button onClick={() => setActiveTab('nepali')} className={`flex-1 py-5 font-black text-xs uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3 ${activeTab === 'nepali' ? 'text-primary border-b-[4px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                        <Globe className="w-4 h-4 md:w-5 md:h-5" /> Nepali
                                    </button>
                                    <button onClick={() => setActiveTab('roman')} className={`flex-1 py-5 font-black text-xs uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3 ${activeTab === 'roman' ? 'text-primary border-b-[4px] border-primary bg-white' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100/50'}`}>
                                        <Search className="w-4 h-4 md:w-5 md:h-5" /> Romanized
                                    </button>
                                </div>
                                <div className="p-2 md:p-3 bg-white flex items-center justify-center gap-2 border-t md:border-t-0 md:border-l border-slate-100">
                                    <div className="flex items-center bg-slate-50 rounded-xl p-1 border border-slate-200">
                                        <button onClick={handleZoomOut} className="p-2 text-slate-400 hover:text-primary"><ZoomOut className="w-4 h-4" /></button>
                                        <span className="text-[9px] font-black text-slate-300 mx-1">{fontSize}</span>
                                        <button onClick={handleZoomIn} className="p-2 text-slate-400 hover:text-primary"><ZoomIn className="w-4 h-4" /></button>
                                    </div>
                                    <button 
                                      onClick={handleFavorite} 
                                      className={`p-3 rounded-xl transition-all shadow-sm border ${isFav ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-slate-400 border-slate-200 hover:border-red-200 hover:text-red-400'}`}
                                      title="Favorite"
                                    >
                                        <Heart className={`w-4 h-4 ${isFav ? 'fill-current' : ''}`} />
                                    </button>
                                    <button 
                                      onClick={handleCopy} 
                                      className={`p-3 rounded-xl transition-all shadow-sm border ${copied ? 'bg-emerald-500 text-white border-emerald-400' : 'bg-white text-slate-400 border-slate-200 hover:border-primary/30'}`}
                                      title="Copy"
                                    >
                                        {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                                    </button>
                                </div>
                            </div>

                            <div className="p-8 md:p-16 lg:p-20 relative bg-white min-h-[500px] flex flex-col items-center">
                                <div className="w-full max-w-2xl">
                                    <div 
                                        className="whitespace-pre-wrap leading-[2.4] transition-all font-medium text-slate-800 tracking-wider text-center selection:bg-primary/20" 
                                        style={{ fontSize: `${fontSize}px` }}
                                    >
                                        {activeTab === 'nepali' ? (data.lyrics_nepali || data.lyrics || "Native lyrics coming soon.") : (data.lyrics_roman || "Romanized lyrics coming soon.")}
                                    </div>
                                </div>

                                <div className="mt-20 pt-10 border-t border-slate-50 w-full flex flex-wrap justify-center gap-4">
                                    <button onClick={handlePrint} className="flex items-center gap-2 px-6 py-2.5 bg-slate-50 text-slate-600 rounded-2xl font-bold text-xs hover:bg-slate-100 transition-all border border-slate-200 group">
                                        <Printer className="w-4 h-4 group-hover:scale-110 transition-transform" /> Save PDF
                                    </button>
                                    <button onClick={() => setIsFeedbackOpen(true)} className="flex items-center gap-2 px-6 py-2.5 bg-red-50/20 text-red-400 rounded-2xl font-bold text-xs hover:bg-red-50 transition-all border border-red-100/50 group">
                                        <Flag className="w-4 h-4 group-hover:rotate-12 transition-transform" /> Report
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* Dedicated Print Section (Side-by-Side during PDF export) */}
                        <div className="hidden print:flex print:flex-row print:gap-10 pb-10 border-b border-slate-100 items-start">
                            <div className="print:w-1/2">
                                <h4 className="text-[10pt] font-black text-slate-400 uppercase tracking-widest mb-4 border-b border-slate-200 pb-1 text-center">Native Script (Nepali)</h4>
                                <div className="whitespace-pre-wrap leading-[1.6] text-[12pt] font-medium text-slate-950 text-center px-2">
                                    {data.lyrics_nepali || data.lyrics || "Native lyrics coming soon."}
                                </div>
                            </div>
                            <div className="print:w-1/2">
                                <h4 className="text-[10pt] font-black text-slate-400 uppercase tracking-widest mb-4 border-b border-slate-200 pb-1 text-center">Romanized Script</h4>
                                <div className="whitespace-pre-wrap leading-[1.6] text-[12pt] font-medium text-slate-950 text-center px-2">
                                    {data.lyrics_roman || "Romanized lyrics coming soon."}
                                </div>
                            </div>
                        </div>

                        {/* Credits Section (Improved Legibility) */}
                        {hasCredits && (
                            <div className="bg-slate-50/60 rounded-[2.5rem] p-8 md:p-12 border border-slate-100 print:hidden">
                                <div className="flex items-center gap-4 mb-10">
                                    <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-xl flex items-center justify-center shadow-sm">
                                        <Info className="w-5 h-5" />
                                    </div>
                                    <h3 className="text-xl font-black text-slate-800 tracking-tight">Song Contributions</h3>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-y-8 gap-x-12">
                                    {singersContent && (
                                        <div className="space-y-2">
                                            <div className="flex items-center gap-2 text-[11px] font-black text-slate-400 uppercase tracking-[0.15em] border-b border-slate-200 pb-2 mb-3">
                                                <Mic2 className="w-3 h-3 text-primary" /> Vocalists
                                            </div>
                                            <div className="pl-1">{singersContent}</div>
                                        </div>
                                    )}
                                    {composersContent && (
                                        <div className="space-y-2">
                                            <div className="flex items-center gap-2 text-[11px] font-black text-slate-400 uppercase tracking-[0.15em] border-b border-slate-200 pb-2 mb-3">
                                                <Music className="w-3 h-3 text-indigo-500" /> Composition
                                            </div>
                                            <div className="pl-1">{composersContent}</div>
                                        </div>
                                    )}
                                    {lyricistsContent && (
                                        <div className="space-y-2">
                                            <div className="flex items-center gap-2 text-[11px] font-black text-slate-400 uppercase tracking-[0.15em] border-b border-slate-200 pb-2 mb-3">
                                                <PenTool className="w-3 h-3 text-emerald-500" /> Lyrics
                                            </div>
                                            <div className="pl-1">{lyricistsContent}</div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}

                        {/* Print Footer Watermark (Visible only in PDF/Print) */}
                        <div className="hidden print:block pt-12 mt-8 border-t border-slate-100 text-center opacity-80">
                            <p className="text-xl font-black text-primary tracking-tighter">Download from SansarPlus.com</p>
                            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-2">The Largest Nepali Christian Lyrics Platform</p>
                        </div>

                        {/* Share Section (Social sharing for Worship teams) */}
                        <div className="bg-white rounded-[2.5rem] p-10 shadow-lg border border-slate-200 space-y-8 print:hidden">
                            <div className="flex items-center gap-4">
                                <div className="w-12 h-12 bg-primary/10 text-primary rounded-2xl flex items-center justify-center">
                                    <Share2 className="w-6 h-6" />
                                </div>
                                <div>
                                    <h3 className="text-2xl font-black text-slate-800">Share with Church</h3>
                                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Send to your worship team or church members</p>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                                <button onClick={shareToFB} className="flex flex-col items-center gap-3 p-6 rounded-[2rem] bg-blue-50 text-blue-600 hover:bg-blue-600 hover:text-white transition-all group border border-blue-100 shadow-sm active:scale-95">
                                    <Facebook className="w-8 h-8 group-hover:scale-110 transition-transform" />
                                    <span className="text-[10px] font-black uppercase tracking-widest">Facebook</span>
                                </button>
                                <button onClick={shareToWA} className="flex flex-col items-center gap-3 p-6 rounded-[2rem] bg-emerald-50 text-emerald-600 hover:bg-emerald-600 hover:text-white transition-all group border border-emerald-100 shadow-sm active:scale-95">
                                    <MessageCircle className="w-8 h-8 group-hover:scale-110 transition-transform" />
                                    <span className="text-[10px] font-black uppercase tracking-widest">WhatsApp</span>
                                </button>
                                <button onClick={handleShare} className="flex flex-col items-center gap-3 p-6 rounded-[2rem] bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white transition-all group border border-indigo-100 shadow-sm active:scale-95">
                                    <Send className="w-8 h-8 group-hover:scale-110 transition-transform" />
                                    <span className="text-[10px] font-black uppercase tracking-widest">Team Share</span>
                                </button>
                                <button onClick={() => { navigator.clipboard.writeText(window.location.href); alert("Copied!"); }} className="flex flex-col items-center gap-3 p-6 rounded-[2rem] bg-slate-50 text-slate-600 hover:bg-slate-800 hover:text-white transition-all group border border-slate-200 shadow-sm active:scale-95">
                                    <LinkIcon className="w-8 h-8 group-hover:scale-110 transition-transform" />
                                    <span className="text-[10px] font-black uppercase tracking-widest">Copy URL</span>
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* Sidebar (Always hidden during print) */}
            <div className="lg:col-span-4 space-y-10 print:hidden">
                <div className="sticky top-24 space-y-10">

                    {/* Media Player */}
                    {data.isYoutubeVisible !== false && embedUrl ? (
                        <div className="bg-slate-950 rounded-[2.5rem] overflow-hidden shadow-2xl border border-slate-800 ring-4 ring-white shadow-primary/5 group/player">
                            <div className="p-5 flex items-center justify-between border-b border-white/5 bg-slate-900/80 backdrop-blur-md">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 bg-red-600 text-white rounded-xl flex items-center justify-center shadow-lg shadow-red-600/20">
                                        <Youtube className="w-5 h-5" />
                                    </div>
                                    <div>
                                        <h3 className="text-white text-sm font-black tracking-tight">Media Hub</h3>
                                        <div className="flex items-center gap-1.5">
                                            <span className="w-1.5 h-1.5 rounded-full bg-red-500 animate-pulse"></span>
                                            <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Worship Session</p>
                                        </div>
                                    </div>
                                </div>
                                <a href={data.youtubeUrl} target="_blank" rel="noopener noreferrer" className="p-2 text-slate-400 hover:text-white transition-colors" title="Open in YouTube">
                                    <ExternalLink className="w-4 h-4" />
                                </a>
                            </div>

                            <div className="aspect-video w-full bg-black relative">
                                <iframe 
                                    className="absolute inset-0 w-full h-full"
                                    src={`${embedUrl}?autoplay=0&rel=0&modestbranding=1`}
                                    title="Official Media"
                                    frameBorder="0"
                                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                    allowFullScreen
                                ></iframe>
                            </div>

                            <div className="p-5 bg-gradient-to-t from-black to-slate-900 flex items-center gap-3">
                                <div className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-primary">
                                    <Volume2 className="w-4 h-4" />
                                </div>
                                <div className="min-w-0 flex-1">
                                    <p className="text-slate-500 text-[8px] font-black uppercase tracking-[0.2em]">Now Reading</p>
                                    <p className="text-white text-xs font-bold truncate pr-2">{displayTitle}</p>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="bg-gradient-to-br from-slate-800 to-slate-950 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group border border-slate-800">
                            <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 rounded-full -mr-10 -mt-10 blur-2xl group-hover:bg-primary/20 transition-all duration-700"></div>
                            <Music className="w-10 h-10 text-slate-700 mb-6 group-hover:rotate-12 transition-transform" />
                            <h4 className="text-lg font-black mb-2 tracking-tight">Audio Unavailable</h4>
                            <p className="text-slate-400 text-xs leading-relaxed font-medium">An official audio or video session for this track hasn't been linked yet. You can contribute by reporting it.</p>
                        </div>
                    )}

                    {/* Explore More Section */}
                    {relatedSongs.length > 0 && (
                        <div className="space-y-6">
                            <h3 className="text-2xl font-black text-slate-900 flex items-center gap-3 px-2 tracking-tighter">
                                 Explore More <ChevronRight className="w-6 h-6 text-primary" />
                            </h3>
                            <div className="space-y-3">
                                {relatedSongs.map((song) => (
                                    <Link 
                                        key={song.id} 
                                        to={`/l/${song.id}`}
                                        className="flex items-center gap-4 p-4 bg-white rounded-[1.8rem] border border-slate-200 hover:border-primary/40 hover:shadow-xl transition-all group shadow-sm"
                                    >
                                        <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300 group-hover:bg-primary group-hover:text-white transition-all shadow-inner">
                                            <Play className="w-5 h-5 fill-current" />
                                        </div>
                                        <div className="min-w-0 flex-1">
                                            <p className="font-bold text-slate-800 text-sm truncate group-hover:text-primary transition-colors">
                                                {appLanguage === 'nepali' ? song.title_nepali || song.title : song.title}
                                            </p>
                                            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-0.5 flex items-center gap-1.5">
                                                Lyrics Available
                                            </p>
                                        </div>
                                    </Link>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>

        {/* Feedback Modal (Hidden during print) */}
        {isFeedbackOpen && (
            <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-md animate-in fade-in duration-300 print:hidden">
                <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300 border border-white/20">
                    <div className="bg-slate-900 p-12 text-white text-center relative overflow-hidden">
                        <div className="absolute inset-0 bg-gradient-to-br from-primary/20 to-transparent"></div>
                        <button onClick={() => setIsFeedbackOpen(false)} className="absolute top-6 right-8 p-3 rounded-full bg-white/10 hover:bg-white/20 transition-all text-white"><X className="w-6 h-6"/></button>
                        <h3 className="text-4xl font-black tracking-tighter relative z-10">Report Issue</h3>
                        <p className="text-[10px] font-black uppercase tracking-widest opacity-60 mt-3 relative z-10">Help Us Maintain Accuracy</p>
                    </div>

                    {feedbackSubmitted ? (
                        <div className="p-16 text-center space-y-6">
                            <div className="w-24 h-24 bg-emerald-50 text-emerald-500 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner border border-emerald-100"><Check className="w-12 h-12" /></div>
                            <h4 className="text-3xl font-black text-slate-900">Message Received</h4>
                            <p className="text-slate-500 font-medium">Thank you for helping the community!</p>
                        </div>
                    ) : (
                        <form onSubmit={submitFeedback} className="p-12 space-y-8">
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Subject</label>
                                <select 
                                    className="w-full bg-slate-50 border-2 border-slate-100 p-5 rounded-2xl font-black text-sm outline-none focus:border-primary appearance-none cursor-pointer shadow-inner"
                                    value={feedbackType}
                                    onChange={(e) => setFeedbackType(e.target.value)}
                                >
                                    <option>Lyrics Issue</option>
                                    <option>Wrong Credits</option>
                                    <option>Broken Video</option>
                                    <option>Typo Error</option>
                                </select>
                            </div>
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Details</label>
                                <textarea 
                                    required
                                    className="w-full h-40 bg-slate-50 border-2 border-slate-100 p-6 rounded-[2rem] text-sm font-medium outline-none focus:bg-white focus:border-primary shadow-inner resize-none"
                                    placeholder="Explain the correction needed..."
                                    value={feedbackText}
                                    onChange={(e) => setFeedbackText(e.target.value)}
                                ></textarea>
                            </div>
                            <button 
                                type="submit" 
                                disabled={isSubmittingFeedback}
                                className="w-full bg-slate-900 text-white py-6 rounded-[2.2rem] font-black text-lg shadow-xl hover:bg-black active:scale-95 transition-all disabled:opacity-50 uppercase tracking-widest"
                            >
                                {isSubmittingFeedback ? 'Submitting...' : 'Send Message'}
                            </button>
                        </form>
                    )}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default LyricsPage;

